function escapeHTML(s) { if (s === null || s === undefined) return ""; return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;"); }
window.__TINCLASS_APP_READY__ = true;

// ─── Matriz EC vs Criterios de Evaluación (Planificación por RA) ──────────
/** Convierte el texto libre de "Criterios de referencia" en una lista numerada
 *  CE.1, CE.2... -- una línea no vacía = un criterio. Si la línea ya trae un
 *  prefijo tipo "CE.1 -" (por si el usuario ya numeraba a mano), se limpia para
 *  no duplicarlo. */
function _parsearCriteriosEvaluacion(texto) {
  const lineas = String(texto || '').split('\n').map(l => l.trim()).filter(Boolean);
  return lineas.map((l, i) => ({ codigo: 'CE.' + (i + 1), descripcion: l.replace(/^CE\.?\s*\d+\s*[-:.]?\s*/i, '') }));
}

/** Arma, por cada EC, a cuáles criterios se refiere (según ec.contraste, un
 *  array de códigos "CE.n" asignado por la IA) y el texto resuelto de esos
 *  criterios. Función pura, reutilizada por Vista Previa, la exportación con
 *  plantilla de centro y el fallback standalone -- una sola fuente de verdad. */
function _construirMatrizEcCriterios(elementosCapacidad, ra) {
  const ceLista = _parsearCriteriosEvaluacion(ra?.criterios);
  const ceByCodigo = new Map(ceLista.map(c => [c.codigo, c.descripcion]));
  return (elementosCapacidad || []).map((ec, i) => {
    const codigos = (Array.isArray(ec.contraste) ? ec.contraste : []).filter(c => ceByCodigo.has(c));
    return {
      numero: i + 1,
      ecCodigo: ec.codigo || '',
      ecEnunciado: ec.enunciado || '',
      contrasteTexto: codigos.length ? codigos.join(' – ') : '—',
      criteriosTexto: codigos.length ? codigos.map(c => c + ': ' + ceByCodigo.get(c)).join('\n') : ''
    };
  });
}

// ─── Funciones de gestión de cursos ───────────────────────────────
const CAL_CURSOS_ELIMINADOS_KEY = 'planificadorRA_cal_cursos_eliminados_v1';
const CAL_CURSOS_ELIMINADOS_DIAS = 30;

/** Registra que un curso se eliminó. Al recargar, _cargarDesdeFirestore fusiona los
 *  cursos locales con los de Firestore como una UNIÓN de claves (para no perder
 *  cursos creados offline que todavía no sincronizaron) -- pero una unión nunca puede
 *  "borrar" una clave, solo agregar/sobreescribir. Si Firestore todavía tiene la
 *  versión vieja del curso (ej. porque se recargó justo antes de que la sincronización
 *  terminara), el curso eliminado resucitaba siempre. Esta lista de "tumbas" le dice a
 *  la fusión que excluya explícitamente esos ids sin importar qué traiga Firestore. */
function _registrarCursoEliminado(id) {
  try {
    const hoy = Date.now();
    let lista = JSON.parse(localStorage.getItem(CAL_CURSOS_ELIMINADOS_KEY) || '[]');
    lista = lista.filter(e => hoy - e.ts < CAL_CURSOS_ELIMINADOS_DIAS * 86400000);
    lista.push({ id, ts: hoy });
    localStorage.setItem(CAL_CURSOS_ELIMINADOS_KEY, JSON.stringify(lista));
  } catch (e) { console.warn('No se pudo registrar el curso eliminado:', e); }
}

/** Quita un id de la lista de "tumbas" de arriba -- se usa al restaurar un
 * curso desde la papelera, para que la próxima sincronización con Firestore
 * no lo vuelva a excluir (lo trataría como "recién eliminado" y lo borraría
 * otra vez sin que el docente lo pidiera). */
function _desregistrarCursoEliminado(id) {
  try {
    let lista = JSON.parse(localStorage.getItem(CAL_CURSOS_ELIMINADOS_KEY) || '[]');
    lista = lista.filter(e => e.id !== id);
    localStorage.setItem(CAL_CURSOS_ELIMINADOS_KEY, JSON.stringify(lista));
  } catch (e) { console.warn('No se pudo quitar el curso de la lista de eliminados:', e); }
}

const CAL_PAPELERA_DIAS = 3;

/** Quita de la papelera los cursos que ya pasaron los CAL_PAPELERA_DIAS días
 * -- se llama cada vez que se abre/renderiza la papelera o el panel de
 * calificaciones, para que se limpie sola sin necesidad de una tarea aparte. */
function _purgarPapeleraCursos() {
  if (!calState.papeleraCursos) return;
  const ahora = Date.now();
  Object.entries(calState.papeleraCursos).forEach(([id, reg]) => {
    const eliminadoEn = reg?.eliminadoEn ? new Date(reg.eliminadoEn).getTime() : 0;
    if (!eliminadoEn || ahora - eliminadoEn >= CAL_PAPELERA_DIAS * 86400000) {
      delete calState.papeleraCursos[id];
    }
  });
}

function eliminarCurso(id) {
  const curso = calState.cursos[id];
  if (!curso) return;
  if (!confirm(`¿Eliminar el curso "${curso.nombre}"? Podrás recuperarlo desde la papelera durante ${CAL_PAPELERA_DIAS} días.`)) return;
  if (!calState.papeleraCursos) calState.papeleraCursos = {};
  calState.papeleraCursos[id] = { ...curso, eliminadoEn: new Date().toISOString() };
  delete calState.cursos[id];
  if (calState.cursoActivoId === id) {
    const ids = Object.keys(calState.cursos);
    calState.cursoActivoId = ids.length ? ids[0] : null;
  }
  _registrarCursoEliminado(id);
  guardarCalificaciones();
  renderizarCalificaciones();
  registrarCambio(`Curso eliminado (a papelera): "${curso.nombre}"`);
  mostrarToast(`Curso eliminado. Puedes recuperarlo desde la papelera por ${CAL_PAPELERA_DIAS} días.`, 'success');
}

/** Restaura un curso desde la papelera a la lista de cursos activos. */
function restaurarCursoPapelera(id) {
  const reg = calState.papeleraCursos?.[id];
  if (!reg) return;
  const curso = { ...reg };
  delete curso.eliminadoEn;
  calState.cursos[id] = curso;
  delete calState.papeleraCursos[id];
  _desregistrarCursoEliminado(id);
  calState.cursoActivoId = id;
  guardarCalificaciones();
  renderizarCalificaciones();
  registrarCambio(`Curso restaurado desde la papelera: "${curso.nombre}"`);
  mostrarToast(`Curso "${curso.nombre}" restaurado`, 'success');
}

/** Elimina un curso de la papelera de forma permanente y definitiva, antes de
 * que se cumplan los CAL_PAPELERA_DIAS días -- por si el docente quiere
 * vaciarla a propósito en vez de esperar. */
function eliminarCursoDefinitivo(id) {
  const reg = calState.papeleraCursos?.[id];
  if (!reg) return;
  if (!confirm(`¿Eliminar "${reg.nombre}" definitivamente? Esta acción ya no se puede deshacer.`)) return;
  delete calState.papeleraCursos[id];
  guardarCalificaciones();
  renderizarPanelPapeleraCursos();
  mostrarToast('Curso eliminado definitivamente', 'success');
}

/** Actualiza solo el contador de la papelera (sin abrir/cerrar el panel) --
 * se llama en cada render del Libro de Calificaciones para que el badge sea
 * visible aunque la papelera esté colapsada. */
function _actualizarBadgePapelera() {
  _purgarPapeleraCursos();
  const badge = document.getElementById('badge-papelera-cal');
  if (!badge) return;
  const n = Object.keys(calState.papeleraCursos || {}).length;
  if (n > 0) { badge.textContent = n > 9 ? '9+' : n; badge.style.display = 'inline-flex'; }
  else badge.style.display = 'none';
}

function renderizarPanelPapeleraCursos() {
  const panel = document.getElementById('cal-papelera-panel');
  if (!panel) return;
  _purgarPapeleraCursos();
  _actualizarBadgePapelera();

  const items = Object.entries(calState.papeleraCursos || {});

  if (!items.length) {
    panel.classList.add('hidden');
    panel.innerHTML = '';
    return;
  }

  panel.innerHTML = '<div style="border:1px solid #FFCDD2;background:#FFF5F5;border-radius:12px;padding:12px 13px;margin-bottom:12px;">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:8px;">'
    + '<div style="font-size:0.82rem;font-weight:800;color:#C62828;text-transform:uppercase;letter-spacing:.06em;display:flex;align-items:center;gap:6px;">'
    + '<span class="material-icons" style="font-size:16px;">delete_outline</span>Papelera de cursos'
    + '</div>'
    + '<div style="font-size:0.74rem;color:#E57373;">Se eliminan solos a los ' + CAL_PAPELERA_DIAS + ' días</div>'
    + '</div>'
    + items.map(([id, reg]) => {
      const eliminadoEn = reg.eliminadoEn ? new Date(reg.eliminadoEn) : null;
      const diasTranscurridos = eliminadoEn ? (Date.now() - eliminadoEn.getTime()) / 86400000 : 0;
      const diasRestantes = Math.max(0, Math.ceil(CAL_PAPELERA_DIAS - diasTranscurridos));
      return '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;background:#fff;border:1px solid #FFCDD2;border-radius:10px;padding:8px 10px;margin-top:8px;flex-wrap:wrap;">'
        + '<div style="min-width:0;">'
        + '<div style="font-weight:700;color:#C62828;font-size:0.88rem;">' + escapeHTML(reg.nombre || 'Curso sin nombre') + '</div>'
        + '<div style="font-size:0.72rem;color:#EF5350;">' + Number((reg.estudiantes || []).length || 0) + ' estudiante(s) · Se borra en ' + diasRestantes + ' día' + (diasRestantes !== 1 ? 's' : '') + '</div>'
        + '</div>'
        + '<div style="display:flex;gap:6px;flex-shrink:0;">'
        + '<button onclick="restaurarCursoPapelera(\'' + id + '\')" style="background:#E8F5E9;color:#2E7D32;border:none;border-radius:999px;padding:5px 12px;font-size:0.75rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:4px;"><span class="material-icons" style="font-size:14px;">restore_from_trash</span>Restaurar</button>'
        + '<button onclick="eliminarCursoDefinitivo(\'' + id + '\')" title="Eliminar definitivamente" style="background:#FFEBEE;color:#C62828;border:none;border-radius:999px;padding:5px 10px;font-size:0.75rem;font-weight:700;cursor:pointer;display:flex;align-items:center;"><span class="material-icons" style="font-size:14px;">delete_forever</span></button>'
        + '</div>'
        + '</div>';
    }).join('')
    + '</div>';
  panel.classList.remove('hidden');
}

function toggleVistaPapeleraCursos() {
  const panel = document.getElementById('cal-papelera-panel');
  if (!panel) return;
  const estabaOculto = panel.classList.contains('hidden') || !panel.innerHTML;
  if (estabaOculto) renderizarPanelPapeleraCursos();
  else { panel.classList.add('hidden'); panel.innerHTML = ''; }
}

// ─── Funciones de estudiantes ─────────────────────────────────────
/** Normaliza un nombre para comparar duplicados: sin mayúsculas/minúsculas
 * ni espacios extra, para que "Ana Pérez" y "ana   pérez " cuenten como el
 * mismo nombre. */
function _normalizarNombreEst(nombre) {
  return String(nombre || '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function agregarEstudiantes() {
  const raw = document.getElementById('input-estudiantes')?.value || '';
  const nombres = raw.split('\n').map(n => n.trim()).filter(n => n.length > 0);
  if (!nombres.length) { mostrarToast('Escribe al menos un nombre', 'error'); return; }
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) { mostrarToast('Selecciona un curso primero', 'error'); return; }
  if (!curso.estudiantes) curso.estudiantes = [];

  // Detectar duplicados: nombres que ya existen en el curso, o repetidos
  // dentro del mismo pegado -- antes se agregaban en silencio (ej. si se
  // pegaba la misma lista dos veces por error), dejando filas idénticas e
  // indistinguibles en la tabla.
  const existentes = new Set(curso.estudiantes.map(e => _normalizarNombreEst(e.nombre)));
  const vistosEnEstePegado = new Set();
  const duplicados = [];
  const aAgregar = [];
  nombres.forEach(nombre => {
    const norm = _normalizarNombreEst(nombre);
    if (existentes.has(norm) || vistosEnEstePegado.has(norm)) duplicados.push(nombre);
    else aAgregar.push(nombre);
    vistosEnEstePegado.add(norm);
  });

  if (duplicados.length) {
    const lista = duplicados.slice(0, 5).join(', ') + (duplicados.length > 5 ? '...' : '');
    const plural = duplicados.length === 1 ? '' : 's';
    const agregarDeTodasFormas = confirm(
      `Ya hay un estudiante con este nombre en el curso${plural ? 's' : ''}: ${lista}\n\n¿Agregarlo${plural} de todas formas?`
    );
    if (agregarDeTodasFormas) aAgregar.push(...duplicados);
  }

  if (!aAgregar.length) { mostrarToast('No se agregó ningún estudiante nuevo (ya existían)', 'info'); return; }

  aAgregar.forEach(nombre => {
    curso.estudiantes.push({ id: uid(), nombre });
  });
  guardarCalificaciones();
  if (document.getElementById('input-estudiantes'))
    document.getElementById('input-estudiantes').value = '';
  renderizarTablaCalificaciones();
  registrarCambio(`${aAgregar.length} estudiante(s) agregado(s) al curso "${curso.nombre}": ${aAgregar.slice(0, 3).join(', ')}${aAgregar.length > 3 ? '...' : ''}`);
  mostrarToast(`${aAgregar.length} estudiante(s) agregado(s)`, 'info');
}

function importarAlumnosCSV(input) {
  const file = input.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    const texto = e.target.result;
    const lineas = texto.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
    const nombres = lineas.map(l => {
      const partes = l.split(/[,;]/);
      return partes[0].replace(/^"+|"+$/g, '').trim();
    }).filter(n => n.length > 0);
    const cabeceras = ['nombre', 'alumno', 'estudiante', 'name', 'student'];
    const inicio = cabeceras.includes((nombres[0] || '').toLowerCase()) ? 1 : 0;
    const nombresFinales = nombres.slice(inicio);
    if (!nombresFinales.length) { mostrarToast('No se encontraron nombres en el archivo', 'error'); return; }
    document.getElementById('input-estudiantes').value = nombresFinales.join('\n');
    agregarEstudiantes();
    input.value = '';
  };
  reader.readAsText(file, 'UTF-8');
}

function exportarAlumnosCSV() {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso || !curso.estudiantes?.length) { mostrarToast('No hay estudiantes en este curso', 'error'); return; }

  const planActiva = _getPlanActivaDeCurso();
  const raKey = planActiva ? _getRaKey() : null;
  const actividades = planActiva?.actividades?.filter(a => !a.esComplementario) || [];
  const raInfo = raKey ? curso.ras?.[raKey] : null;

  if (!raKey || !actividades.length || !raInfo) {
    // Sin RA activo: solo nombres, como CSV plano real -- así sigue siendo
    // compatible con "Importar CSV" (que lee texto plano, no HTML/Excel).
    const csv = 'Nombre\n' + curso.estudiantes.map(e => '"' + e.nombre.replace(/"/g, '""') + '"').join('\n');
    const filename = 'alumnos-' + (curso.nombre || 'curso').replace(/\s+/g, '_') + '.csv';
    const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(url);
    mostrarToast('Lista exportada', 'success');
    return;
  }

  // Con RA activo: notas del RA, exportadas como Excel con formato (bold,
  // banner con el RA una sola vez) -- este archivo no está pensado para
  // reimportarse como lista de alumnos, por eso puede usar el truco HTML/.xls.
  const thStyle = 'background:#1565C0;color:#ffffff;font-weight:bold;padding:6px 8px;border:1px solid #78909C;text-align:center;white-space:nowrap;';
  const thStyleAct = 'background:#1565C0;color:#ffffff;font-weight:bold;padding:6px 8px;border:1px solid #78909C;text-align:center;white-space:normal;max-width:160px;';
  const tdStyle = 'padding:5px 8px;border:1px solid #CFD8DC;';

  // Exportar con notas del RA activo. El RA se muestra UNA sola vez, en un
  // banner sobre la tabla, en vez de repetido en una columna por estudiante.
  const dg = planActiva.datosGenerales || {};
  const ra = planActiva.ra || {};
  const raLabel = ra.descripcion || [dg.moduloFormativo, ra.resultado].filter(Boolean).join(' · ') || raKey;

  const ecCounters = {};
  const actCols = actividades.map(a => {
    const ecBase = a.ecCodigo
      ? a.ecCodigo.replace(/^E\.C\./i, '').replace(/^EC/i, '').trim()
      : '?';
    ecCounters[ecBase] = (ecCounters[ecBase] || 0) + 1;
    const actLabel = 'Act ' + ecBase + '.' + ecCounters[ecBase];
    const max = raInfo.valores?.[a.id] ?? '';
    return { id: a.id, label: actLabel + (max !== '' ? ' (' + max + 'pts)' : ''), enunciado: a.enunciado || '' };
  });

  const totalCols = 2 + actCols.length; // Nombre + actividades + Total RA
  const banner = '<tr><td colspan="' + totalCols + '" style="background:#0D47A1;color:#ffffff;font-weight:bold;padding:8px;font-size:13px;">'
    + escapeHTML((curso.nombre || 'Curso') + ' — ' + raLabel + ' (Valor máximo RA: ' + (raInfo.valorTotal ?? '—') + ' pts)')
    + '</td></tr>';

  const headerRow = '<tr>'
    + '<th style="' + thStyle + '">Nombre</th>'
    + actCols.map(c => '<th style="' + thStyleAct + '">' + escapeHTML(c.label)
        + (c.enunciado ? '<br><span style="font-weight:normal;font-size:10px;color:#E3F2FD;">' + escapeHTML(c.enunciado) + '</span>' : '')
        + '</th>').join('')
    + '<th style="' + thStyle + '">Total RA</th>'
    + '</tr>';

  const filas = curso.estudiantes.map(est => {
    const notasEst = curso.notas?.[est.id]?.[raKey] || {};
    const actCeldas = actCols.map(c => {
      const n = notasEst[c.id];
      return '<td style="' + tdStyle + 'text-align:center;">' + ((n !== undefined && n !== null) ? n : '') + '</td>';
    }).join('');
    const total = _calcNotaRA(curso, est.id, raKey, actividades);
    return '<tr>'
      + '<td style="' + tdStyle + '">' + escapeHTML(est.nombre) + '</td>'
      + actCeldas
      + '<td style="' + tdStyle + 'text-align:center;font-weight:bold;">' + (total !== null ? total : '') + '</td>'
      + '</tr>';
  }).join('');

  const bodyHTML = '<table border="1" cellspacing="0" cellpadding="0" style="border-collapse:collapse;font-family:Calibri,Arial,sans-serif;font-size:12px;">'
    + banner + headerRow + filas + '</table>';
  const filename = 'notas-' + (curso.nombre || 'curso').replace(/\s+/g, '_') + '-' + raKey + '.xls';
  mostrarToast('Notas del RA exportadas', 'success');

  const html = '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">'
    + '<head><meta charset="utf-8"></head><body>' + bodyHTML + '</body></html>';

  const blob = new Blob(['\uFEFF' + html], { type: 'application/vnd.ms-excel' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function descargarPlantillaEstudiantesCSV() {
  // Ejemplo m\u00EDnimo del formato que lee "Importar CSV": una columna con el
  // nombre completo de cada estudiante, un nombre por l\u00EDnea. La primera
  // fila puede ser un encabezado (Nombre/Alumno/Estudiante/Name/Student) y
  // se ignora autom\u00E1ticamente al importar; cualquier columna extra tambi\u00E9n
  // se ignora (solo se lee la primera).
  const csv = 'Nombre\nMar\u00EDa Garc\u00EDa\nJuan P\u00E9rez\nAna L\u00F3pez';
  const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'plantilla_estudiantes.csv';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
  mostrarToast('Plantilla descargada', 'success');
}

function eliminarEstudiante(estudianteId) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  const est = curso.estudiantes.find(e => e.id === estudianteId);
  if (!est) return;
  if (!confirm(`¿Eliminar a "${est.nombre}"?`)) return;
  registrarCambio(`Estudiante eliminado: ${est.nombre}`);
  curso.estudiantes = curso.estudiantes.filter(e => e.id !== estudianteId);
  // Limpiar notas
  if (curso.notas && curso.notas[estudianteId]) delete curso.notas[estudianteId];
  guardarCalificaciones();
  renderizarTablaCalificaciones();
}

function _toggleEstMenu(e, estId) {
  e.stopPropagation();
  _cerrarEstMenus();
  const menuOrig = document.getElementById('est-menu-' + estId);
  if (!menuOrig) return;
  // Clonar menú y ponerlo en body para que quede encima de todo
  const menu = menuOrig.cloneNode(true);
  menu.id = 'est-menu-flotante';
  menu.style.display = 'flex';
  // Cerrar el menú flotante al hacer clic en cualquier opción
  menu.querySelectorAll('button').forEach(btn => {
    btn.addEventListener('click', () => _cerrarEstMenus(), { once: true });
  });
  document.body.appendChild(menu);
  const btn = e.currentTarget;
  const rect = btn.getBoundingClientRect();
  let top = rect.bottom + 4;
  let left = rect.right - menu.offsetWidth;
  if (top + menu.offsetHeight > window.innerHeight) top = rect.top - menu.offsetHeight - 4;
  if (left < 8) left = 8;
  menu.style.top = top + 'px';
  menu.style.left = left + 'px';
}
function _cerrarEstMenus() {
  const f = document.getElementById('est-menu-flotante');
  if (f) f.remove();
}
document.addEventListener('click', function(e) {
  if (!e.target.closest('.est-overflow-wrap') && !e.target.closest('#est-menu-flotante')) {
    _cerrarEstMenus();
  }
});
// Cerrar al hacer scroll en la tabla
document.addEventListener('scroll', _cerrarEstMenus, true);

function _toggleNombreMobile(span) {
  if (window.innerWidth > 600) return; // Solo en móvil
  const td = span.closest('.td-nombre');
  if (!td) return;
  const wasExpanded = td.classList.contains('mobile-expanded');
  // Cerrar todos los demás expandidos
  document.querySelectorAll('.td-nombre.mobile-expanded').forEach(el => el.classList.remove('mobile-expanded'));
  if (!wasExpanded) td.classList.add('mobile-expanded');
}

function editarNombreEstudiante(estudianteId) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  const est = curso.estudiantes.find(e => e.id === estudianteId);
  if (!est) return;
  const nombreAnterior = est.nombre;
  const nuevoNombre = prompt('Nuevo nombre:', est.nombre);
  if (!nuevoNombre || !nuevoNombre.trim()) return;
  est.nombre = nuevoNombre.trim();
  registrarCambio(`Nombre editado: "${nombreAnterior}" → "${est.nombre}"`);
  guardarCalificaciones();
  const el = document.getElementById('nombre-' + estudianteId);
  if (el) el.querySelector('span').textContent = est.nombre;
}

// ─── Helpers de notas ─────────────────────────────────────────────
function _clsNota(nota, max) {
  if (nota === null || nota === undefined) return '';
  const pct = max > 0 ? (nota / max) * 100 : 0;
  if (pct >= 70) return 'nota-aprobado';
  if (pct >= 60) return 'nota-regular';
  return 'nota-reprobado';
}

function _clsProm(prom) {
  if (prom === null || prom === undefined) return '';
  if (prom >= 70) return 'prom-aprobado';
  if (prom >= 60) return 'prom-regular';
  return 'prom-reprobado';
}

function _calcNotaRA(curso, estudianteId, raKey, actividadesVisibles) {
  const raInfo = curso.ras?.[raKey];
  if (!raInfo) return null;
  const notasEst = curso.notas?.[estudianteId]?.[raKey] || {};
  // Si se proveen las actividades visibles, usar solo esas IDs para evitar
  // contar notas huérfanas de actividades viejas/duplicadas que ya no existen
  const idsAUsar = actividadesVisibles ? actividadesVisibles.map(a => a.id) : raInfo.actividades;
  let total = 0, hayNotas = false;
  idsAUsar.forEach(actId => {
    const n = notasEst[actId];
    if (n !== undefined && n !== null) { total += n; hayNotas = true; }
  });
  return hayNotas ? Math.round(total * 10) / 10 : null;
}

function _calcNotaFinal(curso, estudianteId) {
  const rasKeys = Object.keys(curso.ras || {});
  if (!rasKeys.length) return null;
  let total = 0, hayNotas = false;
  rasKeys.forEach(rk => {
    const n = _calcNotaRA(curso, estudianteId, rk);
    if (n !== null) { total += n; hayNotas = true; }
  });
  return hayNotas ? Math.round(total * 10) / 10 : null;
}

function _promedioColRA(curso, raKey) {
  if (!curso.estudiantes?.length) return null;
  const notas = curso.estudiantes
    .map(e => _calcNotaRA(curso, e.id, raKey))
    .filter(n => n !== null);
  if (!notas.length) return null;
  return Math.round((notas.reduce((s, n) => s + n, 0) / notas.length) * 10) / 10;
}

function _promedioFinal(curso) {
  if (!curso.estudiantes?.length) return null;
  const notas = curso.estudiantes
    .map(e => _calcNotaFinal(curso, e.id))
    .filter(n => n !== null);
  if (!notas.length) return null;
  return Math.round((notas.reduce((s, n) => s + n, 0) / notas.length) * 10) / 10;
}

function _actualizarFilaRA(estudianteId, raKey) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  // Usar las actividades de la planificación activa para no contar notas huérfanas
  const planActiva = _getPlanActivaDeCurso();
  const actsVisibles = (planActiva?.actividades?.length ? planActiva.actividades : null);
  const notaRA = _calcNotaRA(curso, estudianteId, raKey, actsVisibles);
  const raInfo = curso.ras?.[raKey];
  const el = document.getElementById(`total-ra-${estudianteId}-${raKey}`);
  if (el) {
    el.textContent = notaRA !== null ? notaRA.toFixed(1) : '—';
    el.className = 'td-total-ra ' + _clsNota(notaRA, raInfo?.valorTotal || 100);
  }
  const notaFinal = _calcNotaFinal(curso, estudianteId);
  const elFinal = document.getElementById(`final-${estudianteId}`);
  if (elFinal) {
    elFinal.textContent = notaFinal !== null ? notaFinal.toFixed(1) : '—';
    elFinal.className = 'td-promedio ' + _clsProm(notaFinal);
  }
}

function _actualizarFooterRA(raKey) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  renderizarTablaCalificaciones(); // re-render completo del footer
}



