/**



 * Genera y renderiza la vista previa completa de la planificación



 */



function renderizarVistaPrevia() {
  const vp = document.getElementById('vista-previa');
  if (!vp) return;
  const dg = planificacion.datosGenerales || {};
  const ra = planificacion.ra || {};
  const ec = planificacion.elementosCapacidad || [];
  const acts = planificacion.actividades || [];
  const fechaHoy = new Date().toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' });







  const nivelLabel = { conocimiento: 'Conocimiento', comprension: 'Comprensión', aplicacion: 'Aplicación', actitudinal: 'Actitudinal' };







  // Tabla de EC



  let tablaEC = `<table class="vp-table">



    <thead><tr><th>Código</th><th>Enunciado del EC</th><th>Nivel Bloom</th><th>Horas</th></tr></thead>



    <tbody>`;



  ec.forEach(e => {



    tablaEC += `<tr>



      <td><code>${e.codigo}</code></td>



      <td>${e.enunciado}</td>



      <td>${nivelLabel[e.nivel]}</td>



      <td>${e.horasAsignadas}h</td>



    </tr>`;



  });



  tablaEC += `</tbody></table>`;

  // Tabla Matriz EC vs Criterios de Evaluación (Contraste)
  let tablaMatrizEC = `<table class="vp-table">
    <thead><tr>
      <th>#EC</th>
      <th>Elemento de Capacidad</th>
      <th>Contraste EC vs CE</th>
      <th>Criterios de Evaluación</th>
    </tr></thead>
    <tbody>`;
  _construirMatrizEcCriterios(ec, ra).forEach(fila => {
    tablaMatrizEC += `<tr>
      <td>${escapeHTML(fila.ecCodigo || String(fila.numero))}</td>
      <td>${escapeHTML(fila.ecEnunciado)}</td>
      <td>${escapeHTML(fila.contrasteTexto)}</td>
      <td style="white-space:pre-wrap;">${escapeHTML(fila.criteriosTexto)}</td>
    </tr>`;
  });
  tablaMatrizEC += `</tbody></table>`;





  // Tabla de actividades agrupada por EC (con rowspan)
  const nivelLabelAct = { conocimiento: 'Conocimiento', comprension: 'Comprensión', aplicacion: 'Aplicación', actitudinal: 'Actitudinal' };

  // Agrupar actividades por EC manteniendo orden
  const _actsSeqVP = {};
  const ecGroups = [];
  const ecGroupMap = {};
  acts.filter(a => !a.esComplementario).forEach(a => {
    const code = a.ecCodigo || '';
    if (!ecGroupMap[code]) {
      ecGroupMap[code] = { code, acts: [] };
      ecGroups.push(ecGroupMap[code]);
    }
    _actsSeqVP[code] = (_actsSeqVP[code] || 0);
    ecGroupMap[code].acts.push({ ...a, numLabel: _getActNumero(code, _actsSeqVP[code]) });
    _actsSeqVP[code]++;
  });

  let tablaActs = `<table class="vp-table">
    <thead><tr>
      <th>Elemento de Capacidad (EC)</th>
      <th>Nivel de Dominio de los EC</th>
      <th>Enunciado de las Actividades de Enseñanza/Aprendizaje</th>
      <th>Fecha de Realización (Actividades)</th>
      <th>Instrumento de evaluación</th>
      <th>Contenidos</th>
    </tr></thead>
    <tbody>`;

  ecGroups.forEach(group => {
    const ecInfo = ec.find(e => e.codigo === group.code);
    const ecEnunciado = ecInfo ? `${ecInfo.codigo}\n${ecInfo.enunciado || ''}` : group.code;
    const ecNivel = ecInfo ? (nivelLabelAct[ecInfo.nivel] || ecInfo.nivel || '') : '';
    const rowspan = group.acts.length;

    group.acts.forEach((a, i) => {
      tablaActs += `<tr>`;
      if (i === 0) {
        tablaActs += `<td rowspan="${rowspan}" style="vertical-align:top;font-weight:600;"><code>${escapeHTML(group.code)}</code><br>${escapeHTML(ecInfo?.enunciado || '')}</td>`;
        tablaActs += `<td rowspan="${rowspan}" style="vertical-align:middle;text-align:center;">${escapeHTML(ecNivel)}</td>`;
      }
      tablaActs += `<td>${escapeHTML(a.numLabel + ': ' + (a.enunciado || ''))}</td>`;
      tablaActs += `<td style="white-space:nowrap;">${escapeHTML(a.fechaStr || '')}</td>`;
      tablaActs += `<td>${escapeHTML(a.instrumento?.tipoLabel || '')}</td>`;
      tablaActs += `<td>${escapeHTML(a.contenidos || '')}</td>`;
      tablaActs += `</tr>`;
    });
  });

  // EC sin actividades propias (el EC actitudinal permea a todos los demás EC
  // y actividades, así que nunca tiene actividades asignadas -- ver
  // construirPromptBase, que ya no le genera ninguna).
  ec.filter(e => !ecGroupMap[e.codigo] && e.nivel === 'actitudinal').forEach(e => {
    tablaActs += `<tr>
      <td style="vertical-align:top;font-weight:600;"><code>${escapeHTML(e.codigo)}</code><br>${escapeHTML(e.enunciado || '')}</td>
      <td style="vertical-align:middle;text-align:center;">${escapeHTML(nivelLabelAct[e.nivel] || e.nivel || '')}</td>
      <td colspan="4" style="font-style:italic;color:#616161;">Permea todos los EC y Actividades, no necesita Actividades asociadas directamente, ni Contenidos sugeridos.</td>
    </tr>`;
  });

  // Complementarios al final sin agrupación EC
  acts.filter(a => a.esComplementario).forEach(a => {
    tablaActs += `<tr>
      <td style="font-style:italic;">Complementario</td>
      <td style="text-align:center;">—</td>
      <td>${escapeHTML(a.enunciado || '')}</td>
      <td style="white-space:nowrap;">${escapeHTML(a.fechaStr || '')}</td>
      <td>${escapeHTML(a.instrumento?.tipoLabel || '')}</td>
      <td>${escapeHTML(a.contenidos || '')}</td>
    </tr>`;
  });

  tablaActs += `</tbody></table>`;







  // Instrumentos completos



  let instrumentosHTML = '';
  const _instSeqVP = {};



  acts.forEach(a => {



    if (!a.instrumento) return;

    _instSeqVP[a.ecCodigo] = _instSeqVP[a.ecCodigo] || 0;
    const _instNum = _getActNumero(a.ecCodigo, _instSeqVP[a.ecCodigo]++);

    instrumentosHTML += `



    <div class="vp-instrumento-box">



      <div class="vp-instrumento-title">



        <span class="material-icons" style="font-size:18px;">${a.instrumento.tipo === 'cotejo' ? 'checklist' : 'table_chart'}</span>
        <span style="font-size:0.78rem;font-weight:700;color:#546E7A;background:#ECEFF1;padding:1px 8px;border-radius:10px;margin-right:6px;">${_instNum}</span>



        ${a.instrumento.titulo}



      </div>



      ${_renderInstrumentoHTML(a.instrumento)}



    </div>`;



  });







  vp.innerHTML = `



    <!-- Encabezado institucional -->



    <div class="vp-header">



      <div class="vp-logo-area">



        <span class="material-icons vp-logo-icon">school</span>



        <div>



          <div class="vp-institucion">República Dominicana · Educación Técnico Profesional</div>



          <div class="vp-titulo-doc">Planificación por Resultados de Aprendizaje</div>



        </div>



      </div>



    </div>







    <!-- Datos generales -->



    <div class="vp-section-title">Datos Generales</div>



    <div class="vp-datos-grid">



      <div class="vp-dato"><strong>Nombre de la Institución</strong><span>${escapeHTML(dg.nombreInstitucion || '-')}</span></div>

      <div class="vp-dato"><strong>Regional/Distrito</strong><span>${escapeHTML(dg.regional || '-')}</span></div>

      <div class="vp-dato"><strong>Politécnico</strong><span>${escapeHTML(dg.politecnico || '-')}</span></div>

      <div class="vp-dato"><strong>Familia Profesional</strong><span>${dg.familiaProfesional || '-'} (${dg.codigoFP || '-'})</span></div>



      <div class="vp-dato"><strong>Bachillerato Técnico</strong><span>${dg.nombreBachillerato || '-'}</span></div>



      <div class="vp-dato"><strong>Código Título</strong><span>${dg.codigoTitulo || '-'}</span></div>



      <div class="vp-dato"><strong>Módulo Formativo</strong><span>${dg.moduloFormativo || '-'} (${dg.codigoModulo || '-'})</span></div>



      <div class="vp-dato"><strong>Docente</strong><span>${dg.nombreDocente || '-'}</span></div>



      <div class="vp-dato"><strong>Ordenanza</strong><span>${escapeHTML(dg.ordenanza || '-')}</span></div>



      <div class="vp-dato"><strong>Período</strong><span>${dg.fechaInicio || '-'} → ${dg.fechaTermino || '-'}</span></div>



      <div class="vp-dato"><strong>Horas por semana / Total</strong><span>${dg.horasSemana || '-'} hrs / ${planificacion.horasTotal} hrs</span></div>



      <div class="vp-dato"><strong>RA N° / Valor</strong><span>${dg.cantidadRA || '-'} RA en el módulo · ${dg.valorRA || '-'} puntos</span></div>



    </div>







    <!-- RA -->



    <div class="vp-section-title">Resultado de Aprendizaje (RA)</div>



    <div class="vp-ra-box">${ra.descripcion || '-'}</div>



    ${ra.criterios ? `<p style="font-size:0.85rem;color:#555;margin-bottom:0.5rem;"><strong>Criterios de referencia:</strong></p><pre style="font-size:0.82rem;color:#333;white-space:pre-wrap;background:#f9f9f9;padding:0.75rem;border-radius:6px;">${ra.criterios}</pre>` : ''}



    ${ra.recursos ? `<p style="font-size:0.85rem;color:#555;margin-top:0.5rem;"><strong>Recursos didácticos:</strong> ${ra.recursos}</p>` : ''}







    <!-- EC -->



    <div class="vp-section-title">Elementos de Capacidad</div>



    ${tablaEC}

    <!-- Matriz EC vs Criterios de Evaluación -->

    <div class="vp-section-title">Matriz EC vs Criterios de Evaluación</div>

    ${tablaMatrizEC}





    <!-- Actividades -->



    <div class="vp-section-title">Actividades de Aprendizaje y Evaluación</div>



    ${tablaActs}







    <!-- Instrumentos -->



    <div class="vp-section-title">Instrumentos de Evaluación</div>



    ${instrumentosHTML}







    <!-- Pie de página -->



    <div class="vp-footer">



      <div>



        <p>Elaborado con: <strong>Planificador Educativo por RA</strong></p>



        <p>Fecha de elaboración: ${fechaHoy}</p>



      </div>



      <div class="vp-firma">



        <div class="vp-firma-linea"></div>



        <strong>${dg.nombreDocente || 'Docente'}</strong>



        <p style="font-size:0.78rem;color:#777;">Firma del Docente</p>



      </div>



    </div>`;



}







