// ── Plantillas Word de centros: almacenamiento en chunks ────────────────
// Un .docx de varias paginas en base64 facilmente supera 1 MiB, el limite
// por documento de Firestore -- guardar plantillaXBase64 directo en el
// documento del centro (como se hacia antes) fallaba al guardar centros con
// plantillas grandes ("The value of property... is longer than 1048487
// bytes"). Mismo patron ya usado para el CV del Portafolio Docente
// (_guardarPortafolioCV/cargarPortafolioCV): se parte el base64 en
// documentos de ~900 KB dentro de una subcoleccion, con un doc de metadatos
// aparte. tipo es uno de: 'planificacion', 'diaria', 'psicologia', 'impacto'.
const PLANTILLA_CENTRO_CHUNK_CHARS = 900000;
const PLANTILLA_CENTRO_CAMPOS = {
  planificacion: { base64: 'plantillaBase64', nombre: 'plantillaNombre', fallback: 'plantilla.docx' },
  diaria: { base64: 'plantillaDiariaBase64', nombre: 'plantillaDiariaNombre', fallback: 'plantilla_diaria.docx' },
  psicologia: { base64: 'plantillaReportePsicologiaBase64', nombre: 'plantillaReportePsicologiaNombre', fallback: 'plantilla_reportes_psicologia.docx' },
  impacto: { base64: 'plantillaImpactoVinculacionBase64', nombre: 'plantillaImpactoVinculacionNombre', fallback: 'plantilla_reporte_impacto.docx' }
};

function _plantillasCentroChunksRef(centroId) {
  return db.collection(CENTROS_COLLECTION).doc(centroId).collection('plantillas_chunks');
}

/** Guarda una plantilla partida en chunks, y limpia el campo viejo (blob
 *  unico en el documento del centro) si existia -- para que ese documento
 *  vuelva a estar bajo el limite de 1 MiB. Tambien deja un flag liviano
 *  (tienePlantilla_<tipo>) en el documento del centro para poder seguir
 *  encontrando "algun centro con esta plantilla" sin traer el base64 completo
 *  (usado por el fallback de superadmin sin centro asignado). */
async function _guardarPlantillaCentroChunked(centroId, tipo, base64, nombre) {
  const base = _plantillasCentroChunksRef(centroId);
  const totalChunks = Math.max(1, Math.ceil(base64.length / PLANTILLA_CENTRO_CHUNK_CHARS));

  let prevChunks = 0;
  try {
    const metaOld = await base.doc(tipo + '_meta').get();
    if (metaOld.exists) prevChunks = metaOld.data().totalChunks || 0;
  } catch {}

  for (let i = 0; i < totalChunks; i++) {
    const chunk = base64.slice(i * PLANTILLA_CENTRO_CHUNK_CHARS, (i + 1) * PLANTILLA_CENTRO_CHUNK_CHARS);
    await base.doc(`${tipo}_chunk_${i}`).set({ payload: chunk });
  }
  for (let i = totalChunks; i < prevChunks; i++) {
    await base.doc(`${tipo}_chunk_${i}`).delete().catch(() => {});
  }
  await base.doc(tipo + '_meta').set({ nombre: nombre || '', totalChunks, actualizadoEn: new Date().toISOString() });

  const cfg = PLANTILLA_CENTRO_CAMPOS[tipo];
  const flagUpdate = { [`tienePlantilla_${tipo}`]: true };
  if (cfg) {
    flagUpdate[cfg.base64] = firebase.firestore.FieldValue.delete();
    flagUpdate[cfg.nombre] = nombre || '';
  }
  await db.collection(CENTROS_COLLECTION).doc(centroId).update(flagUpdate).catch(() => {});
}

/** Carga una plantilla guardada en chunks; si el centro nunca re-subio su
 *  plantilla desde antes de este cambio, cae al campo viejo plantillaXBase64
 *  del documento del centro (formato legado, sin migracion forzada). */
async function _cargarPlantillaCentroChunked(centroId, tipo) {
  try {
    const metaDoc = await _plantillasCentroChunksRef(centroId).doc(tipo + '_meta').get();
    if (metaDoc.exists) {
      const meta = metaDoc.data();
      let base64 = '';
      for (let i = 0; i < (meta.totalChunks || 0); i++) {
        const chunkDoc = await _plantillasCentroChunksRef(centroId).doc(`${tipo}_chunk_${i}`).get();
        base64 += (chunkDoc.exists && chunkDoc.data().payload) || '';
      }
      if (base64) return { base64, nombre: meta.nombre || '' };
    }
  } catch (e) {
    console.warn('_cargarPlantillaCentroChunked:', tipo, e.message);
  }
  const cfg = PLANTILLA_CENTRO_CAMPOS[tipo];
  if (!cfg) return null;
  try {
    const centroDoc = await db.collection(CENTROS_COLLECTION).doc(centroId).get();
    if (centroDoc.exists) {
      const c = centroDoc.data();
      if (c[cfg.base64]) return { base64: c[cfg.base64], nombre: c[cfg.nombre] || '' };
    }
  } catch {}
  return null;
}

/** true/nombre si el centro tiene esta plantilla (chunked o legado), sin
 *  traer el base64 completo -- para el indicador "Plantilla cargada" en el
 *  formulario de Superadmin. centroYaCargado (opcional) evita releer el
 *  documento del centro si ya se tiene a mano. */
async function _tienePlantillaCentroChunked(centroId, tipo, centroYaCargado) {
  try {
    const metaDoc = await _plantillasCentroChunksRef(centroId).doc(tipo + '_meta').get();
    if (metaDoc.exists) return { existe: true, nombre: metaDoc.data().nombre || '' };
  } catch {}
  const cfg = PLANTILLA_CENTRO_CAMPOS[tipo];
  if (cfg && centroYaCargado && centroYaCargado[cfg.base64]) {
    return { existe: true, nombre: centroYaCargado[cfg.nombre] || '' };
  }
  return { existe: false, nombre: '' };
}

/** Elimina una plantilla guardada en chunks (y el campo viejo/flag, por si
 *  quedaba alguno). */
async function _eliminarPlantillaCentroChunked(centroId, tipo) {
  try {
    const base = _plantillasCentroChunksRef(centroId);
    const metaDoc = await base.doc(tipo + '_meta').get();
    const totalChunks = metaDoc.exists ? (metaDoc.data().totalChunks || 0) : 0;
    for (let i = 0; i < totalChunks; i++) {
      await base.doc(`${tipo}_chunk_${i}`).delete().catch(() => {});
    }
    await base.doc(tipo + '_meta').delete().catch(() => {});
  } catch (e) {
    console.warn('_eliminarPlantillaCentroChunked:', tipo, e.message);
  }
  const cfg = PLANTILLA_CENTRO_CAMPOS[tipo];
  const flagUpdate = { [`tienePlantilla_${tipo}`]: firebase.firestore.FieldValue.delete() };
  if (cfg) {
    flagUpdate[cfg.base64] = firebase.firestore.FieldValue.delete();
    flagUpdate[cfg.nombre] = firebase.firestore.FieldValue.delete();
  }
  await db.collection(CENTROS_COLLECTION).doc(centroId).update(flagUpdate).catch(() => {});
}

/** Obtiene la URL de plantilla del centro del usuario actual.
 *
 * Deja un motivo en window._motivoSinPlantillaCentro cuando devuelve null,
 * para que quien exporta pueda avisarle al docente por qué no salió con el
 * diseño de su centro (antes fallaba en silencio, sin ninguna pista). */
async function _getPlantillaUrlCentro() {
  if (!window.currentUser) return null;
  try {
    // 1. Buscar centroId en perfiles
    let centroId = null;
    const userDoc = await db.collection('perfiles').doc(window.currentUser.uid).get();
    if (userDoc.exists && userDoc.data().centroId) centroId = userDoc.data().centroId;

    // 2. Buscar en colección usuarios
    if (!centroId) {
      const userDoc2 = await db.collection('usuarios').doc(window.currentUser.uid).get();
      if (userDoc2.exists && userDoc2.data().centroId) centroId = userDoc2.data().centroId;
    }

    // 3. Si tiene centroId, la plantilla SIEMPRE debe ser la de ESE centro (o
    // ninguna) -- nunca la de otro centro, aunque el suyo no tenga una subida
    // todavía. Antes, si este paso fallaba, el código caía al paso 4 igual
    // (pensado solo para "sin centro") y el docente terminaba recibiendo,
    // sin saberlo, la plantilla de un centro educativo ajeno.
    if (centroId) {
      const result = await _getPlantillaFromCentro(centroId);
      if (result) return result;
      window._motivoSinPlantillaCentro = 'sin_plantilla';
      return null;
    }

    // 4. Solo cuando el usuario NO tiene ningún centro asignado (ej. superadmin
    // sin centro propio): usar cualquier centro que sí tenga plantilla, como
    // referencia genérica para poder probar la exportación.
    const snap = await db.collection(CENTROS_COLLECTION).where('tienePlantilla_planificacion', '==', true).limit(1).get();
    if (!snap.empty) {
      const centro = snap.docs[0].data();
      const result = await _cargarPlantillaCentroChunked(snap.docs[0].id, 'planificacion');
      if (result) return { base64: result.base64, centroId: snap.docs[0].id, centroNombre: centro.nombre || '' };
    }

    window._motivoSinPlantillaCentro = 'sin_centro';
    return null;
  } catch (e) {
    console.warn('[Plantilla] Error obteniendo centro:', e);
    window._motivoSinPlantillaCentro = 'error';
    return null;
  }
}

/** Avisa al docente, con un toast claro, por qué la exportación no usó la
 * plantilla de su centro -- en vez de dejarlo adivinar por qué el Word no
 * coincide con el diseño esperado. Solo avisa en los casos accionables
 * (falta subir la plantilla, o hubo un error de red); si el usuario
 * simplemente no tiene centro asignado (ej. superadmin de prueba), no aplica. */
function _avisarExportSinPlantilla() {
  const motivo = window._motivoSinPlantillaCentro;
  window._motivoSinPlantillaCentro = null;
  if (motivo === 'sin_plantilla') {
    mostrarToast('Tu centro todavía no tiene una plantilla de Word configurada -- se exportó con el diseño estándar. Pide al superadmin que la suba en Superadmin > Centros Educativos.', 'info');
  } else if (motivo === 'error') {
    mostrarToast('No se pudo cargar la plantilla de tu centro (revisa tu conexión) -- se exportó con el diseño estándar.', 'info');
  }
}

async function _getPlantillaFromCentro(centroId) {
  const centroDoc = await db.collection(CENTROS_COLLECTION).doc(centroId).get();
  if (!centroDoc.exists) return null;
  const centro = centroDoc.data();
  const result = await _cargarPlantillaCentroChunked(centroId, 'planificacion');
  if (!result) return null;
  return { base64: result.base64, centroId, centroNombre: centro.nombre || '' };
}

/**
 * Genera el nombre de archivo para exportar una planificación.
 * Formato: "Planificacion RA0208 Nombre Del Modulo"
 * El código del RA se extrae del inicio de ra.descripcion (ej: "RA0208: texto...")
 */
function _nombreArchivoRA(ext) {
  const dg = planificacion.datosGenerales || {};
  const raDesc = (planificacion.ra || {}).descripcion || '';
  // Extraer código del RA: cualquier prefijo antes del primer ":" o espacio (ej: RA0208, RAE3.6, RA3)
  const codigoMatch = raDesc.match(/^([A-Za-z]{1,4}[\w.]+)/);
  const codigoRA = codigoMatch ? codigoMatch[1] : 'RA';
  const modulo = dg.moduloFormativo || 'Modulo';
  return `Planificacion ${codigoRA} ${modulo}.${ext}`;
}

function _toSnakeCasePlaceholderKey(key) {
  return String(key || '')
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/[\s\-./]+/g, '_')
    .replace(/[^a-zA-Z0-9_]/g, '')
    .replace(/_+/g, '_')
    .replace(/^_+|_+$/g, '')
    .toLowerCase();
}

function _placeholderValueToString(value) {
  if (value == null) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) {
    const simple = value
      .map(v => (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') ? String(v) : '')
      .filter(Boolean);
    return simple.join(', ');
  }
  return '';
}

function _isPlainObject(value) {
  return Object.prototype.toString.call(value) === '[object Object]';
}

function _setPlaceholderIfEmpty(target, key, value) {
  if (!key) return;
  if (target[key] === undefined || target[key] === '') target[key] = value;
}

function _agregarPlaceholdersDinamicos(target, source, opts) {
  if (!_isPlainObject(source)) return;

  const prefix = _toSnakeCasePlaceholderKey((opts && opts.prefix) || '');

  const walk = (node, pathSnake, pathRaw) => {
    if (node == null) return;

    if (Array.isArray(node)) {
      const simpleJoined = _placeholderValueToString(node);
      if (simpleJoined) {
        const snakePath = pathSnake.join('_');
        const rawPath = pathRaw.join('_');
        _setPlaceholderIfEmpty(target, snakePath, simpleJoined);
        _setPlaceholderIfEmpty(target, rawPath, simpleJoined);
        if (prefix) {
          _setPlaceholderIfEmpty(target, prefix + '_' + snakePath, simpleJoined);
          _setPlaceholderIfEmpty(target, prefix + '_' + rawPath, simpleJoined);
        }
      }
      return;
    }

    if (_isPlainObject(node)) {
      Object.keys(node).forEach((rawKey) => {
        const snakeKey = _toSnakeCasePlaceholderKey(rawKey);
        if (!snakeKey) return;
        walk(node[rawKey], pathSnake.concat(snakeKey), pathRaw.concat(String(rawKey)));
      });
      return;
    }

    const textValue = _placeholderValueToString(node);
    if (textValue === '') return;

    const snakePath = pathSnake.join('_');
    const rawPath = pathRaw.join('_');
    _setPlaceholderIfEmpty(target, snakePath, textValue);
    _setPlaceholderIfEmpty(target, rawPath, textValue);
    if (prefix) {
      _setPlaceholderIfEmpty(target, prefix + '_' + snakePath, textValue);
      _setPlaceholderIfEmpty(target, prefix + '_' + rawPath, textValue);
    }
  };

  walk(source, [], []);
}

/** Exporta usando la plantilla .docx del centro con docxtemplater */
async function _exportarConPlantillaCentro() {
  const DocxModule = window.docxtemplater || window.Docxtemplater;
  const Docxtemplater = DocxModule?.default || DocxModule;
  if (typeof PizZip === 'undefined' || !Docxtemplater) {
    console.warn('[Plantilla] PizZip o docxtemplater no disponible');
    return false;
  }

  const info = await _getPlantillaUrlCentro();
  if (!info) return false;

  mostrarToast('Exportando con plantilla del centro...', 'info');

  // Decodificar plantilla base64 almacenada en Firestore
  const binaryStr = atob(info.base64);
  const bytes = new Uint8Array(binaryStr.length);
  for (let i = 0; i < binaryStr.length; i++) bytes[i] = binaryStr.charCodeAt(i);
  const arrayBuffer = bytes.buffer;

  const dg = planificacion.datosGenerales || {};
  const ra = planificacion.ra || {};
  const acts = planificacion.actividades || [];
  const ecs = planificacion.elementosCapacidad || [];
  const ahora = new Date();

  // Construir tabla de EC + Actividades
  // Construir filas para loop de docxtemplater (tabla en Word)
  // Usamos marcadores __VMERGE__ para celdas que deben fusionarse verticalmente
  // y __VSTART__ para la primera celda del grupo (restart del merge)
  const nivelLabelTpl = { conocimiento: 'Conocimiento', comprension: 'Comprensión', aplicacion: 'Aplicación', actitudinal: 'Actitudinal' };
  const actividades = [];
  ecs.forEach(ec => {
    const actsEC = acts.filter(a => a.ecCodigo === ec.codigo && !a.esComplementario);
    const needsMerge = actsEC.length > 1;
    const horasActEC = ec.horasAsignadas ? (ec.horasAsignadas / Math.max(1, actsEC.length)) : 1.5;
    actsEC.forEach((a, i) => {
      const ecText = `${ec.codigo}\n${ec.enunciado || ''}`;
      const ecNivel = nivelLabelTpl[ec.nivel] || ec.nivel || ec.nivelBloom || '';
      // Si la actividad nunca se generó manualmente en el Paso 5 (Planificación Diaria),
      // la metodología activa se rellena con la generación local para que nunca quede
      // en blanco en la exportación (mismo criterio que _exportarDiariaConPlantillaCentro).
      const metodologia = estadoDiarias.sesiones[a.id]?.estrategiaCorta || generarContenidoSesion(a, ec, horasActEC).estrategiaCorta || '';
      actividades.push({
        ec_codigo: ec.codigo || '',
        ec_enunciado: i === 0 ? (needsMerge ? '__VSTART__' + ecText : ecText) : '__VMERGE__',
        ec_nivel: i === 0 ? (needsMerge ? '__VSTART__' + ecNivel : ecNivel) : '__VMERGE__',
        act_numero: _getActNumero(ec.codigo, i),
        act_enunciado: `${_getActNumero(ec.codigo, i)}: ${a.enunciado || ''}`,
        act_fecha: a.fechaStr || (a.fecha ? String(a.fecha).split('T')[0] : '') || '',
        act_instrumento: a.instrumento?.tipoLabel || _getInstrLabel(a.instrumento?.tipo) || '',
        act_metodologia: metodologia,
        metodologia_activa: metodologia,
        contenidos_asociados: a.contenidos || ''
      });
    });
  });

  // Datos para placeholders — todo como string, nunca undefined
  const data = {
    familia_profesional: dg.familiaProfesional || '',
    codigo_fp: dg.codigoFP || '',
    bachillerato: dg.nombreBachillerato || '',
    codigo_tit: dg.codigoTitulo || '',
    modulo_formativo: dg.moduloFormativo || '',
    codigo_mf: dg.codigoModulo || '',
    nombre_docente: dg.nombreDocente || '',
    unidad_competencia: dg.unidadCompetencia || dg.competenciaAsociada || '',
    codigo_uc: dg.codigoUC || dg.codigoCompetencia || '',
    cantidad_ra: String(dg.cantidadRA || ''),
    valor_ra: String(dg.valorRA || ''),
    horas_semana: String(dg.horasSemana || ''),
    fecha_inicio: dg.fechaInicio || '',
    fecha_termino: dg.fechaTermino || '',
    resultado_aprendizaje: ra.descripcion || '',
    nivel_dominio: ra.nivelBloom || planificacion.nivelBloomRA || '',
    contenidos_conceptuales: ra.contenidosConceptuales || '',
    contenidos_procedimentales: ra.contenidosProcedimentales || '',
    contenidos_actitudinales: ra.contenidosActitudinales || '',
    criterios_evaluacion: ra.criterios || '',
    recursos_didacticos: ra.recursos || ra.recursosDid || '',
    centro_educativo: info.centroNombre || '',
    codigo_ra: ((ra.descripcion || '').match(/^([A-Za-z]{1,4}[\w.]+)/) || [])[1] || '',
    cantidad_actividades: String(acts.length || 0),
    cantidad_ec: String(ecs.length || 0),
    fecha_exportacion: ahora.toLocaleDateString('es-DO'),
    hora_exportacion: ahora.toLocaleTimeString('es-DO', { hour: '2-digit', minute: '2-digit' }),
    // Array para loop en tabla: {#actividades}...{/actividades}
    actividades: actividades,
    // Array para loop en tabla: {#matriz_ec}...{/matriz_ec} -- una fila por EC
    // con el contraste hacia los Criterios de Evaluación (ver _construirMatrizEcCriterios)
    matriz_ec: _construirMatrizEcCriterios(ecs, ra).map(fila => ({
      ec: fila.ecCodigo,
      ec_enunciado: fila.ecEnunciado,
      contraste: fila.contrasteTexto,
      criterios_evaluacion: fila.criteriosTexto
    }))
  };

  // EC actitudinal sin actividades propias (permea a todos los demás EC) --
  // placeholders para una fila aparte de la tabla de Actividades, FUERA del
  // loop {#actividades}, ya que esa fila necesita celdas fusionadas manualmente
  // en la plantilla (un docxtemplater no puede fusionar celdas condicionalmente
  // dentro de un mismo loop). Envolver esa fila en la plantilla con
  // {#permea_actitudinal}...{/permea_actitudinal} para que solo aparezca cuando
  // aplica (queda vacío/''  -> falsy -> docxtemplater oculta la sección).
  const ecsActitudinalesSinActs = ecs.filter(e => e.nivel === 'actitudinal' && !acts.some(a => a.ecCodigo === e.codigo && !a.esComplementario));
  data.permea_actitudinal = ecsActitudinalesSinActs.length
    ? 'Permea todos los EC y Actividades, no necesita Actividades asociadas directamente, ni Contenidos sugeridos.'
    : '';
  data.permea_ec_codigo = ecsActitudinalesSinActs.map(e => e.codigo).join(', ');
  data.permea_ec_enunciado = ecsActitudinalesSinActs.map(e => e.enunciado).join('\n');

  // Agregar placeholders de priorización RA1-RA10
  const prio = dg.priorizacion || [];
  for (let i = 0; i < 10; i++) {
    data['ra' + (i + 1) + '_tiempo'] = (prio[i] && prio[i].tiempo) || '';
    data['ra' + (i + 1) + '_valor'] = (prio[i] && prio[i].valor) || '';
  }
  // Totales de priorización
  let totalValPrio = 0, totalTiempoPrio = 0, allNum = true;
  prio.forEach(p => {
    totalValPrio += parseFloat(p.valor) || 0;
    const t = parseFloat(p.tiempo);
    if (p.tiempo && isNaN(t)) allNum = false;
    else totalTiempoPrio += t || 0;
  });
  data.prio_total_valor = totalValPrio ? String(totalValPrio) : '';
  data.prio_total_tiempo = allNum && totalTiempoPrio ? String(totalTiempoPrio) : '';

  // Placeholders dinámicos: acepta nuevos campos del sistema sin tocar código.
  // Ejemplos: {dg_nombreDirector}, {ra_criterios}, {dg_campo_nuevo}, etc.
  _agregarPlaceholdersDinamicos(data, dg, { prefix: 'dg' });
  _agregarPlaceholdersDinamicos(data, ra, { prefix: 'ra' });
  _agregarPlaceholdersDinamicos(data, planificacion, { prefix: 'plan' });

  // Procesar con docxtemplater
  const zip = new PizZip(arrayBuffer);
  const doc = new Docxtemplater(zip, {
    paragraphLoop: true,
    linebreaks: true,
    delimiters: { start: '{', end: '}' },
    nullGetter: () => ''
  });
  doc.render(data);

  // Post-procesar XML para fusionar celdas verticalmente (vMerge)
  try {
    const docXml = doc.getZip().file('word/document.xml');
    if (docXml) {
      let xml = docXml.asText();

      // __VSTART__ → primera celda del merge: agregar vMerge restart y quitar marcador
      xml = xml.replace(/<w:tc>([\s\S]*?)<\/w:tc>/g, function(match) {
        if (match.indexOf('__VSTART__') === -1 && match.indexOf('__VMERGE__') === -1) return match;

        if (match.indexOf('__VSTART__') !== -1) {
          // Primera celda del grupo: agregar vMerge restart
          let cell = match.replace(/__VSTART__/g, '');
          if (cell.indexOf('<w:tcPr>') !== -1) {
            cell = cell.replace('<w:tcPr>', '<w:tcPr><w:vMerge w:val="restart"/>');
          } else {
            cell = cell.replace('<w:tc>', '<w:tc><w:tcPr><w:vMerge w:val="restart"/></w:tcPr>');
          }
          return cell;
        }

        if (match.indexOf('__VMERGE__') !== -1) {
          // Celda de continuación: agregar vMerge (sin val) y vaciar contenido
          let cell = match;
          // Quitar todo el contenido de texto de la celda
          cell = cell.replace(/<w:r>[\s\S]*?<\/w:r>/g, '');
          cell = cell.replace(/__VMERGE__/g, '');
          if (cell.indexOf('<w:tcPr>') !== -1) {
            cell = cell.replace('<w:tcPr>', '<w:tcPr><w:vMerge/>');
          } else {
            cell = cell.replace('<w:tc>', '<w:tc><w:tcPr><w:vMerge/></w:tcPr>');
          }
          return cell;
        }

        return match;
      });

      doc.getZip().file('word/document.xml', xml);
    }
  } catch (e) {
    console.warn('[Plantilla] Error post-procesando vMerge:', e);
  }

  // Respaldo oculto: la planificación completa se guarda como JSON dentro del
  // propio .docx, en un archivo que Word ignora (no aparece al abrir el
  // documento, no depende de como cada centro personalizo su plantilla). Si el
  // docente borra esta planificación del sistema pero conserva el .docx
  // exportado, puede recuperarla completa e idéntica con
  // Biblioteca > Importar Planificación > Subir archivo Word.
  try {
    const backupPayload = {
      __tinclass_backup__: true,
      version: 1,
      exportadoEn: ahora.toISOString(),
      planificacion: planificacion
    };
    doc.getZip().file('customXml/tinclass_backup.json', JSON.stringify(backupPayload));
  } catch (e) {
    console.warn('[Plantilla] No se pudo incluir el respaldo oculto:', e);
  }

  const out = doc.getZip().generate({
    type: 'blob',
    mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  });

  // Descargar
  const nombre = _nombreArchivoRA('docx');
  const link = document.createElement('a');
  link.href = URL.createObjectURL(out);
  link.download = nombre;
  link.click();
  URL.revokeObjectURL(link.href);

  mostrarToast('Planificación exportada con plantilla del centro', 'success');
  return true;
}

/** Obtiene la plantilla diaria del centro del usuario actual */
async function _getPlantillaDiariaCentro() {
  if (!window.currentUser) return null;
  try {
    let centroId = null;
    const userDoc = await db.collection('perfiles').doc(window.currentUser.uid).get();
    if (userDoc.exists && userDoc.data().centroId) centroId = userDoc.data().centroId;
    if (!centroId) {
      const userDoc2 = await db.collection('usuarios').doc(window.currentUser.uid).get();
      if (userDoc2.exists && userDoc2.data().centroId) centroId = userDoc2.data().centroId;
    }
    if (centroId) {
      const centroDoc = await db.collection(CENTROS_COLLECTION).doc(centroId).get();
      if (centroDoc.exists) {
        const centro = centroDoc.data();
        const result = await _cargarPlantillaCentroChunked(centroId, 'diaria');
        if (result) return { base64: result.base64, centroId, centroNombre: centro.nombre || '' };
      }
    }
    // Superadmin fallback
    const snap = await db.collection(CENTROS_COLLECTION).where('tienePlantilla_diaria', '==', true).limit(1).get();
    if (!snap.empty) {
      const centro = snap.docs[0].data();
      const result = await _cargarPlantillaCentroChunked(snap.docs[0].id, 'diaria');
      if (result) return { base64: result.base64, centroId: snap.docs[0].id, centroNombre: centro.nombre || '' };
    }
    return null;
  } catch (e) {
    console.warn('[PlantillaDiaria] Error obteniendo centro:', e);
    return null;
  }
}

