/** Exporta un reporte individual de Psicología a Word usando la plantilla del centro */
async function exportarReportePsicologiaDocx(id, estId) {
  const DocxModule = window.docxtemplater || window.Docxtemplater;
  const Docxtemplater = DocxModule?.default || DocxModule;
  if (typeof PizZip === 'undefined' || !Docxtemplater) {
    mostrarToast('No se puede generar Word: faltan librerías de plantilla.', 'error');
    return false;
  }

  const rep = _obtenerReporteVistaPsicologia(estId, id);
  if (!rep) {
    mostrarToast('No se encontró el reporte.', 'error');
    return false;
  }

  const info = await _getPlantillaReportePsicologiaCentro();
  if (!info) {
    mostrarToast('No hay plantilla de reportes de Psicología cargada en el centro.', 'error');
    return false;
  }

  mostrarToast('Exportando reporte de Psicología...', 'info');

  const binaryStr = atob(info.base64);
  const bytes = new Uint8Array(binaryStr.length);
  for (let i = 0; i < binaryStr.length; i++) bytes[i] = binaryStr.charCodeAt(i);
  const zip = new PizZip(bytes.buffer);
  const doc = new Docxtemplater(zip, {
    paragraphLoop: true,
    linebreaks: true,
    delimiters: { start: '{', end: '}' },
    nullGetter: () => ''
  });

  const fecha = rep.fechaReporte || '';
  const fechaBonita = fecha
    ? new Date(fecha + 'T12:00:00').toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' })
    : '';

  doc.render({
    estudiante_nombre: rep.estudianteNombre || '',
    grado_cursa: rep.gradoCursa || rep.cursoNombre || '',
    fecha_reporte: fechaBonita || fecha,
    detalles_evento: rep.detallesEvento || '',
    medidas_docente: rep.medidasDocente || '',
    seguimiento_repetitiva: rep.seguimientoRepetitiva || '',
    firma_estudiante: rep.firmaEstudiante || '',
    celular_estudiante: rep.celularEstudiante || '',
    firma_docente: rep.firmaDocente || '',
    firma_coordinacion: rep.firmaCoordenacion || '',
    firma_psicologia: rep.firmaPsicologia || '',
    firma_tutor: rep.firmaTutor || '',
    telefono_tutor: rep.telefonoTutor || '',
    nombre_centro: info.centroNombre || '',
    nombre_docente: rep.nombreDocente || '',
    curso_nombre: rep.cursoNombre || rep.gradoCursa || ''
  });

  const out = doc.getZip().generate({
    type: 'blob',
    mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  });

  const link = document.createElement('a');
  const safeName = (rep.estudianteNombre || 'reporte').replace(/\s+/g, '_').replace(/[^\w\-]+/g, '_');
  link.href = URL.createObjectURL(out);
  link.download = 'Reporte_Psicologia_' + safeName + '.docx';
  link.click();
  URL.revokeObjectURL(link.href);
  mostrarToast('Reporte exportado en Word', 'success');
  return true;
}

function _obtenerReporteVistaPsicologia(estId, id) {
  for (const estudiante of (_psicoDatos || [])) {
    if (estId && estudiante.estId !== estId) continue;
    const rep = (estudiante.reportes || []).find(r => r.id === id);
    if (rep) return rep;
  }
  return null;
}

function _datosReportePsicologiaDocx(rep, info) {
  const fecha = rep.fechaReporte || '';
  const fechaBonita = fecha
    ? new Date(fecha + 'T12:00:00').toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' })
    : '';

  return {
    estudiante_nombre: rep.estudianteNombre || '',
    grado_cursa: rep.gradoCursa || rep.cursoNombre || '',
    fecha_reporte: fechaBonita || fecha,
    detalles_evento: rep.detallesEvento || '',
    medidas_docente: rep.medidasDocente || '',
    seguimiento_repetitiva: rep.seguimientoRepetitiva || '',
    firma_estudiante: rep.firmaEstudiante || '',
    celular_estudiante: rep.celularEstudiante || '',
    firma_docente: rep.firmaDocente || '',
    firma_coordinacion: rep.firmaCoordenacion || '',
    firma_psicologia: rep.firmaPsicologia || '',
    firma_tutor: rep.firmaTutor || '',
    telefono_tutor: rep.telefonoTutor || '',
    nombre_centro: info?.centroNombre || '',
    nombre_docente: rep.nombreDocente || '',
    curso_nombre: rep.cursoNombre || rep.gradoCursa || ''
  };
}

async function _generarBlobReportePsicologiaDocx(rep) {
  const DocxModule = window.docxtemplater || window.Docxtemplater;
  const Docxtemplater = DocxModule?.default || DocxModule;
  if (typeof PizZip === 'undefined' || !Docxtemplater) return null;

  const info = await _getPlantillaReportePsicologiaCentro();
  if (!info) return null;

  const binaryStr = atob(info.base64);
  const bytes = new Uint8Array(binaryStr.length);
  for (let i = 0; i < binaryStr.length; i++) bytes[i] = binaryStr.charCodeAt(i);
  const zip = new PizZip(bytes.buffer);
  const doc = new Docxtemplater(zip, {
    paragraphLoop: true,
    linebreaks: true,
    delimiters: { start: '{', end: '}' },
    nullGetter: () => ''
  });

  doc.render(_datosReportePsicologiaDocx(rep, info));
  const out = doc.getZip().generate({
    type: 'blob',
    mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  });
  const nombre = 'Reporte_Psicologia_' + (rep.estudianteNombre || 'reporte').replace(/\s+/g, '_').replace(/[^\w\-]+/g, '_') + '.docx';
  return { blob: out, nombre };
}

async function _blobToBase64(blob) {
  const buffer = await blob.arrayBuffer();
  let binary = '';
  const bytes = new Uint8Array(buffer);
  const chunkSize = 0x8000;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunkSize));
  }
  return btoa(binary);
}

/** Devuelve { blob, nombre } si se generó y guardó el docx, o null si no hay plantilla
 *  configurada en el centro (para que quien llama pueda reusar el mismo blob, ej. para
 *  adjuntarlo también a una evidencia de Portafolio, sin regenerarlo dos veces). */
async function _generarYGuardarDocxReportePsicologia(estId, rep) {
  try {
    const generado = await _generarBlobReportePsicologiaDocx(rep);
    if (!generado) return null;
    const base64 = await _blobToBase64(generado.blob);
    const data = cargarReportes();
    const lista = data[estId] || [];
    const idx = lista.findIndex(r => r.id === rep.id);
    if (idx !== -1) {
      lista[idx].reporteDocxBase64 = base64;
      lista[idx].reporteDocxNombre = generado.nombre;
      data[estId] = lista;
      guardarReportes(data);
      renderizarReportes(estId);
    }
    return generado;
  } catch (e) {
    console.warn('[PlantillaPsicologia] No se pudo generar/guardar el docx:', e);
    return null;
  }
}

/** Genera XML de tabla Word para un instrumento de evaluación */
function _generarInstTablaXml(inst) {
  if (!inst || !inst.criterios || !inst.criterios.length) return '<w:p><w:r><w:t>\u2014</w:t></w:r></w:p>';

  const esc = (t) => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

  // Estilos de celda
  const bdr = '<w:tcBorders><w:top w:val="single" w:sz="4" w:color="999999"/><w:bottom w:val="single" w:sz="4" w:color="999999"/><w:left w:val="single" w:sz="4" w:color="999999"/><w:right w:val="single" w:sz="4" w:color="999999"/></w:tcBorders>';
  const headerShd = '<w:shd w:val="clear" w:fill="D9E1F2"/>';
  const cellMarg = '<w:tcMar><w:top w:w="40" w:type="dxa"/><w:bottom w:w="40" w:type="dxa"/><w:left w:w="80" w:type="dxa"/><w:right w:w="80" w:type="dxa"/></w:tcMar>';
  const mkCell = (text, width, isHeader, center) => {
    const tcPr = '<w:tcPr>' + (width ? '<w:tcW w:w="' + width + '" w:type="dxa"/>' : '') + bdr + cellMarg + (isHeader ? headerShd : '') + '</w:tcPr>';
    const rPr = '<w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="18"/>' + (isHeader ? '<w:b/>' : '') + '</w:rPr>';
    const pPr = center ? '<w:pPr><w:jc w:val="center"/></w:pPr>' : '';
    return '<w:tc>' + tcPr + '<w:p>' + pPr + '<w:r>' + rPr + '<w:t xml:space="preserve">' + esc(text) + '</w:t></w:r></w:p></w:tc>';
  };
  const mkRow = (cells) => '<w:tr>' + cells + '</w:tr>';

  // Título
  let xml = '<w:p><w:pPr><w:spacing w:after="80"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="20"/><w:b/><w:color w:val="1F3864"/></w:rPr><w:t xml:space="preserve">' + esc(inst.tipoLabel || '') + '</w:t></w:r></w:p>';

  xml += '<w:tbl><w:tblPr><w:tblStyle w:val="TableGrid"/><w:tblW w:w="5000" w:type="pct"/><w:tblBorders><w:top w:val="single" w:sz="4" w:color="999999"/><w:bottom w:val="single" w:sz="4" w:color="999999"/><w:left w:val="single" w:sz="4" w:color="999999"/><w:right w:val="single" w:sz="4" w:color="999999"/><w:insideH w:val="single" w:sz="4" w:color="999999"/><w:insideV w:val="single" w:sz="4" w:color="999999"/></w:tblBorders><w:tblLook w:val="04A0"/></w:tblPr>';

  if (inst.tipo === 'cotejo') {
    xml += mkRow(mkCell('#', 500, true, true) + mkCell('Indicador / Criterio', null, true) + mkCell('Logrado', 1100, true, true) + mkCell('No Logrado', 1100, true, true));
    (inst.criterios || []).forEach((c, i) => {
      xml += mkRow(mkCell(String(i + 1), 500, false, true) + mkCell(c.indicador || c.criterio || c) + mkCell('', 1100, false, true) + mkCell('', 1100, false, true));
    });
  } else if (inst.tipo === 'rubrica') {
    const niveles = inst.niveles || [{ nombre: 'Excelente' }, { nombre: 'Bueno' }, { nombre: 'En proceso' }, { nombre: 'Insuficiente' }];
    xml += mkRow(mkCell('#', 400, true, true) + mkCell('Criterio', null, true) + niveles.map(n => mkCell(n.nombre, 1400, true, true)).join(''));
  }

  xml += '</w:tbl>';
  return xml;
}

/** Exporta planificaciones diarias usando la plantilla .docx del centro con docxtemplater */
async function _exportarDiariaConPlantillaCentro() {
  const DocxModule = window.docxtemplater || window.Docxtemplater;
  const Docxtemplater = DocxModule?.default || DocxModule;
  if (typeof PizZip === 'undefined' || !Docxtemplater) {
    console.warn('[PlantillaDiaria] PizZip o docxtemplater no disponible');
    return false;
  }

  const info = await _getPlantillaDiariaCentro();
  if (!info) return false;

  mostrarToast('Exportando con plantilla diaria del centro...', 'info');

  const binaryStr = atob(info.base64);
  const bytes = new Uint8Array(binaryStr.length);
  for (let i = 0; i < binaryStr.length; i++) bytes[i] = binaryStr.charCodeAt(i);
  const templateBuffer = bytes.buffer;

  const dg = planificacion.datosGenerales || {};
  const ra = planificacion.ra || {};
  const actividades = planificacion.actividades || [];

  if (!actividades.length) {
    mostrarToast('No hay sesiones para exportar', 'error');
    return true;
  }

  // Generar un documento por sesión y combinar en un solo archivo
  // Usamos docxtemplater para cada sesión con la misma plantilla
  const allBlobs = [];

  for (const act of actividades) {
    // Respaldo local: si el docente nunca generó/guardó esta sesión en el Paso 5,
    // usamos la generación local (sin IA) como relleno campo por campo para que la
    // exportación NUNCA salga en blanco.
    const ecAct = (planificacion.elementosCapacidad || []).find(e => e.codigo === act.ecCodigo);
    const horasActAct = ecAct ? (ecAct.horasAsignadas / Math.max(1, actividades.filter(a => a.ecCodigo === ecAct.codigo && !a.esComplementario).length)) : 1.5;
    const localAct = generarContenidoSesion(act, ecAct, horasActAct);
    const sRaw = estadoDiarias.sesiones[act.id] || {};
    const s = {
      inicio: {
        apertura: sRaw.inicio?.apertura || localAct.inicio.apertura,
        encuadre: sRaw.inicio?.encuadre || localAct.inicio.encuadre,
        organizacion: sRaw.inicio?.organizacion || localAct.inicio.organizacion
      },
      desarrollo: {
        procedimental: sRaw.desarrollo?.procedimental || '',
        conceptual: sRaw.desarrollo?.conceptual || localAct.desarrollo.conceptual,
        pasos: sRaw.desarrollo?.pasos || localAct.desarrollo.pasos
      },
      cierre: {
        sintesis: sRaw.cierre?.sintesis || localAct.cierre.sintesis,
        conexion: sRaw.cierre?.conexion || localAct.cierre.conexion,
        proximopaso: sRaw.cierre?.proximopaso || localAct.cierre.proximopaso
      },
      estrategias: sRaw.estrategias || localAct.estrategias,
      recursos: sRaw.recursos || localAct.recursos,
      recursoUrl: sRaw.recursoUrl || '',
      tiempos: sRaw.tiempos || localAct.tiempos,
      tipo: sRaw.tipo || localAct.tipo,
      estrategiaCorta: sRaw.estrategiaCorta || localAct.estrategiaCorta,
      intencionEducativa: sRaw.intencionEducativa || localAct.intencionEducativa,
      diversidad: {
        apoyos: sRaw.diversidad?.apoyos || localAct.diversidad.apoyos,
        adaptaciones: sRaw.diversidad?.adaptaciones || localAct.diversidad.adaptaciones,
        estrategiasInclusivas: sRaw.diversidad?.estrategiasInclusivas || localAct.diversidad.estrategiasInclusivas,
        adaptacionesEspecificas: sRaw.diversidad?.adaptacionesEspecificas || localAct.diversidad.adaptacionesEspecificas
      },
      contenidos: {
        conceptual: sRaw.contenidos?.conceptual || localAct.contenidos.conceptual,
        procedimental: sRaw.contenidos?.procedimental || localAct.contenidos.procedimental,
        actitudinal: sRaw.contenidos?.actitudinal || localAct.contenidos.actitudinal
      }
    };
    const ti = (s.tiempos && s.tiempos.ini) || 20;
    const td = (s.tiempos && s.tiempos.des) || 55;
    const tc = (s.tiempos && s.tiempos.cie) || 15;
    const tot = ti + td + tc;

    const inicio = s.inicio || {};
    const desarrollo = s.desarrollo || {};
    const cierre = s.cierre || {};

    function instTextoTpl(inst) {
      if (!inst) return '\u2014';
      var txt = inst.tipoLabel || '';
      if (inst.tipo === 'cotejo') {
        (inst.criterios || []).forEach(function (c, i) {
          txt += '\n' + (i + 1) + '. ' + (c.indicador || c);
        });
      } else if (inst.tipo === 'rubrica') {
        (inst.criterios || []).forEach(function (c, i) {
          txt += '\n' + (i + 1) + '. ' + (c.criterio || c);
        });
      } else {
        (inst.criterios || []).forEach(function (c, i) {
          txt += '\n' + (i + 1) + '. ' + (c.criterio || c.indicador || c.texto || c);
        });
      }
      return txt;
    }

    const idxGlobal = actividades.indexOf(act);
    const numeroActividad = act.ecCodigo ? _getActNumero(act.ecCodigo, _actIndexInEC(actividades, idxGlobal)) : '';

    const pasosTxt = desarrollo.pasos || desarrollo.procedimental || '';
    const momentosPedagogicos = [
      `INICIO (${ti} min)`,
      [
        inicio.apertura ? `Apertura: ${inicio.apertura}` : '',
        inicio.encuadre ? `Encuadre: ${inicio.encuadre}` : '',
        inicio.organizacion ? `Organización: ${inicio.organizacion}` : ''
      ].filter(Boolean).join('\n'),
      '',
      `DESARROLLO (${td} min)`,
      [
        pasosTxt,
        desarrollo.conceptual ? `Conceptual/Actitudinal: ${desarrollo.conceptual}` : ''
      ].filter(Boolean).join('\n'),
      '',
      `CIERRE (${tc} min)`,
      [
        cierre.sintesis ? `Síntesis: ${cierre.sintesis}` : '',
        cierre.conexion ? `Conexión con el mundo real: ${cierre.conexion}` : '',
        cierre.proximopaso ? `Próximo paso: ${cierre.proximopaso}` : ''
      ].filter(Boolean).join('\n')
    ].join('\n');

    const div = s.diversidad || {};
    const atencionDiversidad = [
      div.apoyos ? `Apoyos posibles: ${div.apoyos}` : '',
      div.adaptaciones ? `Adaptaciones: ${div.adaptaciones}` : '',
      div.estrategiasInclusivas ? `Estrategias inclusivas: ${div.estrategiasInclusivas}` : '',
      div.adaptacionesEspecificas ? `Adaptaciones específicas: ${div.adaptacionesEspecificas}` : ''
    ].filter(Boolean).join('\n');

    const data = {
      modulo_formativo: dg.moduloFormativo || '',
      nombre_docente: dg.nombreDocente || '',
      centro_educativo: info.centroNombre || '',
      resultado_aprendizaje: ra.descripcion || '',
      familia_profesional: dg.familiaProfesional || '',
      bachillerato: dg.nombreBachillerato || '',
      codigo_mf: dg.codigoModulo || '',
      horas_semana: String(dg.horasSemana || ''),
      fecha: act.fechaStr || (act.fecha ? String(act.fecha).split('T')[0] : '') || '',
      actividad: act.enunciado || '',
      tiempo_total: String(tot),
      tiempo_inicio: String(ti),
      tiempo_desarrollo: String(td),
      tiempo_cierre: String(tc),
      apertura: inicio.apertura || '',
      encuadre: inicio.encuadre || '',
      organizacion: inicio.organizacion || '',
      procedimental: desarrollo.procedimental || '',
      conceptual: desarrollo.conceptual || '',
      sintesis: cierre.sintesis || '',
      conexion: cierre.conexion || '',
      proximopaso: cierre.proximopaso || '',
      estrategias: s.estrategias || '',
      recursos: s.recursos || '',
      instrumento_evaluacion: 'XREPL',
      instrumento_tipo: '',
      instrumento_criterios: [],
      // Alias para los placeholders ya colocados en la plantilla del usuario
      institucion: dg.nombreInstitucion || info.centroNombre || '',
      bachillerato_tecnico: dg.nombreBachillerato || '',
      // Campos nuevos de la matriz de planificación diaria ampliada
      actividad_numero: numeroActividad,
      valor: String(act.valor != null ? act.valor : ''),
      tipo: s.tipo || '',
      estrategia_corta: s.estrategiaCorta || '',
      pasos: pasosTxt,
      intencion_educativa: s.intencionEducativa || '',
      apoyos_posibles: div.apoyos || '',
      adaptaciones: div.adaptaciones || '',
      estrategias_inclusivas: div.estrategiasInclusivas || '',
      adaptaciones_especificas: div.adaptacionesEspecificas || '',
      contenido_conceptual: (s.contenidos && s.contenidos.conceptual) || '',
      contenido_procedimental: (s.contenidos && s.contenidos.procedimental) || '',
      contenido_actitudinal: (s.contenidos && s.contenidos.actitudinal) || '',
      // Campos combinados para plantillas con una sola celda por bloque
      momentos_pedagogicos: momentosPedagogicos,
      atencion_diversidad: atencionDiversidad
    };

    const zip = new PizZip(templateBuffer.slice(0));
    const doc = new Docxtemplater(zip, {
      paragraphLoop: true,
      linebreaks: true,
      delimiters: { start: '{', end: '}' },
      nullGetter: () => ''
    });
    doc.render(data);

    // Post-procesar: insertar tabla real del instrumento
    try {
      const dxf = doc.getZip().file('word/document.xml');
      if (dxf) {
        let xml = dxf.asText();
        // Buscar 'XREPL' teniendo en cuenta que puede estar dividido en múltiples <w:t>
        // Concatenar todos los <w:t> dentro de cada <w:tc> para buscar
        const instXml = _generarInstTablaXml(act.instrumento);
        // Buscar cada <w:tc>...</w:tc> y ver si contiene 'XREPL' en su texto
        xml = xml.replace(/<w:tc\b[^>]*>[\s\S]*?<\/w:tc>/g, function(tcMatch) {
          // Extraer todo el texto de esta celda
          const textos = [];
          tcMatch.replace(/<w:t[^>]*>([\s\S]*?)<\/w:t>/g, function(_, t) { textos.push(t); });
          const textoCompleto = textos.join('');
          if (textoCompleto.indexOf('XREPL') === -1) return tcMatch;
          // Esta celda contiene el marcador: reemplazar contenido con la tabla
          const tcPrMatch = tcMatch.match(/<w:tcPr>[\s\S]*?<\/w:tcPr>/);
          const tcPr = tcPrMatch ? tcPrMatch[0] : '';
          return '<w:tc>' + tcPr + instXml + '<w:p/></w:tc>';
        });
        doc.getZip().file('word/document.xml', xml);
      }
    } catch (e) {
      console.warn('[PlantillaDiaria] Error insertando tabla instrumento:', e);
    }

    allBlobs.push(doc.getZip().generate({ type: 'uint8array' }));
  }

  // Si solo una sesión, descargar directamente
  // Si múltiples, usamos el primero y le agregamos secciones (docxtemplater no soporta merge nativo)
  // Descargamos el primero como archivo principal
  if (allBlobs.length === 1) {
    const blob = new Blob([allBlobs[0]], { type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
    const nombre = 'PlanificacionDiaria_' + (dg.moduloFormativo || 'modulo').replace(/\s+/g, '_') + '.docx';
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = nombre;
    link.click();
    URL.revokeObjectURL(link.href);
  } else {
    // Descargar cada sesión como archivo separado en un ZIP si JSZip available, otherwise download first
    if (typeof JSZip !== 'undefined') {
      const jszip = new JSZip();
      actividades.forEach((act, i) => {
        const fname = 'Sesion_' + (i + 1) + '_' + (act.fechaStr || '').replace(/\//g, '-') + '.docx';
        jszip.file(fname, allBlobs[i]);
      });
      const zipBlob = await jszip.generateAsync({ type: 'blob' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(zipBlob);
      link.download = 'PlanificacionesDiarias_' + (dg.moduloFormativo || 'modulo').replace(/\s+/g, '_') + '.zip';
      link.click();
      URL.revokeObjectURL(link.href);
    } else {
      // Sin JSZip: descargar cada uno individualmente
      for (let i = 0; i < allBlobs.length; i++) {
        const blob = new Blob([allBlobs[i]], { type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
        const fname = 'PlanificacionDiaria_' + (i + 1) + '_' + (actividades[i].fechaStr || '').replace(/\//g, '-') + '.docx';
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = fname;
        link.click();
        URL.revokeObjectURL(link.href);
      }
    }
  }

  mostrarToast('Planificaciones diarias exportadas con plantilla del centro', 'success');
  return true;
}

/** Exporta a Word como .doc (HTML compatible con Word) */



async function exportarWord() {
  // Auto-guardar en biblioteca antes de exportar
  const dgEx = planificacion.datosGenerales || {};
  const raEx = planificacion.ra || {};
  if (dgEx.moduloFormativo || raEx.descripcion) {
    guardarPlanificacionActual(true); // silencioso: sin modal de curso
  }

  // Intentar exportar con plantilla del centro si existe
  try {
    console.log('[Exportar] Intentando con plantilla del centro...');
    const exported = await _exportarConPlantillaCentro();
    if (exported) return; // plantilla usada exitosamente
    console.log('[Exportar] Sin plantilla, usando método HTML-Word');
    _avisarExportSinPlantilla();
  } catch (e) {
    console.warn('[Plantilla] No se pudo usar plantilla del centro:', e.message, e);
  }

  // Fallback: exportar como HTML-Word
  const contenido = document.getElementById('vista-previa').innerHTML;



  const dg = planificacion.datosGenerales;



  const nombreArchivo = _nombreArchivoRA('doc');







  const html = `



    <html xmlns:o='urn:schemas-microsoft-com:office:office'



          xmlns:w='urn:schemas-microsoft-com:office:word'



          xmlns='http://www.w3.org/TR/REC-html40'>



    <head>



      <meta charset="utf-8"/>



      <title>Planificación por RA</title>



      <!--[if gte mso 9]><xml><w:WordDocument><w:View>Print</w:View></w:WordDocument></xml><![endif]-->



      <style>



        body { font-family: Calibri, Arial, sans-serif; font-size: 11pt; margin: 2cm; }



        table { width: 100%; border-collapse: collapse; margin: 12pt 0; }



        th, td { border: 1pt solid #ccc; padding: 6pt 8pt; font-size: 10pt; }



        th { background: #1565C0; color: white; font-weight: bold; }



        h2 { color: #0D47A1; font-size: 14pt; }



        .vp-section-title { color: #0D47A1; font-weight: bold; font-size: 12pt; border-left: 4pt solid #1565C0; padding-left: 8pt; margin: 16pt 0 8pt; }



        .vp-ra-box { background: #E3F2FD; padding: 8pt; font-style: italic; color: #0D47A1; }



        .vp-logo-icon { display: none; }



        .material-icons { display: none; }



        code { font-family: Courier New; font-weight: bold; color: #1565C0; }



      </style>



    </head>



    <body>${contenido}</body></html>`;







  const blob = new Blob(['\ufeff', html], { type: 'application/msword' });



  const url = URL.createObjectURL(blob);



  const a = document.createElement('a');



  a.href = url;



  a.download = nombreArchivo;



  document.body.appendChild(a);



  a.click();



  document.body.removeChild(a);



  URL.revokeObjectURL(url);



  mostrarToast('Archivo Word descargado correctamente', 'success');



}







