// --- SECCIÓN: ORQUESTADOR PRINCIPAL ?" GENERAR PLANIFICACIÓN ---



// ================================================================







/**



 * Función principal: recolecta datos, genera EC, actividades e instrumentos



 */



let _generandoPlanificacion = false;
function generarPlanificacion() {
  if (_generandoPlanificacion) { mostrarToast('Ya hay una generación en curso, espera...', 'warning'); return; }
  _generandoPlanificacion = true;

  // Validar paso 2



  const raTexto = document.getElementById('descripcion-ra').value.trim();



  if (raTexto.length < 20) {



    document.getElementById('descripcion-ra').classList.add('error');
    mostrarToast('Escribe una descripción más completa del RA', 'error');
    _generandoPlanificacion = false;
    return;



  }







  // Animación de carga



  const btn = document.getElementById('btn-generar');



  const txt = document.getElementById('btn-generar-texto');



  const ico = btn.querySelector('.btn-generar-icon');



  btn.disabled = true;



  btn.classList.add('loading');



  ico.textContent = 'cached';



  txt.textContent = 'Generando...';







  // Guardar datos antes de procesar



  guardarDatosFormulario();







  setTimeout(() => {



    try {



      const dg = planificacion.datosGenerales;



      const ra = planificacion.ra;







      // 1. Detectar nivel Bloom del RA



      const nivelRA = analizarNivelBloom(ra.descripcion);



      planificacion.ra.nivelBloom = nivelRA;



      actualizarBloomBadge(ra.descripcion);







      // 2. Calcular fechas de clase reales



      planificacion.fechasClase = calcularFechasClase(



        dg.diasClase, dg.fechaInicio, dg.fechaTermino,
        typeof _calEscGetFestivosAdmin === 'function' ? _calEscGetFestivosAdmin() : []



      );







      // 3. Calcular horas totales y semanas



      planificacion.horasTotal = planificacion.fechasClase.reduce((s, f) => s + f.horas, 0);



      planificacion.semanas = calcularSemanas(dg.fechaInicio, dg.fechaTermino);

      // Mostrar nota de festivos excluidos
      _mostrarNotaFestivosExcluidos(dg.diasClase, dg.fechaInicio, dg.fechaTermino);






      // 4. Generar EC



      const _cantEC = parseInt(dg.cantidadEC) || 4;
      const _cantActPorEC = parseInt(dg.cantidadActPorEC) || 1;
      let ec = generarElementosCapacidad(ra.descripcion, ra.criterios, dg, _cantEC);







      planificacion.elementosCapacidad = ec;





      // 6. Generar actividades con fechas reales
      // Preservar IDs anteriores por posición y EC para no perder diarias guardadas
      const _actsAnteriores = planificacion.actividades || [];
      planificacion.actividades = generarActividades(ec, planificacion.fechasClase, _cantActPorEC);
      // Reasignar IDs previos según EC + posición para mantener vínculo con estadoDiarias
      const _idxPorEC = {};
      planificacion.actividades.forEach(a => {
        const k = a.ecCodigo || '';
        _idxPorEC[k] = (_idxPorEC[k] || 0);
        const pos = _idxPorEC[k]++;
        const anterior = _actsAnteriores.filter(x => x.ecCodigo === k)[pos];
        if (anterior && anterior.id) a.id = anterior.id;
      });

      // 5b. Distribuir horas por EC según actividades × horas por sesión
      const _diasAct = Object.values(dg.diasClase || {}).filter(d => d.activo);
      const _hPS = _diasAct.length > 0
        ? _diasAct.reduce((s, d) => s + d.horas, 0) / _diasAct.length
        : 2;
      ec.forEach(e => {
        const numActs = planificacion.actividades.filter(a => a.ecCodigo === e.codigo).length;
        e.horasAsignadas = Math.round(numActs * _hPS);
      });




      // 7. Renderizar UI



      renderizarEC(ec);



      renderizarActividades(planificacion.actividades);

      console.log('[PlanDebug] generarPlanificacion terminó -> EC=', planificacion.elementosCapacidad?.length, 'actividades=', planificacion.actividades?.length);







      // 8. Habilitar navegación



      document.getElementById('btn-paso2-siguiente').disabled = false;







      // 9. Guardar borrador



      guardarBorrador();







      registrarCambio(`Planificación generada: "${planificacion.dg?.moduloFormativo || 'Sin módulo'}" — ${planificacion.elementosCapacidad?.length || 0} EC(s), ${planificacion.actividades?.length || 0} actividades`);
      mostrarToast('¡Planificación generada exitosamente!', 'success');







    } catch (e) {



      console.error('Error generando planificación:', e);



      mostrarToast('Ocurrió un error al generar. Revisa los datos ingresados.', 'error');



    } finally {



      btn.disabled = false;



      btn.classList.remove('loading');



      ico.textContent = 'auto_awesome';



      txt.textContent = 'Generar Planificación';

      _generandoPlanificacion = false;

    }



  }, 900); // pequeño delay para mostrar animación



}







