// MÓDULO: SELECTOR ALEATORIO DE ALUMNO
// ════════════════════════════════════════════════════════════════════
function elegirAlumnoAleatorio() {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso || !curso.estudiantes || curso.estudiantes.length === 0) {
    mostrarToast('No hay estudiantes en este curso', 'error'); return;
  }
  const lista = curso.estudiantes;
  if (lista.length === 1) { _mostrarGanador(lista[0]); return; }
  const btn = document.querySelector('[onclick="elegirAlumnoAleatorio()"]');
  if (btn) btn.disabled = true;
  let i = 0;
  const timer = setInterval(() => {
    i = (i + 1) % lista.length;
    mostrarToast('🎲 ' + lista[i].nombre, 'info', 250);
  }, 130);
  setTimeout(() => {
    clearInterval(timer);
    if (btn) btn.disabled = false;
    const elegido = lista[Math.floor(Math.random() * lista.length)];
    _mostrarGanador(elegido);
  }, 1100);
}
function _mostrarGanador(est) {
  document.getElementById('modal-title').textContent = '🎲 Estudiante seleccionado';
  document.getElementById('modal-body').innerHTML =
    '<div style="text-align:center;padding:2.5rem 1rem;">'
    + '<div style="font-size:2.2rem;font-weight:800;color:#1565C0;margin-bottom:0.5rem;">' + escapeHTML(est.nombre) + '</div>'
    + '<div style="color:#78909C;font-size:0.9rem;">Seleccionado aleatoriamente 🎉</div>'
    + '</div>';
  document.getElementById('modal-footer').innerHTML =
    '<button class="btn-secundario" onclick="cerrarModalBtn()">Cerrar</button>';
  document.getElementById('modal-overlay').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: BOLETÍN INDIVIDUAL DE NOTAS
// ════════════════════════════════════════════════════════════════════
function abrirBoletin(estId) {
  const cursoId = calState.cursoActivoId;
  const curso = cursoId ? calState.cursos[cursoId] : null;
  if (!curso) { mostrarToast('Sin curso activo', 'error'); return; }
  const est = (curso.estudiantes || []).find(e => e.id === estId);
  if (!est) return;

  const planActiva = _getPlanActivaDeCurso();
  const actividades = (planActiva && planActiva.actividades) || [];
  const dg = planActiva ? (planActiva.datosGenerales || {}) : {};
  const ra = planActiva ? (planActiva.ra || {}) : {};
  const raKey = _getRaKey();
  const raInfo = _ensureRA(curso, raKey);
  const comentarios = _getComentariosEst(estId);
  const incidencias = _getIncidenciasEst(estId);
  const asist = _statsAsistencia(cursoId, estId);
  const notaFinal = _calcNotaFinal(curso, estId);
  const notaRA = _calcNotaRA(curso, estId, raKey);

  const hoy = new Date().toLocaleDateString('es-CL', { day:'2-digit', month:'long', year:'numeric' });
  const esc = s => (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const modulo = esc(dg.moduloFormativo || 'Módulo');
  const periodo = (dg.fechaInicio || '') + (dg.fechaTermino ? ' — ' + dg.fechaTermino : '');
  const instit = esc(dg.institucion || dg.establecimiento || '');
  const raDesc = esc((ra.descripcion || '').substring(0, 120));

  let filasActs = '';
  actividades.forEach((a, idx) => {
    const nota = curso.notas?.[estId]?.[raKey]?.[a.id];
    const max = raInfo.valores[a.id] || 10;
    const pct = (nota !== undefined && nota !== null) ? Math.round((nota / max) * 100) : null;
    const color = pct === null ? '#9E9E9E' : pct >= 70 ? '#2E7D32' : pct >= 50 ? '#E65100' : '#C62828';
    const barra = pct !== null
      ? '<div style="height:8px;background:#eee;border-radius:4px;margin-top:4px;"><div style="height:8px;background:' + color + ';border-radius:4px;width:' + Math.min(100,pct) + '%;"></div></div>'
      : '';
    const enun = esc((a.enunciado||'').substring(0,55)) + (a.enunciado && a.enunciado.length>55 ? '…' : '');
    const ecCorto = esc((a.ecCodigo||'').replace('E.C.','').replace('CE',''));
    filasActs += '<tr>'
      + '<td style="padding:6px 8px;border-bottom:1px solid #eee;font-size:0.82rem;">Act.' + (idx+1)
      + ' <span style="color:#78909C;font-size:0.75rem;">' + ecCorto + '</span>'
      + '<br><span style="font-size:0.72rem;color:#546E7A;">' + enun + '</span></td>'
      + '<td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:center;font-weight:700;color:' + color + ';">'
      + (nota !== undefined && nota !== null ? nota : '—') + '</td>'
      + '<td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:center;color:#546E7A;">' + max + '</td>'
      + '<td style="padding:6px 8px;border-bottom:1px solid #eee;min-width:100px;">' + barra + '</td>'
      + '</tr>';
  });
  if (!filasActs) filasActs = '<tr><td colspan="4" style="text-align:center;padding:1rem;color:#9E9E9E;">Sin actividades registradas</td></tr>';

  let secComent = '';
  if (comentarios.length) {
    secComent = '<div style="margin-top:1.5rem;"><h3 style="font-size:0.95rem;font-weight:700;color:#37474F;border-bottom:2px solid #E3F2FD;padding-bottom:4px;margin-bottom:0.75rem;">Observaciones del docente</h3>';
    comentarios.slice(0,8).forEach(c => {
      const cat = COMENT_CATEGORIAS.find(x => x.id === c.categoria) || COMENT_CATEGORIAS[COMENT_CATEGORIAS.length-1];
      const fecha = new Date(c.ts).toLocaleDateString('es-CL',{day:'2-digit',month:'short',year:'numeric'});
      secComent += '<div style="margin-bottom:0.6rem;padding:8px 10px;background:#F5F5F5;border-radius:6px;border-left:3px solid ' + cat.color + ';">'
        + '<span style="font-size:0.72rem;font-weight:600;color:' + cat.color + ';">' + esc(cat.label) + '</span>'
        + '<span style="font-size:0.72rem;color:#9E9E9E;margin-left:8px;">' + fecha + '</span>'
        + '<div style="font-size:0.83rem;color:#37474F;margin-top:4px;">' + esc(c.texto) + '</div>'
        + '</div>';
    });
    secComent += '</div>';
  }

  let secIncid = '';
  if (incidencias.length) {
    secIncid = '<div style="margin-top:1.5rem;"><h3 style="font-size:0.95rem;font-weight:700;color:#37474F;border-bottom:2px solid #E8F5E9;padding-bottom:4px;margin-bottom:0.75rem;">Registro de eventos</h3>';
    incidencias.slice(0,6).forEach(inc => {
      const tipo = INCID_TIPOS.find(t => t.id === inc.tipo) || INCID_TIPOS[INCID_TIPOS.length-1];
      secIncid += '<div style="margin-bottom:0.6rem;padding:8px 10px;background:#F5F5F5;border-radius:6px;border-left:3px solid ' + tipo.color + ';">'
        + '<span style="font-size:0.72rem;font-weight:600;color:' + tipo.color + ';">' + esc(tipo.label) + '</span>'
        + (inc.fechaEvento ? '<span style="font-size:0.72rem;color:#9E9E9E;margin-left:8px;">' + inc.fechaEvento + '</span>' : '')
        + (inc.participantes ? '<div style="font-size:0.75rem;color:#546E7A;margin-top:2px;"><b>Participantes:</b> ' + esc(inc.participantes) + '</div>' : '')
        + (inc.descripcion ? '<div style="font-size:0.83rem;color:#37474F;margin-top:4px;">' + esc(inc.descripcion) + '</div>' : '')
        + (inc.acuerdos ? '<div style="font-size:0.78rem;color:#1565C0;margin-top:4px;"><b>Acuerdos:</b> ' + esc(inc.acuerdos) + '</div>' : '')
        + '</div>';
    });
    secIncid += '</div>';
  }

  const notaFinalColor = notaFinal === null ? '#9E9E9E' : notaFinal >= 7 ? '#2E7D32' : notaFinal >= 5 ? '#E65100' : '#C62828';
  const asistColor = asist.pct === null ? '#9E9E9E' : asist.pct >= 80 ? '#2E7D32' : asist.pct >= 60 ? '#E65100' : '#C62828';
  const raColor = notaRA === null ? '#9E9E9E' : notaRA >= raInfo.valorTotal * 0.7 ? '#2E7D32' : '#E65100';

  const css = `*{box-sizing:border-box;margin:0;padding:0;}body{font-family:Arial,sans-serif;font-size:14px;color:#212121;background:#fff;}
    .page{max-width:720px;margin:0 auto;padding:2rem;}
    header{background:#1565C0;color:#fff;padding:1.2rem 1.5rem;border-radius:8px 8px 0 0;}
    h1{font-size:1.1rem;font-weight:700;}h2{font-size:0.88rem;font-weight:400;opacity:0.85;margin-top:4px;}
    .alumno-card{background:#E3F2FD;padding:1rem 1.5rem;display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:1.5rem;}
    .alumno-nombre{font-size:1.4rem;font-weight:800;color:#0D47A1;}.alumno-info{font-size:0.82rem;color:#546E7A;margin-top:4px;}
    table{width:100%;border-collapse:collapse;margin-bottom:1.5rem;}
    th{background:#1565C0;color:#fff;padding:8px;text-align:left;font-size:0.82rem;}
    .resumen{display:flex;gap:1rem;margin-bottom:1.5rem;flex-wrap:wrap;}
    .resumen-card{flex:1;min-width:120px;background:#F5F5F5;border-radius:8px;padding:0.8rem;text-align:center;}
    .resumen-val{font-size:1.6rem;font-weight:800;}.resumen-label{font-size:0.72rem;color:#78909C;margin-top:2px;}
    hr{border:none;border-top:1px solid #eee;margin:1.5rem 0;}
    .btn-print{display:block;margin:1.5rem auto 0;padding:10px 2rem;background:#1565C0;color:#fff;border:none;border-radius:8px;font-size:1rem;cursor:pointer;font-weight:600;}
    @media print{.btn-print{display:none;}.page{padding:0;}}`;

  const html = '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">'
    + '<title>Boletín ' + esc(est.nombre) + '</title><style>' + css + '</style></head><body><div class="page">'
    + '<header><h1>📋 Boletín de Calificaciones</h1><h2>' + modulo + (instit ? ' · ' + instit : '') + '</h2></header>'
    + '<div class="alumno-card"><div>'
    + '<div class="alumno-nombre">' + esc(est.nombre) + '</div>'
    + '<div class="alumno-info">Curso: ' + esc(curso.nombre) + (periodo ? ' &nbsp;|&nbsp; Período: ' + esc(periodo) : '') + '</div>'
    + (raDesc ? '<div class="alumno-info" style="margin-top:4px;">RA: ' + raDesc + '</div>' : '')
    + '</div><div style="text-align:right;font-size:0.78rem;color:#546E7A;">Emitido:<br>' + hoy + '</div></div>'
    + '<table><thead><tr>'
    + '<th style="width:45%;">Actividad</th><th style="width:12%;text-align:center;">Nota</th>'
    + '<th style="width:12%;text-align:center;">Máx.</th><th>Progreso</th>'
    + '</tr></thead><tbody>' + filasActs + '</tbody></table>'
    + '<div class="resumen">'
    + '<div class="resumen-card"><div class="resumen-val" style="color:' + raColor + ';">' + (notaRA !== null ? notaRA.toFixed(1) : '—') + '</div><div class="resumen-label">Total RA / ' + raInfo.valorTotal + ' pts</div></div>'
    + (localStorage.getItem('cfg_asistencia_activa') !== 'false' ? '<div class="resumen-card"><div class="resumen-val" style="color:' + asistColor + ';">' + (asist.pct !== null ? asist.pct + '%' : '—') + '</div><div class="resumen-label">Asistencia</div></div>' : '')
    + '<div class="resumen-card" style="background:#E8F5E9;"><div class="resumen-val" style="color:' + notaFinalColor + ';">' + (notaFinal !== null ? notaFinal.toFixed(1) : '—') + '</div><div class="resumen-label">NOTA FINAL</div></div>'
    + '</div>'
    + secComent + secIncid
    + '<hr><button class="btn-print" onclick="window.print()">🖨️ Imprimir / Guardar PDF</button>'
    + '</div></body></html>';

  const w = window.open('', '_blank');
  if (!w) { mostrarToast('Permite ventanas emergentes para ver el boletín', 'error'); return; }
  w.document.write(html);
  w.document.close();
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: BOLETÍN CONSOLIDADO (todas las materias de un estudiante)
// ════════════════════════════════════════════════════════════════════
/** A diferencia de abrirBoletin (una sola materia), este junta al mismo estudiante
 *  en TODOS los cursos del docente. No hay un ID de estudiante compartido entre
 *  cursos -- cada curso genera el suyo con uid() -- así que el emparejamiento es
 *  por nombre normalizado, igual que hace el Buscador de Estudiantes. */
function abrirBoletinConsolidado(estId) {
  const cursoBase = calState.cursos[calState.cursoActivoId];
  if (!cursoBase) { mostrarToast('Sin curso activo', 'error'); return; }
  const estBase = (cursoBase.estudiantes || []).find(e => e.id === estId);
  if (!estBase) return;

  const _norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
  const nombreNorm = _norm(estBase.nombre);
  const esc = s => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

  // Una fila por MATERIA (módulo formativo), no por curso ni por RA individual: un
  // mismo curso acumula un RA nuevo cada vez que se le asigna una planificación
  // distinta, y esos RA pueden pertenecer a módulos/materias distintos si el docente
  // reutilizó un mismo curso para más de una materia (ej. "Formación y Orientación
  // Laboral" y "Desarrollo de Aplicaciones..." dentro del mismo curso "5to B"). Cada
  // RA guarda su módulo de origen en curso.ras[raKey].modulo (ver _ensureRA), así que
  // se agrupan por ahí para sumar los RA de una misma materia entre sí, sin mezclarlos
  // con los de otra materia distinta que comparta el curso.
  const materias = [];
  // Una entrada por curso encontrado (no por RA/materia), para no repetir comentarios
  // ni eventos si el curso tiene varias materias o varios RA.
  const cursosMatch = [];
  Object.values(calState.cursos).forEach(curso => {
    (curso.estudiantes || []).forEach(est => {
      if (_norm(est.nombre) !== nombreNorm) return;
      const nombreCurso = curso.nombre || 'Curso sin nombre';
      cursosMatch.push({
        cursoNombre: nombreCurso,
        comentarios: _getComentariosEst(est.id),
        incidencias: _getIncidenciasEst(est.id)
      });

      const asist = _statsAsistencia(curso.id, est.id);
      const rasKeys = Object.keys(curso.ras || {});
      if (!rasKeys.length) {
        materias.push({ label: nombreCurso, notaFinal: null, totalPosible: 0, pct: null, asist });
        return;
      }

      const porModulo = {};
      rasKeys.forEach(rk => {
        const raInfo = curso.ras[rk] || {};
        const moduloKey = raInfo.modulo || '__sin_modulo__';
        if (!porModulo[moduloKey]) porModulo[moduloKey] = { modulo: raInfo.modulo || '', raKeys: [] };
        porModulo[moduloKey].raKeys.push(rk);
      });
      const hayVariasMaterias = Object.keys(porModulo).length > 1;

      Object.values(porModulo).forEach(grupo => {
        let notaSuma = 0, totalSuma = 0, hayNota = false;
        const detalleRA = [];
        grupo.raKeys.forEach(rk => {
          const raInfo = curso.ras[rk] || {};
          const notaRA = _calcNotaRA(curso, est.id, rk);
          const totalRA = raInfo.valorTotal || 0;
          totalSuma += totalRA;
          if (notaRA !== null) { notaSuma += notaRA; hayNota = true; }
          detalleRA.push({
            label: String(raInfo.label || rk || ''),
            notaFinal: notaRA,
            totalPosible: totalRA,
            pct: (notaRA !== null && totalRA > 0) ? Math.round((notaRA / totalRA) * 100) : null
          });
        });
        const notaFinal = hayNota ? Math.round(notaSuma * 10) / 10 : null;
        const pct = (notaFinal !== null && totalSuma > 0) ? Math.round((notaFinal / totalSuma) * 100) : null;
        const label = hayVariasMaterias
          ? nombreCurso + ' — ' + (grupo.modulo || 'Sin módulo especificado')
          : nombreCurso;
        materias.push({ label, notaFinal, totalPosible: totalSuma, pct, asist, detalleRA });
      });
    });
  });
  materias.sort((a, b) => a.label.localeCompare(b.label, 'es'));
  const nCursos = cursosMatch.length;

  const pctsConNota = materias.map(m => m.pct).filter(p => p !== null);
  const promedioGeneral = pctsConNota.length ? Math.round(pctsConNota.reduce((s, p) => s + p, 0) / pctsConNota.length) : null;
  const aprobadas = materias.filter(m => m.pct !== null && m.pct >= 70).length;
  const reprobadas = materias.filter(m => m.pct !== null && m.pct < 70).length;
  const asistPcts = materias.map(m => m.asist.pct).filter(p => p !== null);
  const asistPromedio = asistPcts.length ? Math.round(asistPcts.reduce((s, p) => s + p, 0) / asistPcts.length) : null;

  const hoy = new Date().toLocaleDateString('es-CL', { day: '2-digit', month: 'long', year: 'numeric' });

  let filasMaterias = materias.map(m => {
    const color = m.pct === null ? '#9E9E9E' : m.pct >= 70 ? '#2E7D32' : m.pct >= 50 ? '#E65100' : '#C62828';
    const asistColor = m.asist.pct === null ? '#9E9E9E' : m.asist.pct >= 80 ? '#2E7D32' : m.asist.pct >= 60 ? '#E65100' : '#C62828';
    const filaPrincipal = '<tr>'
      + '<td style="padding:8px;border-bottom:1px solid #eee;font-size:0.85rem;font-weight:700;">' + esc(m.label) + '</td>'
      + '<td style="padding:8px;border-bottom:1px solid #eee;text-align:center;font-weight:700;">' + (m.notaFinal !== null ? m.notaFinal.toFixed(1) : '—') + (m.totalPosible ? ' / ' + m.totalPosible : '') + '</td>'
      + '<td style="padding:8px;border-bottom:1px solid #eee;text-align:center;font-weight:700;color:' + color + ';">' + (m.pct !== null ? m.pct + '%' : '—') + '</td>'
      + '<td style="padding:8px;border-bottom:1px solid #eee;text-align:center;color:' + asistColor + ';">' + (m.asist.pct !== null ? m.asist.pct + '%' : '—') + '</td>'
      + '</tr>';

    // Desglose por RA: solo tiene sentido mostrarlo si la materia junta más de un RA
    // (si es uno solo, la fila principal ya es ese RA, repetirlo sería redundante).
    let filasDetalle = '';
    if (m.detalleRA && m.detalleRA.length > 1) {
      filasDetalle = m.detalleRA.map(d => {
        const dColor = d.pct === null ? '#9E9E9E' : d.pct >= 70 ? '#2E7D32' : d.pct >= 50 ? '#E65100' : '#C62828';
        const dLabel = d.label.length > 70 ? d.label.slice(0, 70) + '…' : d.label;
        return '<tr style="background:#FAFAFA;">'
          + '<td style="padding:5px 8px 5px 26px;border-bottom:1px solid #eee;font-size:0.76rem;color:#607D8B;">↳ ' + esc(dLabel) + '</td>'
          + '<td style="padding:5px 8px;border-bottom:1px solid #eee;text-align:center;font-size:0.78rem;color:#546E7A;">' + (d.notaFinal !== null ? d.notaFinal.toFixed(1) : '—') + (d.totalPosible ? ' / ' + d.totalPosible : '') + '</td>'
          + '<td style="padding:5px 8px;border-bottom:1px solid #eee;text-align:center;font-size:0.78rem;font-weight:600;color:' + dColor + ';">' + (d.pct !== null ? d.pct + '%' : '—') + '</td>'
          + '<td style="padding:5px 8px;border-bottom:1px solid #eee;"></td>'
          + '</tr>';
      }).join('');
    }

    return filaPrincipal + filasDetalle;
  }).join('');
  if (!filasMaterias) filasMaterias = '<tr><td colspan="4" style="text-align:center;padding:1rem;color:#9E9E9E;">No se encontraron materias para este estudiante</td></tr>';

  let secObs = '';
  cursosMatch.forEach(m => {
    if (!m.comentarios.length && !m.incidencias.length) return;
    secObs += '<div style="margin-top:1.2rem;"><h3 style="font-size:0.9rem;font-weight:700;color:#37474F;border-bottom:2px solid #E3F2FD;padding-bottom:4px;margin-bottom:0.6rem;">' + esc(m.cursoNombre) + '</h3>';
    m.comentarios.slice(0, 5).forEach(c => {
      const cat = COMENT_CATEGORIAS.find(x => x.id === c.categoria) || COMENT_CATEGORIAS[COMENT_CATEGORIAS.length - 1];
      const fecha = new Date(c.ts).toLocaleDateString('es-CL', { day: '2-digit', month: 'short', year: 'numeric' });
      secObs += '<div style="margin-bottom:0.5rem;padding:8px 10px;background:#F5F5F5;border-radius:6px;border-left:3px solid ' + cat.color + ';">'
        + '<span style="font-size:0.7rem;font-weight:600;color:' + cat.color + ';">' + esc(cat.label) + '</span>'
        + '<span style="font-size:0.7rem;color:#9E9E9E;margin-left:8px;">' + fecha + '</span>'
        + '<div style="font-size:0.82rem;color:#37474F;margin-top:4px;">' + esc(c.texto) + '</div>'
        + '</div>';
    });
    m.incidencias.slice(0, 4).forEach(inc => {
      const tipo = INCID_TIPOS.find(t => t.id === inc.tipo) || INCID_TIPOS[INCID_TIPOS.length - 1];
      secObs += '<div style="margin-bottom:0.5rem;padding:8px 10px;background:#F5F5F5;border-radius:6px;border-left:3px solid ' + tipo.color + ';">'
        + '<span style="font-size:0.7rem;font-weight:600;color:' + tipo.color + ';">' + esc(tipo.label) + '</span>'
        + (inc.fechaEvento ? '<span style="font-size:0.7rem;color:#9E9E9E;margin-left:8px;">' + inc.fechaEvento + '</span>' : '')
        + (inc.descripcion ? '<div style="font-size:0.82rem;color:#37474F;margin-top:4px;">' + esc(inc.descripcion) + '</div>' : '')
        + '</div>';
    });
    secObs += '</div>';
  });
  if (secObs) secObs = '<hr><h3 style="font-size:0.95rem;font-weight:700;color:#37474F;margin-bottom:0.5rem;">Observaciones y eventos por materia</h3>' + secObs;

  const promColor = promedioGeneral === null ? '#9E9E9E' : promedioGeneral >= 70 ? '#2E7D32' : promedioGeneral >= 50 ? '#E65100' : '#C62828';
  const asistColorGral = asistPromedio === null ? '#9E9E9E' : asistPromedio >= 80 ? '#2E7D32' : asistPromedio >= 60 ? '#E65100' : '#C62828';

  const css = `*{box-sizing:border-box;margin:0;padding:0;}body{font-family:Arial,sans-serif;font-size:14px;color:#212121;background:#fff;}
    .page{max-width:760px;margin:0 auto;padding:2rem;}
    header{background:#00838F;color:#fff;padding:1.2rem 1.5rem;border-radius:8px 8px 0 0;}
    h1{font-size:1.1rem;font-weight:700;}h2{font-size:0.88rem;font-weight:400;opacity:0.85;margin-top:4px;}
    .alumno-card{background:#E0F7FA;padding:1rem 1.5rem;display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:1.5rem;}
    .alumno-nombre{font-size:1.4rem;font-weight:800;color:#00695C;}.alumno-info{font-size:0.82rem;color:#546E7A;margin-top:4px;}
    table{width:100%;border-collapse:collapse;margin-bottom:1.5rem;}
    th{background:#00838F;color:#fff;padding:8px;text-align:left;font-size:0.82rem;}
    .resumen{display:flex;gap:1rem;margin-bottom:1.5rem;flex-wrap:wrap;}
    .resumen-card{flex:1;min-width:120px;background:#F5F5F5;border-radius:8px;padding:0.8rem;text-align:center;}
    .resumen-val{font-size:1.6rem;font-weight:800;}.resumen-label{font-size:0.72rem;color:#78909C;margin-top:2px;}
    hr{border:none;border-top:1px solid #eee;margin:1.5rem 0;}
    .btn-print{display:block;margin:1.5rem auto 0;padding:10px 2rem;background:#00838F;color:#fff;border:none;border-radius:8px;font-size:1rem;cursor:pointer;font-weight:600;}
    @media print{.btn-print{display:none;}.page{padding:0;}}`;

  const html = '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">'
    + '<title>Boletín consolidado ' + esc(estBase.nombre) + '</title><style>' + css + '</style></head><body><div class="page">'
    + '<header><h1>📋 Boletín Consolidado</h1><h2>' + materias.length + ' materia' + (materias.length !== 1 ? 's' : '') + ' · ' + nCursos + ' curso' + (nCursos !== 1 ? 's' : '') + '</h2></header>'
    + '<div class="alumno-card"><div>'
    + '<div class="alumno-nombre">' + esc(estBase.nombre) + '</div>'
    + '<div class="alumno-info">Consolidado de todos los cursos donde aparece este estudiante</div>'
    + '</div><div style="text-align:right;font-size:0.78rem;color:#546E7A;">Emitido:<br>' + hoy + '</div></div>'
    + '<table><thead><tr>'
    + '<th style="width:40%;">Materia</th><th style="width:20%;text-align:center;">Nota</th>'
    + '<th style="width:20%;text-align:center;">%</th><th style="width:20%;text-align:center;">Asistencia</th>'
    + '</tr></thead><tbody>' + filasMaterias + '</tbody></table>'
    + '<div class="resumen">'
    + '<div class="resumen-card"><div class="resumen-val" style="color:#2E7D32;">' + aprobadas + '</div><div class="resumen-label">Materias aprobadas</div></div>'
    + '<div class="resumen-card"><div class="resumen-val" style="color:' + (reprobadas ? '#C62828' : '#9E9E9E') + ';">' + reprobadas + '</div><div class="resumen-label">Materias reprobadas</div></div>'
    + '<div class="resumen-card"><div class="resumen-val" style="color:' + asistColorGral + ';">' + (asistPromedio !== null ? asistPromedio + '%' : '—') + '</div><div class="resumen-label">Asistencia promedio</div></div>'
    + '<div class="resumen-card" style="background:#E0F7FA;"><div class="resumen-val" style="color:' + promColor + ';">' + (promedioGeneral !== null ? promedioGeneral + '%' : '—') + '</div><div class="resumen-label">PROMEDIO GENERAL</div></div>'
    + '</div>'
    + secObs
    + '<hr><button class="btn-print" onclick="window.print()">🖨️ Imprimir / Guardar PDF</button>'
    + '</div></body></html>';

  const w = window.open('', '_blank');
  if (!w) { mostrarToast('Permite ventanas emergentes para ver el boletín', 'error'); return; }
  w.document.write(html);
  w.document.close();
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: GENERADOR DE CERTIFICADOS / DIPLOMAS
// ════════════════════════════════════════════════════════════════════
const CERT_TIPOS = [
  { id: 'mejor_promedio', label: 'Mejor promedio del curso', texto: 'por haber obtenido el mejor promedio académico del curso.' },
  { id: 'asistencia_perfecta', label: 'Asistencia perfecta', texto: 'por su asistencia perfecta y compromiso durante el periodo.' },
  { id: 'merito_academico', label: 'Mérito académico', texto: 'por su desempeño académico sobresaliente.' },
  { id: 'participacion', label: 'Participación destacada', texto: 'por su participación destacada y compromiso en clase.' },
  { id: 'mejora', label: 'Mayor superación / mejora', texto: 'por su notable superación y esfuerzo durante el periodo.' },
  { id: 'otro', label: 'Otro (personalizado)', texto: '' }
];

function abrirGeneradorCertificado(estId) {
  const cursoId = calState.cursoActivoId;
  const curso = calState.cursos[cursoId];
  if (!curso) { mostrarToast('Sin curso activo', 'error'); return; }
  const est = (curso.estudiantes || []).find(e => e.id === estId);
  if (!est) return;

  const portBase = cargarPortafolioBase();
  const dg = planificacion?.datosGenerales || {};
  const docenteNombre = portBase?.docente?.nombre || dg.nombreDocente || window.currentUser?.displayName || '';

  const overlay = document.createElement('div');
  overlay.id = 'cert-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.45);z-index:9000;display:flex;align-items:flex-start;justify-content:center;padding:24px 16px;overflow-y:auto;';
  overlay.onclick = (e) => { if (e.target === overlay) cerrarGeneradorCertificado(); };
  overlay.innerHTML = `
    <div style="background:var(--color-superficie,#fff);border-radius:16px;padding:24px;max-width:480px;width:100%;box-shadow:0 8px 32px rgba(0,0,0,0.22);margin:auto;" onclick="event.stopPropagation()">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:14px;">
        <span class="material-icons" style="color:#AD1457;font-size:24px;">workspace_premium</span>
        <h3 style="margin:0;font-size:1rem;font-weight:800;color:var(--color-texto-primario,#212121);">Generar certificado</h3>
      </div>
      <p style="font-size:0.85rem;color:#546E7A;margin:0 0 14px;">Para: <strong>${escapeHTML(est.nombre)}</strong></p>

      <label style="font-size:0.78rem;font-weight:700;color:#546E7A;display:block;margin-bottom:4px;">Tipo de reconocimiento</label>
      <select id="cert-tipo" onchange="_certActualizarMotivo()" style="width:100%;padding:9px 11px;border:1.5px solid #B0BEC5;border-radius:8px;font-size:0.9rem;margin-bottom:12px;box-sizing:border-box;">
        ${CERT_TIPOS.map(t => `<option value="${t.id}">${escapeHTML(t.label)}</option>`).join('')}
      </select>

      <label style="font-size:0.78rem;font-weight:700;color:#546E7A;display:block;margin-bottom:4px;">Título del certificado</label>
      <input id="cert-titulo" type="text" value="Certificado de Reconocimiento" style="width:100%;padding:9px 11px;border:1.5px solid #B0BEC5;border-radius:8px;font-size:0.9rem;margin-bottom:12px;box-sizing:border-box;">

      <label style="font-size:0.78rem;font-weight:700;color:#546E7A;display:block;margin-bottom:4px;">Motivo</label>
      <textarea id="cert-motivo" style="width:100%;min-height:70px;padding:9px 11px;border:1.5px solid #B0BEC5;border-radius:8px;font-size:0.88rem;margin-bottom:12px;box-sizing:border-box;resize:vertical;">${escapeHTML(CERT_TIPOS[0].texto)}</textarea>

      <label style="font-size:0.78rem;font-weight:700;color:#546E7A;display:block;margin-bottom:4px;">Fecha</label>
      <input id="cert-fecha" type="date" value="${new Date().toISOString().split('T')[0]}" style="width:100%;padding:9px 11px;border:1.5px solid #B0BEC5;border-radius:8px;font-size:0.9rem;margin-bottom:12px;box-sizing:border-box;">

      <label style="font-size:0.78rem;font-weight:700;color:#546E7A;display:block;margin-bottom:4px;">Firma (nombre del docente)</label>
      <input id="cert-firma" type="text" value="${escapeHTML(docenteNombre)}" style="width:100%;padding:9px 11px;border:1.5px solid #B0BEC5;border-radius:8px;font-size:0.9rem;margin-bottom:6px;box-sizing:border-box;">

      <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px;">
        <button onclick="cerrarGeneradorCertificado()" style="background:none;border:1.5px solid #E0E0E0;color:#757575;border-radius:20px;padding:8px 18px;font-size:0.85rem;cursor:pointer;">Cancelar</button>
        <button onclick="_generarCertificadoImprimir('${estId}')" style="background:#AD1457;color:#fff;border:none;border-radius:20px;padding:8px 18px;font-size:0.85rem;cursor:pointer;font-weight:700;">
          <span class="material-icons" style="font-size:16px;vertical-align:-3px;">print</span> Generar
        </button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
}

function cerrarGeneradorCertificado() {
  document.getElementById('cert-overlay')?.remove();
}

function _certActualizarMotivo() {
  const tipo = document.getElementById('cert-tipo')?.value;
  const info = CERT_TIPOS.find(t => t.id === tipo);
  const motivoEl = document.getElementById('cert-motivo');
  if (motivoEl && info && info.texto) motivoEl.value = info.texto;
}

/** Abre el certificado imprimible en una pestaña nueva (mismo patrón que abrirBoletin)
 *  y, en segundo plano, registra el reconocimiento como evidencia en el Portafolio
 *  Docente bajo "Logros y reconocimientos" -- mejor esfuerzo, no bloquea si falla. */
async function _generarCertificadoImprimir(estId) {
  const cursoId = calState.cursoActivoId;
  const curso = calState.cursos[cursoId];
  if (!curso) return;
  const est = (curso.estudiantes || []).find(e => e.id === estId);
  if (!est) return;

  const titulo = (document.getElementById('cert-titulo')?.value || 'Certificado de Reconocimiento').trim();
  const motivo = (document.getElementById('cert-motivo')?.value || '').trim();
  const fecha = document.getElementById('cert-fecha')?.value || new Date().toISOString().split('T')[0];
  const firma = (document.getElementById('cert-firma')?.value || '').trim();

  const centroInfo = await _portafolioCargarIdentidadCentro();
  const esc = escapeHTML;
  const fechaFmt = new Date(fecha + 'T12:00:00').toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' });

  const css = '*{box-sizing:border-box;margin:0;padding:0;}'
    + 'body{font-family:Georgia,"Times New Roman",serif;background:#f0ede4;padding:24px;}'
    + '.cert{max-width:900px;margin:0 auto;background:#fffdf7;border:10px double #AD1457;border-radius:6px;padding:56px 60px;text-align:center;}'
    + '.cert-logo{width:76px;height:76px;object-fit:contain;margin:0 auto 12px;display:block;}'
    + '.cert-centro{font-size:14px;letter-spacing:2px;text-transform:uppercase;color:#6A1B9A;font-weight:700;margin-bottom:26px;}'
    + '.cert-titulo{font-size:34px;color:#AD1457;font-weight:700;letter-spacing:1px;margin-bottom:8px;}'
    + '.cert-sub{font-size:15px;color:#757575;margin-bottom:34px;}'
    + '.cert-nombre{font-size:30px;color:#212121;font-weight:700;border-bottom:2px solid #AD1457;display:inline-block;padding:0 24px 8px;margin-bottom:28px;}'
    + '.cert-motivo{font-size:16px;color:#424242;line-height:1.7;max-width:640px;margin:0 auto 40px;}'
    + '.cert-firmas{display:flex;justify-content:center;gap:80px;margin-top:20px;}'
    + '.cert-firma-linea{border-top:1.5px solid #757575;padding-top:6px;font-size:13px;color:#424242;min-width:220px;}'
    + '.cert-fecha{margin-top:34px;font-size:13px;color:#9E9E9E;}'
    + '.btn-print{display:block;margin:24px auto 0;padding:10px 2rem;background:#AD1457;color:#fff;border:none;border-radius:8px;font-size:1rem;cursor:pointer;font-weight:600;}'
    + '@media print{.btn-print{display:none;}body{background:#fff;padding:0;}.cert{border-width:6px;}}';

  const html = '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">'
    + '<title>' + esc(titulo) + ' — ' + esc(est.nombre) + '</title><style>' + css + '</style></head><body>'
    + '<div class="cert">'
    + (centroInfo?.logoUrl ? '<img class="cert-logo" src="' + esc(centroInfo.logoUrl) + '">' : '')
    + '<div class="cert-centro">' + esc(centroInfo?.nombre || 'Centro Educativo') + '</div>'
    + '<div class="cert-titulo">' + esc(titulo) + '</div>'
    + '<div class="cert-sub">Se otorga el presente reconocimiento a</div>'
    + '<div class="cert-nombre">' + esc(est.nombre) + '</div>'
    + (motivo ? '<div class="cert-motivo">' + esc(motivo) + '</div>' : '')
    + '<div class="cert-firmas"><div><div class="cert-firma-linea">' + esc(firma || 'Docente') + '</div></div></div>'
    + '<div class="cert-fecha">' + esc(fechaFmt) + '</div>'
    + '</div>'
    + '<button class="btn-print" onclick="window.print()">🖨️ Imprimir / Guardar PDF</button>'
    + '</body></html>';

  const w = window.open('', '_blank', 'width=1000,height=800');
  if (!w) { mostrarToast('Permite ventanas emergentes para ver el certificado', 'error'); return; }
  w.document.write(html);
  w.document.close();

  _crearEvidenciaPortafolioAuto({
    categoria: 'logros_reconocimientos',
    titulo: titulo + ' — ' + est.nombre,
    descripcion: motivo || ('Certificado emitido a ' + est.nombre),
    fecha,
    origen: 'Generador de certificados · ' + (curso.nombre || '')
  });

  registrarCambio(`Certificado generado: "${titulo}" — ${est.nombre}`);
  cerrarGeneradorCertificado();
  mostrarToast('Certificado generado', 'success');
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: REGISTRO DE INCIDENCIAS / REUNIONES / TUTORÍAS
// ════════════════════════════════════════════════════════════════════
const INCID_KEY = 'planificadorRA_incidencias_v1';
const INCID_TIPOS = [
  { id: 'reunion_familia', label: 'Reunión con familia', icono: 'people',        color: '#1565C0' },
  { id: 'tutoria',         label: 'Tutoría',             icono: 'school',        color: '#6A1B9A' },
  { id: 'incidencia',      label: 'Incidencia',          icono: 'warning',       color: '#C62828' },
  { id: 'seguimiento',     label: 'Seguimiento',         icono: 'track_changes', color: '#E65100' },
  { id: 'otro',            label: 'Otro',                icono: 'label',         color: '#546E7A' }
];
function cargarIncidencias() {
  try { return JSON.parse(localStorage.getItem(INCID_KEY) || '{}'); } catch { return {}; }
}
function guardarIncidencias(data) {
  localStorage.setItem(INCID_KEY, JSON.stringify(data));
  if (window._syncFirebase) _syncFirebase('incidencias', data);
}
function _getIncidenciasEst(estId) {
  const data = cargarIncidencias();
  return (data[estId] || []).slice().sort((a, b) => (b.fechaEvento || b.ts) > (a.fechaEvento || a.ts) ? 1 : -1);
}
function abrirIncidencias(estId) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  const est = (curso.estudiantes || []).find(e => e.id === estId);
  if (!est) return;
  document.getElementById('inc-titulo').textContent = 'Eventos — ' + est.nombre;
  renderizarIncidencias(estId);
  document.getElementById('incidencias-overlay').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}
function cerrarIncidenciasBtn() {
  document.getElementById('incidencias-overlay').classList.add('hidden');
  document.body.style.overflow = '';
}
function cerrarIncidencias(e) {
  if (e.target === document.getElementById('incidencias-overlay')) cerrarIncidenciasBtn();
}
function renderizarIncidencias(estId) {
  const lista = _getIncidenciasEst(estId);
  const hoyISO = new Date().toISOString().split('T')[0];
  let html = '<div style="padding:1rem;">';

  if (lista.length === 0) {
    html += '<p style="color:#9E9E9E;font-size:0.88rem;text-align:center;padding:1rem 0;">No hay eventos registrados para este estudiante.</p>';
  } else {
    lista.forEach(inc => {
      const tipo = INCID_TIPOS.find(t => t.id === inc.tipo) || INCID_TIPOS[INCID_TIPOS.length-1];
      html += '<div style="background:#F8F9FA;border-radius:8px;border-left:4px solid ' + tipo.color + ';padding:10px 12px;margin-bottom:10px;">'
        + '<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">'
        + '<span class="material-icons" style="font-size:16px;color:' + tipo.color + ';">' + tipo.icono + '</span>'
        + '<strong style="font-size:0.85rem;color:' + tipo.color + ';">' + escapeHTML(tipo.label) + '</strong>'
        + (inc.fechaEvento ? '<span style="font-size:0.78rem;color:#78909C;margin-left:4px;"> · ' + inc.fechaEvento + '</span>' : '')
        + '<button onclick="eliminarIncidencia(\'' + inc.id + '\',\'' + estId + '\')" style="margin-left:auto;background:none;border:none;cursor:pointer;color:#EF5350;padding:2px;" title="Eliminar"><span class="material-icons" style="font-size:16px;">delete</span></button>'
        + '</div>'
        + (inc.participantes ? '<div style="font-size:0.78rem;color:#546E7A;"><b>Participantes:</b> ' + escapeHTML(inc.participantes) + '</div>' : '')
        + (inc.descripcion ? '<div style="font-size:0.85rem;color:#37474F;margin-top:4px;">' + escapeHTML(inc.descripcion) + '</div>' : '')
        + (inc.acuerdos ? '<div style="font-size:0.8rem;color:#1565C0;margin-top:4px;"><b>Acuerdos:</b> ' + escapeHTML(inc.acuerdos) + '</div>' : '')
        + '</div>';
    });
  }

  html += '<div style="border-top:2px solid #E3F2FD;margin-top:1rem;padding-top:1rem;">'
    + '<h4 style="font-size:0.9rem;font-weight:700;color:#1565C0;margin-bottom:0.75rem;">+ Registrar nuevo evento</h4>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;">'
    + '<div><label style="font-size:0.78rem;color:#546E7A;display:block;margin-bottom:3px;">Tipo</label>'
    + '<select id="inc-tipo" style="width:100%;padding:6px 8px;border:1px solid #B0BEC5;border-radius:6px;font-size:0.85rem;">'
    + INCID_TIPOS.map(t => '<option value="' + t.id + '">' + t.label + '</option>').join('')
    + '</select></div>'
    + '<div><label style="font-size:0.78rem;color:#546E7A;display:block;margin-bottom:3px;">Fecha del evento</label>'
    + '<input type="date" id="inc-fecha" value="' + hoyISO + '" style="width:100%;padding:6px 8px;border:1px solid #B0BEC5;border-radius:6px;font-size:0.85rem;"></div>'
    + '</div>'
    + '<div style="margin-bottom:8px;"><label style="font-size:0.78rem;color:#546E7A;display:block;margin-bottom:3px;">Participantes</label>'
    + '<input type="text" id="inc-participantes" placeholder="Ej: padre, madre, apoderado..." style="width:100%;padding:6px 8px;border:1px solid #B0BEC5;border-radius:6px;font-size:0.85rem;"></div>'
    + '<div style="margin-bottom:8px;"><label style="font-size:0.78rem;color:#546E7A;display:block;margin-bottom:3px;">Descripción</label>'
    + '<textarea id="inc-descripcion" rows="3" placeholder="¿Qué ocurrió? ¿De qué se trató?" style="width:100%;padding:6px 8px;border:1px solid #B0BEC5;border-radius:6px;font-size:0.85rem;resize:vertical;"></textarea></div>'
    + '<div style="margin-bottom:12px;"><label style="font-size:0.78rem;color:#546E7A;display:block;margin-bottom:3px;">Acuerdos / compromisos</label>'
    + '<textarea id="inc-acuerdos" rows="2" placeholder="¿Qué se acordó? ¿Cuáles son los próximos pasos?" style="width:100%;padding:6px 8px;border:1px solid #B0BEC5;border-radius:6px;font-size:0.85rem;resize:vertical;"></textarea></div>'
    + '<button onclick="guardarIncidenciaNueva(\'' + estId + '\')" style="width:100%;padding:10px;background:#1565C0;color:#fff;border:none;border-radius:8px;font-size:0.9rem;font-weight:600;cursor:pointer;">Guardar evento</button>'
    + '</div></div>';

  document.getElementById('inc-body').innerHTML = html;
}
function guardarIncidenciaNueva(estId) {
  const tipo = document.getElementById('inc-tipo')?.value;
  const fechaEvento = document.getElementById('inc-fecha')?.value;
  const participantes = (document.getElementById('inc-participantes')?.value || '').trim();
  const descripcion = (document.getElementById('inc-descripcion')?.value || '').trim();
  const acuerdos = (document.getElementById('inc-acuerdos')?.value || '').trim();
  if (!descripcion) { mostrarToast('Escribe al menos una descripción', 'error'); return; }
  const data = cargarIncidencias();
  if (!data[estId]) data[estId] = [];
  data[estId].push({ id: uid(), ts: Date.now(), fechaEvento, tipo, participantes, descripcion, acuerdos });
  guardarIncidencias(data);
  renderizarIncidencias(estId);
  renderizarTablaCalificaciones();
  registrarCambio('Evento/incidencia registrado: ' + tipo);
  mostrarToast('Evento registrado', 'success');

  // Enlazar con el Portafolio Docente como evidencia (automático, best-effort)
  const cursoInc = calState.cursos[calState.cursoActivoId];
  const estInc = cursoInc?.estudiantes?.find(e => e.id === estId);
  const tipoInfo = INCID_TIPOS.find(t => t.id === tipo) || INCID_TIPOS[INCID_TIPOS.length - 1];
  let descEvidenciaInc = descripcion;
  if (participantes) descEvidenciaInc += '\n\nParticipantes: ' + participantes;
  if (acuerdos) descEvidenciaInc += '\n\nAcuerdos: ' + acuerdos;
  _crearEvidenciaPortafolioAuto({
    categoria: 'reunion_seguimiento',
    titulo: tipoInfo.label + (estInc ? ' — ' + estInc.nombre : ''),
    descripcion: descEvidenciaInc,
    fecha: fechaEvento,
    origen: 'Calificaciones — Eventos'
  });
}
function eliminarIncidencia(incId, estId) {
  if (!confirm('¿Eliminar este evento?')) return;
  const data = cargarIncidencias();
  if (data[estId]) data[estId] = data[estId].filter(i => i.id !== incId);
  guardarIncidencias(data);
  renderizarIncidencias(estId);
  renderizarTablaCalificaciones();
  registrarCambio('Evento/incidencia eliminado');
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: VISTA DEL ESTUDIANTE (solo lectura + QR)
// ════════════════════════════════════════════════════════════════════
let _vistaEstUrl = '';
function abrirVistaEstudiante(estId) {
  const cursoId = calState.cursoActivoId;
  const curso = calState.cursos[cursoId];
  if (!curso) return;
  const est = (curso.estudiantes || []).find(e => e.id === estId);
  if (!est) return;

  const raKey = calState.raActivaKey || _getRaKey();
  const raInfo = curso.ras?.[raKey];
  const planActiva = _getPlanActivaDeCurso();
  let actividades = (planActiva && planActiva.actividades) || [];
  if (actividades.length === 0) actividades = raInfo?._actividadesSnapshot || [];
  const planDg = planActiva?.datosGenerales || {};
  const planRa = planActiva?.ra || {};
  const recupMap = _getRecuperacionesEst(cursoId, estId);

  const notaRA = _calcNotaRA(curso, estId, raKey);
  let notaRecupSum = 0, hasRecup = false;
  actividades.forEach(a => {
    const reg = _normalizarRegRecup(recupMap[raKey + '__' + a.id]);
    (reg?.intentos || []).forEach(intento => {
      if (intento?.notaRecuperacion != null) { notaRecupSum += intento.notaRecuperacion; hasRecup = true; }
    });
  });
  const tTotal = (notaRA !== null || hasRecup)
    ? Math.min((notaRA || 0) + notaRecupSum, raInfo?.valorTotal || 0)
    : null;

  const data = {
    n: est.nombre,
    c: curso.nombre || cursoId,
    m: (planDg.moduloFormativo || '').substring(0, 50),
    ra: (planRa.descripcion || '').substring(0, 100),
    vt: raInfo?.valorTotal || 0,
    f: new Date().toISOString().slice(0, 10),
    acts: actividades.map(a => {
      const reg = _normalizarRegRecup(recupMap[raKey + '__' + a.id]);
      const intentos = (reg?.intentos || []).filter(i => i);
      const rSum = intentos.reduce((s, i) => s + (i.notaRecuperacion != null ? i.notaRecuperacion : 0), 0);
      const rHas = intentos.some(i => i.notaRecuperacion != null);
      const rPend = intentos.some(i => i.estado === 'pendiente');
      return {
        l: (a.enunciado || a.ecCodigo || '').substring(0, 50),
        v: raInfo?.valores?.[a.id] || 0,
        n: curso.notas?.[estId]?.[raKey]?.[a.id] ?? null,
        r: rHas ? rSum : null,
        rs: rHas ? (rPend ? 'pendiente' : 'completada') : null
      };
    }),
    tRA: notaRA,
    tTotal: tTotal,
    asist: _statsAsistencia(cursoId, estId).pct
  };

  const base = window.location.href.replace(/[#?].*$/, '').replace(/[^/]*$/, '');

  const b64Full = btoa(encodeURIComponent(JSON.stringify(data)));
  _vistaEstUrl = base + 'viewer.html#data=' + b64Full;

  document.getElementById('vista-est-titulo').textContent = est.nombre;
  document.getElementById('vista-est-url').value = _vistaEstUrl;

  document.getElementById('vista-est-overlay').classList.remove('hidden');
}
function cerrarVistaEstudianteBtn() {
  document.getElementById('vista-est-overlay').classList.add('hidden');
}
function cerrarVistaEstudiante(e) {
  if (e.target === document.getElementById('vista-est-overlay')) cerrarVistaEstudianteBtn();
}
function abrirVistaEstudianteTab() {
  window.open(_vistaEstUrl, '_blank');
}
function copiarLinkEstudiante() {
  const inp = document.getElementById('vista-est-url');
  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(_vistaEstUrl).then(() => {
      mostrarToast('Enlace copiado al portapapeles', 'success');
    }).catch(() => _copiarFallback(inp));
  } else {
    _copiarFallback(inp);
  }
}
function _copiarFallback(inp) {
  inp.select();
  inp.setSelectionRange(0, 99999);
  document.execCommand('copy');
  mostrarToast('Enlace copiado', 'success');
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: MODO RECUPERACIÓN / SEGUNDA OPORTUNIDAD
// ════════════════════════════════════════════════════════════════════
const RECUP_KEY = 'planificadorRA_recuperaciones_v1';
// Cuántas oportunidades de recuperación se le dan a un estudiante por
// actividad (además de la nota original) y cómo se etiqueta cada una.
const CAL_RECUP_NUM_INTENTOS = 3;
const CAL_RECUP_LABELS = ['2da oport.', '3ra oport.', '4ta oport.'];

/** Normaliza un registro de recuperación al formato con varios intentos
 * (arreglo `intentos`). Migra automáticamente el formato viejo -- un solo
 * intento guardado directo en la raíz del registro, de antes de que
 * existieran varias oportunidades -- sin perder ninguna nota ya guardada. */
function _normalizarRegRecup(reg) {
  if (!reg) return null;
  if (Array.isArray(reg.intentos)) return reg;
  if (reg.notaRecuperacion !== undefined || reg.fechaLimite !== undefined || reg.estado !== undefined) {
    return { ...reg, intentos: [{ notaRecuperacion: reg.notaRecuperacion, fechaLimite: reg.fechaLimite, estado: reg.estado }] };
  }
  return { ...reg, intentos: [] };
}

function cargarRecuperaciones() {
  try { return JSON.parse(localStorage.getItem(RECUP_KEY) || '{}'); } catch { return {}; }
}
function guardarRecuperaciones(data) {
  localStorage.setItem(RECUP_KEY, JSON.stringify(data));
  if (window._syncFirebase) _syncFirebase('recuperaciones', data);
}
function _getRecuperacionesEst(cursoId, estId) {
  return cargarRecuperaciones()[cursoId]?.[estId] || {};
}
function abrirRecuperaciones(estId) {
  const cursoId = calState.cursoActivoId;
  const curso = calState.cursos[cursoId];
  if (!curso) return;
  const est = (curso.estudiantes || []).find(e => e.id === estId);
  if (!est) return;
  // Limpiar entradas corruptas con actividadId 'undefined' (generadas antes del fix)
  const data = cargarRecuperaciones();
  let dirty = false;
  if (data[cursoId]?.[estId]) {
    Object.keys(data[cursoId][estId]).forEach(k => {
      if (k.endsWith('__undefined')) { delete data[cursoId][estId][k]; dirty = true; }
    });
    if (dirty) guardarRecuperaciones(data);
  }
  document.getElementById('recup-titulo').textContent = 'Recuperaciones — ' + est.nombre;
  document.getElementById('recuperaciones-overlay')._estId = estId;
  renderizarRecuperaciones(estId);
  document.getElementById('recuperaciones-overlay').classList.remove('hidden');
}
function cerrarRecuperacionesBtn() {
  document.getElementById('recuperaciones-overlay').classList.add('hidden');
}
function cerrarRecuperaciones(e) {
  if (e.target === document.getElementById('recuperaciones-overlay')) cerrarRecuperacionesBtn();
}
function renderizarRecuperaciones(estId) {
  const cursoId = calState.cursoActivoId;
  const curso = calState.cursos[cursoId];
  if (!curso) return;
  const raKey = calState.raActivaKey || _getRaKey();
  const raInfo = curso.ras?.[raKey];
  if (!raInfo) {
    document.getElementById('recup-body').innerHTML = '<p style="padding:1rem;color:#9E9E9E;">Sin RA activo.</p>';
    return;
  }
  // Actividades como objetos {id, enunciado, ecCodigo, ...}
  const planActiva = _getPlanActivaDeCurso();
  let actividades = (planActiva && planActiva.actividades) || [];
  if (actividades.length === 0) actividades = raInfo._actividadesSnapshot || [];
  const recupMap = _getRecuperacionesEst(cursoId, estId);
  let html = '<div style="padding:12px 16px;">';
  if (actividades.length === 0) {
    html += '<p style="color:#9E9E9E;">Este RA no tiene actividades definidas.</p>';
  } else {
    actividades.forEach(a => {
      const max = raInfo.valores?.[a.id] || 100;
      const nota = curso.notas?.[estId]?.[raKey]?.[a.id];
      const notaStr = nota !== undefined ? nota.toFixed(1) : '—';
      const pct = nota !== undefined ? (nota / max) * 100 : null;
      const emoji = pct === null ? '⬜' : (pct >= 70 ? '✅' : (pct >= 50 ? '🟡' : '❌'));
      const recKey = raKey + '__' + a.id;
      const reg = _normalizarRegRecup(recupMap[recKey]);
      html += '<div style="border:1px solid #2a2a3a;border-radius:8px;padding:12px 14px;margin-bottom:10px;background:#1a1a2a;">';
      html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">'
        + '<span style="font-weight:600;flex:1;font-size:0.88rem;color:#ECEFF1;">' + escapeHTML((a.enunciado || ('Act. ' + a.id)).substring(0, 60)) + '</span>'
        + '<span style="font-size:1.1rem;">' + emoji + '</span>'
        + '<span style="color:#B0BEC5;font-size:0.82rem;white-space:nowrap;">Nota: <strong>' + notaStr + '</strong> / ' + max + '</span>'
        + '</div>';

      for (let idx = 0; idx < CAL_RECUP_NUM_INTENTOS; idx++) {
        const label = CAL_RECUP_LABELS[idx];
        const intento = reg?.intentos?.[idx];
        if (idx > 0) html += '<div style="height:8px;"></div>';
        if (intento) {
          const isPendiente = intento.estado === 'pendiente';
          const colorEstado = isPendiente ? '#FF8F00' : '#2E7D32';
          const bgEstado = isPendiente ? 'rgba(255,143,0,0.12)' : 'rgba(46,125,50,0.12)';
          const maxRecup = _calcMaxRecupPermitida(cursoId, estId, raKey, a.id, idx);
          const topeReal = Math.max(maxRecup, intento.notaRecuperacion || 0);
          html += '<div style="background:' + bgEstado + ';border-radius:6px;padding:10px 12px;">';
          html += '<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;flex-wrap:wrap;">'
            + '<span class="material-icons" style="font-size:15px;color:' + colorEstado + ';">' + (isPendiente ? 'schedule' : 'check_circle') + '</span>'
            + '<strong style="color:' + colorEstado + ';font-size:0.85rem;">' + escapeHTML(label).toUpperCase() + ' · ' + (isPendiente ? 'PENDIENTE' : 'COMPLETADA') + '</strong>'
            + '<span style="color:#9E9E9E;font-size:0.8rem;margin-left:4px;">· Vence: ' + (intento.fechaLimite || '—') + '</span>'
            + '</div>';
          html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">'
            + '<label style="font-size:0.82rem;color:#CFD8DC;">Nota recuperación <span style="color:#FF8F00;">(máx. ' + topeReal.toFixed(1) + ' pts)</span>:</label>'
            + '<input type="number" id="recup-nota-' + a.id + '-' + idx + '" min="0" max="' + topeReal + '" step="0.5" placeholder="—"'
            + ' value="' + (intento.notaRecuperacion !== null && intento.notaRecuperacion !== undefined ? intento.notaRecuperacion : '') + '"'
            + ' style="width:80px;padding:4px 6px;border-radius:4px;border:1px solid #444;background:#0e0e1a;color:#fff;font-size:0.9rem;"'
            + ' onwheel="event.preventDefault()" /></div>';
          html += '<div style="display:flex;gap:8px;">'
            + '<button onclick="guardarRecuperacion(\'' + estId + '\',\'' + a.id + '\',' + idx + ')" style="padding:5px 12px;background:#1565C0;color:#fff;border:none;border-radius:5px;cursor:pointer;font-size:0.82rem;display:flex;align-items:center;gap:4px;"><span class="material-icons" style="font-size:13px;">save</span>Guardar nota</button>'
            + '<button onclick="quitarRecuperacion(\'' + estId + '\',\'' + a.id + '\',' + idx + ')" style="padding:5px 12px;background:none;color:#EF5350;border:1px solid #EF5350;border-radius:5px;cursor:pointer;font-size:0.82rem;display:flex;align-items:center;gap:4px;"><span class="material-icons" style="font-size:13px;">close</span>Quitar</button>'
            + '</div></div>';
        } else {
          html += '<div id="recup-form-' + a.id + '-' + idx + '">'
            + '<button onclick="_abrirFormRecup(\'' + a.id + '\',' + idx + ')" style="padding:5px 12px;background:none;color:#E65100;border:1px solid #E65100;border-radius:5px;cursor:pointer;font-size:0.82rem;display:flex;align-items:center;gap:4px;">'
            + '<span class="material-icons" style="font-size:13px;">replay</span>Marcar ' + escapeHTML(label) + '</button>'
            + '</div>';
        }
      }
      html += '</div>';
    });
  }
  html += '</div>';
  document.getElementById('recup-body').innerHTML = html;
}
// Calcula cuántos puntos de recuperación quedan disponibles para un estudiante
// en el RA activo, excluyendo el intento (actividad + número de oportunidad)
// que se está editando en este momento, para no restarse a sí mismo.
function _calcMaxRecupPermitida(cursoId, estId, raKey, excludeActId, excludeIntentoIdx) {
  const curso = calState.cursos[cursoId];
  const raInfo = curso?.ras?.[raKey];
  if (!raInfo) return 0;
  const notaRA = _calcNotaRA(curso, estId, raKey) || 0;
  const planActiva = _getPlanActivaDeCurso();
  let acts = (planActiva && planActiva.actividades) || [];
  if (acts.length === 0) acts = raInfo._actividadesSnapshot || [];
  const data = cargarRecuperaciones();
  const recMap = data[cursoId]?.[estId] || {};
  let otrasRecup = 0;
  acts.forEach(a => {
    const reg = _normalizarRegRecup(recMap[raKey + '__' + a.id]);
    (reg?.intentos || []).forEach((intento, idx) => {
      if (a.id === excludeActId && idx === excludeIntentoIdx) return;
      if (intento?.notaRecuperacion != null) otrasRecup += intento.notaRecuperacion;
    });
  });
  return Math.max(0, raInfo.valorTotal - notaRA - otrasRecup);
}
function _abrirFormRecup(actId, intentoIdx) {
  const overlay = document.getElementById('recuperaciones-overlay');
  const estId = overlay._estId;
  const cursoId = calState.cursoActivoId;
  const raKey = calState.raActivaKey || _getRaKey();
  const maxRecup = _calcMaxRecupPermitida(cursoId, estId, raKey, actId, intentoIdx);
  const hoy = new Date().toISOString().slice(0, 10);
  const div = document.getElementById('recup-form-' + actId + '-' + intentoIdx);
  if (!div) return;
  div.innerHTML = '<div style="background:rgba(230,81,0,0.08);border:1px solid #E65100;border-radius:6px;padding:10px 12px;">'
    + '<div style="display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;margin-bottom:8px;">'
    + '<div><label style="font-size:0.78rem;color:#CFD8DC;display:block;margin-bottom:3px;">Fecha límite</label>'
    + '<input type="date" id="recup-fecha-' + actId + '-' + intentoIdx + '" value="' + hoy + '" style="padding:4px 6px;border-radius:4px;border:1px solid #E65100;background:#0e0e1a;color:#fff;font-size:0.88rem;" /></div>'
    + '<div><label style="font-size:0.78rem;color:#CFD8DC;display:block;margin-bottom:3px;">Nota <span style="color:#FF8F00;">(máx. ' + maxRecup.toFixed(1) + ' pts)</span></label>'
    + '<input type="number" id="recup-nota-inline-' + actId + '-' + intentoIdx + '" min="0" max="' + maxRecup + '" step="0.5" placeholder="—" style="width:80px;padding:4px 6px;border-radius:4px;border:1px solid #444;background:#0e0e1a;color:#fff;font-size:0.88rem;" onwheel="event.preventDefault()" /></div>'
    + '</div>'
    + (maxRecup <= 0 ? '<p style="color:#EF5350;font-size:0.8rem;margin:0 0 8px;">⚠ El estudiante ya alcanzó el máximo del RA. No hay margen de recuperación.</p>' : '')
    + '<div style="display:flex;gap:8px;">'
    + '<button onclick="guardarNuevaRecuperacion(\'' + estId + '\',\'' + actId + '\',' + intentoIdx + ')" style="padding:5px 12px;background:#E65100;color:#fff;border:none;border-radius:5px;cursor:pointer;font-size:0.82rem;display:flex;align-items:center;gap:4px;"><span class="material-icons" style="font-size:13px;">save</span>Guardar</button>'
    + '<button onclick="renderizarRecuperaciones(\'' + estId + '\')" style="padding:5px 12px;background:none;color:#9E9E9E;border:1px solid #9E9E9E;border-radius:5px;cursor:pointer;font-size:0.82rem;">Cancelar</button>'
    + '</div></div>';
}
function guardarNuevaRecuperacion(estId, actId, intentoIdx) {
  const cursoId = calState.cursoActivoId;
  const raKey = calState.raActivaKey || _getRaKey();
  const fecha = (document.getElementById('recup-fecha-' + actId + '-' + intentoIdx)?.value || '').trim();
  const notaVal = (document.getElementById('recup-nota-inline-' + actId + '-' + intentoIdx)?.value || '').trim();
  const nota = notaVal !== '' ? parseFloat(notaVal) : null;
  if (!fecha) { mostrarToast('Indica una fecha límite', 'error'); return; }
  if (nota !== null) {
    const maxRecup = _calcMaxRecupPermitida(cursoId, estId, raKey, actId, intentoIdx);
    if (nota > maxRecup) {
      mostrarToast('La nota excede el límite del RA. Máximo permitido: ' + maxRecup.toFixed(1) + ' pts', 'error');
      return;
    }
  }
  const data = cargarRecuperaciones();
  if (!data[cursoId]) data[cursoId] = {};
  if (!data[cursoId][estId]) data[cursoId][estId] = {};
  const recKey = raKey + '__' + actId;
  const reg = _normalizarRegRecup(data[cursoId][estId][recKey]) || { id: recKey, actividadId: actId, raKey, intentos: [] };
  reg.intentos[intentoIdx] = {
    notaRecuperacion: nota,
    fechaLimite: fecha,
    estado: nota !== null ? 'completada' : 'pendiente'
  };
  data[cursoId][estId][recKey] = reg;
  guardarRecuperaciones(data);
  renderizarRecuperaciones(estId);
  renderizarTablaCalificaciones();
  registrarCambio('Recuperación registrada');
  mostrarToast('Recuperación registrada', 'success');
}
function guardarRecuperacion(estId, actId, intentoIdx) {
  const cursoId = calState.cursoActivoId;
  const raKey = calState.raActivaKey || _getRaKey();
  const notaVal = (document.getElementById('recup-nota-' + actId + '-' + intentoIdx)?.value || '').trim();
  const nota = notaVal !== '' ? parseFloat(notaVal) : null;
  if (nota !== null) {
    const maxRecup = _calcMaxRecupPermitida(cursoId, estId, raKey, actId, intentoIdx);
    if (nota > maxRecup) {
      mostrarToast('La nota excede el límite del RA. Máximo permitido: ' + maxRecup.toFixed(1) + ' pts', 'error');
      return;
    }
  }
  const data = cargarRecuperaciones();
  const recKey = raKey + '__' + actId;
  const reg = _normalizarRegRecup(data[cursoId]?.[estId]?.[recKey]);
  if (!reg || !reg.intentos[intentoIdx]) return;
  reg.intentos[intentoIdx].notaRecuperacion = nota;
  reg.intentos[intentoIdx].estado = nota !== null ? 'completada' : 'pendiente';
  data[cursoId][estId][recKey] = reg;
  guardarRecuperaciones(data);
  renderizarRecuperaciones(estId);
  renderizarTablaCalificaciones();
  registrarCambio('Nota de recuperación guardada');
  mostrarToast('Nota de recuperación guardada', 'success');
}
function quitarRecuperacion(estId, actId, intentoIdx) {
  if (!confirm('¿Quitar esta recuperación?')) return;
  const cursoId = calState.cursoActivoId;
  const raKey = calState.raActivaKey || _getRaKey();
  const data = cargarRecuperaciones();
  const recKey = raKey + '__' + actId;
  const reg = _normalizarRegRecup(data[cursoId]?.[estId]?.[recKey]);
  if (reg) {
    reg.intentos[intentoIdx] = null;
    if (data[cursoId]?.[estId]) {
      if (!reg.intentos.some(i => i)) delete data[cursoId][estId][recKey];
      else data[cursoId][estId][recKey] = reg;
      if (Object.keys(data[cursoId][estId]).length === 0) delete data[cursoId][estId];
    }
    if (data[cursoId] && Object.keys(data[cursoId]).length === 0) delete data[cursoId];
  }
  guardarRecuperaciones(data);
  renderizarRecuperaciones(estId);
  renderizarTablaCalificaciones();
  registrarCambio('Recuperación eliminada');
  mostrarToast('Recuperación eliminada', 'success');
}







