/** Renderiza la cuadrícula de planificaciones guardadas */



function renderizarBiblioteca() {
  const grid = document.getElementById('pln-grid');
  const vacio = document.getElementById('pln-vacio');
  if (!grid || !vacio) return;
  // Recalcular plan activa por fechas antes de renderizar
  _actualizarPlanActivaPorFechas();
  const biblio = cargarBiblioteca();
  const items = biblio.items || [];
  const query = (document.getElementById('pln-buscar')?.value || '').toLowerCase();

  if (items.length === 0) {
    grid.innerHTML = '';
    vacio.classList.remove('hidden');
    return;
  }
  vacio.classList.add('hidden');
  grid.innerHTML = '';

  // ── Separar planificaciones archivadas (individualmente, no por curso) ──
  const activosBase = items.filter(reg => !reg.archivada);
  const archivadosBase = items.filter(reg => reg.archivada);

  // ── Filtrar por búsqueda ──────────────────────────────────────
  const _matchQuery = reg => {
    if (!query) return true;
    const dg = reg.planificacion?.datosGenerales || {};
    const ra = reg.planificacion?.ra || {};
    return [dg.moduloFormativo, dg.nombreDocente, dg.nombreBachillerato,
    dg.familiaProfesional, ra.descripcion].join(' ').toLowerCase().includes(query);
  };
  const filtrados = activosBase.filter(_matchQuery);
  const archivadosFiltrados = archivadosBase.filter(_matchQuery);

  if (filtrados.length === 0 && archivadosFiltrados.length === 0) {
    grid.innerHTML = '<p style="text-align:center;color:#9E9E9E;padding:40px;">Sin resultados para la búsqueda.</p>';
    return;
  }

  // ── Agrupar por curso (activo + archivados por ciclo) ───────────────────
  const gruposActivos = {};          // { cursoNombre: { cursoId, planes[] } }
  const gruposArchivados = {};       // { yearId: { cursoNombre: { cursoId, planes[] } } }
  const sinCurso = [];
  const cursosActivosMap = calState.cursos || {};
  const cursosArchivadosMap = calState.cursosArchivados || {};

  filtrados.forEach(reg => {
    let encontrado = false;

    const cursosActivosDePlan = Object.values(cursosActivosMap).filter(c => (c.planIds || []).includes(reg.id));
    if (cursosActivosDePlan.length > 0) {
      encontrado = true;
      cursosActivosDePlan.forEach(c => {
        if (!gruposActivos[c.nombre]) gruposActivos[c.nombre] = { cursoId: c.id, planes: [] };
        const idx = (c.planIds || []).indexOf(reg.id);
        gruposActivos[c.nombre].planes.push({ reg, esPlanActiva: c.planActivaId === reg.id, idx });
      });
    }

    Object.entries(cursosArchivadosMap).forEach(([yearId, yearData]) => {
      const cursos = Array.isArray(yearData?.cursos) ? yearData.cursos : [];
      const cursosDePlan = cursos.filter(c => (c.planIds || []).includes(reg.id));
      if (!cursosDePlan.length) return;
      encontrado = true;
      if (!gruposArchivados[yearId]) gruposArchivados[yearId] = {};
      cursosDePlan.forEach(c => {
        if (!gruposArchivados[yearId][c.nombre]) gruposArchivados[yearId][c.nombre] = { cursoId: c.id, planes: [] };
        const idx = (c.planIds || []).indexOf(reg.id);
        gruposArchivados[yearId][c.nombre].planes.push({ reg, esPlanActiva: false, idx });
      });
    });

    if (!encontrado) sinCurso.push(reg);
  });

  Object.values(gruposActivos).forEach(g => g.planes.sort((a, b) => a.idx - b.idx));
  Object.values(gruposArchivados).forEach(byCourse => {
    Object.values(byCourse).forEach(g => g.planes.sort((a, b) => a.idx - b.idx));
  });

  const nombresCursoActivos = Object.keys(gruposActivos).sort();
  const yearsArchivados = Object.keys(gruposArchivados).sort((a, b) => String(b).localeCompare(String(a)));

  // ── Renderizar función de card ────────────────────────────────
  const _renderCard = (reg, esPlanActiva, cursoId, raNum, totalPlanes, archivada) => {
    const dg = reg.planificacion?.datosGenerales || {};
    const ra = reg.planificacion?.ra || {};
    const ec = reg.planificacion?.elementosCapacidad || [];
    const acts = reg.planificacion?.actividades || [];
    const horasTotal = reg.planificacion?.horasTotal || 0;
    const resumenRA = ra.descripcion
      ? ra.descripcion.substring(0, 120) + (ra.descripcion.length > 120 ? '…' : '')
      : 'Sin descripción del RA';

    // Días del horario
    const _DIAS_ORD = ['lunes','martes','miércoles','miercoles','jueves','viernes','sábado','sabado'];
    const diasClase = dg.diasClase || {};
    const diasActivos = Object.entries(diasClase)
      .filter(([, v]) => v && v.activo)
      .sort((a, b) => {
        const ai = _DIAS_ORD.findIndex(d => a[0].toLowerCase().replace('é','e').replace('á','a').startsWith(d.replace('é','e').replace('á','a').slice(0,3)));
        const bi = _DIAS_ORD.findIndex(d => b[0].toLowerCase().replace('é','e').replace('á','a').startsWith(d.replace('é','e').replace('á','a').slice(0,3)));
        return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi);
      })
      .map(([d, v]) => `${d.charAt(0).toUpperCase() + d.slice(1)}${v.horas ? ' ('+v.horas+'h)' : ''}`)
      .join(' · ');
    const diasChip = diasActivos
      ? `<div class="pln-card-dias"><span class="material-icons">event_repeat</span>${escHTML(diasActivos)}</div>`
      : '';

    const card = document.createElement('div');
    card.className = 'pln-card' + (esPlanActiva ? ' pln-card-activa' : '');
    const raLabel = cursoId && raNum ? `<span class="pln-badge-ra">#${raNum}</span>` : '';
    const moveButtons = cursoId && totalPlanes > 1 ? `
      <div class="pln-card-move">
        <button class="btn-pln-move" onclick="moverPlanEnCurso('${cursoId}','${reg.id}',-1)" title="Mover arriba" ${raNum === 1 ? 'disabled' : ''}>
          <span class="material-icons">arrow_upward</span>
        </button>
        <button class="btn-pln-move" onclick="moverPlanEnCurso('${cursoId}','${reg.id}',1)" title="Mover abajo" ${raNum === totalPlanes ? 'disabled' : ''}>
          <span class="material-icons">arrow_downward</span>
        </button>
      </div>` : '';
    card.innerHTML = `
      <div class="pln-card-date">
        ${raLabel}
        <span class="material-icons">schedule</span>
        ${escHTML(reg.fechaGuardadoLabel || reg.fechaGuardado)}
        ${esPlanActiva ? '<span class="pln-badge-activa"><span class="material-icons" style="font-size:11px;">star</span>Activa</span>' : ''}
        ${moveButtons}
      </div>
      <div class="pln-card-modulo">${escHTML(dg.moduloFormativo || 'Sin módulo')}</div>
      <div class="pln-card-meta">
        <span><span class="material-icons">person</span>${escHTML(dg.nombreDocente || '—')}</span>
        <span><span class="material-icons">school</span>${escHTML(dg.nombreBachillerato || '—')}</span>
        ${dg.fechaInicio ? '<span><span class="material-icons">date_range</span>' +
        escHTML(dg.fechaInicio) + ' → ' + escHTML(dg.fechaTermino || '') + '</span>' : ''}
      </div>
      ${diasChip}
      <div class="pln-card-ra">${escHTML(resumenRA)}</div>
      <div class="pln-card-chips">
        ${ec.length ? '<span class="pln-chip pln-chip-ec"><span class="material-icons" style="font-size:12px;">layers</span>' + ec.length + ' EC</span>' : ''}
        ${acts.length ? '<span class="pln-chip pln-chip-acts"><span class="material-icons" style="font-size:12px;">event_note</span>' + acts.length + ' actividades</span>' : ''}
        ${horasTotal ? '<span class="pln-chip pln-chip-pts"><span class="material-icons" style="font-size:12px;">schedule</span>' + horasTotal + 'h</span>' : ''}
        ${dg.valorRA ? '<span class="pln-chip pln-chip-pts"><span class="material-icons" style="font-size:12px;">star</span>' + dg.valorRA + ' pts</span>' : ''}
      </div>
      <button class="pln-card-comentarios-badge" data-plan-id="${reg.id}" onclick="event.stopPropagation();_verComentariosPlanDocente('${reg.id}')"
        style="display:none;align-items:center;gap:5px;background:#EDE7F6;color:#4527A0;border:1px solid #D1C4E9;border-radius:8px;padding:5px 10px;font-size:0.75rem;font-weight:700;cursor:pointer;margin-bottom:8px;width:100%;justify-content:center;font-family:inherit;">
        <span class="material-icons" style="font-size:15px;">forum</span>
        <span class="pln-coment-count">0</span> comentario(s) de tu coordinador(a)
      </button>
      <div class="pln-card-actions" style="display:grid;grid-template-columns:1fr 1fr;gap:6px;">
        <button class="btn-pln-cargar" onclick="cargarPlanificacionGuardada('${reg.id}')" style="width:100%;justify-content:center;">
          <span class="material-icons">folder_open</span> Cargar
        </button>
        ${archivada
          ? `<button onclick="desarchivarPlanificacion('${reg.id}')" title="Desarchivar" style="width:100%;justify-content:center;background:#EDE7F6;color:#4527A0;border:1px solid #D1C4E9;border-radius:8px;padding:4px 10px;font-size:0.78rem;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;gap:4px;">
              <span class="material-icons" style="font-size:15px;">unarchive</span> Desarchivar</button>`
          : `<button class="btn-pln-asignar" onclick="asignarPlanACurso('${reg.id}')" title="Asignar a un curso" style="width:100%;justify-content:center;">
              <span class="material-icons">link</span> Asignar curso</button>`}
        <button class="btn-pln-dup" onclick="abrirDuplicarPlan('${reg.id}')" title="Duplicar planificación" style="width:100%;justify-content:center;">
          <span class="material-icons">content_copy</span> Duplicar
        </button>
        <button class="btn-pln-export" onclick="exportarPlanDesdeListado('${reg.id}')" title="Exportar planificación RA a Word" style="width:100%;justify-content:center;background:#E3F2FD;color:#1565C0;border:1px solid #90CAF9;border-radius:8px;padding:4px 10px;font-size:0.78rem;cursor:pointer;display:inline-flex;align-items:center;gap:4px;">
          <span class="material-icons" style="font-size:15px;">description</span> Word RA
        </button>
        <button class="btn-pln-export" onclick="exportarDiariasDesdeListado('${reg.id}')" title="Exportar planificaciones diarias a Word" style="width:100%;justify-content:center;background:#FFF3E0;color:#E65100;border:1px solid #FFCC80;border-radius:8px;padding:4px 10px;font-size:0.78rem;cursor:pointer;display:inline-flex;align-items:center;gap:4px;">
          <span class="material-icons" style="font-size:15px;">event_note</span> Word Diarias
        </button>
        ${archivada ? '' : `<button onclick="archivarPlanificacion('${reg.id}')" title="Archivar planificación" style="width:100%;justify-content:center;grid-column:1/-1;background:#F5F5F5;color:#546E7A;border:1px solid #E0E0E0;border-radius:8px;padding:6px 10px;font-size:0.8rem;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;gap:6px;font-family:inherit;">
          <span class="material-icons" style="font-size:15px;">archive</span> Archivar</button>`}
        <button onclick="cerrarPanelBiblioteca?.();cargarPlanEnPaso5('${reg.id}')" title="Ver planificaciones diarias de esta planificación" style="width:100%;justify-content:center;grid-column:1/-1;background:#E0F2F1;color:#00695C;border:1.5px solid #80CBC4;border-radius:8px;padding:6px 10px;font-size:0.8rem;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;gap:6px;font-family:inherit;">
          <span class="material-icons" style="font-size:15px;">today</span> Ver Planificaciones Diarias
        </button>
        <button class="btn-pln-del" onclick="eliminarPlanificacionGuardada('${reg.id}')" title="Eliminar" style="width:100%;justify-content:center;grid-column:1/-1;">
          <span class="material-icons">delete_outline</span>
        </button>
      </div>`;
    return card;
  };

  // ── Sección de grupo ──────────────────────────────────────────
  const _renderGrupo = (titulo, icono, color, planes, cursoId) => {
    const section = document.createElement('div');
    section.className = 'pln-grupo';
    const header = document.createElement('div');
    header.className = 'pln-grupo-header';
    header.innerHTML = `
      <span class="material-icons" style="color:${color};">${icono}</span>
      <span class="pln-grupo-nombre">${escHTML(titulo)}</span>
      <span class="pln-grupo-count">${planes.length} plan${planes.length !== 1 ? 'es' : ''}</span>
      <span class="material-icons pln-grupo-chevron">expand_more</span>`;
    // Toggle colapsar
    header.addEventListener('click', () => {
      section.classList.toggle('pln-grupo-collapsed');
    });
    section.appendChild(header);
    const cardsWrap = document.createElement('div');
    cardsWrap.className = 'pln-grupo-cards';
    planes.forEach(({ reg, esPlanActiva }, i) => {
      cardsWrap.appendChild(_renderCard(reg, esPlanActiva, cursoId, i + 1, planes.length, false));
    });
    section.appendChild(cardsWrap);
    return section;
  };

  // Cursos del ciclo activo (arriba)
  nombresCursoActivos.forEach(nombre => {
    const g = gruposActivos[nombre];
    grid.appendChild(_renderGrupo(nombre, 'class', '#1565C0', g.planes, g.cursoId));
  });

  // Cursos archivados por ciclo (panel expandible debajo)
  if (yearsArchivados.length) {
    const panel = document.createElement('div');
    panel.className = 'pln-grupo';
    panel.style.borderColor = '#D1C4E9';
    panel.style.background = '#F7F3FF';
    panel.style.marginTop = '12px';
    panel.innerHTML = '<div class="pln-grupo-header" style="cursor:default;">'
      + '<span class="material-icons" style="color:#6A1B9A;">inventory_2</span>'
      + '<span class="pln-grupo-nombre" style="color:#4A148C;">Ciclos archivados</span>'
      + '<span class="pln-grupo-count" style="background:#EDE7F6;color:#5E35B1;">' + yearsArchivados.length + ' ciclo' + (yearsArchivados.length !== 1 ? 's' : '') + '</span>'
      + '</div>';

    const content = document.createElement('div');
    content.className = 'pln-grupo-cards';

    yearsArchivados.forEach(yearId => {
      const byCourse = gruposArchivados[yearId] || {};
      const courseNames = Object.keys(byCourse).sort();
      const details = document.createElement('details');
      details.style.cssText = 'background:#fff;border:1px solid #E1D5F6;border-radius:10px;padding:8px 10px;margin-bottom:8px;';
      details.innerHTML = '<summary style="cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;list-style:none;">'
        + '<span style="font-size:0.88rem;font-weight:800;color:#4527A0;">' + escHTML(yearId) + '</span>'
        + '<span style="font-size:0.72rem;color:#6A1B9A;background:#F3E5F5;border-radius:999px;padding:3px 8px;font-weight:700;white-space:nowrap;margin-left:auto;">'
        + courseNames.length + ' curso' + (courseNames.length !== 1 ? 's' : '') + '</span>'
        + '</summary>';

      const wrap = document.createElement('div');
      wrap.style.marginTop = '8px';

      courseNames.forEach(nombre => {
        const g = byCourse[nombre];
        const section = _renderGrupo(nombre, 'class', '#7E57C2', g.planes, g.cursoId);
        section.style.marginBottom = '8px';
        wrap.appendChild(section);
      });

      if (!courseNames.length) {
        wrap.innerHTML = '<div style="font-size:0.78rem;color:#9E9E9E;padding:6px 4px;">Sin cursos vinculados en este ciclo.</div>';
      }

      details.appendChild(wrap);
      content.appendChild(details);
    });

    panel.appendChild(content);
    grid.appendChild(panel);
  }

  // Sin curso asignado
  if (sinCurso.length > 0) {
    grid.appendChild(_renderGrupo('Sin curso asignado', 'folder_off', '#78909C',
      sinCurso.map(reg => ({ reg, esPlanActiva: false, idx: 0 })), null));
  }

  // Planificaciones archivadas individualmente (independiente de si el curso está archivado)
  if (archivadosFiltrados.length > 0) {
    const panel = document.createElement('div');
    panel.className = 'pln-grupo';
    panel.style.borderColor = '#E0E0E0';
    panel.style.background = '#FAFAFA';
    panel.style.marginTop = '12px';
    const header = document.createElement('div');
    header.className = 'pln-grupo-header';
    header.innerHTML = `
      <span class="material-icons" style="color:#546E7A;">archive</span>
      <span class="pln-grupo-nombre" style="color:#424242;">Planificaciones archivadas</span>
      <span class="pln-grupo-count" style="background:#EEEEEE;color:#616161;">${archivadosFiltrados.length} plan${archivadosFiltrados.length !== 1 ? 'es' : ''}</span>
      <span class="material-icons pln-grupo-chevron">expand_more</span>`;
    header.addEventListener('click', () => panel.classList.toggle('pln-grupo-collapsed'));
    panel.classList.add('pln-grupo-collapsed');
    panel.appendChild(header);
    const cardsWrap = document.createElement('div');
    cardsWrap.className = 'pln-grupo-cards';
    archivadosFiltrados.forEach(reg => {
      cardsWrap.appendChild(_renderCard(reg, false, null, null, 0, true));
    });
    panel.appendChild(cardsWrap);
    grid.appendChild(panel);
  }

  _cargarComentariosDeMisPlanes();
}

/** Archiva una planificación individual: deja de mostrarse agrupada por curso y pasa al apartado "Planificaciones archivadas" */
function archivarPlanificacion(id) {
  const biblio = cargarBiblioteca();
  const reg = (biblio.items || []).find(i => i.id === id);
  if (!reg) return;
  reg.archivada = true;
  reg.archivadaEn = new Date().toISOString();
  persistirBiblioteca(biblio);
  renderizarBiblioteca();
  mostrarToast('Planificación archivada', 'info');
}

/** Devuelve una planificación archivada a su agrupación normal por curso */
function desarchivarPlanificacion(id) {
  const biblio = cargarBiblioteca();
  const reg = (biblio.items || []).find(i => i.id === id);
  if (!reg) return;
  reg.archivada = false;
  delete reg.archivadaEn;
  persistirBiblioteca(biblio);
  renderizarBiblioteca();
  mostrarToast('Planificación desarchivada', 'success');
}

// ── Comentarios de coordinadora sobre planificaciones (lado docente) ──────
let _planComentariosPorId = {}; // { planId: [ {id, texto, coordNombre, fecha, leido}, ... ] }

/** Trae en segundo plano los comentarios que la coordinadora dejó en las planificaciones propias y pinta los badges */
async function _cargarComentariosDeMisPlanes() {
  if (!window.currentUser || !window.currentUser.uid || !window.firebase || !firebase.firestore || !db) return;
  try {
    const snap = await db.collection('users').doc(window.currentUser.uid).collection('plan_comentarios')
      .orderBy('fecha', 'desc').get();
    _planComentariosPorId = {};
    snap.forEach(doc => {
      const c = { id: doc.id, ...doc.data() };
      (_planComentariosPorId[c.planId] = _planComentariosPorId[c.planId] || []).push(c);
    });
    _pintarBadgesComentariosPlan();
  } catch (e) {
    console.warn('[Comentarios] Error cargando comentarios de planificaciones:', e);
  }
}

function _pintarBadgesComentariosPlan() {
  document.querySelectorAll('.pln-card-comentarios-badge').forEach(el => {
    const planId = el.dataset.planId;
    const coms = _planComentariosPorId[planId] || [];
    if (!coms.length) { el.style.display = 'none'; return; }
    el.style.display = 'flex';
    const conteo = el.querySelector('.pln-coment-count');
    if (conteo) conteo.textContent = coms.length;
    const noLeidos = coms.some(c => !c.leido);
    el.style.background = noLeidos ? '#FFF3E0' : '#EDE7F6';
    el.style.color = noLeidos ? '#E65100' : '#4527A0';
    el.style.borderColor = noLeidos ? '#FFB74D' : '#D1C4E9';
  });
}

/** Abre un modal de solo lectura con los comentarios que la coordinadora dejó sobre una planificación, y los marca como leídos */
async function _verComentariosPlanDocente(planId) {
  const coms = (_planComentariosPorId[planId] || []).slice();
  const overlay = document.getElementById('modal-overlay');
  const title = document.getElementById('modal-title');
  const body = document.getElementById('modal-body');
  if (!overlay || !body) return;
  if (title) title.textContent = 'Comentarios de tu coordinador(a)';

  body.innerHTML = !coms.length
    ? '<p style="color:#9E9E9E;text-align:center;padding:20px;">Sin comentarios todavía.</p>'
    : '<div style="display:flex;flex-direction:column;gap:10px;">' + coms.map(c => {
        const fecha = c.fecha ? new Date(c.fecha).toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
        return '<div style="background:#F5F5F5;border:1px solid #E0E0E0;border-radius:10px;padding:10px 12px;">'
          + '<div style="font-weight:700;font-size:0.85rem;color:#1565C0;">' + escHTML(c.coordNombre || 'Coordinador(a)') + '</div>'
          + '<div style="font-size:0.72rem;color:#9E9E9E;margin-bottom:6px;">' + fecha + '</div>'
          + '<div style="font-size:0.85rem;color:#212121;white-space:pre-wrap;">' + escHTML(c.texto || '') + '</div>'
          + '</div>';
      }).join('') + '</div>';

  _usarFooterDinamico('<button class="btn-secundario" onclick="cerrarModalBtn()">Cerrar</button>');
  overlay.classList.remove('hidden');
  document.body.style.overflow = 'hidden';

  const noLeidos = coms.filter(c => !c.leido);
  if (noLeidos.length && window.currentUser) {
    try {
      const batch = db.batch();
      noLeidos.forEach(c => {
        const ref = db.collection('users').doc(window.currentUser.uid).collection('plan_comentarios').doc(c.id);
        batch.update(ref, { leido: true });
        c.leido = true;
        const original = (_planComentariosPorId[planId] || []).find(x => x.id === c.id);
        if (original) original.leido = true;
      });
      await batch.commit();
      _pintarBadgesComentariosPlan();
    } catch (e) {
      console.warn('[Comentarios] Error marcando como leído:', e);
    }
  }
}

/** Mueve una planificación arriba (-1) o abajo (+1) dentro de un curso */
function moverPlanEnCurso(cursoId, planId, dir) {
  cargarCalificaciones();
  const curso = calState.cursos[cursoId];
  if (!curso || !curso.planIds) return;
  const idx = curso.planIds.indexOf(planId);
  if (idx < 0) return;
  const newIdx = idx + dir;
  if (newIdx < 0 || newIdx >= curso.planIds.length) return;
  // Intercambiar posiciones
  [curso.planIds[idx], curso.planIds[newIdx]] = [curso.planIds[newIdx], curso.planIds[idx]];
  guardarCalificaciones();
  renderizarBiblioteca();
  mostrarToast('Orden actualizado (RA' + (newIdx + 1) + ')', 'success');
}

/** Escapa HTML básico (helper local para la biblioteca) */



function escHTML(s) {



  return String(s || '')



    .replace(/&/g, '&amp;').replace(/</g, '&lt;')



    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');



}







