const DIARIAS_KEY = 'planificadorRA_diarias_v1';







/** Estado de las planificaciones diarias generadas/editadas */



let estadoDiarias = {



  sesiones: {} // { actividadId: { inicio:{...}, desarrollo:{...}, cierre:{...}, estrategias:'', recursos:'', tiempos:{ini:20,des:60,cie:20} } }



};







function cargarDiarias() {
  try {
    const raw = localStorage.getItem(DIARIAS_KEY);
    if (raw) {
      estadoDiarias = JSON.parse(raw);
      // Si hay datos en local y Firebase aún no tiene chunks, subir ahora
      if (window._diariasFbVacio && Object.keys(estadoDiarias.sesiones || {}).length > 0) {
        window._diariasFbVacio = false;
        setTimeout(_syncDiariasChunks, 500);
      }
    }
  } catch (e) { estadoDiarias = { sesiones: {} }; }
}







function persistirDiarias() {
  localStorage.setItem(DIARIAS_KEY, JSON.stringify(estadoDiarias));
  if (window.currentUser) _syncDiariasChunks();
}

// Sincroniza estadoDiarias a Firebase en chunks (evita límite de 1MB por doc)
function _syncDiariasChunks() {
  if (!window.currentUser) return;
  const uid = window.currentUser.uid;
  const base = db.collection('users').doc(uid).collection('data');
  const sesionIds = Object.keys(estadoDiarias.sesiones || {});
  const chunks = [];
  let currentChunk = {};
  let currentSize = 0;
  for (const id of sesionIds) {
    const s = JSON.stringify(estadoDiarias.sesiones[id]);
    if (currentSize + s.length > 700000 && Object.keys(currentChunk).length > 0) {
      chunks.push(currentChunk);
      currentChunk = {};
      currentSize = 0;
    }
    currentChunk[id] = estadoDiarias.sesiones[id];
    currentSize += s.length;
  }
  if (Object.keys(currentChunk).length > 0) chunks.push(currentChunk);
  if (chunks.length === 0) chunks.push({});

  const meta = { totalChunks: chunks.length, updatedAt: Date.now() };
  base.doc('diarias_meta').set({ payload: JSON.stringify(meta) })
    .catch(e => console.warn('Sync diarias_meta error:', e));
  chunks.forEach((chunk, i) => {
    base.doc('diarias_chunk_' + i).set({ payload: JSON.stringify({ sesiones: chunk }) })
      .catch(e => console.warn('Sync diarias_chunk_' + i + ' error:', e));
  });
  // Eliminar chunks sobrantes de guardados anteriores con más chunks
  for (let i = chunks.length; i < 10; i++) {
    base.doc('diarias_chunk_' + i).delete().catch(() => {});
  }
}







function guardarTodasDiarias() {



  // Leer todos los textareas y volcar al estado



  (planificacion.actividades || []).forEach(act => {



    const s = estadoDiarias.sesiones[act.id] || {};



    const read = (campo, sub) => {



      const el = document.getElementById(`pd-${campo}-${sub}-${act.id}`);



      return el ? el.value : (s[campo]?.[sub] || '');



    };



    const readT = (m) => {



      const el = document.getElementById(`pd-t-${m}-${act.id}`);



      return el ? parseInt(el.value) || (m === 'ini' ? 20 : m === 'des' ? 55 : 15) : (s.tiempos?.[m] || (m === 'ini' ? 20 : m === 'des' ? 55 : 15));



    };



    const readSec = (id, fbk) => { const el = document.getElementById(id); return el ? el.value : (fbk || ''); };







    estadoDiarias.sesiones[act.id] = {



      inicio: {



        apertura: read('inicio', 'apertura'),



        encuadre: read('inicio', 'encuadre'),



        organizacion: read('inicio', 'organizacion')



      },



      desarrollo: {



        procedimental: read('desarrollo', 'procedimental'),



        conceptual: read('desarrollo', 'conceptual'),

        pasos: read('desarrollo', 'pasos')



      },



      cierre: {



        sintesis: read('cierre', 'sintesis'),



        conexion: read('cierre', 'conexion'),



        proximopaso: read('cierre', 'proximopaso')



      },



      estrategias: readSec(`pd-estrategias-${act.id}`, s.estrategias),



      recursos: readSec(`pd-recursos-${act.id}`, s.recursos),

      recursoUrl: readSec(`pd-recurso-url-${act.id}`, s.recursoUrl),

      tiempos: { ini: readT('ini'), des: readT('des'), cie: readT('cie') },

      tipo: readSec(`pd-tipo-${act.id}`, s.tipo),

      estrategiaCorta: readSec(`pd-estrategiaCorta-${act.id}`, s.estrategiaCorta),

      intencionEducativa: readSec(`pd-intencionEducativa-${act.id}`, s.intencionEducativa),

      diversidad: {

        apoyos: read('diversidad', 'apoyos'),

        adaptaciones: read('diversidad', 'adaptaciones'),

        estrategiasInclusivas: read('diversidad', 'estrategiasInclusivas'),

        adaptacionesEspecificas: read('diversidad', 'adaptacionesEspecificas')

      },

      contenidos: {

        conceptual: read('contenidos', 'conceptual'),

        procedimental: read('contenidos', 'procedimental'),

        actitudinal: read('contenidos', 'actitudinal')

      }



    };



  });



  persistirDiarias();



  mostrarToast('Planificaciones diarias guardadas', 'info');



}







