// BOTÓN GENERAR INDIVIDUAL



// ----------------------------------------------------------------




/** Regenera el instrumento de evaluación de una actividad y actualiza su sección en la tarjeta de sesión */
function _regenerarInstrumentoEnCard(act, ec) {
  const nivel = ec?.nivelBloom || ec?.nivel || 'aplicacion';
  act.instrumento = generarInstrumento(act, nivel);
  guardarBorrador();
  const body = document.getElementById(`pd-instrumento-body-${act.id}`);
  if (body) {
    body.innerHTML = _renderInstrumentoHTML(act.instrumento);
  }
  const label = document.getElementById(`pd-instrumento-label-${act.id}`);
  if (label) label.textContent = act.instrumento?.tipoLabel || 'Sin instrumento';
}

// ════════════════════════════════════════════════════════════════════
// GENERAR SESIÓN DIARIA CON GROQ — PROMPT PERSONALIZADO
// ════════════════════════════════════════════════════════════════════
// Normaliza la respuesta libre de la IA para "tipo" a uno de los 3 valores válidos del <select>
function _normalizarTipoSesion(valor) {
  const v = (valor || '').toLowerCase();
  if (!v) return '';
  if (v.includes('par')) return 'Por Equipos (en pares)';
  if (v.includes('equipo') || v.includes('grupo')) return 'Por Equipo';
  if (v.includes('individual')) return 'Individual';
  return '';
}

async function _generarSesionConIA(actId, act, ec) {
  const dg = planificacion.datosGenerales || {};
  const ra = planificacion.ra || {};
  const horasAct = ec ? (ec.horasAsignadas / Math.max(1, (planificacion.actividades || []).filter(a => a.ecCodigo === ec.codigo).length)) : 1.5;
  const minTotal = Math.round((horasAct || 1.5) * 60);
  const minInicio = Math.round(minTotal * 0.20);
  const minDesarr = Math.round(minTotal * 0.60);
  const minCierre = minTotal - minInicio - minDesarr;

  // Botón: estado cargando
  const btn = document.querySelector(`[onclick*="generarSesion('${actId}')"]`);
  const _setBtnEstado = (icono, texto) => {
    if (btn) btn.innerHTML = `<span class="material-icons" style="font-size:14px;animation:spin 1s linear infinite;">${icono}</span> ${texto}`;
  };
  if (btn) btn.disabled = true;
  _setBtnEstado('hourglass_top', 'Conectando...');
  mostrarToast('🧠 Generando sesión personalizada con IA...', 'info');

  const prompt = await _getPromptResuelto('prompt_sesion', {
    moduloFormativo: dg.moduloFormativo || '',
    familiaProfesional: dg.familiaProfesional || '',
    actividad: act.enunciado,
    ecEnunciado: ec?.enunciado || '',
    nivelBloom: ec?.nivel || 'aplicación',
    minTotal, minInicio, minDesarrollo: minDesarr, minCierre,
    contenidosConceptualesRA: ra.contenidosConceptuales || '',
    contenidosProcedimentalesRA: ra.contenidosProcedimentales || '',
    contenidosActitudinalesRA: ra.contenidosActitudinales || ''
  });

  try {
    let data = null;
    // Intentar con Groq primero
    if (getGroqKey()) {
      try {
        _setBtnEstado('hourglass_top', 'Groq...');
        data = await _llamarGroqConFallback(prompt, 'Generando sesión', 3000);
      } catch (eGroq) {
        console.warn('[IA] Sesión falló en Groq:', eGroq.message);
        const esLimite = eGroq.message?.includes('rate_limit') || eGroq.message?.includes('cuota');
        _setBtnEstado('hourglass_top', esLimite ? 'Groq ocupado, usando alternativa...' : 'Groq falló, usando alternativa...');
        mostrarToast('⚠️ Groq con límite de uso. Probando OpenRouter...', 'warning');
      }
    }
    // Si Groq falló, intentar con Gemini
    if (!data && getGeminiKey()) {
      try {
        _setBtnEstado('hourglass_top', 'Gemini...');
        mostrarToast('🟡 Generando sesión con Gemini...', 'info');
        data = await _llamarGemini(prompt, 3000);
      } catch (eGemini) {
        console.warn('[IA] Sesión falló en Gemini:', eGemini.message);
        _setBtnEstado('hourglass_top', 'Gemini ocupado, usando alternativa...');
      }
    }
    // Si Gemini también falló, intentar con OpenRouter
    if (!data && getOpenRouterKey()) {
      _setBtnEstado('hourglass_top', 'Buscando modelo disponible...');
      mostrarToast('🔵 Generando sesión con OpenRouter...', 'info');
      data = await _llamarOpenRouterConFallback(prompt, getOpenRouterKey(), 'Generando sesión', 4096, 60000);
    }
    if (!data) throw new Error('Sin respuesta de IA');

    // Normaliza un campo: convierte arrays u objetos a texto legible
    const toStr = (val) => {
      if (!val) return '';
      if (typeof val === 'string') return val;
      if (Array.isArray(val)) return val.map(item => {
        if (typeof item === 'string') return item;
        if (typeof item === 'object' && item) {
          // Convertir objeto a "clave: valor" líneas legibles
          return Object.entries(item).map(([k, v]) => `${k}: ${typeof v === 'string' ? v : String(v)}`).join('\n');
        }
        return String(item);
      }).join('\n\n');
      if (typeof val === 'object') {
        // Convertir objeto a líneas legibles clave: valor
        return Object.entries(val).map(([k, v]) => {
          if (typeof v === 'string') return `${k}: ${v}`;
          if (Array.isArray(v)) return `${k}:\n${toStr(v)}`;
          if (typeof v === 'object' && v) return `${k}: ${Object.entries(v).map(([k2, v2]) => `${k2}: ${v2}`).join(', ')}`;
          return `${k}: ${String(v)}`;
        }).join('\n');
      }
      return String(val);
    };

    // Si la IA devolvió sesionDiaria anidado (otro formato), usar ese
    let d = data.sesionDiaria || data;

    // Si la IA no devolvió las claves esperadas (apertura, procedimental, etc.)
    // normalizar: convertir cualquier formato a texto legible en los campos esperados
    if (!d.apertura && !d.procedimental && !d.sintesis) {
      // Caso especial: {detalles: [...]} — expandir el array
      if (d.detalles && Array.isArray(d.detalles)) {
        d = { apertura: toStr(d.detalles) };
      }
      const entries = Object.entries(d);
      if (entries.length > 0) {
        const norm = {};
        // Convertir todo a texto limpio sin JSON
        const textos = entries.map(([k, v]) => {
          const texto = typeof v === 'string' ? v : toStr(v);
          // No prefijar con la clave si es genérica como "detalles" o "respuesta"
          if (['detalles', 'respuesta', 'resultado', 'contenido', 'data'].includes(k.toLowerCase())) return texto;
          return `${k}: ${texto}`;
        });
        const total = textos.length;
        if (total >= 7) {
          // Muchos campos: distribuir entre inicio/desarrollo/cierre
          const corte1 = Math.max(1, Math.ceil(total * 0.3));
          const corte2 = Math.max(corte1 + 1, Math.ceil(total * 0.75));
          norm.apertura = textos.slice(0, corte1).join('\n\n');
          norm.encuadre = textos.slice(corte1, corte1 + 1).join('\n\n');
          norm.organizacion = textos.slice(corte1 + 1, corte1 + 2).join('\n\n');
          norm.procedimental = textos.slice(corte1 + 2, corte2).join('\n\n');
          norm.conceptual = textos.slice(corte2, corte2 + 1).join('\n\n');
          norm.sintesis = textos.slice(corte2 + 1).join('\n\n');
        } else {
          // Pocos campos: todo al campo apertura, el resto usa fallback local
          norm.apertura = textos.join('\n\n');
        }
        d = norm;
        console.log('[IA] Sesión normalizada desde formato libre:', total, 'campos →', Object.keys(norm));
      }
    }

    // Generación local de respaldo para campos vacíos
    const local = generarContenidoSesion(act, ec, horasAct);

    const tIni = minInicio, tDes = minDesarr, tCie = minCierre;
    const gen = {
      inicio: {
        apertura:      toStr(d.apertura)      || local.inicio.apertura,
        encuadre:      toStr(d.encuadre)      || local.inicio.encuadre,
        organizacion:  toStr(d.organizacion)  || local.inicio.organizacion
      },
      desarrollo: {
        procedimental: (estadoDiarias.sesiones[actId]?.desarrollo?.procedimental) || '',
        conceptual:    toStr(d.conceptual)    || local.desarrollo.conceptual,
        pasos:         toStr(d.pasos)         || local.desarrollo.pasos
      },
      cierre: {
        sintesis:      toStr(d.sintesis)      || local.cierre.sintesis,
        conexion:      toStr(d.conexion || d.conceptual) || local.cierre.conexion,
        proximopaso:   toStr(d.proximopaso)   || local.cierre.proximopaso
      },
      estrategias: toStr(d.estrategias) || local.estrategias,
      recursos: ra.recursosDid || local.recursos,
      tiempos: { ini: tIni, des: tDes, cie: tCie },
      tipo: _normalizarTipoSesion(d.tipo) || local.tipo,
      estrategiaCorta: toStr(d.estrategiaCorta) || local.estrategiaCorta,
      intencionEducativa: toStr(d.intencionEducativa) || local.intencionEducativa,
      diversidad: {
        apoyos: toStr(d.apoyosPosibles) || local.diversidad.apoyos,
        adaptaciones: toStr(d.adaptaciones) || local.diversidad.adaptaciones,
        estrategiasInclusivas: toStr(d.estrategiasInclusivas) || local.diversidad.estrategiasInclusivas,
        adaptacionesEspecificas: toStr(d.adaptacionesEspecificas) || local.diversidad.adaptacionesEspecificas
      },
      contenidos: {
        conceptual: toStr(d.contenidoConceptual) || local.contenidos.conceptual,
        procedimental: toStr(d.contenidoProcedimental) || local.contenidos.procedimental,
        actitudinal: toStr(d.contenidoActitudinal) || local.contenidos.actitudinal
      }
    };

    // Guardar datos normalizados en sesionIA y en estadoDiarias
    act.sesionIA = d;
    estadoDiarias.sesiones[actId] = gen;
    persistirDiarias();

    // Actualizar textareas en pantalla
    const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = val; };
    set(`pd-inicio-apertura-${actId}`, gen.inicio.apertura);
    set(`pd-inicio-encuadre-${actId}`, gen.inicio.encuadre);
    set(`pd-inicio-organizacion-${actId}`, gen.inicio.organizacion);
    set(`pd-desarrollo-pasos-${actId}`, gen.desarrollo.pasos);
    set(`pd-desarrollo-conceptual-${actId}`, gen.desarrollo.conceptual);
    set(`pd-cierre-sintesis-${actId}`, gen.cierre.sintesis);
    set(`pd-cierre-conexion-${actId}`, gen.cierre.conexion);
    set(`pd-cierre-proximopaso-${actId}`, gen.cierre.proximopaso);
    set(`pd-estrategias-${actId}`, gen.estrategias);
    set(`pd-recursos-${actId}`, gen.recursos);
    set(`pd-tipo-${actId}`, gen.tipo);
    set(`pd-estrategiaCorta-${actId}`, gen.estrategiaCorta);
    set(`pd-intencionEducativa-${actId}`, gen.intencionEducativa);
    set(`pd-diversidad-apoyos-${actId}`, gen.diversidad.apoyos);
    set(`pd-diversidad-adaptaciones-${actId}`, gen.diversidad.adaptaciones);
    set(`pd-diversidad-estrategiasInclusivas-${actId}`, gen.diversidad.estrategiasInclusivas);
    set(`pd-diversidad-adaptacionesEspecificas-${actId}`, gen.diversidad.adaptacionesEspecificas);
    set(`pd-contenidos-conceptual-${actId}`, gen.contenidos.conceptual);
    set(`pd-contenidos-procedimental-${actId}`, gen.contenidos.procedimental);
    set(`pd-contenidos-actitudinal-${actId}`, gen.contenidos.actitudinal);
    _regenerarInstrumentoEnCard(act, ec);

    guardarTodasDiarias();
    _setBtnEstado('check_circle', '¡Listo!');
    mostrarToast('✅ Sesión generada con IA', 'success');
  } catch (e) {
    console.error('_generarSesionConIA error:', e);
    _setBtnEstado('warning', 'Sin IA, generando local...');
    mostrarToast('⚠️ Error con IA, usando generación local', 'warning');
    // Fallback a generación local
    const ec2 = (planificacion.elementosCapacidad || []).find(e => e.codigo === act.ecCodigo);
    const gen = generarContenidoSesion(act, ec2, horasAct);
    estadoDiarias.sesiones[actId] = gen;
    persistirDiarias();
    guardarTodasDiarias();
    const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = val; };
    const s = gen;
    set(`pd-inicio-apertura-${actId}`, s.inicio.apertura);
    set(`pd-inicio-encuadre-${actId}`, s.inicio.encuadre);
    set(`pd-inicio-organizacion-${actId}`, s.inicio.organizacion);
    set(`pd-desarrollo-pasos-${actId}`, s.desarrollo.pasos);
    set(`pd-desarrollo-conceptual-${actId}`, s.desarrollo.conceptual);
    set(`pd-cierre-sintesis-${actId}`, s.cierre.sintesis);
    set(`pd-cierre-conexion-${actId}`, s.cierre.conexion);
    set(`pd-cierre-proximopaso-${actId}`, s.cierre.proximopaso);
    set(`pd-estrategias-${actId}`, s.estrategias);
    set(`pd-recursos-${actId}`, s.recursos);
    set(`pd-tipo-${actId}`, s.tipo);
    set(`pd-estrategiaCorta-${actId}`, s.estrategiaCorta);
    set(`pd-intencionEducativa-${actId}`, s.intencionEducativa);
    set(`pd-diversidad-apoyos-${actId}`, s.diversidad.apoyos);
    set(`pd-diversidad-adaptaciones-${actId}`, s.diversidad.adaptaciones);
    set(`pd-diversidad-estrategiasInclusivas-${actId}`, s.diversidad.estrategiasInclusivas);
    set(`pd-diversidad-adaptacionesEspecificas-${actId}`, s.diversidad.adaptacionesEspecificas);
    set(`pd-contenidos-conceptual-${actId}`, s.contenidos.conceptual);
    set(`pd-contenidos-procedimental-${actId}`, s.contenidos.procedimental);
    set(`pd-contenidos-actitudinal-${actId}`, s.contenidos.actitudinal);
    _regenerarInstrumentoEnCard(act, ec2);
    mostrarToast('Sesión generada (modo local)', 'info');
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = '<span class="material-icons" style="font-size:14px;">auto_awesome</span> Generar'; }
  }
}

async function generarTodasLasSesiones() {
  const acts = (planificacion.actividades || []).filter(a => !a.esComplementario);
  if (acts.length === 0) { mostrarToast('No hay actividades para generar.', 'warning'); return; }

  const btn = document.getElementById('btn-generar-todas');
  if (btn) { btn.disabled = true; btn.innerHTML = '<span class="material-icons" style="font-size:17px;animation:spin 1s linear infinite;">sync</span> Generando...'; }

  let generadas = 0;
  for (const act of acts) {
    if (act.sesion && (act.sesion.inicio || act.sesion.desarrollo || act.sesion.cierre)) {
      generadas++;
      continue; // Ya tiene contenido, saltar
    }
    await new Promise(resolve => {
      generarSesion(act.id);
      setTimeout(resolve, getGroqKey() || getOpenRouterKey() ? 1800 : 200);
    });
    generadas++;
    if (btn) btn.innerHTML = `<span class="material-icons" style="font-size:17px;">sync</span> ${generadas}/${acts.length}`;
  }

  if (btn) { btn.disabled = false; btn.innerHTML = '<span class="material-icons" style="font-size:17px;">auto_awesome</span> Generar todas'; }
  mostrarToast(`✓ ${generadas} sesiones generadas`, 'success');
}

function generarSesion(actId) {
  const act = (planificacion.actividades || []).find(a => a.id === actId);
  if (!act) return;
  const ec = (planificacion.elementosCapacidad || []).find(e => e.codigo === act.ecCodigo);
  // Si tiene clave de IA, regenerar con IA directamente
  if (getGroqKey() || getOpenRouterKey()) {
    _generarSesionConIA(actId, act, ec);
    return;
  }
  const horasAct = ec ? (ec.horasAsignadas / Math.max(1, (planificacion.actividades || []).filter(a => a.ecCodigo === ec.codigo).length)) : 1.5;







  // Si la actividad tiene sesión generada por IA, usarla; si no, generar local
  let gen;
  if (act.sesionIA) {
    const s = act.sesionIA;
    const minSesion = Math.round((horasAct || 1.5) * 60);
    const tIni = Math.round(minSesion * 0.20);
    const tDes = Math.round(minSesion * 0.60);
    const tCie = minSesion - tIni - tDes;
    gen = {
      inicio: {
        apertura: s.apertura || '',
        encuadre: s.encuadre || '',
        organizacion: s.organizacion || 'Trabajo individual y grupal según la dinámica de la actividad.'
      },
      desarrollo: {
        procedimental: (estadoDiarias.sesiones[actId]?.desarrollo?.procedimental) || s.procedimental || '',
        conceptual: s.conceptual || '',
        pasos: s.pasos || s.procedimental || ''
      },
      cierre: {
        sintesis: s.sintesis || '',
        conexion: s.conceptual || '',
        proximopaso: s.proximopaso || 'Continuar con la siguiente actividad del EC.'
      },
      estrategias: s.estrategias || '',
      recursos: planificacion.ra?.recursosDid || 'Material del módulo, pizarrón, guías de trabajo.',
      tiempos: { ini: tIni, des: tDes, cie: tCie },
      tipo: _normalizarTipoSesion(s.tipo) || 'Individual',
      estrategiaCorta: s.estrategiaCorta || '',
      intencionEducativa: s.intencionEducativa || '',
      diversidad: {
        apoyos: s.apoyosPosibles || '',
        adaptaciones: s.adaptaciones || '',
        estrategiasInclusivas: s.estrategiasInclusivas || '',
        adaptacionesEspecificas: s.adaptacionesEspecificas || ''
      },
      contenidos: {
        conceptual: s.contenidoConceptual || '',
        procedimental: s.contenidoProcedimental || '',
        actitudinal: s.contenidoActitudinal || ''
      }
    };
  } else {
    gen = generarContenidoSesion(act, ec, horasAct);
  }



  estadoDiarias.sesiones[actId] = gen;



  persistirDiarias();







  // Actualizar textareas en vivo



  const s = gen;



  const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = val; };



  set(`pd-inicio-apertura-${actId}`, s.inicio.apertura);



  set(`pd-inicio-encuadre-${actId}`, s.inicio.encuadre);



  set(`pd-inicio-organizacion-${actId}`, s.inicio.organizacion);



  set(`pd-desarrollo-pasos-${actId}`, s.desarrollo.pasos);



  set(`pd-desarrollo-conceptual-${actId}`, s.desarrollo.conceptual);



  set(`pd-cierre-sintesis-${actId}`, s.cierre.sintesis);



  set(`pd-cierre-conexion-${actId}`, s.cierre.conexion);



  set(`pd-cierre-proximopaso-${actId}`, s.cierre.proximopaso);



  set(`pd-estrategias-${actId}`, s.estrategias);



  set(`pd-recursos-${actId}`, s.recursos);
  set(`pd-tipo-${actId}`, s.tipo);
  set(`pd-estrategiaCorta-${actId}`, s.estrategiaCorta);
  set(`pd-intencionEducativa-${actId}`, s.intencionEducativa);
  set(`pd-diversidad-apoyos-${actId}`, s.diversidad.apoyos);
  set(`pd-diversidad-adaptaciones-${actId}`, s.diversidad.adaptaciones);
  set(`pd-diversidad-estrategiasInclusivas-${actId}`, s.diversidad.estrategiasInclusivas);
  set(`pd-diversidad-adaptacionesEspecificas-${actId}`, s.diversidad.adaptacionesEspecificas);
  set(`pd-contenidos-conceptual-${actId}`, s.contenidos.conceptual);
  set(`pd-contenidos-procedimental-${actId}`, s.contenidos.procedimental);
  set(`pd-contenidos-actitudinal-${actId}`, s.contenidos.actitudinal);
  _regenerarInstrumentoEnCard(act, ec);







  const setT = (m, v) => { const el = document.getElementById(`pd-t-${m}-${actId}`); if (el) el.value = v; };



  setT('ini', s.tiempos.ini);



  setT('des', s.tiempos.des);



  setT('cie', s.tiempos.cie);







  guardarTodasDiarias();
  registrarCambio(`Sesión diaria generada: "${act.enunciado?.substring(0, 60) || actId}"`);
  mostrarToast('Sesión generada automáticamente', 'info');



}

