    h += '<div class="motivation-box"><p>' + _e(s1.preg || '') + '</p></div>\n';
    (s1.inputs || []).forEach(function(lbl) { h += '<span class="write-label">' + _e(lbl) + '</span><input class="write-line" type="text" placeholder="Escribe aqu&#237;...">\n'; });
    h += '</div>' + D;
    // S2: Conceptos clave
