// __old_cerrarDiarias__

// ── Mover actividades de un día al siguiente ─────────────────────

function _isoDate(d) {
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

function _fecStr(fechaISO) {
  const d = new Date(fechaISO + 'T12:00:00');
  return d.toLocaleDateString('es-DO', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' });
}

function _actFechaISO(act) {
  return act.fecha instanceof Date ? _isoDate(act.fecha) : String(act.fecha || '').split('T')[0];
}

// Devuelve los días del horario (0=Lun…4=Vie) donde aparece la sección del curso activo
function _diasHorarioDeSeccion(seccion) {
  if (!seccion) return [];
  const horario = cargarHorario().filter(e => e.materia);
  const dias = horario
    .filter(e => e.seccion === seccion || e.materia === seccion)
    .map(e => e.dia);
  return [...new Set(dias)];
}

// Devuelve los días del horario filtrando por materia Y sección a la vez
function _diasHorarioDeMateriaYSeccion(materia, seccion) {
  const horario = cargarHorario().filter(e => e.materia);
  const _norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  const matNorm = _norm(materia);
  const secNorm = _norm(seccion);
  const _palabras = str => str.split(' ').filter(w => w.length > 3);
  const dias = horario.filter(e => {
    const eMat = _norm(e.materia);
    const eSec = _norm(e.seccion || '');
    // Coincidencia de sección exacta
    const secOk = !secNorm || eSec === secNorm;
    // Coincidencia de materia: substring o ≥50% palabras clave en común
    let matOk = false;
    if (!matNorm) { matOk = true; }
    else if (eMat.includes(matNorm) || matNorm.includes(eMat)) { matOk = true; }
    else {
      const wa = _palabras(matNorm), wb = _palabras(eMat);
      const wbSet = new Set(wb);
      const shared = wa.filter(w => wbSet.has(w)).length;
      matOk = Math.min(wa.length, wb.length) > 0 && shared / Math.min(wa.length, wb.length) >= 0.5;
    }
    return secOk && matOk;
  }).map(e => e.dia);
  return [...new Set(dias)];
}

// Próxima fecha después de fechaISO donde la sección tiene clase según el horario
// Si se provee materia, filtra por materia+sección para no confundir materias distintas del mismo grupo
// Si no hay datos de horario, usa mismo día de semana +7 días
function _proximaFechaHorario(fechaISO, seccion, materia) {
  const diasSec = materia
    ? _diasHorarioDeMateriaYSeccion(materia, seccion)
    : _diasHorarioDeSeccion(seccion);
  const base = new Date(fechaISO + 'T12:00:00');
  const next = new Date(base);
  next.setDate(next.getDate() + 1);
  for (let i = 0; i < 60; i++) {
    const horIdx = next.getDay() - 1; // 0=Lun … 4=Vie
    if (diasSec.length > 0) {
      if (horIdx >= 0 && horIdx <= 4 && diasSec.includes(horIdx)) return _isoDate(next);
    } else {
      if (next.getDay() === base.getDay()) return _isoDate(next);
    }
    next.setDate(next.getDate() + 1);
  }
  const fb = new Date(base);
  fb.setDate(fb.getDate() + 7);
  return _isoDate(fb);
}

function abrirMoverDia(fechaInicial) {
  const hoy = fechaInicial || _isoDate(new Date());
  const overlay = document.createElement('div');
  overlay.id = 'mover-dia-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.45);z-index:9000;display:flex;align-items:flex-start;justify-content:center;padding:24px 16px;overflow-y:auto;';
  overlay.innerHTML = `
    <div style="background:var(--color-superficie,#fff);border-radius:16px;padding:24px;max-width:500px;width:100%;box-shadow:0 8px 32px rgba(0,0,0,0.22);margin:auto;" onclick="event.stopPropagation()">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">
        <span class="material-icons" style="color:#0277BD;font-size:24px;">swap_horiz</span>
        <h3 style="margin:0;font-size:1rem;font-weight:800;color:var(--color-texto-primario,#212121);">Mover actividades de un día</h3>
      </div>
      <p style="font-size:0.82rem;color:var(--color-texto-secundario,#757575);margin:0 0 14px;">
        Selecciona el día sin clases. El sistema sugerirá el próximo día que toca cada sección según el horario. Puedes ajustar la fecha de cada actividad individualmente.
      </p>
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:14px;flex-wrap:wrap;">
        <label style="font-size:0.82rem;font-weight:700;color:var(--color-texto-primario,#212121);white-space:nowrap;">Día a omitir:</label>
        <input type="date" id="mover-dia-fecha" value="${hoy}"
          style="flex:1;min-width:140px;padding:8px 12px;border:1.5px solid #B3E5FC;border-radius:8px;font-size:0.9rem;font-family:inherit;background:var(--color-superficie,#fff);color:var(--color-texto-primario,#212121);"
          oninput="_renderMoverDiaLista()" />
      </div>
      <div id="mover-dia-lista"></div>
      <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:16px;">
        <button onclick="cerrarMoverDia()" style="background:none;border:1.5px solid #E0E0E0;color:#757575;border-radius:20px;padding:8px 18px;font-size:0.85rem;cursor:pointer;font-family:inherit;">Cancelar</button>
        <button id="mover-dia-btn" onclick="_ejecutarMoverDia()" disabled
          style="background:#0277BD;color:#fff;border:none;border-radius:20px;padding:8px 20px;font-size:0.85rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px;font-family:inherit;opacity:0.5;">
          <span class="material-icons" style="font-size:16px;">check</span> Confirmar y mover
        </button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  _renderMoverDiaLista();
}

// Recolecta actividades de TODA la biblioteca para una fecha dada
function _actsDeTodasLasPlanesEnFecha(fecha) {
  const resultado = []; // { act, planId, seccion }
  const biblio = cargarBiblioteca();
  (biblio.items || []).forEach(reg => {
    (reg.planificacion?.actividades || []).forEach(act => {
      if (_actFechaISO(act) !== fecha) return;
      const cursosConPlan = Object.values(calState.cursos)
        .filter(c => (c.planIds || []).includes(reg.id));
      const seccion = cursosConPlan.length > 0 ? cursosConPlan[0].nombre : null;
      resultado.push({ act, planId: reg.id, seccion });
    });
  });
  return resultado;
}

function _renderMoverDiaLista() {
  const fecha = document.getElementById('mover-dia-fecha')?.value;
  const lista = document.getElementById('mover-dia-lista');
  const btn = document.getElementById('mover-dia-btn');
  if (!fecha || !lista) return;

  const entries = _actsDeTodasLasPlanesEnFecha(fecha);

  if (entries.length === 0) {
    const dn = new Date(fecha + 'T12:00:00').toLocaleDateString('es-DO', { weekday: 'long', day: '2-digit', month: 'short' });
    lista.innerHTML = `<p style="font-size:0.83rem;color:#E65100;text-align:center;padding:12px 0;">⚠ No hay actividades el ${dn}.</p>`;
    if (btn) { btn.disabled = true; btn.style.opacity = '0.5'; }
    return;
  }

  let html = `<div style="font-size:0.8rem;font-weight:700;color:#546E7A;margin-bottom:10px;">${entries.length} actividad(es) encontradas — ajusta la fecha destino de cada una:</div>`;

  entries.forEach(({ act, seccion }, i) => {
    const enunciado = (act.enunciado || 'Sin descripción').substring(0, 72);
    const sugerida = _proximaFechaHorario(fecha, seccion);
    const tieneHorario = _diasHorarioDeSeccion(seccion).length > 0;
    const fuenteTag = tieneHorario
      ? `<span style="font-size:0.7rem;background:#E3F2FD;color:#1565C0;border-radius:6px;padding:1px 6px;white-space:nowrap;">📅 horario</span>`
      : `<span style="font-size:0.7rem;background:#FFF3E0;color:#E65100;border-radius:6px;padding:1px 6px;white-space:nowrap;">+7 días</span>`;
    const seccionTag = seccion
      ? `<span style="font-size:0.72rem;background:#E8F5E9;color:#2E7D32;border-radius:6px;padding:1px 6px;">${escapeHTML(seccion)}</span>`
      : '';
    html += `
    <div style="border:1.5px solid #E3F2FD;border-radius:10px;padding:10px 12px;margin-bottom:8px;">
      <div style="font-size:0.82rem;font-weight:600;color:var(--color-texto-primario,#212121);margin-bottom:6px;line-height:1.4;display:flex;align-items:flex-start;gap:6px;flex-wrap:wrap;">
        <span>${i + 1}. ${enunciado}${(act.enunciado?.length || 0) > 72 ? '…' : ''}</span>
        ${seccionTag}
      </div>
      <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
        <span style="font-size:0.75rem;color:#C62828;text-decoration:line-through;white-space:nowrap;">${act.fechaStr || fecha}</span>
        <span class="material-icons" style="font-size:14px;color:#9E9E9E;">arrow_forward</span>
        <input type="date" id="mover-dest-${act.id}" value="${sugerida}"
          style="padding:5px 10px;border:1.5px solid #90CAF9;border-radius:8px;font-size:0.82rem;font-family:inherit;background:var(--color-superficie,#fff);color:var(--color-texto-primario,#212121);" />
        ${fuenteTag}
      </div>
    </div>`;
  });

  lista.innerHTML = html;
  if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
}

function cerrarMoverDia() {
  document.getElementById('mover-dia-overlay')?.remove();
}

function _ejecutarMoverDia() {
  const fecha = document.getElementById('mover-dia-fecha')?.value;
  if (!fecha) return;
  const biblio = cargarBiblioteca();
  let movidas = 0;

  (biblio.items || []).forEach(reg => {
    (reg.planificacion?.actividades || []).forEach(act => {
      if (_actFechaISO(act) !== fecha) return;
      const input = document.getElementById(`mover-dest-${act.id}`);
      const nuevaFecha = input?.value;
      if (!nuevaFecha || nuevaFecha === fecha) return;
      act.fecha = nuevaFecha;
      act.fechaStr = _fecStr(nuevaFecha);
      movidas++;
    });
  });

  if (movidas > 0) {
    persistirBiblioteca(biblio);
    // Sincronizar con planificacion activa en editor si aplica
    guardarBorrador();
    guardarTodasDiarias();
    renderizarDiarias();
    renderizarDashboard();
    registrarCambio(`${movidas} actividad(es) reagendadas desde ${fecha}`);
    mostrarToast(`${movidas} actividad(es) movidas correctamente`, 'success');
  }
  cerrarMoverDia();
}

// ── Mover clase individual al próximo día programado ─────────────

function _actsDeSeccionEnFecha(fecha, seccion, materia) {
  const resultado = [];
  const biblio = cargarBiblioteca();
  const _norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  const _palabras = str => str.split(' ').filter(w => w.length > 3);
  const secNorm = _norm(seccion);
  const matNorm = _norm(materia || '');
  (biblio.items || []).forEach(reg => {
    // Filtrar por materia si se provee (compara con moduloFormativo de la planificación)
    if (matNorm) {
      const modNorm = _norm(reg.planificacion?.datosGenerales?.moduloFormativo || '');
      const wa = _palabras(matNorm), wb = _palabras(modNorm);
      const wbSet = new Set(wb);
      const shared = wa.filter(w => wbSet.has(w)).length;
      const coincide = modNorm.includes(matNorm) || matNorm.includes(modNorm) ||
        (Math.min(wa.length, wb.length) > 0 && shared / Math.min(wa.length, wb.length) >= 0.5);
      if (!coincide) return;
    }
    (reg.planificacion?.actividades || []).forEach(act => {
      if (_actFechaISO(act) !== fecha) return;
      if (!secNorm) { resultado.push({ act, planId: reg.id }); return; }
      const cursosConPlan = Object.values(calState.cursos).filter(c => (c.planIds || []).includes(reg.id));
      if (cursosConPlan.some(c => _norm(c.nombre) === secNorm)) {
        resultado.push({ act, planId: reg.id });
      }
    });
  });
  return resultado;
}

function abrirMoverClaseIndividual(encodedSlot) {
  let slot;
  try { slot = JSON.parse(decodeURIComponent(encodedSlot)); } catch { return; }

  cargarCalificaciones();
  const acts = _actsDeSeccionEnFecha(slot.fecha, slot.seccion, slot.materia);

  if (acts.length === 0) {
    mostrarToast('No hay actividades planificadas para esta clase en esta fecha', 'info');
    return;
  }

  const fechaStr = new Date(slot.fecha + 'T12:00:00').toLocaleDateString('es-DO', { weekday: 'long', day: '2-digit', month: 'long' });
  // Filtrar por materia+sección para no confundir distintas materias del mismo grupo
  const sugerida = _proximaFechaHorario(slot.fecha, slot.seccion, slot.materia);
  const tieneHorario = _diasHorarioDeMateriaYSeccion(slot.materia, slot.seccion).length > 0;
  const fuenteTag = tieneHorario
    ? `<span style="font-size:0.7rem;background:#E3F2FD;color:#1565C0;border-radius:6px;padding:1px 7px;">📅 según horario</span>`
    : `<span style="font-size:0.7rem;background:#FFF3E0;color:#E65100;border-radius:6px;padding:1px 7px;">+7 días</span>`;

  const matEsc = (slot.materia || '').replace(/'/g, "\\'");
  const secEsc = (slot.seccion || '').replace(/'/g, "\\'");

  const overlay = document.createElement('div');
  overlay.id = 'mover-clase-ind-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.45);z-index:9100;display:flex;align-items:center;justify-content:center;padding:24px 16px;';
  overlay.onclick = () => overlay.remove();
  overlay.innerHTML = `
    <div style="background:var(--color-superficie,#fff);border-radius:16px;padding:22px;max-width:420px;width:100%;box-shadow:0 8px 32px rgba(0,0,0,0.22);" onclick="event.stopPropagation()">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:14px;">
        <span class="material-icons" style="color:${slot.color};font-size:22px;">swap_horiz</span>
        <h3 style="margin:0;font-size:0.95rem;font-weight:800;color:var(--color-texto-primario,#212121);">Mover clase al próximo día</h3>
      </div>
      <div style="background:var(--color-fondo,#F5F5F5);border-left:3px solid ${slot.color};border-radius:0 10px 10px 0;padding:10px 14px;margin-bottom:14px;">
        <div style="font-size:0.87rem;font-weight:700;color:${slot.color};">${escapeHTML(slot.materia)}</div>
        ${slot.seccion ? `<div style="font-size:0.78rem;color:#546E7A;margin-top:3px;display:flex;align-items:center;gap:4px;"><span class="material-icons" style="font-size:13px;">group</span>${escapeHTML(slot.seccion)}</div>` : ''}
      </div>
      <p style="font-size:0.82rem;color:var(--color-texto-secundario,#757575);margin:0 0 14px;">
        Se moverán <strong>${acts.length} actividad(es)</strong> del <strong>${fechaStr}</strong> a:
      </p>
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;flex-wrap:wrap;">
        <label style="font-size:0.8rem;font-weight:700;color:var(--color-texto-primario,#212121);white-space:nowrap;">Nueva fecha:</label>
        <input type="date" id="mover-clase-ind-fecha" value="${sugerida}"
          style="flex:1;min-width:140px;padding:7px 12px;border:1.5px solid #B3E5FC;border-radius:8px;font-size:0.88rem;font-family:inherit;background:var(--color-superficie,#fff);color:var(--color-texto-primario,#212121);" />
      </div>
      <div style="margin-bottom:18px;padding-left:2px;">${fuenteTag}</div>
      <div style="display:flex;gap:8px;justify-content:flex-end;">
        <button onclick="document.getElementById('mover-clase-ind-overlay').remove()"
          style="background:none;border:1.5px solid #E0E0E0;color:#757575;border-radius:20px;padding:8px 18px;font-size:0.85rem;cursor:pointer;font-family:inherit;">Cancelar</button>
        <button onclick="_ejecutarMoverClaseIndividual('${slot.fecha}','${secEsc}','${matEsc}',document.getElementById('mover-clase-ind-fecha').value)"
          style="background:${slot.color};color:#fff;border:none;border-radius:20px;padding:8px 20px;font-size:0.85rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px;font-family:inherit;">
          <span class="material-icons" style="font-size:16px;">check</span> Confirmar y mover
        </button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
}

function _ejecutarMoverClaseIndividual(fechaOrigen, seccion, materia, nuevaFecha) {
  if (!nuevaFecha || nuevaFecha === fechaOrigen) {
    mostrarToast('La fecha de destino debe ser diferente a la original', 'warning');
    return;
  }
  cargarCalificaciones();
  const biblio = cargarBiblioteca();
  const _norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  const _palabras = str => str.split(' ').filter(w => w.length > 3);
  const secNorm = _norm(seccion);
  const matNorm = _norm(materia || '');
  let movidas = 0;

  (biblio.items || []).forEach(reg => {
    // Filtrar por sección
    const cursosConPlan = Object.values(calState.cursos).filter(c => (c.planIds || []).includes(reg.id));
    if (secNorm && !cursosConPlan.some(c => _norm(c.nombre) === secNorm)) return;
    // Filtrar por materia
    if (matNorm) {
      const modNorm = _norm(reg.planificacion?.datosGenerales?.moduloFormativo || '');
      const wa = _palabras(matNorm), wb = _palabras(modNorm);
      const wbSet = new Set(wb);
      const shared = wa.filter(w => wbSet.has(w)).length;
      const coincide = modNorm.includes(matNorm) || matNorm.includes(modNorm) ||
        (Math.min(wa.length, wb.length) > 0 && shared / Math.min(wa.length, wb.length) >= 0.5);
      if (!coincide) return;
    }
    (reg.planificacion?.actividades || []).forEach(act => {
      if (_actFechaISO(act) !== fechaOrigen) return;
      act.fecha = nuevaFecha;
      act.fechaStr = _fecStr(nuevaFecha);
      movidas++;
    });
  });

  document.getElementById('mover-clase-ind-overlay')?.remove();

  if (movidas > 0) {
    persistirBiblioteca(biblio);
    guardarBorrador();
    guardarTodasDiarias();
    renderizarDiarias();
    renderizarDashboard();
    registrarCambio(`${movidas} actividad(es) de ${seccion} movidas al ${nuevaFecha}`);
    mostrarToast(`${movidas} actividad(es) movidas correctamente`, 'success');
  } else {
    mostrarToast('No se encontraron actividades para mover', 'info');
  }
}






// ── Mover una actividad individual desde el modal de clase ────────

function moverActividadUnicaDesdeModal(encodedData) {
  let d;
  try { d = JSON.parse(decodeURIComponent(encodedData)); } catch { return; }
  const { planId, actId, fecha, seccion, materia, color } = d;

  const biblio = cargarBiblioteca();
  const reg = (biblio.items || []).find(i => i.id === planId);
  const act = (reg?.planificacion?.actividades || []).find(a => a.id === actId);
  if (!act) { mostrarToast('Actividad no encontrada', 'error'); return; }

  const sugerida = _proximaFechaHorario(fecha, seccion, materia);
  const tieneHorario = _diasHorarioDeMateriaYSeccion(materia, seccion).length > 0;
  const fuenteTag = tieneHorario
    ? `<span style="font-size:0.7rem;background:#E3F2FD;color:#1565C0;border-radius:6px;padding:2px 7px;">📅 según horario</span>`
    : `<span style="font-size:0.7rem;background:#FFF3E0;color:#E65100;border-radius:6px;padding:2px 7px;">+7 días</span>`;

  const enunciado = (act.enunciado || '').substring(0, 60) + ((act.enunciado || '').length > 60 ? '…' : '');
  const fechaActStr = new Date(fecha + 'T12:00:00').toLocaleDateString('es-DO', { weekday: 'long', day: '2-digit', month: 'short' });
  const clr = color || '#0277BD';

  const overlay = document.createElement('div');
  overlay.id = 'mover-act-unica-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:10100;display:flex;align-items:center;justify-content:center;padding:16px;';
  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };
  overlay.innerHTML = `
    <div style="background:var(--color-superficie,#fff);border-radius:16px;padding:22px 24px;max-width:380px;width:100%;box-shadow:0 8px 32px rgba(0,0,0,0.28);" onclick="event.stopPropagation()">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;">
        <span class="material-icons" style="color:${clr};font-size:22px;">event_repeat</span>
        <h3 style="margin:0;font-size:0.95rem;font-weight:800;color:var(--color-texto-primario,#212121);">Mover actividad</h3>
      </div>
      <div style="background:var(--color-fondo,#F5F5F5);border-left:3px solid ${clr};border-radius:0 10px 10px 0;padding:9px 13px;margin-bottom:12px;font-size:0.82rem;color:var(--color-texto-primario,#212121);line-height:1.4;">
        ${escapeHTML(enunciado)}<br>
        <span style="color:#9E9E9E;font-size:0.75rem;">Fecha actual: <span style="color:#C62828;text-decoration:line-through;">${fechaActStr}</span></span>
      </div>
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;flex-wrap:wrap;">
        <label style="font-size:0.82rem;font-weight:700;color:var(--color-texto-primario,#212121);white-space:nowrap;">Nueva fecha:</label>
        <input type="date" id="mover-act-unica-fecha" value="${sugerida}"
          style="flex:1;min-width:140px;padding:7px 11px;border:1.5px solid #90CAF9;border-radius:8px;font-size:0.85rem;font-family:inherit;background:var(--color-superficie,#fff);color:var(--color-texto-primario,#212121);" />
      </div>
      <div style="margin-bottom:16px;padding-left:2px;">${fuenteTag}</div>
      <div style="display:flex;gap:8px;justify-content:flex-end;">
        <button onclick="document.getElementById('mover-act-unica-overlay').remove()"
          style="background:none;border:1.5px solid #E0E0E0;color:#757575;border-radius:20px;padding:7px 16px;font-size:0.82rem;cursor:pointer;font-family:inherit;">Cancelar</button>
        <button onclick="_confirmarMoverActividadUnica('${planId}','${actId}')"
          style="background:${clr};color:#fff;border:none;border-radius:20px;padding:7px 18px;font-size:0.82rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px;font-family:inherit;">
          <span class="material-icons" style="font-size:15px;">check</span> Confirmar
        </button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
}

function _confirmarMoverActividadUnica(planId, actId) {
  const nuevaFecha = document.getElementById('mover-act-unica-fecha')?.value;
  if (!nuevaFecha) return;
  const biblio = cargarBiblioteca();
  const reg = (biblio.items || []).find(i => i.id === planId);
  const act = (reg?.planificacion?.actividades || []).find(a => a.id === actId);
  if (!act) { mostrarToast('Actividad no encontrada', 'error'); return; }
  act.fecha = nuevaFecha;
  act.fechaStr = _fecStr(nuevaFecha);
  persistirBiblioteca(biblio);
  guardarBorrador();
  guardarTodasDiarias();
  renderizarDiarias();
  renderizarDashboard();
  registrarCambio(`Actividad "${(act.enunciado || '').substring(0, 40)}" movida a ${nuevaFecha}`);
  mostrarToast('Actividad movida a ' + act.fechaStr, 'success');
  document.getElementById('mover-act-unica-overlay')?.remove();
  cerrarModalBtn();
}

