// ── Saludo + estadísticas ────────────────────────────────────────
function _renderizarSaludo() {
  const ahora = new Date();
  const DIAS = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
  const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
  const hora = ahora.getHours();
  const saludo = hora < 12 ? '¡Buenos días' : hora < 18 ? '¡Buenas tardes' : '¡Buenas noches';
  const dg = planificacion.datosGenerales || {};
  const nombreRaw = dg.nombreDocente
    || window.currentUser?.displayName
    || '';
  const nombre = nombreRaw
    ? ', ' + nombreRaw.trim().split(' ')[0] + '!'
    : '!';
  const fechaStr = DIAS[ahora.getDay()] + ', ' + ahora.getDate() + ' de ' + MESES[ahora.getMonth()] + ' · ' + ahora.getFullYear();

  const biblio = cargarBiblioteca();
  const nPlans = (biblio.items || []).filter(i => !i.archivada && _planPerteneceCicloActivo(i.id)).length;
  const nCursos = Object.keys(calState.cursos || {}).length;
  const tareas = cargarTareas();
  const nPend = tareas.filter(t => _estadoTarea(t) === 'pendiente').length;
  const nVenc = tareas.filter(t => _estadoTarea(t) === 'vencida').length;
  const buildBadge = String(window.TINCLASS_BUILD_VERSION || 'vdev');

  // Clases hoy desde horario
  const horario = cargarHorario();
  const diaHoy = new Date().getDay(); // 0=Dom…6=Sab
  const diaIdx = diaHoy === 0 ? -1 : diaHoy - 1; // 0=Lu…4=Vi
  const clasesHoy = diaIdx >= 0 ? horario.filter(e => e.dia === diaIdx && e.materia).length : 0;

  const foto = cargarPortafolioFoto();
  const avatarHtml = foto?.fotoBase64
    ? `<img src="data:${escapeHTML(foto.fotoMime)};base64,${foto.fotoBase64}">`
    : `<span>${ahora.getDate()}</span>`;

  const el = document.getElementById('dash-greeting');
  if (!el) return;
  el.innerHTML = `
    <div class="dash-greeting-left">
      <div class="dash-greeting-avatar">${avatarHtml}</div>
      <div class="dash-greeting-info">
        <div class="dash-greeting-date">${fechaStr}</div>
        <div class="dash-greeting-title">${saludo}${nombre}</div>
        <div class="dash-greeting-sub">Sistema de Planificación Educativa · República Dominicana <span class="dash-version-badge" onclick="abrirAcercaDe()" title="Ver novedades de la versión">${buildBadge}</span></div>
      </div>
    </div>
    <div class="dash-stats-row">
      <div id="dash-stat-planificaciones" class="dash-stat-pill" title="Planificaciones guardadas" onclick="abrirPlanificaciones()" style="cursor:pointer;">
        <div class="dash-stat-icon"><span class="material-icons">folder_special</span></div>
        <div class="dash-stat-num">${nPlans}</div>
        <div class="dash-stat-lbl">Planific.</div>
      </div>
      <div id="dash-stat-cursos" class="dash-stat-pill" title="Cursos activos" onclick="abrirCalificaciones()" style="cursor:pointer;">
        <div class="dash-stat-icon"><span class="material-icons">school</span></div>
        <div class="dash-stat-num">${nCursos}</div>
        <div class="dash-stat-lbl">Cursos</div>
      </div>
      <div id="dash-stat-clases-hoy" class="dash-stat-pill" title="Clases programadas hoy" onclick="abrirHorario()" style="cursor:pointer;">
        <div class="dash-stat-icon"><span class="material-icons">today</span></div>
        <div class="dash-stat-num">${clasesHoy}</div>
        <div class="dash-stat-lbl">Clases hoy</div>
      </div>
      <div id="dash-stat-tareas" class="dash-stat-pill ${nVenc > 0 ? 'stat-alerta' : nPend > 0 ? 'stat-warning' : ''}" title="Tareas pendientes" onclick="abrirTareas()" style="cursor:pointer;">
        <div class="dash-stat-icon"><span class="material-icons">assignment</span></div>
        <div class="dash-stat-num">${nPend + nVenc}</div>
        <div class="dash-stat-lbl">Tareas</div>
      </div>
      <div class="dash-stat-pill" title="Historial de cierres de ciclo" onclick="abrirHistorialCierres()" style="cursor:pointer;">
        <div class="dash-stat-icon"><span class="material-icons">history</span></div>
        <div class="dash-stat-num">↗</div>
        <div class="dash-stat-lbl">Historial</div>
      </div>
    </div>`;
}

let _dashCalBannerFetchInFlight = false;

function _dashFechaDiffDias(hoy, fecha) {
  const a = new Date(hoy); a.setHours(0, 0, 0, 0);
  const b = new Date(fecha); b.setHours(0, 0, 0, 0);
  return Math.round((b.getTime() - a.getTime()) / 86400000);
}

function _dashParseDmyFecha(dmy) {
  const m = String(dmy || '').trim().match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (!m) return null;
  const fecha = new Date(`${m[3]}-${m[2]}-${m[1]}T12:00:00`);
  if (Number.isNaN(fecha.getTime())) return null;
  if (fecha.getDate() !== parseInt(m[1], 10) || (fecha.getMonth() + 1) !== parseInt(m[2], 10)) return null;
  return fecha;
}

function _dashFechaCorta(fecha) {
  return fecha.toLocaleDateString('es-DO', { weekday: 'short', day: '2-digit', month: 'short' });
}

function _dashEtiquetaAnticipacion(dias, enCurso) {
  if (enCurso) return 'En curso';
  if (dias === 0) return 'Hoy';
  if (dias === 1) return 'Mañana';
  return `En ${dias} días`;
}

function _dashObtenerDatosCalendario() {
  if (_calEsc.modo === 'personal' && _calEsc.personalDatos) return _calEsc.personalDatos;
  if (_calEsc.adminDatos) return _calEsc.adminDatos;
  try {
    const raw = localStorage.getItem(CAL_ESC_KEY);
    const parsed = raw ? JSON.parse(raw) : null;
    if (parsed && parsed.meses) return parsed;
  } catch (e) {}
  return _calEscDatosVacios();
}

function _dashAsegurarCalendarioAdminBanner() {
  if (_dashCalBannerFetchInFlight || _calEsc.adminDatos || typeof db === 'undefined') return;
  _dashCalBannerFetchInFlight = true;
  (async () => {
    if (!_calEsc.centroId) {
      _calEsc.centroId = await _obtenerCentroIdDeUsuarioActual();
    }
    await _calEscCargarAdmin();
    _renderizarBannerCalendarioDashboard();
  })().finally(() => { _dashCalBannerFetchInFlight = false; });
}

function _dashParseActividadConFecha(texto) {
  const t = String(texto || '').trim();
  if (!t) return null;

  let m = t.match(/^[Dd]el\s+(\d{2}\/\d{2}\/\d{4})\s+al\s+(\d{2}\/\d{2}\/\d{4})\s*:\s*(.*)$/);
  if (m) return { fechaDmy: m[1], fechaHastaDmy: m[2], titulo: m[3] || 'Actividad escolar' };

  m = t.match(/^[Dd][íi]a\s+(\d{2}\/\d{2}\/\d{4})\s*:\s*(.*)$/);
  if (m) return { fechaDmy: m[1], fechaHastaDmy: m[1], titulo: m[2] || 'Actividad escolar' };

  m = t.match(/^`?(\d{2}\/\d{2}\/\d{4})`?\s+`?(\d{2}\/\d{2}\/\d{4})`?\s+(.*)$/);
  if (m) return { fechaDmy: m[1], fechaHastaDmy: m[2], titulo: m[3] || 'Actividad escolar' };

  return null;
}

function _dashConstruirAvisosCalendario(datos) {
  const hoy = new Date();
  hoy.setHours(0, 0, 0, 0);
  const avisos = [];

  const pushAviso = (tipo, fecha, titulo, icono, anticipacionDias) => {
    const diff = _dashFechaDiffDias(hoy, fecha);
    if (diff < 0 || diff > anticipacionDias) return;
    avisos.push({ tipo, fecha, titulo: String(titulo || '').trim(), icono, diff });
  };

  (_calEsc.adminDatos?.festivos || datos.festivos || []).forEach(f => {
    const fecha = /^\d{4}-\d{2}-\d{2}$/.test(String(f.fecha || '')) ? new Date(f.fecha + 'T12:00:00') : null;
    if (!fecha || Number.isNaN(fecha.getTime())) return;
    pushAviso('Festivo', fecha, f.motivo || 'Día festivo / no lectivo', 'event_busy', 4);
  });

  const mesNum = {
    enero: 1, febrero: 2, marzo: 3, abril: 4, mayo: 5, junio: 6,
    julio: 7, agosto: 8, septiembre: 9, octubre: 10, noviembre: 11, diciembre: 12
  };

  Object.entries(datos.meses || {}).forEach(([mesKey, mesData]) => {
    (mesData.actividades || []).forEach(a => {
      const parsed = _dashParseActividadConFecha(a.texto);
      if (!parsed) return;
      const fechaInicio = _dashParseDmyFecha(parsed.fechaDmy);
      if (!fechaInicio) return;
      const fechaFin = _dashParseDmyFecha(parsed.fechaHastaDmy) || fechaInicio;

      // Actividad de varios días: si ya empezó pero hoy sigue dentro del rango, no se
      // debe filtrar por "cuántos días faltan" (la fecha de inicio ya pasó, daría un
      // diff negativo y se perdería aunque siga vigente) -- se marca como "en curso".
      const diffInicio = _dashFechaDiffDias(hoy, fechaInicio);
      const diffFin = _dashFechaDiffDias(hoy, fechaFin);
      if (diffInicio <= 0 && diffFin >= 0) {
        avisos.push({ tipo: 'Actividad', fecha: fechaFin, titulo: parsed.titulo, icono: 'task_alt', diff: 0, enCurso: true });
        return;
      }
      pushAviso('Actividad', fechaInicio, parsed.titulo, 'task_alt', 2);
    });

    (mesData.efemerides || []).forEach(e => {
      const dia = parseInt(e.dia, 10);
      const mes = mesNum[mesKey];
      if (!mes || !dia) return;

      const y = hoy.getFullYear();
      const cands = [new Date(y, mes - 1, dia, 12), new Date(y + 1, mes - 1, dia, 12)]
        .filter(d => d.getMonth() === (mes - 1) && d.getDate() === dia)
        .sort((a, b) => a - b);

      const prox = cands.find(d => _dashFechaDiffDias(hoy, d) >= 0);
      if (!prox) return;
      pushAviso('Efeméride', prox, e.titulo || e.descripcion || 'Efeméride escolar', 'auto_stories', 2);
    });
  });

  _listaCumpleanosOrdenada(10).forEach(c => {
    pushAviso('Cumpleaños', c.fecha, `Cumpleaños de ${c.nombre}`, 'cake', 10);
  });

  const prioridadTipo = { Festivo: 1, 'Cumpleaños': 2, Actividad: 3, 'Efeméride': 4 };
  avisos.sort((a, b) => (a.diff - b.diff) || ((prioridadTipo[a.tipo] || 9) - (prioridadTipo[b.tipo] || 9)) || a.titulo.localeCompare(b.titulo));

  // El banner del Dashboard solo muestra un puñado de avisos (ver _renderizarBanner-
  // CalendarioDashboard, slice(0,6)). Sin esto, un tipo con muchos elementos "urgentes"
  // (ej. varias actividades de varios días "en curso", todas con diff 0) ocupa TODOS
  // los cupos visibles y deja afuera a los demás tipos (Cumpleaños, Efemérides,
  // Festivos) aunque también sean próximos -- por eso se limita cuántos entran por
  // tipo antes de recortar el total, para que ningún tipo acapare el banner.
  const MAX_POR_TIPO = 3;
  const contadorTipo = {};
  return avisos.filter(a => {
    contadorTipo[a.tipo] = (contadorTipo[a.tipo] || 0) + 1;
    return contadorTipo[a.tipo] <= MAX_POR_TIPO;
  });
}

function _renderizarBannerCalendarioDashboard() {
  const el = document.getElementById('dash-calendario-banner');
  if (!el) return;

  // Asegura que el calendario admin (Firestore) se cargue en segundo plano y
  // vuelva a renderizar el banner cuando llegue, sin importar si ya hay avisos
  // (p.ej. cumpleaños, que están disponibles de inmediato desde datos locales).
  _dashAsegurarCalendarioAdminBanner();

  const datos = _dashObtenerDatosCalendario();
  let avisos = _dashConstruirAvisosCalendario(datos);

  // Aviso de suscripción del centro en período de gracia: se antepone a los
  // avisos de calendario (siempre visible, es el más urgente) en vez de tener
  // su propio banner aparte -- solo lo ve admin_centro/director (ver
  // window._suscripcionCentroInfo, fijado en auth.js durante el login).
  const susc = window._suscripcionCentroInfo;
  if (susc && susc.enGracia && susc.puedeVerBanner) {
    avisos = [{
      tipo: 'Suscripción',
      titulo: 'Pago pendiente: quedan ' + susc.diasRestantes + ' día' + (susc.diasRestantes === 1 ? '' : 's') + ' de gracia',
      icono: 'warning',
      esSuscripcion: true
    }, ...avisos];
  }

  avisos = avisos.slice(0, 8);

  if (!avisos.length) {
    el.style.display = 'none';
    el.innerHTML = '';
    return;
  }

  el.style.display = 'block';
  el.innerHTML = `
    <div class="dash-cal-banner" style="background:linear-gradient(135deg,#FFF8E1 0%,#FFF3E0 100%);border:1.5px solid #FFCC80;border-radius:12px;padding:10px 12px;">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:8px;">
        <div class="dash-cal-banner-title" style="display:flex;align-items:center;gap:6px;font-size:0.83rem;font-weight:700;color:#E65100;">
          <span class="material-icons" style="font-size:17px;">notifications_active</span>
          Próximos avisos del calendario escolar
        </div>
        <button onclick="abrirCalendarioEscolar()" class="dash-cal-banner-link" style="background:none;border:none;color:#1565C0;font-size:0.76rem;font-weight:700;cursor:pointer;">Ver calendario →</button>
      </div>
      <div style="display:flex;flex-wrap:wrap;gap:6px;">
        ${avisos.map(a => `
          <div class="dash-cal-pill" style="display:flex;align-items:center;gap:5px;background:#fff;border:1px solid ${a.esSuscripcion ? '#EF9A9A' : '#FFE0B2'};border-radius:18px;padding:5px 9px;max-width:100%;">
            <span class="material-icons" style="font-size:13px;color:${a.esSuscripcion ? '#C62828' : a.tipo === 'Festivo' ? '#EF6C00' : a.tipo === 'Actividad' ? '#1565C0' : a.tipo === 'Cumpleaños' ? '#AD1457' : '#6A1B9A'};">${a.icono}</span>
            ${a.esSuscripcion ? '' : `<span class="dash-cal-pill-meta" style="font-size:0.75rem;color:#455A64;white-space:nowrap;">${_dashEtiquetaAnticipacion(a.diff, a.enCurso)} · ${_dashFechaCorta(a.fecha)}</span>`}
            <span class="dash-cal-pill-titulo" style="font-size:0.78rem;color:${a.esSuscripcion ? '#C62828' : '#263238'};font-weight:${a.esSuscripcion ? '700' : '400'};">${escapeHTML(a.titulo)}</span>
          </div>
        `).join('')}
      </div>
    </div>`;
}

// ── Alertas inteligentes ─────────────────────────────────────────
// ── Detección de estudiantes en riesgo ──────────────────────────
function _estudiantesEnRiesgo(curso) {
  const umbralPct  = (parseInt(localStorage.getItem('cfg_umbral_riesgo') || '70')) / 100;
  const umbralActs = parseInt(localStorage.getItem('cfg_umbral_acts')    || '3');
  const maxTotal   = _rendMaxTotal(curso);

  return (curso.estudiantes || []).map(est => {
    const nota = _calcNotaFinal(curso, est.id);
    const pct  = maxTotal > 0 && nota !== null ? nota / maxTotal : null;

    // Contar actividades sin calificar
    let actsSinNota = 0;
    Object.entries(curso.ras || {}).forEach(([rk, ra]) => {
      (ra.actividades || []).forEach(actId => {
        const n = curso.notas?.[est.id]?.[rk]?.[actId];
        if (n === undefined || n === null) actsSinNota++;
      });
    });

    const bajoProm       = pct !== null && pct < umbralPct;
    const muchasActsSin  = actsSinNota >= umbralActs;
    if (!bajoProm && !muchasActsSin) return null;

    return {
      id: est.id, nombre: est.nombre, nota, pct, actsSinNota,
      razones: [
        bajoProm      ? `Promedio ${pct !== null ? (pct*100).toFixed(1)+'%' : '—'} < ${Math.round(umbralPct*100)}%` : null,
        muchasActsSin ? `${actsSinNota} actividad${actsSinNota !== 1 ? 'es' : ''} sin calificar` : null,
      ].filter(Boolean),
    };
  }).filter(Boolean);
}

function _renderizarAlertas() {
  const el = document.getElementById('dash-alertas');
  if (!el) return;
  const alertas = [];

  // Tareas vencidas
  const tareas = cargarTareas();
  const vencidas = tareas.filter(t => _estadoTarea(t) === 'vencida');
  if (vencidas.length > 0) {
    const grupos = {};
    vencidas.forEach(t => { grupos[t.seccion || '?'] = (grupos[t.seccion || '?'] || 0) + 1; });
    const txt = Object.entries(grupos).map(([s, n]) => `${s} (${n})`).join(', ');
    alertas.push({ tipo: 'error', icono: 'warning', msg: `${vencidas.length} tarea(s) vencida(s): ${txt}`, accion: 'abrirTareas()', label: 'Ver tareas' });
  }

  // Tareas que vencen hoy o mañana
  const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
  const manana = new Date(hoy); manana.setDate(manana.getDate() + 1);
  const urgentes = tareas.filter(t => {
    if (!t.fechaLimite || _estadoTarea(t) !== 'pendiente') return false;
    const fl = new Date(t.fechaLimite + 'T12:00:00'); fl.setHours(0, 0, 0, 0);
    return fl <= manana;
  });
  urgentes.forEach(t => {
    const fl = new Date(t.fechaLimite + 'T12:00:00'); fl.setHours(0, 0, 0, 0);
    const esHoy = fl.getTime() === hoy.getTime();
    alertas.push({
      tipo: 'warning',
      icono: 'schedule',
      msg: `Tarea de ${t.seccion || '?'} vence ${esHoy ? 'HOY' : 'mañana'}${t.horaLimite ? ' a las ' + t.horaLimite : ''}: "${(t.descripcion || '').substring(0, 50)}"`,
      accion: 'abrirTareas()', label: 'Ver'
    });
  });

  // Cursos sin planificación asignada
  const _bibIds = new Set((cargarBiblioteca().items || []).map(i => i.id));
  const cursosSinPlan = Object.values(calState.cursos).filter(c =>
    !(c.planIds || []).some(pid => _bibIds.has(pid))
  );
  if (cursosSinPlan.length > 0) {
    alertas.push({ tipo: 'info', icono: 'link_off', msg: `${cursosSinPlan.length} curso(s) sin planificación asignada: ${cursosSinPlan.map(c => c.nombre).join(', ')}`, accion: 'abrirPlanificaciones()', label: 'Asignar' });
  }

  // Actividades sin instrumento
  const biblio = cargarBiblioteca();
  let sinInst = 0;
  (biblio.items || []).forEach(r => {
    (r.planificacion?.actividades || []).forEach(a => { if (!a.instrumento) sinInst++; });
  });
  if (sinInst > 0) {
    alertas.push({ tipo: 'info', icono: 'assignment_late', msg: `${sinInst} actividad(es) sin instrumento de evaluación asignado`, accion: 'abrirPlanificaciones()', label: 'Revisar' });
  }

  // Estudiantes en riesgo
  Object.values(calState.cursos || {}).forEach(curso => {
    const enRiesgo = _estudiantesEnRiesgo(curso);
    if (!enRiesgo.length) return;
    const nombres = enRiesgo.slice(0, 3).map(e => e.nombre.split(' ')[0]).join(', ');
    const extra = enRiesgo.length > 3 ? ` y ${enRiesgo.length - 3} más` : '';
    alertas.push({
      tipo: 'riesgo',
      icono: 'person_alert',
      msg: `${enRiesgo.length} estudiante${enRiesgo.length !== 1 ? 's' : ''} en riesgo en "${curso.nombre}": ${nombres}${extra}`,
      accion: `abrirRendimiento()`,
      label: 'Ver gráficas',
    });
  });

  if (alertas.length === 0) { el.innerHTML = ''; return; }

  el.innerHTML = `<div class="dash-alertas-wrap">` +
    alertas.map(a => `
      <div class="dash-alerta dash-alerta-${a.tipo}">
        <span class="material-icons">${a.icono}</span>
        <span class="dash-alerta-msg">${escapeHTML(a.msg)}</span>
        <button onclick="${a.accion}" class="dash-alerta-btn">${a.label} →</button>
      </div>`
    ).join('') +
    `</div>`;
}

// ── Clases de hoy desde horario ──────────────────────────────────
// ── Clases de hoy y mañana (función genérica) ────────────────────
// Offset global de navegación de días en el dashboard (0 = hoy/mañana/pasado)
let _dashDiaOffset = 0;

function _dashNavDias(delta) {
  if (delta === 0) {
    _dashDiaOffset = 0; // Ir a hoy
  } else {
    _dashDiaOffset += delta;
  }
  _renderizarClasesHoy();
  _renderizarClasesManana();
  _renderizarClasesPasado();
  _actualizarLabelsDias();
}

function _actualizarLabelsDias() {
  const o = _dashDiaOffset;
  const DIAS = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
  const label = (offset) => {
    const d = new Date(); d.setDate(d.getDate() + offset); return DIAS[d.getDay()];
  };
  const hoyBtn = document.getElementById('dash-nav-hoy-btn');
  if (hoyBtn) hoyBtn.style.color = o === 0 ? '#1565C0' : '#E65100';

  // Labels de columnas
  const l0 = document.getElementById('dash-hoy-label');
  const l1 = document.getElementById('dash-manana-label');
  const l2 = document.getElementById('dash-pasado-label');
  if (l0) l0.textContent = o === 0 ? 'Clases de hoy' : label(o);
  if (l1) l1.textContent = o === 0 ? 'Mañana' : label(o + 1);
  if (l2) l2.textContent = o === 0 ? 'Pasado mañana' : label(o + 2);

  // Botones Mover — actualizar la fecha que usan
  const d0 = new Date(); d0.setDate(d0.getDate() + o);
  const d1 = new Date(); d1.setDate(d1.getDate() + o + 1);
  const d2 = new Date(); d2.setDate(d2.getDate() + o + 2);
  const iso = d => _isoDate(d); // usar hora local, no UTC
  const b0 = document.getElementById('dash-hoy-mover-btn');
  const b1 = document.getElementById('dash-manana-mover-btn');
  const b2 = document.getElementById('dash-pasado-mover-btn');
  if (b0) b0.setAttribute('onclick', `abrirMoverDia('${iso(d0)}')`);
  if (b1) b1.setAttribute('onclick', `abrirMoverDia('${iso(d1)}')`);
  if (b2) b2.setAttribute('onclick', `abrirMoverDia('${iso(d2)}')`);
}

function _renderizarClasesHoy() {
  _renderizarClasesDia('dash-hoy', 'dash-hoy-fecha', _dashDiaOffset);
}
function _renderizarClasesManana() {
  _renderizarClasesDia('dash-manana', 'dash-manana-fecha', _dashDiaOffset + 1);
}
function _renderizarClasesPasado() {
  _renderizarClasesDia('dash-pasado', 'dash-pasado-fecha', _dashDiaOffset + 2);
}

function _renderizarClasesDia(contId, fechaLabelId, offsetDias) {
  const cont = document.getElementById(contId);
  if (!cont) return;
  const DIAS = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
  const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
  const target = new Date();
  target.setDate(target.getDate() + offsetDias);
  target.setHours(0, 0, 0, 0);
  const diaJS = target.getDay();            // 0=Dom…6=Sab
  const diaIdx = diaJS === 0 || diaJS === 6 ? -1 : diaJS - 1; // 0=Lu…4=Vi

  const fechaEl = document.getElementById(fechaLabelId);
  if (fechaEl) fechaEl.textContent = DIAS[diaJS] + ' ' + target.getDate() + ' de ' + MESES[target.getMonth()];

  if (diaIdx < 0) {
    const msgFinde = offsetDias === 0 ? '¡Es fin de semana!' : offsetDias === 1 ? 'Mañana es fin de semana 😄' : 'Es fin de semana 😄';
    cont.innerHTML = `<div class="dash-empty-card"><span class="material-icons">weekend</span><p>${msgFinde}</p></div>`;
    return;
  }

  const horario = cargarHorario().filter(e => e.dia === diaIdx && e.materia);
  const coloresMateria = _horarioColores();

  if (horario.length === 0) {
    cont.innerHTML = `<div class="dash-empty-card"><span class="material-icons">event_available</span><p>Sin clases programadas.<br><button onclick="abrirHorario()" style="margin-top:8px;background:none;border:1.5px solid #90CAF9;color:#1565C0;border-radius:20px;padding:4px 14px;font-size:0.8rem;cursor:pointer;">Configurar horario</button></p></div>`;
    return;
  }

  horario.sort((a, b) => a.periodo - b.periodo);

  // Buscar actividades de planificaciones para esa fecha
  const _normStr = s => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
  // target ya esta en horario LOCAL (construido con setDate/setHours, no UTC) --
  // se extraen sus componentes locales para no desfasar por huso horario.
  const targetISO = target.getFullYear() + '-' + String(target.getMonth() + 1).padStart(2, '0') + '-' + String(target.getDate()).padStart(2, '0');
  const planPorSeccion = {};
  const biblio = cargarBiblioteca();
  (biblio.items || []).forEach(reg => {
    (reg.planificacion?.actividades || []).forEach(act => {
      if (!act.fecha || act.esComplementario) return;
      // Actividades de varios dias (duracionDias): _actividadCubreFecha revisa
      // si targetISO cae dentro de [act.fecha, act.fechaFin || act.fecha].
      if (_actividadCubreFecha(act, targetISO)) {
        const cursosConPlan = Object.values(calState.cursos).filter(c => (c.planIds || []).includes(reg.id));
        cursosConPlan.forEach(c => {
          const modulo = _normStr(reg.planificacion?.datosGenerales?.moduloFormativo || '');
          const key = _normStr(c.nombre) + '|||' + modulo;
          if (!planPorSeccion[key]) planPorSeccion[key] = [];
          planPorSeccion[key].push({ act, dg: reg.planificacion?.datosGenerales || {}, ra: reg.planificacion?.ra || {}, planId: reg.id, cursoId: c.id, coursePlanActivaId: c.planActivaId || null });
        });
      }
    });
  });

  const horaActual = offsetDias === 0 ? new Date().getHours() * 60 + new Date().getMinutes() : -1;
  const horasPer = { 1: 480, 2: 530, 3: 600, 4: 650, 5: 750, 6: 800, 7: 860, 8: 910 };

  cont.innerHTML = horario.map(e => {
    const color = coloresMateria[e.materia.trim()] || '#78909C';
    const per = PERIODOS.find(p => p.id === e.periodo);
    const _normSec = _normStr(e.seccion);
    const _normMat = _normStr(e.materia);
    let sesiones = planPorSeccion[_normSec + '|||' + _normMat] || [];
    if (!sesiones.length && _normSec) {
      // Fallback: buscar por sección + palabras clave (≥60% de palabras >3 chars coinciden)
      const _words = str => str.split(' ').filter(w => w.length > 3);
      const wa = _words(_normMat);
      const fallbackKey = Object.keys(planPorSeccion).find(k => {
        const parts = k.split('|||');
        if (parts[0] !== _normSec || parts.length < 2) return false;
        const wb = _words(parts[1]);
        const wbSet = new Set(wb);
        const shared = wa.filter(w => wbSet.has(w)).length;
        return Math.min(wa.length, wb.length) > 0 && shared / Math.min(wa.length, wb.length) >= 0.6;
      });
      if (fallbackKey) sesiones = planPorSeccion[fallbackKey] || [];
    }
    // Dedup: si hay actividades de múltiples planes con el mismo módulo, preferir el plan activo del curso
    if (sesiones.length > 1) {
      const planIdsUnicos = [...new Set(sesiones.map(s => s.planId))];
      if (planIdsUnicos.length > 1) {
        // Buscar planes que sean el planActivaId de su curso
        const activosIds = new Set(
          sesiones.filter(s => s.coursePlanActivaId && s.planId === s.coursePlanActivaId).map(s => s.planId)
        );
        if (activosIds.size > 0) {
          sesiones = sesiones.filter(s => activosIds.has(s.planId));
        }
        // Si ninguno coincide (planActivaId es de otra materia), mostrar solo el primer plan encontrado
        else {
          const primero = planIdsUnicos[0];
          sesiones = sesiones.filter(s => s.planId === primero);
        }
      }
    }
    const inicioMin = horasPer[e.periodo] || 0;
    const finMin = inicioMin + 50;
    const estado = horaActual < 0 ? 'futura'
      : horaActual > finMin ? 'pasada'
        : horaActual >= inicioMin ? 'ahora' : 'futura';

    // Datos para el modal — serializados en data-attrs
    const dataClase = JSON.stringify({
      materia: e.materia, seccion: e.seccion || '', aula: e.aula || '', notas: e.notas || '',
      periodo: e.periodo, hora: per?.hora || '', color,
      sesiones: sesiones.map(s => ({ enunciado: s.act.enunciado || '', actId: s.act.id || '', planId: s.planId || '', cursoId: s.cursoId || '', instrumento: s.act.instrumento || null, dg: s.dg, ra: s.ra || {} })),
      fecha: target.toISOString().split('T')[0]
    }).replace(/'/g, '&apos;');

    const slotMover = encodeURIComponent(JSON.stringify({
      fecha: target.toISOString().split('T')[0],
      seccion: e.seccion || '',
      materia: e.materia,
      color,
      periodo: e.periodo
    }));

    return `<div class="dash-clase-card" style="--clase-color:${color};opacity:${estado === 'pasada' ? '0.65' : '1'};"
      onclick="abrirModalClase('${encodeURIComponent(dataClase)}')" title="Ver detalles de la clase">
      <div class="dash-clase-barra" style="background:${color};"></div>
      <div class="dash-clase-body">
        <div class="dash-clase-header">
          <span class="dash-clase-periodo">P${e.periodo} · ${per?.hora || ''}</span>
          ${estado === 'ahora' ? '<span class="dash-clase-ahora"><span class="material-icons" style="font-size:12px;">fiber_manual_record</span>Ahora</span>' : ''}
          ${estado === 'pasada' ? '<span class="dash-clase-pasada">Finalizada</span>' : ''}
          <button class="dash-clase-mover-btn" onclick="event.stopPropagation();abrirMoverClaseIndividual('${slotMover}')" title="Mover esta clase al próximo día programado">
            <span class="material-icons" style="font-size:12px;">swap_horiz</span> Mover
          </button>
        </div>
        <div class="dash-clase-materia" style="color:${color};">${escapeHTML(e.materia)}</div>
        ${e.seccion ? `<div class="dash-clase-seccion"><span class="material-icons" style="font-size:13px;">group</span>${escapeHTML(e.seccion)}</div>` : ''}
        ${e.aula ? `<div class="dash-clase-aula"><span class="material-icons" style="font-size:13px;">room</span>${escapeHTML(e.aula)}</div>` : ''}
        ${(() => {
          const v = new Set();
          return sesiones
            .filter(s => s.ra && s.ra.descripcion && !v.has(s.ra.descripcion) && v.add(s.ra.descripcion))
            .map(s => {
              const desc = s.ra.descripcion;
              const txt = escapeHTML(desc.substring(0, 72)) + (desc.length > 72 ? '…' : '');
              return '<div style="margin-top:5px;font-size:.71rem;color:#2E7D32;display:flex;gap:4px;align-items:flex-start;line-height:1.35;">'
                + '<span class="material-icons" style="font-size:12px;flex-shrink:0;margin-top:1px;color:#2E7D32;">school</span>'
                + '<span>' + txt + '</span></div>';
            }).join('');
        })()}
        ${sesiones.length ? sesiones.map(s => `
          <div class="dash-clase-plan">
            <span class="material-icons" style="font-size:12px;">description</span>
            ${escapeHTML((s.act.enunciado || '').substring(0, 52))}${(s.act.enunciado || '').length > 52 ? '…' : ''}
          </div>`).join('') : ''}
      </div>
      <span class="material-icons dash-clase-chevron" style="color:${color};">chevron_right</span>
    </div>`;
  }).join('');
}

function _extraerMetaNotaClase(key) {
  const k = String(key || '');
  const mV2 = k.match(/^notaclasev2_(\d{4}-\d{2}-\d{2})_(.+)$/);
  if (mV2) {
    return { key: k, fecha: mV2[1], scopeId: mV2[2], periodo: '', tipo: 'v2' };
  }

  const m = k.match(/^notaclase_(\d{4}-\d{2}-\d{2})_(.+)_(\d+)$/);
  if (!m) return null;
  return { key: k, fecha: m[1], seccion: m[2], periodo: m[3], tipo: 'legacy' };
}

function _normalizarTextoNotaClase(txt) {
  return String(txt || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function _scopeNotaClase(seccion, materia) {
  const s = _normalizarTextoNotaClase(seccion) || 'sin_seccion';
  const m = _normalizarTextoNotaClase(materia) || 'sin_materia';
  return s + '__' + m;
}

function _notaClaseKeyV2(fecha, seccion, materia) {
  return `notaclasev2_${fecha}_${_scopeNotaClase(seccion, materia)}`;
}

function _buscarNotaLegacyMismaClase(fecha, seccion) {
  if (!fecha || !seccion) return '';
  const pref = `notaclase_${fecha}_${seccion}_`;
  let mejor = '';
  try {
    Object.keys(localStorage)
      .filter(k => k.startsWith(pref))
      .sort((a, b) => b.localeCompare(a))
      .forEach((k) => {
        if (mejor) return;
        const txt = (localStorage.getItem(k) || '').trim();
        if (txt) mejor = txt;
      });
  } catch { }
  return mejor;
}

function _obtenerHistorialNotasClase(seccion, materia) {
  const out = [];
  const scopeId = _scopeNotaClase(seccion, materia);
  const agregado = new Set();

  try {
    Object.keys(localStorage)
      .filter(k => k.startsWith('notaclase_') || k.startsWith('notaclasev2_'))
      .forEach((k) => {
        const meta = _extraerMetaNotaClase(k);
        if (!meta) return;

        if (meta.tipo === 'v2') {
          if (meta.scopeId !== scopeId) return;
        } else {
          // Compatibilidad: mostrar notas antiguas por sección aunque sean del esquema por período.
          if (seccion && meta.seccion !== seccion) return;
        }

        const texto = (localStorage.getItem(k) || '').trim();
        if (!texto) return;

        const dedupeKey = `${meta.fecha}__${texto}`;
        if (agregado.has(dedupeKey)) return;
        agregado.add(dedupeKey);

        out.push({ ...meta, texto, scopeId });
      });
  } catch (e) {
    console.warn('Error leyendo historial de notas de clase:', e);
  }

  out.sort((a, b) => {
    if (a.fecha === b.fecha) return Number(b.periodo) - Number(a.periodo);
    return b.fecha.localeCompare(a.fecha);
  });

  return out;
}

function _diasTranscurridosDesde(fechaISO) {
  try {
    const hoy = new Date();
    const d = new Date(fechaISO + 'T12:00:00');
    const diff = Math.floor((hoy - d) / (1000 * 60 * 60 * 24));
    return Number.isFinite(diff) ? Math.max(0, diff) : null;
  } catch {
    return null;
  }
}

function _renderHistorialNotasClaseHTML(seccion, materia, fechaActual, color) {
  const historial = _obtenerHistorialNotasClase(seccion, materia);
  if (!historial.length) {
    return `<div style="padding:10px 12px;border:1px dashed #CFD8DC;border-radius:8px;background:#FAFAFA;color:#90A4AE;font-size:0.78rem;">
      Todavía no hay notas guardadas para esta clase.
    </div>`;
  }

  return `<div style="display:flex;flex-direction:column;gap:8px;">${historial.map((n) => {
    const fechaFmt = new Date(n.fecha + 'T12:00:00').toLocaleDateString('es-DO', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' });
    const esHoy = n.fecha === fechaActual;
    const dias = _diasTranscurridosDesde(n.fecha);
    const textoEnc = encodeURIComponent(n.texto);
    return `<div style="border:1px solid #E0E0E0;border-radius:9px;padding:9px 10px;background:#fff;">
      <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:6px;">
        <span style="font-size:0.73rem;color:#546E7A;font-weight:700;display:inline-flex;align-items:center;gap:3px;">
          <span class="material-icons" style="font-size:13px;">event</span>${escapeHTML(fechaFmt)}
        </span>
        ${n.periodo ? `<span style="font-size:0.69rem;background:#ECEFF1;color:#455A64;border-radius:10px;padding:2px 8px;font-weight:700;">P${escapeHTML(String(n.periodo))}</span>` : '<span style="font-size:0.69rem;background:#E3F2FD;color:#1565C0;border-radius:10px;padding:2px 8px;font-weight:700;">Compartida</span>'}
        ${esHoy ? '<span style="font-size:0.68rem;background:#E8F5E9;color:#2E7D32;border-radius:10px;padding:2px 8px;font-weight:700;">Hoy</span>' : (dias !== null ? '<span style="font-size:0.68rem;background:#FFF3E0;color:#E65100;border-radius:10px;padding:2px 8px;font-weight:700;">Hace ' + dias + ' día' + (dias === 1 ? '' : 's') + '</span>' : '')}
        <span style="margin-left:auto;font-size:0.68rem;color:#90A4AE;">${n.texto.length} caracteres</span>
      </div>
      <div style="font-size:0.81rem;color:#37474F;line-height:1.45;white-space:pre-wrap;border-left:3px solid ${color}33;padding-left:8px;">${escapeHTML(n.texto)}</div>
      <div style="display:flex;justify-content:flex-end;margin-top:6px;">
        <button onclick="_cargarNotaHistoricaEnModal('${textoEnc}')"
          style="background:none;border:1px solid #BBDEFB;color:#1565C0;border-radius:12px;padding:3px 10px;font-size:0.72rem;cursor:pointer;display:inline-flex;align-items:center;gap:3px;">
          <span class="material-icons" style="font-size:13px;">history</span> Cargar en nota actual
        </button>
      </div>
    </div>`;
  }).join('')}</div>`;
}

function _cargarNotaHistoricaEnModal(textoCodificado) {
  const ta = document.getElementById('mcl-nota-textarea');
  if (!ta) return;
  let texto = '';
  try { texto = decodeURIComponent(textoCodificado || ''); } catch { texto = textoCodificado || ''; }
  ta.value = texto;
  ta.focus();
  const key = ta.getAttribute('data-nota-key') || '';
  if (key) guardarNotaClaseDebounce(key, texto);
  const ind = document.getElementById('mcl-nota-guardada');
  if (ind) ind.style.display = 'none';
  mostrarToast('Nota anterior cargada en la nota actual', 'success');
}

// ── Modal de detalle de clase ────────────────────────────────────
function abrirModalClase(encodedData) {
  let d;
  try { d = JSON.parse(decodeURIComponent(encodedData)); } catch { return; }
  const color = d.color || '#1565C0';

  const FORM_EVAL = [
    { id: 'exposicion', icono: 'mic', label: 'Exposición oral' },
    { id: 'cuaderno', icono: 'menu_book', label: 'Cuaderno / Portafolio' },
    { id: 'participacion', icono: 'record_voice_over', label: 'Participación' },
    { id: 'practica', icono: 'computer', label: 'Práctica / Lab' },
    { id: 'trabajo', icono: 'assignment', label: 'Trabajo escrito' },
    { id: 'examen', icono: 'quiz', label: 'Examen / Prueba' },
    { id: 'proyecto', icono: 'engineering', label: 'Proyecto' },
    { id: 'actitud', icono: 'emoji_people', label: 'Actitud / Comportamiento' },
  ];

  const evalKey = `eval_${d.fecha}_${d.seccion}_${d.periodo}`;
  const notaKey = _notaClaseKeyV2(d.fecha, d.seccion || '', d.materia || '');
  let savedEval = {};
  let savedNota = '';
  try { savedEval = JSON.parse(localStorage.getItem(evalKey) || '{}'); } catch { }
  try { savedNota = localStorage.getItem(notaKey) || ''; } catch { }
  if (!savedNota) {
    const legacy = _buscarNotaLegacyMismaClase(d.fecha, d.seccion || '');
    if (legacy) {
      savedNota = legacy;
      try { localStorage.setItem(notaKey, legacy); } catch { }
    }
  }

  const asistModuloActivo = localStorage.getItem('cfg_asistencia_activa') !== 'false';
  const asistData = cargarAsistencia();
  const cursoConSeccion = Object.values(calState.cursos).find(c => c.nombre === d.seccion);
  const asistDia = cursoConSeccion ? ((asistData[cursoConSeccion.id] || {})[d.fecha] || {}) : {};
  const nEst = cursoConSeccion ? (cursoConSeccion.estudiantes || []).length : 0;
  const nPres = Object.values(asistDia).filter(v => v === 'P').length;
  const nAus = Object.values(asistDia).filter(v => v === 'A').length;
  const nTard = Object.values(asistDia).filter(v => v === 'T').length;
  const asistRegistrada = nPres + nAus + nTard > 0;

  const allSesiones = (d.sesiones && d.sesiones.length) ? d.sesiones : [];
  const sesionInfo = allSesiones[0] || null;
  const recursoActId = sesionInfo ? sesionInfo.actId : `recurso_${d.fecha}_${d.seccion}_${d.periodo}`;
  const sesion = sesionInfo ? (estadoDiarias.sesiones[sesionInfo.actId] || {}) : (estadoDiarias.sesiones[recursoActId] || {});
  const tiempos = sesion.tiempos || { ini: 20, des: 55, cie: 15 };
  const recursoUrl = sesion.recursoUrl || '';

  document.getElementById('modal-title').innerHTML =
    `<span style="color:${color};">●</span> ${escapeHTML(d.materia)}
     <span style="font-size:0.78rem;font-weight:400;color:#fff;margin-left:8px;">P${d.periodo} · ${d.hora}</span>`;

  document.getElementById('modal-body').innerHTML = `
    <div style="display:flex;flex-direction:column;gap:14px;">

      <!-- Info básica -->
      <div class="modal-clase-header" style="border-left:4px solid ${color};padding-left:12px;">
        ${d.seccion ? `<div class="mcl-row"><span class="material-icons">group</span><strong>${escapeHTML(d.seccion)}</strong></div>` : ''}
        ${d.aula ? `<div class="mcl-row"><span class="material-icons">room</span>${escapeHTML(d.aula)}</div>` : ''}
        ${d.notas ? `<div class="mcl-row"><span class="material-icons">info</span>${escapeHTML(d.notas)}</div>` : ''}
      </div>

      <!-- Actividades / Planificación -->
      ${allSesiones.length > 0 ? allSesiones.map((si, idx) => {
        const ses = estadoDiarias.sesiones[si.actId] || {};
        const t = ses.tiempos || { ini: 20, des: 55, cie: 15 };
        const rUrl = ses.recursoUrl || '';
        const sIni = ses.inicio || {};
        const sDev = ses.desarrollo || {};
        const sCie = ses.cierre || {};
        const hasDiaria = sIni.apertura || sDev.procedimental || sCie.sintesis;
        return `
      <div class="mcl-seccion">
        <div class="mcl-titulo"><span class="material-icons">description</span>Actividad planificada${allSesiones.length > 1 ? ' (' + (idx+1) + '/' + allSesiones.length + ')' : ''}</div>
        ${(si.ra?.descripcion || si.dg?.moduloFormativo) ? `
        <div class="mcl-ra-box" style="background:#E8F5E9;border-left:3px solid #2E7D32;border-radius:6px;padding:8px 12px;margin-bottom:10px;font-size:0.78rem;">
          <div class="mcl-ra-box-title" style="font-weight:700;color:#1B5E20;display:flex;align-items:center;gap:5px;margin-bottom:2px;">
            <span class="material-icons" style="font-size:14px;">school</span>
            RA${si.dg?.moduloFormativo ? ' — ' + escapeHTML(si.dg.moduloFormativo) : ''}
          </div>
          ${si.ra?.descripcion ? `<div class="mcl-ra-box-desc" style="color:#2E7D32;line-height:1.45;font-weight:600;">${escapeHTML(si.ra.descripcion)}</div>` : ''}
        </div>` : ''}
        <div class="mcl-actividad-txt">${escapeHTML(si.enunciado)}</div>
        ${si.instrumento ? `
        <div class="mcl-instrumento" style="background:${color}18;border-color:${color}44;">
          <span class="material-icons" style="color:${color};">${si.instrumento.tipo === 'rubrica' ? 'table_chart' : 'checklist'}</span>
          <span><strong>${escapeHTML(si.instrumento.tipoLabel || '')}</strong></span>
        </div>` : ''}
        <div class="mcl-tiempos">
          <span class="mcl-tiempo ini">Inicio&nbsp;${t.ini}min</span>
          <span class="mcl-tiempo des">Desarrollo&nbsp;${t.des}min</span>
          <span class="mcl-tiempo cie">Cierre&nbsp;${t.cie}min</span>
        </div>
        ${hasDiaria ? `
          <div class="mcl-sesion-diaria">
            <button class="mcl-sesion-toggle" onclick="this.parentElement.classList.toggle('mcl-sesion-open')" style="color:${color};border-color:${color}44;">
              <span class="material-icons" style="font-size:15px;">calendar_today</span>
              <strong>Planificación diaria</strong>
              <span class="material-icons mcl-sesion-chevron" style="margin-left:auto;font-size:18px;transition:transform 0.2s;">expand_more</span>
            </button>
            <div class="mcl-sesion-contenido">
              ${sIni.apertura ? `
              <div class="mcl-momento" style="border-left:3px solid #4CAF50;">
                <div class="mcl-momento-hdr" style="color:#2E7D32;"><span class="material-icons">play_circle_filled</span>1er Momento — Inicio (${t.ini} min)</div>
                <div class="mcl-momento-txt">${sIni.apertura.replace(/\n/g, '<br>')}</div>
              </div>` : ''}
              ${sDev.procedimental ? `
              <div class="mcl-momento" style="border-left:3px solid #2196F3;">
                <div class="mcl-momento-hdr" style="color:#1565C0;"><span class="material-icons">play_circle_filled</span>2do Momento — Desarrollo (${t.des} min)</div>
                <div class="mcl-momento-txt">${sDev.procedimental.replace(/\n/g, '<br>')}</div>
              </div>` : ''}
              ${sCie.sintesis ? `
              <div class="mcl-momento" style="border-left:3px solid #FF9800;">
                <div class="mcl-momento-hdr" style="color:#E65100;"><span class="material-icons">play_circle_filled</span>3er Momento — Cierre (${t.cie} min)</div>
                <div class="mcl-momento-txt">${sCie.sintesis.replace(/\n/g, '<br>')}</div>
              </div>` : ''}
              ${ses.estrategias ? `
              <div class="mcl-momento" style="border-left:3px solid #9C27B0;margin-top:4px;">
                <div class="mcl-momento-hdr" style="color:#6A1B9A;"><span class="material-icons">lightbulb</span>Estrategias</div>
                <div class="mcl-momento-txt">${ses.estrategias.replace(/\n/g, '<br>')}</div>
              </div>` : ''}
            </div>
          </div>` : ''}
        <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">
          <button onclick="cerrarModalBtn();cargarPlanEnPaso1('${si.planId}');" class="mcl-btn-link" style="color:#1565C0;border-color:#90CAF9;">
            <span class="material-icons" style="font-size:14px;">edit_note</span> Ver planificación
          </button>
          ${!hasDiaria ? `<button onclick="cerrarModalBtn();cargarPlanEnPaso5('${si.planId}');" class="mcl-btn-link" style="color:${color};border-color:${color}44;">
            <span class="material-icons" style="font-size:14px;">open_in_new</span> Planificación diaria
          </button>` : ''}
          ${rUrl ? `<a href="${rUrl}" target="_blank" rel="noopener" class="mcl-btn-link" style="color:#0277BD;border-color:#B3E5FC;text-decoration:none;">
            <span class="material-icons" style="font-size:14px;">link</span> Recurso
          </a>` : ''}
          <button onclick="moverActividadUnicaDesdeModal('${encodeURIComponent(JSON.stringify({planId:si.planId,actId:si.actId,fecha:d.fecha,seccion:d.seccion||'',materia:d.materia||'',color}))}')" class="mcl-btn-link" style="color:#0277BD;border-color:#B3E5FC;">
            <span class="material-icons" style="font-size:14px;">event_repeat</span> Mover
          </button>
        </div>
        ${_renderBtnGuiaHtml(si.actId)}
        <!-- Forma de evaluación por actividad -->
        ${(() => {
          const actEvalKey = evalKey + '_' + si.actId;
          let actEval = {};
          try { actEval = JSON.parse(localStorage.getItem(actEvalKey) || '{}'); } catch {}
          return `<div class="mcl-divisor" style="margin-top:10px;padding-top:10px;border-top:1px solid #F0F0F0;">
            <div style="font-size:0.72rem;font-weight:700;color:#78909C;text-transform:uppercase;letter-spacing:0.04em;margin-bottom:6px;display:flex;align-items:center;gap:4px;">
              <span class="material-icons" style="font-size:13px;">star_rate</span>Forma de evaluación
            </div>
            <div class="mcl-eval-grid">
              ${FORM_EVAL.map(f => `
              <button class="mcl-eval-btn ${actEval[f.id] ? 'activo' : ''}"
                style="font-size:0.72rem;padding:5px 8px;${actEval[f.id] ? `background:${color}18;border-color:${color};color:${color};` : ''}"
                onclick="toggleFormaEval('${actEvalKey}','${f.id}','${color}',this)">
                <span class="material-icons" style="font-size:13px;">${f.icono}</span>
                <span>${f.label}</span>
              </button>`).join('')}
            </div>
          </div>`;
        })()}
      </div>`;
      }).join('') : `
      <div class="mcl-seccion mcl-seccion-vacia" style="background:#F5F5F5;border-radius:8px;padding:12px;text-align:center;color:#9E9E9E;font-size:0.82rem;">
        <span class="material-icons" style="font-size:1.8rem;display:block;margin-bottom:4px;opacity:0.4;">event_note</span>
        Sin actividad planificada para esta fecha.<br>
        <button onclick="cerrarModalBtn();abrirDiarias();" style="margin-top:8px;background:none;border:1.5px solid #90CAF9;color:#1565C0;border-radius:20px;padding:4px 14px;font-size:0.78rem;cursor:pointer;">
          Crear planificación diaria
        </button>
      </div>`}

      <!-- Enlace de recurso (cuando no hay actividades planificadas) -->
      ${allSesiones.length === 0 ? `
      <div class="mcl-seccion">
        <div style="margin-top:2px;">
          <label style="font-size:0.72rem;color:#78909C;font-weight:600;display:block;margin-bottom:3px;">
            <span class="material-icons" style="font-size:14px;vertical-align:middle;">link</span> Enlace de recurso
          </label>
          <div style="display:flex;gap:6px;align-items:center;">
            <input id="mcl-recurso-url" type="url" value="${(recursoUrl||'').replace(/"/g,'&quot;')}" placeholder="https://ejemplo.com/recurso"
              style="flex:1;padding:6px 10px;border:1.5px solid #B0BEC5;border-radius:8px;font-size:0.82rem;outline:none;"
              onchange="_guardarRecursoDesdeModal('${recursoActId}',this.value)">
            ${recursoUrl ? `<a href="${recursoUrl}" target="_blank" rel="noopener" title="Abrir recurso"
              style="color:#0277BD;font-size:1.2rem;display:flex;align-items:center;">
              <span class="material-icons">open_in_new</span>
            </a>` : ''}
          </div>
        </div>
      </div>` : ''}

      <!-- Asistencia rápida -->
      ${asistModuloActivo ? `
      <div class="mcl-seccion">
        <div class="mcl-titulo"><span class="material-icons">how_to_reg</span>Asistencia
          ${asistRegistrada ? `<span class="mcl-badge-ok" style="font-size:0.7rem;background:#E8F5E9;color:#2E7D32;border-radius:10px;padding:2px 8px;margin-left:6px;font-weight:700;">Registrada</span>` : ''}
        </div>
        ${nEst > 0 ? `
        <div class="mcl-asist-resumen">
          <span class="mcl-asist-chip pres"><span class="material-icons">check_circle</span>${nPres} P</span>
          <span class="mcl-asist-chip tard"><span class="material-icons">schedule</span>${nTard} T</span>
          <span class="mcl-asist-chip ause"><span class="material-icons">cancel</span>${nAus} A</span>
          <span style="color:#78909C;font-size:0.75rem;">/ ${nEst} estudiantes</span>
        </div>` : '<p style="font-size:0.8rem;color:#9E9E9E;">Curso sin estudiantes registrados.</p>'}
        <button onclick="cerrarModalBtn();abrirCalificaciones();setTimeout(()=>toggleVistaAsistencia(),300);"
          class="mcl-btn-link" style="color:#00695C;border-color:#B2DFDB;">
          <span class="material-icons" style="font-size:14px;">how_to_reg</span>
          ${asistRegistrada ? 'Ver / editar asistencia' : 'Pasar lista ahora'}
        </button>
      </div>` : ''}

      <!-- Tarea rápida -->
      <div class="mcl-seccion">
        <div class="mcl-titulo">
          <span class="material-icons">assignment_add</span>Dejar tarea
        </div>
        ${_renderTareasDelCurso(d.seccion, color)}
        <div style="display:flex;gap:8px;margin-top:8px;align-items:flex-end;">
          <input id="mcl-tarea-desc" type="text" placeholder="Descripción de la tarea..."
            style="flex:1;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.85rem;font-family:inherit;outline:none;"
            onfocus="this.style.borderColor='${color}'" onblur="this.style.borderColor='#E0E0E0'"
            onkeydown="if(event.key==='Enter')_crearTareaDesdeModal('${escapeHTML(d.seccion)}')"/>
          <input id="mcl-tarea-fecha" type="date"
            style="padding:8px 6px;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.82rem;font-family:inherit;outline:none;color:#546E7A;"
            onfocus="this.style.borderColor='${color}'" onblur="this.style.borderColor='#E0E0E0'"/>
          <button onclick="_crearTareaDesdeModal('${escapeHTML(d.seccion)}')"
            style="background:${color};color:#fff;border:none;border-radius:8px;padding:8px 14px;font-size:0.82rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:4px;white-space:nowrap;">
            <span class="material-icons" style="font-size:15px;">add</span>Agregar
          </button>
        </div>
      </div>

      <!-- Calificar actividades rápido -->
      ${cursoConSeccion && (cursoConSeccion.estudiantes||[]).length > 0 && allSesiones.filter(s=>s.planId).length > 0 ? (() => {
        const estudiantes = cursoConSeccion.estudiantes || [];
        const sesionesConPlan = allSesiones.filter(s => s.planId);
        const tituloSeccion = sesionesConPlan.length > 1 ? `Calificar (${sesionesConPlan.length} actividades)` : 'Calificar actividad';
        let html = `<div class="mcl-seccion">
          <div class="mcl-titulo" onclick="const b=document.getElementById('mcl-cal-body');const ic=document.getElementById('mcl-cal-icon');if(b){b.style.display=b.style.display==='none'?'block':'none';ic.style.transform=b.style.display==='none'?'':'rotate(180deg)';}" style="cursor:pointer;user-select:none;">
            <span class="material-icons">grade</span>${tituloSeccion}
            <span style="font-size:0.7rem;color:#9E9E9E;font-weight:400;margin-left:4px;">${estudiantes.length} est.</span>
            <span class="material-icons" id="mcl-cal-icon" style="margin-left:auto;font-size:20px;transition:transform 0.2s;">expand_more</span>
          </div>
          <div id="mcl-cal-body" style="display:none;margin-top:8px;">`;
        sesionesConPlan.forEach((si, rendIdx) => {
          const rk = _getPlanIdClave(si.planId);
          const maxVal = (cursoConSeccion.ras?.[rk]?.valores?.[si.actId]) ?? 10;
          if (rendIdx > 0) html += `<div class="mcl-divisor" style="height:1px;background:#F0F0F0;margin:14px 0;"></div>`;
          html += `<div style="margin-bottom:6px;">
            <div style="font-size:0.72rem;font-weight:700;color:${color};display:flex;align-items:center;gap:4px;margin-bottom:6px;">
              <span class="material-icons" style="font-size:13px;">assignment</span>
              Act. ${rendIdx+1}${sesionesConPlan.length > 1 ? ' / ' + sesionesConPlan.length : ''}
              <span style="font-weight:400;color:#78909C;margin-left:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:220px;" title="${escapeHTML(si.enunciado||'')}">— ${escapeHTML((si.enunciado||'').substring(0,60))}${(si.enunciado||'').length>60?'…':''}</span>
            </div>
            <div style="display:grid;grid-template-columns:1fr 88px;gap:4px 8px;align-items:center;">
              <span style="font-size:0.68rem;font-weight:700;color:#B0BEC5;text-transform:uppercase;letter-spacing:0.04em;">Estudiante</span>
              <span style="font-size:0.68rem;font-weight:700;color:#B0BEC5;text-align:center;">/ ${maxVal} pts</span>`;
          estudiantes.forEach(est => {
            const notaActual = cursoConSeccion.notas?.[est.id]?.[rk]?.[si.actId] ?? '';
            html += `<span style="font-size:0.82rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${escapeHTML(est.nombre)}">${escapeHTML(est.nombre)}</span>
              <input type="number" min="0" max="${maxVal}" step="0.1" value="${notaActual}" placeholder="—"
                style="width:100%;padding:5px 6px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.9rem;text-align:center;box-sizing:border-box;"
                onfocus="this.style.borderColor='${color}'" onblur="this.style.borderColor='#E0E0E0'"
                oninput="_notaModalGuardar('${cursoConSeccion.id}','${rk}','${est.id}','${si.actId}',this.value,${maxVal})">`;
          });
          html += `</div></div>`;
        });
        html += `</div></div>`;
        return html;
      })() : ''}

      <!-- Notas rápidas de clase -->
      <div class="mcl-seccion">
        <div class="mcl-titulo">
          <span class="material-icons">edit_note</span>Notas de la clase
          <span id="mcl-nota-guardada" style="margin-left:auto;font-size:0.68rem;color:#9E9E9E;font-weight:400;display:none;">
            <span class="material-icons" style="font-size:11px;vertical-align:middle;">check</span> Guardado
          </span>
        </div>
        <p style="font-size:0.75rem;color:#78909C;margin:0 0 8px;">
          Lo que pasó realmente en clase, observaciones, pendientes para la próxima vez…
        </p>
        <textarea id="mcl-nota-textarea"
          data-nota-key="${notaKey}"
          placeholder="Ej: Los estudiantes llegaron tarde. Cubrimos el tema hasta la sección 2. Pendiente: traer material de práctica el jueves..."
          style="width:100%;min-height:110px;padding:10px 12px;border:1.5px solid #E0E0E0;border-radius:9px;
                 font-size:0.85rem;font-family:inherit;resize:vertical;line-height:1.5;
                 transition:border-color 0.15s;box-sizing:border-box;"
          onfocus="this.style.borderColor='${color}'"
          onblur="this.style.borderColor='#E0E0E0'"
          oninput="guardarNotaClaseDebounce('${notaKey}',this.value)"
        >${escapeHTML(savedNota)}</textarea>
        ${savedNota ? `
        <div style="display:flex;justify-content:flex-end;margin-top:6px;">
          <button onclick="borrarNotaClase('${notaKey}')"
            style="background:none;border:none;color:#BDBDBD;font-size:0.72rem;cursor:pointer;display:flex;align-items:center;gap:3px;">
            <span class="material-icons" style="font-size:13px;">delete_outline</span> Borrar nota
          </button>
        </div>` : ''}

        <div style="margin-top:10px;padding-top:10px;border-top:1px dashed #E0E0E0;">
          <div style="font-size:0.74rem;font-weight:700;color:#607D8B;margin-bottom:6px;display:flex;align-items:center;gap:4px;">
            <span class="material-icons" style="font-size:14px;">history</span>
            Historial de esta clase (${escapeHTML(d.seccion || '')} · ${escapeHTML(d.materia || 'Módulo')})
          </div>
          <p style="font-size:0.72rem;color:#90A4AE;margin:0 0 7px;">Aquí puedes ver todo lo que anotaste en clases anteriores para este mismo grupo y módulo (P1/P2 comparten notas).</p>
          ${_renderHistorialNotasClaseHTML(d.seccion || '', d.materia || '', d.fecha || '', color)}
        </div>
      </div>

      <!-- Ir a calificaciones -->
      <button onclick="cerrarModalBtn();_irACalificacionesPlan('${sesionInfo?.cursoId || cursoConSeccion?.id || ''}','${sesionInfo?.planId || ''}');"
        class="mcl-btn-link" style="color:#E65100;border-color:#FFCCBC;width:100%;justify-content:center;">
        <span class="material-icons" style="font-size:15px;">grade</span> Ir al libro de calificaciones
      </button>

    </div>`;

  // botones en body

  document.getElementById('modal-overlay').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

// ── Calificar actividad desde modal de clase ─────────────────────
function _notaModalGuardar(cursoId, raKey, estId, actId, valor, maxVal) {
  const curso = calState.cursos[cursoId];
  if (!curso) return;
  if (!curso.notas) curso.notas = {};
  if (!curso.notas[estId]) curso.notas[estId] = {};
  if (!curso.notas[estId][raKey]) curso.notas[estId][raKey] = {};
  const num = parseFloat(valor);
  if (valor === '' || isNaN(num)) {
    delete curso.notas[estId][raKey][actId];
  } else {
    const max = parseFloat(maxVal) || 100;
    curso.notas[estId][raKey][actId] = Math.min(max, Math.max(0, num));
  }
  guardarCalificaciones();
}

// ── Debounce para guardado de notas de clase ─────────────────────
let _notaDebounceTimer = null;
function guardarNotaClaseDebounce(key, valor) {
  clearTimeout(_notaDebounceTimer);
  const ind = document.getElementById('mcl-nota-guardada');
  if (ind) ind.style.display = 'none';
  _notaDebounceTimer = setTimeout(() => {
    localStorage.setItem(key, valor);
    registrarCambio('Nota de clase actualizada');
    if (ind) { ind.style.display = 'inline'; }
    if (window._syncFirebase) {
      const data = {};
      Object.keys(localStorage).filter(k => k.startsWith('notaclase_') || k.startsWith('notaclasev2_')).forEach(k => { data[k] = localStorage.getItem(k); });
      _syncFirebase('notas_clase', data);
    }
  }, 600);
}

function borrarNotaClase(key) {
  if (!confirm('¿Borrar la nota de esta clase?')) return;
  localStorage.removeItem(key);
  const ta = document.getElementById('mcl-nota-textarea');
  if (ta) ta.value = '';
  mostrarToast('Nota borrada', 'success');
  if (window._syncFirebase) {
    const data = {};
    Object.keys(localStorage).filter(k => k.startsWith('notaclase_') || k.startsWith('notaclasev2_')).forEach(k => { data[k] = localStorage.getItem(k); });
    _syncFirebase('notas_clase', data);
  }
}

function _guardarRecursoDesdeModal(actId, url) {
  if (!estadoDiarias.sesiones[actId]) estadoDiarias.sesiones[actId] = {};
  estadoDiarias.sesiones[actId].recursoUrl = url.trim();
  persistirDiarias();
  // Actualizar el icono de abrir enlace junto al input
  const inp = document.getElementById('mcl-recurso-url');
  if (inp) {
    const wrapper = inp.parentElement;
    const oldLink = wrapper.querySelector('a');
    if (url.trim()) {
      if (oldLink) { oldLink.href = url.trim(); }
      else {
        const a = document.createElement('a');
        a.href = url.trim(); a.target = '_blank'; a.rel = 'noopener'; a.title = 'Abrir recurso';
        a.style.cssText = 'color:#0277BD;font-size:1.2rem;display:flex;align-items:center;';
        a.innerHTML = '<span class="material-icons">open_in_new</span>';
        wrapper.appendChild(a);
      }
    } else if (oldLink) { oldLink.remove(); }
  }
}

// ── Tarea rápida desde modal de clase ──────────────────────────────
function _renderTareasDelCurso(seccion, color) {
  const tareas = cargarTareas().filter(t => t.seccion === seccion && t.estado !== 'entregada');
  if (!tareas.length) return '';
  return `<div style="margin-bottom:6px;">
    ${tareas.slice(0, 3).map(t => `
      <div style="display:flex;align-items:center;gap:6px;padding:5px 8px;background:#F5F5F5;border-radius:7px;margin-bottom:4px;font-size:0.8rem;">
        <span class="material-icons" style="font-size:14px;color:${color};">assignment</span>
        <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHTML(t.descripcion)}</span>
        ${t.fechaLimite ? `<span style="color:#9E9E9E;font-size:0.72rem;white-space:nowrap;">${t.fechaLimite}</span>` : ''}
      </div>`).join('')}
    ${tareas.length > 3 ? `<div style="font-size:0.72rem;color:#9E9E9E;padding-left:4px;">+${tareas.length - 3} más en Tareas</div>` : ''}
  </div>`;
}

function _crearTareaDesdeModal(seccion) {
  const descEl = document.getElementById('mcl-tarea-desc');
  const fechaEl = document.getElementById('mcl-tarea-fecha');
  if (!descEl) return;
  const desc = descEl.value.trim();
  if (!desc) { descEl.focus(); return; }
  const fecha = fechaEl?.value || '';
  const tareas = cargarTareas();
  tareas.push({
    id: uid(),
    descripcion: desc,
    seccion: seccion || '',
    fechaLimite: fecha,
    horaLimite: '',
    observaciones: '',
    estado: 'pendiente',
    creadaEn: new Date().toISOString()
  });
  guardarTareas(tareas);
  registrarCambio(`Tarea creada desde modal: "${desc.substring(0, 60)}"${seccion ? ' — ' + seccion : ''}`);
  mostrarToast('Tarea agregada ✓', 'success');
  descEl.value = '';
  if (fechaEl) fechaEl.value = '';
  // Refrescar la lista de tareas en el modal
  const listEl = descEl.closest('.mcl-seccion')?.querySelector('div[style*="margin-bottom:6px"]');
  if (listEl) listEl.outerHTML = _renderTareasDelCurso(seccion, '');
}

// ── Guía HTML adjunta a actividad (Firebase Storage) ───────────────────────
// Metadatos en Firestore: users/{uid}/data/guias_meta → { [actId]: { nombre, url, fecha } }
// Archivo real en Storage: guias/{uid}/{actId}.html

function _guiasDataRef() {
  if (!window.currentUser) return null;
  return db.collection('users').doc(window.currentUser.uid).collection('data').doc('guias_meta');
}

function _guiaStorageRef(actId) {
  if (!window.currentUser) return null;
  return storage.ref(`guias/${window.currentUser.uid}/${actId}.html`);
}

// Cache en memoria para no ir a Firestore en cada render del modal
const _guiasCache = {};

async function _cargarGuiasMeta() {
  const ref = _guiasDataRef();
  if (!ref) return;
  const doc = await ref.get();
  if (doc.exists && doc.data().payload) {
    const data = JSON.parse(doc.data().payload);
    Object.assign(_guiasCache, data);
  }
}

async function _persistirGuiasMeta() {
  const ref = _guiasDataRef();
  if (!ref) return;
  await ref.set({ payload: JSON.stringify(_guiasCache) });
}

function _renderBtnGuiaHtml(actId) {
  const meta = _guiasCache[actId];
  if (meta) {
    return `<div data-guia-act="${actId}" style="display:flex;align-items:center;gap:6px;margin-top:6px;background:#E8F5E9;border:1.5px solid #A5D6A7;border-radius:8px;padding:7px 10px;">
      <span class="material-icons" style="font-size:16px;color:#2E7D32;">html</span>
      <span style="flex:1;font-size:0.78rem;color:#2E7D32;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${escapeHTML(meta.nombre || 'Guía HTML')}">${escapeHTML(meta.nombre || 'Guía HTML')}</span>
      <button onclick="_abrirGuiaHtml('${actId}')" title="Abrir guía en nueva pestaña"
        style="background:#2E7D32;color:#fff;border:none;border-radius:6px;padding:4px 10px;font-size:0.75rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:4px;white-space:nowrap;font-family:inherit;">
        <span class="material-icons" style="font-size:13px;">open_in_new</span> Abrir
      </button>
      <button onclick="_eliminarGuiaHtml('${actId}')" title="Quitar guía"
        style="background:none;border:none;color:#C62828;cursor:pointer;padding:2px;border-radius:4px;display:flex;align-items:center;">
        <span class="material-icons" style="font-size:16px;">close</span>
      </button>
    </div>`;
  }
  return `<div data-guia-act="${actId}" style="margin-top:6px;">
    <label style="display:inline-flex;align-items:center;gap:5px;font-size:0.75rem;font-weight:600;color:#546E7A;cursor:pointer;
      background:#FAFAFA;border:1.5px dashed #B0BEC5;border-radius:8px;padding:6px 12px;transition:background 0.15s;"
      onmouseover="this.style.background='#ECEFF1'" onmouseout="this.style.background='#FAFAFA'">
      <span class="material-icons" style="font-size:15px;">attach_file</span> Adjuntar guía HTML
      <input type="file" accept=".html,.htm" style="display:none;" onchange="_subirGuiaHtml('${actId}',this)">
    </label>
  </div>`;
}

function _refrescarBtnGuia(actId) {
  const el = document.querySelector(`[data-guia-act="${actId}"]`);
  if (!el) return;
  const tmp = document.createElement('div');
  tmp.innerHTML = _renderBtnGuiaHtml(actId);
  el.replaceWith(tmp.firstElementChild);
}

async function _subirGuiaHtml(actId, input) {
  const file = input.files[0];
  if (!file) return;
  if (file.size > 10 * 1024 * 1024) { mostrarToast('El archivo es demasiado grande (máx. 10 MB)', 'error'); return; }
  if (!window.currentUser) { mostrarToast('Debes iniciar sesión', 'error'); return; }

  // Mostrar estado de carga en el botón
  const label = input.closest('label');
  const textoOrig = label ? label.textContent.trim() : '';
  if (label) label.innerHTML = '<span class="material-icons" style="font-size:15px;animation:spin 0.7s linear infinite;">refresh</span> Subiendo...';

  try {
    const ref = _guiaStorageRef(actId);
    await ref.put(file, { contentType: 'text/html' });
    const url = await ref.getDownloadURL();

    const meta = { nombre: file.name, url, fecha: new Date().toISOString() };
    _guiasCache[actId] = meta;
    await _persistirGuiasMeta();

    _refrescarBtnGuia(actId);
    mostrarToast('Guía guardada en Firebase', 'success');
  } catch(err) {
    console.error('Error subiendo guía:', err);
    if (label) label.innerHTML = `<span class="material-icons" style="font-size:15px;">attach_file</span> ${textoOrig}`;
    mostrarToast('Error al subir la guía: ' + (err.message || err), 'error');
  }
}

async function _abrirGuiaHtml(actId) {
  const meta = _guiasCache[actId];
  if (!meta?.url) { mostrarToast('Guía no encontrada', 'error'); return; }
  try {
    const resp = await fetch(meta.url);
    const html = await resp.text();
    const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
    const blobUrl = URL.createObjectURL(blob);
    const win = window.open(blobUrl, '_blank');
    if (win) win.addEventListener('load', () => setTimeout(() => URL.revokeObjectURL(blobUrl), 2000));
  } catch(err) {
    // Fallback: abrir URL directa de Storage
    window.open(meta.url, '_blank');
  }
}

async function _eliminarGuiaHtml(actId) {
  if (!confirm('¿Quitar la guía HTML adjunta? Se eliminará de Firebase.')) return;
  try { await _guiaStorageRef(actId).delete(); } catch(e) { /* ya no existía en Storage */ }
  delete _guiasCache[actId];
  try { await _persistirGuiasMeta(); } catch(e) { /* ignorar */ }
  _refrescarBtnGuia(actId);
  mostrarToast('Guía eliminada', 'success');
}

function toggleFormaEval(evalKey, formaId, color, btn) {
  let saved = {};
  try { saved = JSON.parse(localStorage.getItem(evalKey) || '{}'); } catch { }
  saved[formaId] = !saved[formaId];
  localStorage.setItem(evalKey, JSON.stringify(saved));
  const activo = saved[formaId];
  registrarCambio(`Forma de evaluación ${formaId} ${activo ? 'activada' : 'desactivada'}`);
  btn.classList.toggle('activo', activo);
  btn.style.background = activo ? color + '18' : '';
  btn.style.borderColor = activo ? color : '';
  btn.style.color = activo ? color : '';
  if (window._syncFirebase) {
    const data = {};
    Object.keys(localStorage).filter(k => k.startsWith('eval_')).forEach(k => { data[k] = localStorage.getItem(k); });
    _syncFirebase('eval_formas', data);
  }
}


// ── Tareas próximas (7 días) ─────────────────────────────────────
function _renderizarTareasProximas() {
  const cont = document.getElementById('dash-tareas-proximas');
  if (!cont) return;

  const tareas = cargarTareas();
  const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
  const en7 = new Date(hoy); en7.setDate(en7.getDate() + 7);

  const proximas = tareas
    .map(t => ({ ...t, _estado: _estadoTarea(t) }))
    .filter(t => {
      if (t._estado === 'entregada') return false;
      if (!t.fechaLimite) return t._estado === 'vencida';
      const fl = new Date(t.fechaLimite); fl.setHours(0, 0, 0, 0);
      return fl <= en7;
    })
    .sort((a, b) => {
      if (!a.fechaLimite) return 1;
      if (!b.fechaLimite) return -1;
      return new Date(a.fechaLimite) - new Date(b.fechaLimite);
    })
    .slice(0, 8); // max 8 en el dash

  if (proximas.length === 0) {
    cont.innerHTML = `<div class="dash-empty-card"><span class="material-icons">task_alt</span><p>Sin tareas pendientes esta semana 🎉</p></div>`;
    return;
  }

  cont.innerHTML = proximas.map(t => {
    const dias = _diasRestantes(t.fechaLimite);
    const estadoCls = { pendiente: 'dash-tarea-pend', vencida: 'dash-tarea-venc' }[t._estado] || 'dash-tarea-pend';
    let diasStr = '';
    if (t._estado === 'vencida') diasStr = `<span class="dt-dias venc">Vencida</span>`;
    else if (dias === 0) diasStr = `<span class="dt-dias hoy">Hoy</span>`;
    else if (dias === 1) diasStr = `<span class="dt-dias pronto">Mañana</span>`;
    else diasStr = `<span class="dt-dias">En ${dias}d</span>`;

    const horaStr = t.horaLimite ? ` · ${t.horaLimite}` : '';
    const fechaStr = t.fechaLimite
      ? new Date(t.fechaLimite + 'T12:00:00').toLocaleDateString('es-DO', { weekday: 'short', day: '2-digit', month: 'short' }) + horaStr
      : '';

    return `<div class="dash-tarea-row ${estadoCls}">
      <div class="dt-left">
        <span class="dt-seccion">${escapeHTML(t.seccion || '—')}</span>
        <span class="dt-desc">${escapeHTML((t.descripcion || '').substring(0, 50))}${(t.descripcion || '').length > 50 ? '…' : ''}</span>
        ${fechaStr ? `<span class="dt-fecha"><span class="material-icons" style="font-size:11px;">event</span>${fechaStr}</span>` : ''}
      </div>
      <div class="dt-right">
        ${diasStr}
        <button onclick="marcarTareaEntregada('${t.id}')" class="dt-check" title="Marcar entregada">
          <span class="material-icons">check</span>
        </button>
      </div>
    </div>`;
  }).join('');
}

// ── Resumen de cursos ────────────────────────────────────────────
function _renderizarResumenCursos() {
  const cont = document.getElementById('dash-cursos');
  if (!cont) return;

  const cursos = Object.values(calState.cursos || {});
  if (cursos.length === 0) {
    cont.innerHTML = `<div class="dash-empty-card"><span class="material-icons">school</span><p>No hay cursos creados aún.<br><button onclick="abrirCalificaciones()" style="margin-top:8px;background:none;border:1.5px solid #90CAF9;color:#1565C0;border-radius:20px;padding:4px 14px;font-size:0.8rem;cursor:pointer;">Crear curso</button></p></div>`;
    return;
  }

  cont.innerHTML = `<div class="dash-cursos-grid">` + cursos.map(curso => {
    const nEst = (curso.estudiantes || []).length;
    const nPlans = (curso.planIds || []).length;
    const _biblioItems = cargarBiblioteca().items || [];
    // Si planActivaId no existe en biblioteca, buscar la primera de planIds que sí exista
    let planActiva = null;
    if (curso.planActivaId) planActiva = _biblioItems.find(i => i.id === curso.planActivaId);
    if (!planActiva && (curso.planIds || []).length) {
      for (const pid of curso.planIds) {
        const found = _biblioItems.find(i => i.id === pid);
        if (found) { planActiva = found; curso.planActivaId = pid; break; }
      }
    }
    const modulo = planActiva?.planificacion?.datosGenerales?.moduloFormativo || '—';

    // Calcular promedio general del curso
    let promedioLabel = '—';
    if (nEst > 0 && planActiva) {
      const raKey = Object.keys(curso.ras || {})[0];
      if (raKey) {
        const pf = _promedioFinal(curso);
        if (pf !== null) promedioLabel = pf.toFixed(1);
      }
    }

    // Tareas pendientes para este curso
    const tareasCurso = cargarTareas().filter(t =>
      t.seccion === curso.nombre && _estadoTarea(t) !== 'entregada'
    );
    const nTareasVenc = tareasCurso.filter(t => _estadoTarea(t) === 'vencida').length;
    const nTareasPend = tareasCurso.filter(t => _estadoTarea(t) === 'pendiente').length;

    const statusColor = nTareasVenc > 0 ? '#C62828' : nTareasPend > 0 ? '#E65100' : '#2E7D32';

    return `<div class="dash-curso-card" onclick="abrirCalificaciones('${curso.id}')">
      <div class="dash-curso-header">
        <div class="dash-curso-nombre">${escapeHTML(curso.nombre)}</div>
        <div class="dash-curso-dot" style="background:${statusColor};"></div>
      </div>
      <div class="dash-curso-modulo" title="${escapeHTML(modulo)}">${escapeHTML(modulo.substring(0, 40))}${modulo.length > 40 ? '…' : ''}</div>
      <div class="dash-curso-stats">
        <span title="Estudiantes"><span class="material-icons" style="font-size:13px;">group</span>${nEst}</span>
        <span title="Planificaciones"><span class="material-icons" style="font-size:13px;">description</span>${nPlans}</span>
          ${promedioLabel !== '—' ? '<span title="Promedio general"><span class="material-icons" style="font-size:13px;">grade</span>' + promedioLabel + '</span>' : ''}
        ${nTareasPend + nTareasVenc > 0 ? '<span style="color:' + statusColor + ';" title="Tareas"><span class="material-icons" style="font-size:13px;">assignment</span>' + (nTareasPend + nTareasVenc) + '</span>' : ''}
      </div>
    </div>`;
  }).join('') + `</div>`;
}

// ── Estadísticas de rendimiento (por curso y por RA) ────────────
function _renderizarEstadisticasDashboard() {
  const cont = document.getElementById('dash-estadisticas');
  if (!cont) return;

  const cursos = Object.values(calState.cursos || {});
  const cursosConEst = cursos.filter(c => (c.estudiantes || []).length > 0 && (c.planIds || []).length > 0);

  if (cursosConEst.length === 0) {
    cont.innerHTML = '<div class="dash-empty-card"><span class="material-icons">bar_chart</span><p>Las estadísticas aparecerán cuando tengas cursos con estudiantes y planificaciones asignadas.</p></div>';
    return;
  }

  // Cargar biblioteca una sola vez
  const biblio = cargarBiblioteca();
  const biblioMap = {};
  (biblio.items || []).forEach(i => { biblioMap[i.id] = i.planificacion; });

  let html = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:14px;">';

  cursosConEst.forEach(curso => {
    const estudiantes = curso.estudiantes || [];
    const planIdsValidos = (curso.planIds || []).filter(pid => biblioMap[pid]);
    if (!planIdsValidos.length) return;

    // Inasistencias a nivel de curso (una sola vez por curso)
    // Requiere al menos 2 sesiones para evitar falsos positivos de prueba
    const inasistentes = estudiantes
      .map(est => ({ nombre: est.nombre, stats: _statsAsistencia(curso.id, est.id) }))
      .filter(x => x.stats.total >= 2 && x.stats.pct !== null && x.stats.pct < 80)
      .sort((a, b) => a.stats.pct - b.stats.pct)
      .slice(0, 3);

    html += '<div class="dash-stat-card" style="background:#fff;border:1px solid #E3F2FD;border-radius:12px;padding:14px 16px;box-shadow:0 1px 6px rgba(0,0,0,0.07);">';

    // Cabecera del curso
    html += '<div class="dash-stat-card-header" style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;padding-bottom:8px;border-bottom:2px solid #E3F2FD;">'
      + '<strong class="dash-stat-card-title" style="font-size:1rem;color:#212121;">'
      + '<span class="material-icons" style="font-size:16px;vertical-align:middle;margin-right:4px;color:#1565C0;">school</span>'
      + escapeHTML(curso.nombre) + '</strong>'
      + '<span class="dash-stat-card-badge" style="font-size:0.75rem;background:#E3F2FD;color:#1565C0;padding:2px 8px;border-radius:10px;">'
      + estudiantes.length + ' estudiantes</span>'
      + '</div>';

    // Una fila por RA/planificación
    planIdsValidos.forEach(planId => {
      const plan = biblioMap[planId];
      const raKey = _getPlanIdClave(planId);
      const raInfo = curso.ras?.[raKey];
      const dg = plan?.datosGenerales || {};
      const ra = plan?.ra || {};
      const moduloLabel = (dg.moduloFormativo || 'Módulo').substring(0, 35);
      const raDesc = (ra.descripcion || '').substring(0, 70);
      const valorTotal = raInfo?.valorTotal || parseFloat(dg.valorRA) || 10;

      let aprobados = 0, reprobados = 0, sinNotas = 0, sumaNotas = 0, conNotas = 0;
      estudiantes.forEach(est => {
        const nota = raInfo ? _calcNotaRA(curso, est.id, raKey) : null;
        if (nota === null) { sinNotas++; return; }
        conNotas++;
        sumaNotas += nota;
        if ((nota / valorTotal) * 100 >= 70) aprobados++; else reprobados++;
      });

      const total = aprobados + reprobados;
      const pctBar = total > 0 ? Math.round((aprobados / total) * 100) : 0;
      const barColor = pctBar >= 70 ? '#2E7D32' : pctBar >= 50 ? '#E65100' : '#C62828';
      const promedio = conNotas > 0 ? (sumaNotas / conNotas).toFixed(1) : null;

      html += '<div class="dash-stat-ra-row" onclick="_irACalificacionesPlan(\'' + curso.id + '\',\'' + planId + '\')" style="margin-bottom:10px;padding:8px 8px 8px 10px;border-left:3px solid ' + barColor + ';cursor:pointer;border-radius:6px;">';
      html += '<div style="font-size:0.82rem;font-weight:700;color:#1565C0;display:flex;justify-content:space-between;align-items:center;">'
        + '<span>' + escapeHTML(moduloLabel) + (moduloLabel.length === 35 ? '…' : '') + '</span>'
        + '<span class="dash-stat-ra-ver" style="font-size:0.65rem;color:#90A4AE;font-weight:400;">Ver →</span>'
        + '</div>';
      if (raDesc) html += '<div class="dash-stat-ra-desc" style="font-size:0.72rem;color:#78909C;margin-bottom:4px;">' + escapeHTML(raDesc) + (raDesc.length === 70 ? '…' : '') + '</div>';

      if (total > 0) {
        html += '<div class="dash-stat-ra-bar-track" style="height:8px;background:#eee;border-radius:4px;overflow:hidden;margin-bottom:3px;">'
          + '<div style="height:8px;background:' + barColor + ';border-radius:4px;width:' + pctBar + '%;"></div></div>';
        html += '<div style="display:flex;flex-wrap:wrap;gap:8px;font-size:0.72rem;">'
          + '<span style="color:' + barColor + ';font-weight:600;">' + aprobados + ' aprobados</span>'
          + '<span style="color:#C62828;">' + reprobados + ' reprobados</span>'
          + (sinNotas ? '<span class="dash-stat-ra-muted">' + sinNotas + ' sin notas</span>' : '')
          + (promedio !== null ? '<span class="dash-stat-ra-muted" style="margin-left:auto;">Prom: <strong>' + promedio + '</strong>/' + valorTotal + '</span>' : '')
          + '</div>';
      } else {
        html += '<div class="dash-stat-ra-muted" style="font-size:0.72rem;font-style:italic;">Sin calificaciones registradas</div>';
      }
      html += '</div>';
    });

    // Alerta de inasistencias al pie de la tarjeta
    if (inasistentes.length > 0) {
      html += '<div class="dash-stat-inasist" style="font-size:0.75rem;color:#E65100;padding-top:8px;border-top:1px dashed #FFE0B2;margin-top:6px;">'
        + '<span class="material-icons" style="font-size:14px;vertical-align:middle;margin-right:2px;">warning</span>'
        + '<strong>Baja asistencia:</strong> '
        + inasistentes.map(x => escapeHTML(x.nombre.split(' ')[0]) + ' (' + x.stats.pct + '% · ' + x.stats.total + ' cls)').join(' · ')
        + '</div>';
    }

    html += '</div>';
  });

  html += '</div>';
  cont.innerHTML = html;
}

// ════════════════════════════════════════════════════════════════════
// BLOG DEL DOCENTE
// ════════════════════════════════════════════════════════════════════

const BLOG_KEY = 'planificadorRA_blog_v1';
let _blogTempAdjuntos = [];

function cargarBlog() {
  try {
    const raw = JSON.parse(localStorage.getItem(BLOG_KEY) || '{"posts":[]}') || {};
    return {
      ...raw,
      posts: Array.isArray(raw.posts) ? raw.posts : [],
      postsArchivados: raw.postsArchivados && typeof raw.postsArchivados === 'object' ? raw.postsArchivados : {}
    };
  } catch {
    return { posts: [], postsArchivados: {} };
  }
}
function guardarBlog(data) {
  const payload = {
    ...(data || {}),
    posts: Array.isArray(data?.posts) ? data.posts : [],
    postsArchivados: data?.postsArchivados && typeof data.postsArchivados === 'object' ? data.postsArchivados : {},
    _lastModified: Date.now()
  };
  localStorage.setItem(BLOG_KEY, JSON.stringify(payload));
  if (window._syncFirebase) _syncFirebase('blog', payload);
}

function _archivarPostsBlogDocente(yearId, closedAt) {
  const blog = cargarBlog();
  const postsActivos = Array.isArray(blog.posts) ? blog.posts : [];
  if (!postsActivos.length) return 0;

  if (!blog.postsArchivados || typeof blog.postsArchivados !== 'object') {
    blog.postsArchivados = {};
  }

  const prevReg = blog.postsArchivados[yearId] || {};
  const prevPosts = Array.isArray(prevReg.posts) ? prevReg.posts : [];
  const nuevosPosts = JSON.parse(JSON.stringify(postsActivos));
  const merged = [...prevPosts, ...nuevosPosts];
  const seen = new Set();
  const dedup = merged.filter((p, idx) => {
    const key = p && p.id ? ('id:' + p.id) : ('idx:' + idx + ':' + (p?.titulo || '') + ':' + (p?.creadoEn || ''));
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  blog.postsArchivados[yearId] = {
    yearId,
    yearLabel: yearId,
    closedAt: closedAt || prevReg.closedAt || new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    count: dedup.length,
    posts: dedup
  };

  postsActivos
    .filter(p => p && p.publicado && p.id)
    .forEach(p => _blogDespublicarEnFirestore(p.id));

  blog.posts = [];
  guardarBlog(blog);
  return postsActivos.length;
}

function _blogRenderArchivados(blog, filtroCurso) {
  const archivados = blog.postsArchivados || {};
  const years = Object.keys(archivados).sort((a, b) => String(b).localeCompare(String(a)));
  if (!years.length) return '';

  const blocks = years.map(yearId => {
    const reg = archivados[yearId] || {};
    let posts = Array.isArray(reg.posts) ? reg.posts.slice() : [];
    if (filtroCurso) posts = posts.filter(p => p.cursoId === filtroCurso);
    posts.sort((a, b) => new Date(b.creadoEn || 0) - new Date(a.creadoEn || 0));
    if (!posts.length) return '';

    return '<details style="background:#fff;border:1px solid #D1C4E9;border-radius:10px;padding:8px 10px;">'
      + '<summary style="cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:8px;list-style:none;flex-wrap:wrap;">'
      + '<span style="font-size:0.88rem;font-weight:800;color:#4527A0;">' + escapeHTML(yearId) + '</span>'
      + '<span style="font-size:0.72rem;color:#6A1B9A;background:#F3E5F5;border-radius:999px;padding:3px 8px;font-weight:700;white-space:nowrap;">'
      + posts.length + ' post' + (posts.length !== 1 ? 's' : '') + '</span>'
      + '</summary>'
      + '<div style="display:flex;flex-direction:column;gap:8px;margin-top:8px;">'
      + posts.map(p => {
        const fecha = p.creadoEn ? new Date(p.creadoEn).toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
        return '<div style="border:1px solid #ECE3F8;border-radius:8px;padding:8px 10px;background:#FCFAFF;">'
          + '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;">'
          + '<div style="font-size:0.82rem;font-weight:700;color:#4527A0;">' + escapeHTML(p.titulo || 'Post sin título') + '</div>'
          + '<div style="font-size:0.7rem;color:#7E57C2;">' + escapeHTML(fecha) + '</div>'
          + '</div>'
          + '<div style="margin-top:4px;font-size:0.74rem;color:#616161;">'
          + '<span style="color:#1565C0;font-weight:700;">' + escapeHTML(p.cursoNombre || 'Sin curso') + '</span>'
          + ' · ' + escapeHTML((p.raLabel || 'Sin RA').substring(0, 85))
          + '</div>'
          + '</div>';
      }).join('')
      + '</div>'
      + '</details>';
  }).filter(Boolean);

  if (!blocks.length) return '';

  return '<div style="border:1px solid #D1C4E9;background:#F7F3FF;border-radius:12px;padding:12px 13px;margin-bottom:12px;">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:8px;">'
    + '<div style="font-size:0.82rem;font-weight:800;color:#5E35B1;text-transform:uppercase;letter-spacing:.06em;display:flex;align-items:center;gap:6px;">'
    + '<span class="material-icons" style="font-size:16px;">inventory_2</span>Posts archivados por ciclo'
    + '</div>'
    + '<div style="font-size:0.74rem;color:#7E57C2;">Se ocultan del ciclo activo, pero siguen en historial</div>'
    + '</div>'
    + '<div style="display:flex;flex-direction:column;gap:8px;">' + blocks.join('') + '</div>'
    + '</div>';
}

function abrirBlog() {
  cargarCalificaciones();
  _mostrarPanel('panel-blog');
  const sel = document.getElementById('blog-filtro-curso');
  if (sel) {
    const cursos = Object.values(calState.cursos || {}).sort((a, b) => a.nombre.localeCompare(b.nombre));
    sel.innerHTML = '<option value="">Todos los cursos</option>'
      + cursos.map(c => `<option value="${escapeHTML(c.id)}">${escapeHTML(c.nombre)}</option>`).join('');
  }
  renderizarBlog();
}
function cerrarBlog() { abrirDashboard(); }

function renderizarBlog() {
  const cont = document.getElementById('blog-container');
  if (!cont) return;
  const filtro = document.getElementById('blog-filtro-curso')?.value || '';
  const blog = cargarBlog();
  const panelArchivados = _blogRenderArchivados(blog, filtro);
  let posts = (blog.posts || []).slice().sort((a, b) => new Date(b.creadoEn) - new Date(a.creadoEn));
  if (filtro) posts = posts.filter(p => p.cursoId === filtro);

  // Link bar — siempre por curso para evitar mezcla de grupos
  const linkBar = document.getElementById('blog-link-bar');
  const linkUrl = document.getElementById('blog-link-url');
  if (linkBar && linkUrl && window.currentUser) {
    const base = window.location.href.replace(/[^/]*$/, '');
    const uid  = window.currentUser.uid;
    if (filtro) {
      linkUrl.textContent = base + 'blog.html?uid=' + uid + '&curso=' + filtro;
      linkBar.classList.remove('hidden');
    } else {
      // Sin filtro: mostrar links de todos los cursos que tengan posts publicados
      const cursosConPosts = [...new Map(
        (blog.posts || []).filter(p => p.publicado).map(p => [p.cursoId, p.cursoNombre])
      ).entries()];
      if (cursosConPosts.length > 0) {
        linkUrl.innerHTML = cursosConPosts.map(([cid, cnombre]) => {
          const url = base + 'blog.html?uid=' + uid + '&curso=' + cid;
          return `<span style="display:block;margin:2px 0;"><strong>${escapeHTML(cnombre)}:</strong> ${escapeHTML(url)}</span>`;
        }).join('');
        linkBar.classList.remove('hidden');
      } else {
        linkBar.classList.add('hidden');
      }
    }
  }

  if (posts.length === 0) {
    cont.innerHTML = panelArchivados
      + '<div class="dash-empty-card"><span class="material-icons">article</span>'
      + '<p>No hay posts todavía.<br>Crea tu primer post con el botón <strong>Nuevo post</strong>.</p></div>';
    return;
  }
  cont.innerHTML = panelArchivados + posts.map(p => _blogRenderCard(p)).join('');
}

function _blogRenderCard(p) {
  const tipoMap = {
    pc:       { label: 'Tarea PC',       icon: 'computer',   color: '#1565C0', bg: '#E3F2FD' },
    cuaderno: { label: 'Tarea Cuaderno', icon: 'menu_book',  color: '#2E7D32', bg: '#E8F5E9' },
    info:     { label: 'Información',    icon: 'info',       color: '#E65100', bg: '#FFF3E0' }
  };
  const ti = tipoMap[p.tipo] || tipoMap.info;
  const fecha = p.fechaLimite
    ? new Date(p.fechaLimite + 'T12:00:00').toLocaleDateString('es', { day: '2-digit', month: 'short', year: 'numeric' })
    : null;
  const adjuntos = p.adjuntos || [];
  return `<div class="blog-post-card">
    <div class="blog-post-header">
      <span class="blog-tipo-badge" style="background:${ti.bg};color:${ti.color};">
        <span class="material-icons" style="font-size:13px;">${ti.icon}</span> ${ti.label}
      </span>
      ${p.publicado
        ? '<span class="blog-pub-badge pub">Publicado</span>'
        : '<span class="blog-pub-badge borrador">Borrador</span>'}
    </div>
    <div class="blog-post-title">${escapeHTML(p.titulo)}</div>
    <div class="blog-post-meta">
      <span><span class="material-icons" style="font-size:13px;">school</span> ${escapeHTML(p.cursoNombre || '—')}</span>
      <span><span class="material-icons" style="font-size:13px;">bookmark</span> ${escapeHTML((p.raLabel || '—').substring(0, 45))}</span>
      ${fecha ? `<span><span class="material-icons" style="font-size:13px;">event</span> Límite: ${fecha}</span>` : ''}
      <span><span class="material-icons" style="font-size:13px;">schedule</span> ${new Date(p.creadoEn).toLocaleDateString('es')}</span>
    </div>
    <div class="blog-post-contenido">${escapeHTML(p.contenido || '').replace(/\n/g, '<br>')}</div>
    ${adjuntos.length > 0
      ? `<div class="blog-adjuntos-row">${adjuntos.map(a =>
          `<span class="blog-adjunto-chip"><span class="material-icons" style="font-size:13px;">attach_file</span> ${escapeHTML(a.nombre)}</span>`
        ).join('')}</div>`
      : ''}
    <div class="blog-post-actions">
      <button onclick="abrirModalPost('${p.id}')"><span class="material-icons">edit</span> Editar</button>
      ${p.publicado
        ? `<button onclick="despublicarPost('${p.id}')" style="color:#E65100;"><span class="material-icons">visibility_off</span> Despublicar</button>`
        : `<button onclick="publicarPost('${p.id}')" style="color:#2E7D32;"><span class="material-icons">publish</span> Publicar</button>`}
      ${p.tipo === 'pc'
        ? `<button onclick="verEntregasPost('${p.id}')" style="color:#1565C0;"><span class="material-icons">folder_open</span> Entregas</button>`
        : ''}
      <button onclick="_duplicarPostACurso('${p.id}')" style="color:#00695C;"><span class="material-icons">content_copy</span> Duplicar</button>
      <button onclick="imprimirPost('${p.id}')" style="color:#C62828;"><span class="material-icons">print</span> Imprimir</button>
      <button onclick="eliminarPost('${p.id}')" style="color:#C62828;margin-left:auto;"><span class="material-icons">delete</span></button>
    </div>
  </div>`;
}

