let _psicoDatos = []; // {docenteUid, docenteNombre, estNombre, estId, curso, reportes[]}

async function abrirPsicologia() {
  if (!window.currentUser) return;
  try {
    const doc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    const rol = doc.exists ? (doc.data().rol || '') : '';
    const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
    const permitido = ['psicologia', 'psicologa', 'psicologo', 'director', 'superadmin'].includes(rol) || esSA;
    if (!permitido) { mostrarToast('No tienes acceso a este panel.', 'error'); return; }
  } catch { mostrarToast('Error verificando acceso.', 'error'); return; }
  _mostrarPanel('panel-psicologia');
  cargarReportesPsicologia();
}

async function cargarReportesPsicologia() {
  const cont = document.getElementById('psico-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:40px;color:#9E9E9E;"><span class="material-icons" style="font-size:36px;display:block;margin-bottom:10px;">hourglass_empty</span>Cargando reportes…</div>';

  try {
    // collectionGroup consulta datos_padre en TODOS los usuarios sin necesitar listar public_blogs
    const snap = await db.collectionGroup('datos_padre').get();

    const resultados = [];
    const docenteNombres = {};

    for (const doc of snap.docs) {
      const d = doc.data();
      const reportes = (d.reportes || []).filter(r => r.detallesEvento && r.detallesEvento.trim());
      if (reportes.length === 0) continue;

      // Extraer uid del path: public_blogs/{uid}/datos_padre/{estId}
      const segmentos = doc.ref.path.split('/');
      const uid = segmentos[1];

      // Obtener nombre del docente (con caché)
      if (!docenteNombres[uid]) {
        try {
          const perfil = await db.collection('perfiles').doc(uid).get();
          if (perfil.exists && perfil.data().nombre) docenteNombres[uid] = perfil.data().nombre;
          else {
            const usuario = await db.collection('usuarios').doc(uid).get();
            docenteNombres[uid] = (usuario.exists && usuario.data().nombre) ? usuario.data().nombre : uid;
          }
        } catch(e) { docenteNombres[uid] = uid; }
      }

      resultados.push({
        docenteUid: uid,
        docenteNombre: docenteNombres[uid],
        estId: doc.id,
        estNombre: d.nombre || doc.id,
        curso: d.curso || '',
        reportes: reportes.sort((a, b) => b.ts - a.ts)
      });
    }

    _psicoDatos = resultados;

    // Poblar filtros
    const docentes = [...new Set(resultados.map(r => r.docenteNombre))].sort();
    const cursos   = [...new Set(resultados.map(r => r.curso).filter(Boolean))].sort();

    const selDoc = document.getElementById('psico-filtro-docente');
    if (selDoc) {
      const prevDoc = selDoc.value;
      selDoc.innerHTML = '<option value="">Todos los docentes</option>' +
        docentes.map(d => `<option value="${escapeHTML(d)}" ${d === prevDoc ? 'selected' : ''}>${escapeHTML(d)}</option>`).join('');
    }
    const selCurso = document.getElementById('psico-filtro-curso');
    if (selCurso) {
      const prevCurso = selCurso.value;
      selCurso.innerHTML = '<option value="">Todos los cursos</option>' +
        cursos.map(c => `<option value="${escapeHTML(c)}" ${c === prevCurso ? 'selected' : ''}>${escapeHTML(c)}</option>`).join('');
    }

    renderPsicologia();

  } catch(e) {
    if (cont) cont.innerHTML = '<div style="text-align:center;padding:30px;color:#C62828;">Error al cargar: ' + escapeHTML(e.message) + '</div>';
  }
}

function renderPsicologia() {
  const cont = document.getElementById('psico-contenido');
  if (!cont) return;

  const filtroDoc    = document.getElementById('psico-filtro-docente')?.value || '';
  const filtroCurso  = document.getElementById('psico-filtro-curso')?.value   || '';
  const buscar       = (document.getElementById('psico-buscar')?.value || '').toLowerCase().trim();

  let datos = _psicoDatos;
  if (filtroDoc)   datos = datos.filter(d => d.docenteNombre === filtroDoc);
  if (filtroCurso) datos = datos.filter(d => d.curso === filtroCurso);
  if (buscar)      datos = datos.filter(d => d.estNombre.toLowerCase().includes(buscar));

  if (datos.length === 0) {
    cont.innerHTML = '<div style="text-align:center;padding:40px;color:#9E9E9E;">' +
      '<span class="material-icons" style="font-size:48px;display:block;margin-bottom:10px;">inbox</span>' +
      '<p>No se encontraron reportes con los filtros aplicados.</p></div>';
    return;
  }

  const totalRep = datos.reduce((s, d) => s + d.reportes.length, 0);
  let html = `<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;font-size:0.78rem;color:#9E9E9E;margin-bottom:14px;">${datos.length} estudiante${datos.length !== 1 ? 's' : ''} · ${totalRep} reporte${totalRep !== 1 ? 's' : ''}<button class="btn-secundario" onclick="_mostrarGuiaPlaceholdersPsicologia()" style="padding:6px 10px;font-size:0.75rem;border-radius:8px;">Ver placeholders Word</button></div>`;

  datos.forEach(d => {
    html += `
      <div style="background:#fff;border:1px solid #E0E0E0;border-radius:12px;margin-bottom:14px;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,0.06);">
        <div class="psico-rep-header" style="background:linear-gradient(90deg,#F3E5F5,#EDE7F6);padding:10px 14px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
          <span class="material-icons" style="color:#6A1B9A;font-size:20px;">person</span>
          <strong style="color:#4A148C;font-size:0.95rem;">${escapeHTML(d.estNombre)}</strong>
          ${d.curso ? `<span style="background:#CE93D8;color:#fff;border-radius:10px;padding:1px 9px;font-size:0.72rem;font-weight:700;">${escapeHTML(d.curso)}</span>` : ''}
          <span style="margin-left:auto;font-size:0.75rem;color:#7B1FA2;">Docente: ${escapeHTML(d.docenteNombre)}</span>
          <span style="background:#B39DDB;color:#fff;border-radius:10px;padding:1px 9px;font-size:0.72rem;font-weight:700;">${d.reportes.length} reporte${d.reportes.length !== 1 ? 's' : ''}</span>
        </div>
        <div style="padding:12px 14px;display:flex;flex-direction:column;gap:10px;">`;

    d.reportes.forEach(r => {
      const fecha = r.fechaReporte
        ? new Date(r.fechaReporte + 'T12:00:00').toLocaleDateString('es-DO', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' })
        : (r.ts ? new Date(r.ts).toLocaleDateString('es-DO', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' }) : '—');

      const campos = [
        { label: 'Descripción del evento',            valor: r.detallesEvento },
        { label: 'Medidas del docente',               valor: r.medidasDocente },
        { label: 'Seguimiento Coordinación/Psicología', valor: r.seguimientoRepetitiva },
      ].filter(c => c.valor && c.valor.trim());

      html += `
        <div style="border-left:3px solid #7B1FA2;padding:8px 12px;background:#FAFAFA;border-radius:0 8px 8px 0;">
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;flex-wrap:wrap;">
            <span style="background:#EDE7F6;color:#4A148C;font-size:0.72rem;font-weight:700;padding:2px 8px;border-radius:10px;display:inline-flex;align-items:center;gap:3px;">
              <span class="material-icons" style="font-size:11px;">description</span> Reporte formal
            </span>
            <span style="font-size:0.78rem;font-weight:600;color:#37474F;">${escapeHTML(fecha)}</span>
            <button class="btn-icon-sm" title="Exportar a Word" onclick="exportarReportePsicologiaDocx('${r.id}','${d.estId}')" style="margin-left:auto;color:#6A1B9A;">
              <span class="material-icons" style="font-size:16px;">description</span>
            </button>
            <button class="btn-icon-sm" title="Descargar Word" onclick="descargarReportePsicologiaGuardado('${d.estId}','${r.id}')" style="color:#1565C0;">
              <span class="material-icons" style="font-size:16px;">download</span>
            </button>
          </div>
          ${campos.map(c => `
            <div style="margin-bottom:4px;">
              <div style="font-size:0.68rem;font-weight:700;color:#7B1FA2;text-transform:uppercase;letter-spacing:0.05em;">${escapeHTML(c.label)}</div>
              <div style="font-size:0.85rem;color:#37474F;line-height:1.4;">${escapeHTML(c.valor)}</div>
            </div>`).join('')}
        </div>`;
    });

    html += '</div></div>';
  });

  cont.innerHTML = html;
}

// Sincronizar reporte nuevo a Firestore para que Psicología lo vea en tiempo real
async function _syncReportePsicologia(estId, reportes) {
  if (typeof db === 'undefined' || !firebase.auth().currentUser) return;
  const uid = firebase.auth().currentUser.uid;
  try {
    await db.collection('public_blogs').doc(uid).collection('datos_padre').doc(estId)
      .set({ reportes }, { merge: true });
  } catch(e) { console.warn('sync psicologia:', e); }
}

function _esRolPsicologia(rol) {
  return ['psicologia', 'psicologa', 'psicologo'].includes((rol || '').toLowerCase());
}

// Un usuario puede tener varios roles (campo `roles`, arreglo). Las cuentas viejas que
// todavia no tienen ese campo caen al singular `rol`.
function _tieneRol(perfil, rolBuscado) {
  if (!perfil) return false;
  const roles = Array.isArray(perfil.roles) ? perfil.roles : [perfil.rol];
  if (rolBuscado === 'psicologia') return roles.some(r => _esRolPsicologia(r));
  return roles.includes(rolBuscado);
}

async function _getRolActual() {
  if (!window.currentUser) return '';
  try {
    const doc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    return doc.exists ? (doc.data().rol || '') : '';
  } catch {
    return '';
  }
}

async function _esVistaGlobalConvivencia() {
  const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
  if (esSA) return true;
  const rol = await _getRolActual();
  return _esRolPsicologia(rol);
}

const _cacheNombresDocentesConvivencia = {};

async function _nombreDocentePorUid(uid) {
  if (!uid) return '—';
  if (_cacheNombresDocentesConvivencia[uid]) return _cacheNombresDocentesConvivencia[uid];
  try {
    const perfil = await db.collection('perfiles').doc(uid).get();
    if (perfil.exists && perfil.data().nombre) {
      _cacheNombresDocentesConvivencia[uid] = perfil.data().nombre;
      return _cacheNombresDocentesConvivencia[uid];
    }
  } catch {}
  try {
    const usuario = await db.collection('usuarios').doc(uid).get();
    if (usuario.exists && usuario.data().nombre) {
      _cacheNombresDocentesConvivencia[uid] = usuario.data().nombre;
      return _cacheNombresDocentesConvivencia[uid];
    }
  } catch {}
  _cacheNombresDocentesConvivencia[uid] = uid;
  return uid;
}

let _repCompTab = 'reportes';

function abrirReportesComportamiento() {
  _mostrarPanel('panel-reportes-comp');
  _repCompTab = 'reportes';
  switchTabReportes('reportes');
}

function switchTabReportes(tab) {
  _repCompTab = tab;
  const tabs = { reportes: 'tab-rep-reportes', cuentas: 'tab-rep-cuentas', enlace: 'tab-rep-enlace' };
  Object.entries(tabs).forEach(([k, id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (k === tab) {
      el.style.background = '#1565C0'; el.style.color = '#fff'; el.style.borderColor = '#1565C0';
    } else {
      el.style.background = '#F5F5F5'; el.style.color = '#616161'; el.style.borderColor = '#E0E0E0';
    }
  });
  if (tab === 'reportes') _renderReportesRecibidos();
  else if (tab === 'cuentas') _renderCuentasEstudiantes();
  else if (tab === 'enlace') _renderEnlaceReportes();
}

// ── Tab: Reportes recibidos ─────────────────────────────────────
async function _renderReportesRecibidos() {
  const cont = document.getElementById('rep-comp-contenido');
  if (!cont) return;

  const user = window.currentUser;
  if (!user) { cont.innerHTML = '<p style="color:#9E9E9E;text-align:center;padding:20px;">Inicia sesión primero.</p>'; return; }

  const vistaGlobal = await _esVistaGlobalConvivencia();

  cont.innerHTML = '<div style="text-align:center;padding:30px;color:#9E9E9E;"><span class="material-icons" style="font-size:32px;display:block;margin-bottom:8px;">hourglass_empty</span>Cargando reportes...</div>';
  const panelArchivados = _panelArchivadosReportesComp('');

  try {
    let reportes = [];
    if (vistaGlobal) {
      try {
        const snap = await db.collectionGroup('reportes_comportamiento').get();
        reportes = [];
        for (const d of snap.docs) {
          const raw = d.data() || {};
          const partes = d.ref.path.split('/');
          const docenteUid = partes[1] || '';
          reportes.push({
            ...raw,
            id: raw.id || d.id,
            docenteUid,
            docenteNombre: await _nombreDocentePorUid(docenteUid)
          });
        }
      } catch (e) {
        const permiso = (e?.code === 'permission-denied') || /insufficient permissions|permission/i.test(String(e?.message || ''));
        if (!permiso) throw e;
        const snap = await db.collection('public_blogs').doc(user.uid)
          .collection('reportes_comportamiento').get();
        reportes = snap.docs.map(d => ({ ...d.data(), id: d.data().id || d.id }));
        mostrarToast('No se pudo abrir la vista global por permisos de Firestore. Se muestran tus reportes.', 'info');
      }
    } else {
      const snap = await db.collection('public_blogs').doc(user.uid)
        .collection('reportes_comportamiento').get();
      reportes = snap.docs.map(d => ({ ...d.data(), id: d.data().id || d.id }));
    }

    reportes.sort((a, b) => new Date(b.creadoEn) - new Date(a.creadoEn));

    if (reportes.length === 0) {
      cont.innerHTML = panelArchivados + '<div style="text-align:center;padding:40px;color:#9E9E9E;">' +
        '<span class="material-icons" style="font-size:48px;display:block;margin-bottom:10px;">inbox</span>' +
        (vistaGlobal
          ? '<p>No hay reportes de comportamiento en los centros.</p>'
          : '<p>No se han recibido reportes de comportamiento.</p><p style="font-size:0.78rem;margin-top:6px;">Comparte el enlace con tus estudiantes desde la pestaña "Enlace".</p>')
        + '</div>';
      return;
    }

    // Filtro por curso
    const cursosSet = [...new Set(reportes.map(r => r.cursoNombre || r.cursoId))];
    let filtroHTML = '';
    if (cursosSet.length > 1) {
      filtroHTML = '<div style="margin-bottom:14px;display:flex;gap:6px;flex-wrap:wrap;">' +
        '<button onclick="_filtrarRepComp(\'\')" class="rep-filtro-btn rep-filtro-activo" style="padding:4px 12px;border-radius:16px;border:1px solid #90CAF9;background:#E3F2FD;color:#1565C0;font-size:0.75rem;font-weight:600;cursor:pointer;">Todos</button>' +
        cursosSet.map(c =>
          '<button onclick="_filtrarRepComp(\'' + escapeHTML(c) + '\')" class="rep-filtro-btn" style="padding:4px 12px;border-radius:16px;border:1px solid #E0E0E0;background:#fff;color:#616161;font-size:0.75rem;font-weight:600;cursor:pointer;">' + escapeHTML(c) + '</button>'
        ).join('') + '</div>';
    }

    const vistaGlobalActiva = vistaGlobal && reportes.some(r => !!r.docenteUid);
    cont.innerHTML = panelArchivados + filtroHTML + '<div id="rep-comp-lista">' + _buildReportesHTML(reportes, { vistaGlobal: vistaGlobalActiva }) + '</div>';
    window._repCompTodos = reportes;
    window._repCompVistaGlobal = vistaGlobalActiva;

  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:30px;color:#C62828;">Error al cargar reportes: ' + escapeHTML(e.message) + '</div>';
  }
}

function _filtrarRepComp(curso) {
  const reportes = window._repCompTodos || [];
  const filtered = curso ? reportes.filter(r => (r.cursoNombre || r.cursoId) === curso) : reportes;
  const lista = document.getElementById('rep-comp-lista');
  if (lista) lista.innerHTML = _buildReportesHTML(filtered, { vistaGlobal: !!window._repCompVistaGlobal });

  // Actualizar estilos de filtros
  document.querySelectorAll('.rep-filtro-btn').forEach(b => {
    const esFiltro = curso ? b.textContent.trim() === curso : b.textContent.trim() === 'Todos';
    b.style.background = esFiltro ? '#E3F2FD' : '#fff';
    b.style.borderColor = esFiltro ? '#90CAF9' : '#E0E0E0';
    b.style.color = esFiltro ? '#1565C0' : '#616161';
  });
}

function _buildReportesHTML(reportes, opts = {}) {
  const vistaGlobal = !!opts.vistaGlobal;
  if (!reportes.length) return '<div style="text-align:center;padding:20px;color:#9E9E9E;">Sin reportes para este filtro.</div>';

  const tipoLabel = { positivo: 'Positivo', negativo: 'Negativo', neutral: 'Observación' };
  const tipoCls   = { positivo: '#E8F5E9;color:#2E7D32', negativo: '#FFEBEE;color:#C62828', neutral: '#FFF3E0;color:#E65100' };
  const tipoIcon  = { positivo: 'thumb_up', negativo: 'thumb_down', neutral: 'info' };

  return reportes.map(r => {
    const fechaStr = r.fecha
      ? new Date(r.fecha + 'T12:00:00').toLocaleDateString('es-ES', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' })
      : '—';
    const tStyle = tipoCls[r.tipo] || tipoCls.neutral;
    const tIcon  = tipoIcon[r.tipo] || 'info';
    const tLabel = tipoLabel[r.tipo] || 'Observación';

    const docenteLinea = vistaGlobal
      ? '<div style="font-size:0.75rem;color:#6A1B9A;display:flex;align-items:center;gap:4px;margin-bottom:6px;">'
        + '<span class="material-icons" style="font-size:14px;">badge</span> <strong>Docente:</strong> ' + escapeHTML(r.docenteNombre || r.docenteUid || '—') +
      '</div>'
      : '';
    const accionEliminar = !vistaGlobal
      ? '<div style="margin-top:8px;text-align:right;">' +
          '<button onclick="_eliminarReporteComp(\'' + escapeHTML(r.id) + '\')" style="background:none;border:1px solid #FFCDD2;color:#C62828;border-radius:6px;padding:4px 10px;font-size:0.72rem;cursor:pointer;display:inline-flex;align-items:center;gap:3px;font-family:inherit;">' +
            '<span class="material-icons" style="font-size:14px;">delete</span> Eliminar</button>' +
        '</div>'
      : '';

    return '<div style="background:var(--color-superficie,#fff);border:1px solid var(--color-borde,#E0E0E0);border-radius:10px;padding:16px;margin-bottom:10px;">' +
      '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px;">' +
        '<span style="display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:20px;font-size:0.72rem;font-weight:700;background:' + tStyle + ';">' +
          '<span class="material-icons" style="font-size:12px;">' + tIcon + '</span> ' + tLabel +
        '</span>' +
        '<span style="font-size:0.75rem;color:#9E9E9E;display:flex;align-items:center;gap:3px;">' +
          '<span class="material-icons" style="font-size:13px;">schedule</span> ' + escapeHTML(fechaStr) +
        '</span>' +
        '<span style="font-size:0.75rem;color:#78909C;margin-left:auto;">' + escapeHTML(r.cursoNombre || '') + '</span>' +
      '</div>' +
      '<div style="font-size:0.78rem;color:#616161;display:flex;align-items:center;gap:4px;margin-bottom:6px;">' +
        '<span class="material-icons" style="font-size:14px;">people</span> <strong>Involucrados:</strong> ' + escapeHTML(r.involucrados || '') +
      '</div>' +
      docenteLinea +
      '<div style="font-size:0.86rem;color:var(--color-texto-primario,#424242);line-height:1.6;white-space:pre-wrap;word-break:break-word;">' + escapeHTML(r.descripcion || '') + '</div>' +
      '<div style="font-size:0.72rem;color:#BDBDBD;margin-top:8px;display:flex;align-items:center;gap:4px;">' +
        '<span class="material-icons" style="font-size:12px;">person</span> Reportado por: ' + escapeHTML(r.reportadoPor || r.usuario || '') +
      '</div>' +
      accionEliminar +
    '</div>';
  }).join('');
}

async function _eliminarReporteComp(id) {
  if (!confirm('¿Eliminar este reporte? No se puede deshacer.')) return;
  const user = window.currentUser;
  if (!user) return;
  try {
    await db.collection('public_blogs').doc(user.uid)
      .collection('reportes_comportamiento').doc(id).delete();
    registrarCambio('Reporte de comportamiento eliminado');
    mostrarToast('Reporte eliminado', 'success');
    _renderReportesRecibidos();
  } catch (e) {
    mostrarToast('Error al eliminar: ' + e.message, 'error');
  }
}

// ── Tab: Cuentas de estudiantes ─────────────────────────────────
function _renderCuentasEstudiantes() {
  const cont = document.getElementById('rep-comp-contenido');
  if (!cont) return;

  const data = _cargarCuentasEst();
  const cuentas = data.cuentas || [];

  // Obtener cursos disponibles
  const cursos = Object.values(calState?.cursos || {});
  const sinCursos = cursos.length === 0;

  let html = '<div style="background:#E3F2FD;border:1.5px solid #90CAF9;border-radius:10px;padding:12px 16px;margin-bottom:16px;font-size:0.82rem;color:#0D47A1;display:flex;align-items:center;gap:8px;">' +
    '<span class="material-icons" style="font-size:18px;">info</span>' +
    'Crea cuentas para que los estudiantes puedan iniciar sesión en la página de reportes y enviar reportes de comportamiento.' +
    '</div>';

  // Formulario nueva cuenta
  html += '<div style="background:var(--color-superficie,#fff);border:1.5px solid #E3F2FD;border-radius:10px;padding:16px;margin-bottom:16px;">' +
    '<div style="font-size:0.85rem;font-weight:700;color:#1565C0;margin-bottom:12px;display:flex;align-items:center;gap:6px;">' +
      '<span class="material-icons" style="font-size:18px;">person_add</span> Nueva cuenta' +
    '</div>' +
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">' +
      '<div><label style="font-size:0.75rem;font-weight:600;color:#546E7A;display:block;margin-bottom:3px;">Nombre del estudiante *</label>' +
        '<input id="ce-nombre" style="width:100%;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.85rem;font-family:inherit;" placeholder="Ej: Juan Pérez"></div>' +
      '<div><label style="font-size:0.75rem;font-weight:600;color:#546E7A;display:block;margin-bottom:3px;">Curso asignado' + (sinCursos ? ' (opcional)' : ' *') + '</label>' +
        (sinCursos
          ? '<input id="ce-curso-texto" style="width:100%;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.85rem;font-family:inherit;" placeholder="Ej: 4to A (opcional, no tienes cursos creados)">'
          : '<select id="ce-curso" style="width:100%;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.85rem;font-family:inherit;">' +
              cursos.map(c => '<option value="' + escapeHTML(c.id) + '" data-nombre="' + escapeHTML(c.nombre) + '">' + escapeHTML(c.nombre) + '</option>').join('') +
            '</select>'
        ) + '</div>' +
    '</div>' +
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px;">' +
      '<div><label style="font-size:0.75rem;font-weight:600;color:#546E7A;display:block;margin-bottom:3px;">Usuario *</label>' +
        '<input id="ce-usuario" style="width:100%;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.85rem;font-family:inherit;" placeholder="Ej: juan.perez"></div>' +
      '<div><label style="font-size:0.75rem;font-weight:600;color:#546E7A;display:block;margin-bottom:3px;">Contraseña *</label>' +
        '<input id="ce-pass" type="text" style="width:100%;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.85rem;font-family:inherit;" placeholder="Ej: 1234"></div>' +
    '</div>' +
    '<div id="ce-error" style="color:#C62828;font-size:0.8rem;min-height:18px;margin-top:6px;"></div>' +
    '<button onclick="_crearCuentaEstudiante()" style="margin-top:8px;background:#1565C0;color:#fff;border:none;border-radius:8px;padding:9px 18px;font-size:0.85rem;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px;font-family:inherit;">' +
      '<span class="material-icons" style="font-size:16px;">add</span> Crear cuenta</button>' +
  '</div>';

  // Lista de cuentas existentes
  if (cuentas.length > 0) {
    html += '<div style="font-size:0.75rem;font-weight:800;text-transform:uppercase;letter-spacing:0.08em;color:#546E7A;margin-bottom:10px;">Cuentas creadas (' + cuentas.length + ')</div>';
    cuentas.forEach((c, i) => {
      const activo = c.activo !== false;
      html += '<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:8px;border:1px solid var(--color-borde,#E0E0E0);margin-bottom:8px;background:var(--color-superficie,#FAFAFA);' + (!activo ? 'opacity:0.5;' : '') + '">' +
        '<span class="material-icons" style="font-size:22px;color:' + (activo ? '#1565C0' : '#BDBDBD') + ';">account_circle</span>' +
        '<div style="flex:1;min-width:0;">' +
          '<div style="font-size:0.88rem;font-weight:600;color:var(--color-texto-primario,#212121);">' + escapeHTML(c.nombre) + '</div>' +
          '<div style="font-size:0.75rem;color:#757575;">Usuario: <strong>' + escapeHTML(c.usuario) + '</strong> · Contraseña: <strong>' + escapeHTML(c.password) + '</strong></div>' +
          '<div style="font-size:0.72rem;color:#9E9E9E;">' + escapeHTML(c.cursoNombre || c.cursoId || 'Sin curso asignado') + '</div>' +
        '</div>' +
        '<button onclick="_toggleCuentaEst(' + i + ')" title="' + (activo ? 'Desactivar' : 'Activar') + '" style="background:none;border:1px solid ' + (activo ? '#FFCDD2' : '#C8E6C9') + ';color:' + (activo ? '#C62828' : '#2E7D32') + ';border-radius:6px;padding:4px 8px;font-size:0.72rem;cursor:pointer;display:inline-flex;align-items:center;gap:3px;font-family:inherit;">' +
          '<span class="material-icons" style="font-size:14px;">' + (activo ? 'block' : 'check_circle') + '</span>' + (activo ? 'Desactivar' : 'Activar') +
        '</button>' +
        '<button onclick="_eliminarCuentaEst(' + i + ')" title="Eliminar" style="background:none;border:1px solid #FFCDD2;color:#C62828;border-radius:6px;padding:4px 8px;font-size:0.72rem;cursor:pointer;display:inline-flex;align-items:center;gap:3px;font-family:inherit;">' +
          '<span class="material-icons" style="font-size:14px;">delete</span>' +
        '</button>' +
      '</div>';
    });
  } else {
    html += '<div style="text-align:center;padding:20px;color:#9E9E9E;font-size:0.85rem;">' +
      '<span class="material-icons" style="font-size:32px;display:block;margin-bottom:8px;">person_off</span>' +
      'No hay cuentas de estudiantes creadas.</div>';
  }

  cont.innerHTML = html;
}

function _crearCuentaEstudiante() {
  const nombre  = (document.getElementById('ce-nombre')?.value || '').trim();
  const usuario = (document.getElementById('ce-usuario')?.value || '').trim().toLowerCase();
  const pass    = (document.getElementById('ce-pass')?.value || '').trim();
  const cursoSel = document.getElementById('ce-curso');
  const cursoTexto = document.getElementById('ce-curso-texto');
  // Si hay <select> (el usuario tiene cursos), el curso es obligatorio. Si no hay
  // cursos creados (p.ej. psicologo sin rol de docente), el campo es un texto libre opcional.
  const cursoId = cursoSel?.value || '';
  const cursoNombre = cursoSel
    ? (cursoSel.selectedOptions[0]?.dataset?.nombre || cursoId)
    : (cursoTexto?.value || '').trim();
  const errEl   = document.getElementById('ce-error');

  if (!nombre || !usuario || !pass) {
    if (errEl) errEl.textContent = 'Completa todos los campos.';
    return;
  }
  if (cursoSel && !cursoId) {
    if (errEl) errEl.textContent = 'Selecciona un curso.';
    return;
  }
  if (usuario.length < 3) {
    if (errEl) errEl.textContent = 'El usuario debe tener al menos 3 caracteres.';
    return;
  }

  const data = _cargarCuentasEst();
  // Verificar unicidad de usuario
  if (data.cuentas.some(c => c.usuario.toLowerCase() === usuario)) {
    if (errEl) errEl.textContent = 'Ya existe una cuenta con ese usuario.';
    return;
  }

  data.cuentas.push({
    id: uid(),
    nombre,
    usuario,
    password: pass,
    cursoId,
    cursoNombre,
    activo: true,
    creadoEn: new Date().toISOString()
  });
  _guardarCuentasEst(data);
  registrarCambio('Cuenta de estudiante creada: ' + nombre);
  mostrarToast('Cuenta creada para ' + nombre, 'success');
  _renderCuentasEstudiantes();
}

function _toggleCuentaEst(index) {
  const data = _cargarCuentasEst();
  if (!data.cuentas[index]) return;
  data.cuentas[index].activo = !data.cuentas[index].activo;
  _guardarCuentasEst(data);
  mostrarToast(data.cuentas[index].activo ? 'Cuenta activada' : 'Cuenta desactivada', 'success');
  _renderCuentasEstudiantes();
}

function _eliminarCuentaEst(index) {
  const data = _cargarCuentasEst();
  if (!data.cuentas[index]) return;
  if (!confirm('¿Eliminar la cuenta de ' + data.cuentas[index].nombre + '?')) return;
  const nombre = data.cuentas[index].nombre;
  data.cuentas.splice(index, 1);
  _guardarCuentasEst(data);
  registrarCambio('Cuenta de estudiante eliminada: ' + nombre);
  mostrarToast('Cuenta eliminada', 'success');
  _renderCuentasEstudiantes();
}

// ── Tab: Enlace ─────────────────────────────────────────────────
function _renderEnlaceReportes() {
  const cont = document.getElementById('rep-comp-contenido');
  if (!cont) return;
  const user = window.currentUser;
  if (!user) { cont.innerHTML = '<p style="color:#9E9E9E;text-align:center;padding:20px;">Inicia sesión primero.</p>'; return; }

  const baseUrl = window.location.origin + window.location.pathname.replace(/[^/]*$/, '') + 'reporte.html';
  const url = baseUrl + '?uid=' + encodeURIComponent(user.uid);

  cont.innerHTML =
    '<div style="text-align:center;padding:20px;">' +
      '<div style="font-size:0.85rem;color:#546E7A;margin-bottom:16px;">Comparte este enlace con tus estudiantes para que puedan acceder a la página de reportes de comportamiento.</div>' +
      '<div style="display:flex;gap:8px;max-width:500px;margin:0 auto;">' +
        '<input id="rep-comp-url" readonly value="' + escapeHTML(url) + '" style="flex:1;padding:10px 12px;background:#F5F5F5;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.82rem;color:#424242;font-family:monospace;">' +
        '<button onclick="_copiarEnlaceReportes()" style="background:#1565C0;color:#fff;border:none;border-radius:8px;padding:10px 16px;font-size:0.82rem;font-weight:600;cursor:pointer;display:flex;align-items:center;gap:4px;font-family:inherit;white-space:nowrap;">' +
          '<span class="material-icons" style="font-size:16px;">content_copy</span> Copiar' +
        '</button>' +
      '</div>' +
      '<div style="margin-top:20px;background:#FFF3E0;border:1.5px solid #FFE0B2;border-radius:10px;padding:14px 18px;text-align:left;font-size:0.82rem;color:#E65100;">' +
        '<div style="font-weight:700;margin-bottom:6px;display:flex;align-items:center;gap:6px;">' +
          '<span class="material-icons" style="font-size:16px;">warning</span> Importante</div>' +
        '<ul style="margin:0;padding-left:20px;line-height:1.8;">' +
          '<li>Primero crea las cuentas de los estudiantes en la pestaña "Cuentas de estudiantes".</li>' +
          '<li>El estudiante necesita el enlace + su usuario y contraseña para acceder.</li>' +
          '<li>Los reportes enviados aparecerán en la pestaña "Reportes recibidos".</li>' +
        '</ul>' +
      '</div>' +
    '</div>';
}

function _copiarEnlaceReportes() {
  const input = document.getElementById('rep-comp-url');
  if (!input) return;
  navigator.clipboard.writeText(input.value).then(() => {
    mostrarToast('Enlace copiado al portapapeles', 'success');
  }).catch(() => {
    input.select();
    document.execCommand('copy');
    mostrarToast('Enlace copiado', 'success');
  });
}

// ════════════════════════════════════════════════════════════════════
//  MÓDULO: BUZÓN DE DENUNCIAS (anónimas, sin login)
// ════════════════════════════════════════════════════════════════════

function abrirDenuncias() {
  _mostrarPanel('panel-denuncias');
  switchTabDenuncias('recibidas');
}

function switchTabDenuncias(tab) {
  const tabs = { recibidas: 'tab-den-recibidas', enlace: 'tab-den-enlace' };
  Object.entries(tabs).forEach(([key, id]) => {
    const btn = document.getElementById(id);
    if (!btn) return;
    if (key === tab) {
      btn.style.background = '#6A1B9A'; btn.style.color = '#fff'; btn.style.borderColor = '#6A1B9A';
    } else {
      btn.style.background = '#F5F5F5'; btn.style.color = '#616161'; btn.style.borderColor = '#E0E0E0';
    }
  });

  if (tab === 'recibidas') _renderDenunciasRecibidas();
  else if (tab === 'enlace') _renderEnlaceDenuncias();
}

async function _renderDenunciasRecibidas() {
  const cont = document.getElementById('den-contenido');
  if (!cont) return;
  const user = window.currentUser;
  if (!user) { cont.innerHTML = '<p style="color:#9E9E9E;text-align:center;padding:20px;">Inicia sesión primero.</p>'; return; }

  const vistaGlobal = await _esVistaGlobalConvivencia();

  cont.innerHTML = '<div style="text-align:center;padding:30px;color:#9E9E9E;"><span class="material-icons" style="font-size:32px;display:block;margin-bottom:8px;animation:spin 1s linear infinite;">hourglass_empty</span>Cargando denuncias...</div>';
  const panelArchivados = _panelArchivadosDenuncias('');

  try {
    let denuncias = [];
    if (vistaGlobal) {
      try {
        const snap = await db.collectionGroup('denuncias').get();
        denuncias = [];
        for (const d of snap.docs) {
          const raw = d.data() || {};
          const partes = d.ref.path.split('/');
          const docenteUid = partes[1] || '';
          denuncias.push({
            ...raw,
            id: raw.id || d.id,
            docenteUid,
            docenteNombre: await _nombreDocentePorUid(docenteUid)
          });
        }
      } catch (e) {
        const permiso = (e?.code === 'permission-denied') || /insufficient permissions|permission/i.test(String(e?.message || ''));
        if (!permiso) throw e;
        const snap = await db.collection('public_blogs').doc(user.uid)
          .collection('denuncias').get();
        denuncias = snap.docs.map(d => ({ ...d.data(), id: d.data().id || d.id }));
        mostrarToast('No se pudo abrir la vista global por permisos de Firestore. Se muestran tus denuncias.', 'info');
      }
    } else {
      const snap = await db.collection('public_blogs').doc(user.uid)
        .collection('denuncias').get();
      denuncias = snap.docs.map(d => ({ ...d.data(), id: d.data().id || d.id }));
    }

    denuncias.sort((a, b) => new Date(b.creadoEn) - new Date(a.creadoEn));

    if (denuncias.length === 0) {
      cont.innerHTML = panelArchivados + '<div style="text-align:center;padding:40px;color:#9E9E9E;">' +
        '<span class="material-icons" style="font-size:40px;display:block;margin-bottom:8px;opacity:0.4;">campaign</span>' +
        (vistaGlobal ? 'No hay denuncias registradas en los centros.' : 'No hay denuncias recibidas.') + '</div>';
      return;
    }

    // Filtro por curso
    const cursos = [...new Set(denuncias.map(d => d.curso))].sort();
    let html = '<div style="display:flex;gap:6px;margin-bottom:14px;flex-wrap:wrap;">' +
      '<button onclick="_filtrarDenuncias(\'\')" class="ra-tab" style="padding:4px 12px;border-radius:16px;border:1px solid #CE93D8;background:#EDE7F6;color:#6A1B9A;font-size:0.75rem;font-weight:600;cursor:pointer;">Todos (' + denuncias.length + ')</button>';
    cursos.forEach(c => {
      const n = denuncias.filter(d => d.curso === c).length;
      html += '<button onclick="_filtrarDenuncias(\'' + escapeHTML(c) + '\')" class="ra-tab" style="padding:4px 12px;border-radius:16px;border:1px solid #E0E0E0;background:#F5F5F5;color:#616161;font-size:0.75rem;font-weight:600;cursor:pointer;">' + escapeHTML(c) + ' (' + n + ')</button>';
    });
    html += '</div>';
    const vistaGlobalActiva = vistaGlobal && denuncias.some(d => !!d.docenteUid);
    html += '<div id="den-lista-items">' + _buildDenunciasHTML(denuncias, { vistaGlobal: vistaGlobalActiva }) + '</div>';

    cont.innerHTML = panelArchivados + html;
    window._denunciasCache = denuncias;
    window._denunciasVistaGlobal = vistaGlobalActiva;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error al cargar: ' + escapeHTML(e.message) + '</div>';
  }
}

function _filtrarDenuncias(curso) {
  const items = document.getElementById('den-lista-items');
  if (!items || !window._denunciasCache) return;
  const filtered = curso ? window._denunciasCache.filter(d => d.curso === curso) : window._denunciasCache;
  items.innerHTML = _buildDenunciasHTML(filtered, { vistaGlobal: !!window._denunciasVistaGlobal });
}

function _buildDenunciasHTML(denuncias, opts = {}) {
  const vistaGlobal = !!opts.vistaGlobal;
  if (!denuncias.length) return '<div style="text-align:center;padding:20px;color:#9E9E9E;">Sin denuncias en este filtro.</div>';

  const tipoLabels = {
    acoso: 'Acoso / Bullying', pelea: 'Pelea / Agresión', robo: 'Robo / Hurto',
    discriminacion: 'Discriminación', sustancias: 'Sustancias prohibidas',
    vandalismo: 'Vandalismo', amenaza: 'Amenaza', otro: 'Otro'
  };
  const tipoColors = {
    acoso: '#C62828', pelea: '#D84315', robo: '#E65100', discriminacion: '#AD1457',
    sustancias: '#6A1B9A', vandalismo: '#4527A0', amenaza: '#B71C1C', otro: '#546E7A'
  };

  return denuncias.map(d => {
    const color = tipoColors[d.tipo] || '#546E7A';
    const fechaStr = d.fecha
      ? new Date(d.fecha + 'T12:00:00').toLocaleDateString('es', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' })
      : '—';
    const esAnonimo = !d.nombre || d.nombre === 'Anónimo';
    const docenteLinea = vistaGlobal
      ? '<div style="font-size:0.74rem;color:#6A1B9A;margin-bottom:5px;display:flex;align-items:center;gap:4px;">'
        + '<span class="material-icons" style="font-size:13px;">badge</span><strong>Docente:</strong> ' + escapeHTML(d.docenteNombre || d.docenteUid || '—') +
      '</div>'
      : '';
    const accionImprimir = !vistaGlobal
      ? '<button onclick="imprimirDenuncia(\'' + d.id + '\')" title="Imprimir" style="background:none;border:none;color:#6A1B9A;cursor:pointer;padding:4px;">'
          + '<span class="material-icons" style="font-size:18px;">print</span></button>'
      : '';
    const accionEliminar = !vistaGlobal
      ? '<button onclick="_eliminarDenuncia(\'' + d.id + '\')" title="Eliminar" style="background:none;border:none;color:#EF5350;cursor:pointer;padding:4px;">'
          + '<span class="material-icons" style="font-size:18px;">delete_outline</span></button>'
      : '';

    return '<div style="background:#fff;border-radius:12px;box-shadow:0 1px 4px rgba(0,0,0,0.07);padding:16px;margin-bottom:12px;border-left:4px solid ' + color + ';">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">' +
        '<div style="display:flex;align-items:center;gap:6px;">' +
          '<span style="background:' + color + '18;color:' + color + ';padding:3px 10px;border-radius:20px;font-size:0.72rem;font-weight:700;">' +
            (tipoLabels[d.tipo] || d.tipo) + '</span>' +
          '<span style="font-size:0.72rem;color:#9E9E9E;display:flex;align-items:center;gap:3px;">' +
            '<span class="material-icons" style="font-size:13px;">schedule</span>' + escapeHTML(fechaStr) + '</span>' +
        '</div>' +
        '<div>' + accionImprimir + accionEliminar + '</div>' +
      '</div>' +
      '<div style="font-size:0.78rem;color:#78909C;margin-bottom:4px;display:flex;align-items:center;gap:4px;">' +
        '<span class="material-icons" style="font-size:14px;">school</span> ' + escapeHTML(d.curso) +
        ' &nbsp;·&nbsp; <span class="material-icons" style="font-size:14px;">person</span> ' +
        (esAnonimo ? '<em style="color:#BDBDBD;">Anónimo</em>' : escapeHTML(d.nombre)) +
      '</div>' +
      docenteLinea +
      '<div style="font-size:0.78rem;color:#616161;margin-bottom:6px;display:flex;align-items:center;gap:4px;">' +
        '<span class="material-icons" style="font-size:14px;">people</span> <strong>Involucrados:</strong> ' + escapeHTML(d.involucrados) +
      '</div>' +
      '<div style="font-size:0.85rem;color:#424242;line-height:1.6;white-space:pre-wrap;word-break:break-word;">' + escapeHTML(d.descripcion) + '</div>' +
    '</div>';
  }).join('');
}

/** Abre una ventana con el reporte de una denuncia formateado para imprimir / entregar a dirección, y la registra como evidencia en el Portafolio */
async function imprimirDenuncia(id) {
  const d = (window._denunciasCache || []).find(x => x.id === id);
  if (!d) { mostrarToast('Denuncia no encontrada', 'error'); return; }

  const tipoLabels = {
    acoso: 'Acoso / Bullying', pelea: 'Pelea / Agresión', robo: 'Robo / Hurto',
    discriminacion: 'Discriminación', sustancias: 'Sustancias prohibidas',
    vandalismo: 'Vandalismo', amenaza: 'Amenaza', otro: 'Otro'
  };
  const tipoLabel = tipoLabels[d.tipo] || d.tipo || 'Otro';
  const fechaStr = d.fecha
    ? new Date(d.fecha + 'T12:00:00').toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' })
    : '—';
  const esAnonimo = !d.nombre || d.nombre === 'Anónimo';
  const generado = new Date().toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' });

  const centroInfo = await _portafolioCargarIdentidadCentro();

  const ventana = window.open('', '_blank', 'width=900,height=700');
  if (!ventana) { mostrarToast('El navegador bloqueó la ventana de impresión. Permite ventanas emergentes e intenta de nuevo.', 'error'); return; }
  ventana.document.write(`
    <html><head><title>Reporte de Denuncia</title>
    <style>
      * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; color-adjust: exact !important; }
      body { font-family: Arial, sans-serif; margin: 1.8cm; color: #212121; font-size: 11pt; }
      ${MEMBRETE_CSS}
      .tipo-badge { display: inline-block; background: #F3E5F5; color: #6A1B9A; border-radius: 20px; padding: 3px 12px; font-size: 9pt; font-weight: bold; margin-bottom: 8pt; }
      h1 { color: #6A1B9A; font-size: 16pt; margin: 0 0 10pt; }
      .campos { border-collapse: collapse; width: 100%; margin-bottom: 14pt; }
      .campos td { border: 1px solid #CFD8DC; padding: 6px 10px; font-size: 10pt; }
      .campos td.label { background: #F5F5F5; font-weight: bold; width: 160px; color: #37474F; }
      .descripcion-title { font-weight: bold; font-size: 10.5pt; color: #37474F; margin-bottom: 6pt; }
      .descripcion { font-size: 10.5pt; line-height: 1.6; white-space: pre-wrap; border: 1px solid #CFD8DC; border-radius: 6px; padding: 10pt; min-height: 100pt; }
      .firma { margin-top: 40pt; display: flex; justify-content: space-between; gap: 40px; }
      .firma div { border-top: 1px solid #616161; padding-top: 6pt; font-size: 9.5pt; color: #424242; flex: 1; text-align: center; }
      .gen { margin-top: 14pt; font-size: 8.5pt; color: #9E9E9E; }
      @page { margin: 1.6cm; }
    </style>
    </head><body>
      ${_encabezadoImpresionHTML(centroInfo)}
      <span class="tipo-badge">${escapeHTML(tipoLabel)}</span>
      <h1>Reporte de Denuncia Escolar</h1>
      <table class="campos">
        <tr><td class="label">Curso / Sección</td><td>${escapeHTML(d.curso || '—')}</td></tr>
        <tr><td class="label">Fecha del incidente</td><td>${escapeHTML(fechaStr)}</td></tr>
        <tr><td class="label">Reportado por</td><td>${esAnonimo ? 'Anónimo' : escapeHTML(d.nombre)}</td></tr>
        <tr><td class="label">Involucrados</td><td>${escapeHTML(d.involucrados || '—')}</td></tr>
      </table>
      <div class="descripcion-title">Descripción del incidente</div>
      <div class="descripcion">${escapeHTML(d.descripcion || '')}</div>
      <div class="firma">
        <div>Docente / Encargado</div>
        <div>Dirección / Coordinación</div>
      </div>
      <div class="gen">Generado: ${generado}</div>
      <script>window.onload=function(){ setTimeout(function(){ window.print(); }, 300); };<\/script>
    </body></html>
  `);
  ventana.document.close();

  _crearEvidenciaPortafolioAuto({
    categoria: 'otro',
    titulo: 'Denuncia: ' + tipoLabel + (d.curso ? ' — ' + d.curso : ''),
    descripcion: d.descripcion || '',
    fecha: d.fecha,
    origen: 'Buzón de Denuncias'
  });
}

async function _eliminarDenuncia(id) {
  if (!confirm('¿Eliminar esta denuncia?')) return;
  const user = window.currentUser;
  if (!user) return;
  try {
    await db.collection('public_blogs').doc(user.uid)
      .collection('denuncias').doc(id).delete();
    registrarCambio('Denuncia eliminada');
    mostrarToast('Denuncia eliminada', 'success');
    _renderDenunciasRecibidas();
  } catch (e) {
    mostrarToast('Error: ' + e.message, 'error');
  }
}

