/** Dar/quitar acceso de Docente (Planificaciones/Calificaciones) -- esto es lo que permite
 * que alguien con otro rol (ej. Psicología) tambien pueda dar clases. */
async function _promoverDocente(uid) {
  await _toggleRolDocente(uid, 'docente', true, 'Acceso de Docente activado');
}
async function _quitarDocente(uid) {
  if (!confirm('¿Quitar el acceso de Docente a este usuario? Ya no vera Planificaciones ni Calificaciones.')) return;
  await _toggleRolDocente(uid, 'docente', false, 'Acceso de Docente removido');
}

// ════════════════════════════════════════════════════════════════════
// ── MÓDULO: DIRECTOR — AVISOS Y MONITOREO ────────────────────────
// ════════════════════════════════════════════════════════════════════

/** Verifica si el usuario actual es director */
async function _esDirector() {
  if (!window.currentUser) return false;
  try {
    const perfil = await _getPerfilUsuarioActualCacheado();
    return !!perfil && _tieneRol(perfil, 'director');
  } catch { return false; }
}

/** Muestra/oculta botón director en dashboard */
async function _verificarAccesoDirector() {
  const btn = document.getElementById('btn-dash-director');
  if (!btn) return;
  const esDir = await _esDirector();
  const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
  btn.style.display = (esDir || esSA) ? '' : 'none';
}

/** Abre panel de director */
async function abrirDirector() {
  _mostrarPanel('panel-director');
  window._coordCentroSeleccionado = null; // reset al (re)entrar al panel
  // Limpiar contenido que Panel Coordinadora pudo haber dejado renderizado en
  // su propio contenedor en esta misma sesión -- evita ids duplicados (ej.
  // dos elementos "coord-rend-buscar" vivos a la vez).
  const coordCont = document.getElementById('coord-contenido');
  if (coordCont) coordCont.innerHTML = '';
  // 'docentes' (Monitoreo Docentes) es la única pestaña con contenido propio de
  // Director -- las otras 5 muestran el mismo contenido de Panel Coordinadora,
  // pero renderizado aquí mismo (ver switchTabDirector), no navegando a otro panel.
  switchTabDirector('docentes');
}

/** Tabs del director */
function switchTabDirector(tab) {
  const tabs = {
    avisos: 'tab-dir-avisos', calificaciones: 'tab-dir-calificaciones', rendimiento: 'tab-dir-rendimiento',
    planificaciones: 'tab-dir-planificaciones', resumen: 'tab-dir-resumen', docentes: 'tab-dir-docentes',
    sesiones: 'tab-dir-sesiones'
  };
  Object.entries(tabs).forEach(([key, id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (key === tab) { el.classList.add('activo'); el.style.background = '#4A148C'; el.style.color = '#fff'; }
    else { el.classList.remove('activo'); el.style.background = '#F5F5F5'; el.style.color = '#616161'; }
  });
  window._dirTabActual = tab;

  // Calificaciones, Rendimiento, Planificaciones, Resumen Docentes y Avisos
  // reutilizan directamente las funciones ya construidas para Panel
  // Coordinadora (mismos datos, misma lógica), pero renderizando dentro del
  // contenedor propio de Panel Director ('dir-contenido') en vez de duplicar
  // su implementación o navegar a otro panel con otro encabezado.
  const dispatch = {
    calificaciones: _coordMonitorCalificaciones, rendimiento: _coordMonitorRendimiento,
    planificaciones: _coordMonitorPlanificaciones, resumen: _coordResumenDocentes, avisos: _coordAvisos,
    sesiones: _renderMonitoreoSesiones
  };
  if (dispatch[tab]) { dispatch[tab]('dir-contenido'); return; }

  _renderMonitoreoDocentes();
}

// ── AVISOS ──────────────────────────────────────────────────────

/** Obtener centroId del director actual */
async function _getCentroDirector() {
  if (!window.currentUser) return null;
  try {
    const doc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    if (doc.exists) return doc.data().centroId || null;
  } catch {}
  return null;
}

// Nota: la pestaña "Avisos" de Director reutiliza directamente _coordAvisos()/
// _coordEnviarAviso()/_coordEliminarAviso() (ver switchTabDirector) — antes había
// una implementación aparte aquí que escribía con un esquema de campos distinto
// al de Coordinadora en la misma colección de Firestore, causando que cada UI
// mostrara en blanco la fecha o el remitente de los avisos del otro rol.

// ── MONITOREO DE DOCENTES ──────────────────────────────────────

/** Renderiza monitoreo: lista de docentes con su última actividad */
async function _renderMonitoreoDocentes() {
  const cont = document.getElementById('dir-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:20px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando docentes...</div>';

  let centroId = await _getCentroDirector();
  const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
  if (!centroId && esSA) {
    try { const s = await db.collection('centros').limit(1).get(); if (!s.empty) centroId = s.docs[0].id; } catch {}
  }
  if (!centroId) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay centro asignado.</div>'; return; }

  try {
    const snap = await db.collection('usuarios').where('centroId', '==', centroId).get();
    const docentes = snap.docs.map(d => ({ uid: d.id, ...d.data() })).filter(d => d.estado === 'aprobado');

    if (docentes.length === 0) {
      cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;"><span class="material-icons" style="font-size:48px;display:block;margin-bottom:8px;">person_off</span>No hay docentes aprobados en este centro</div>';
      return;
    }

    // Cargar última sesión de cada docente
    const docentesConSesion = await Promise.all(docentes.map(async d => {
      try {
        const sesSnap = await db.collection('users').doc(d.uid).collection('sessions').orderBy('timestamp', 'desc').limit(1).get();
        d.ultimaSesion = sesSnap.empty ? null : sesSnap.docs[0].data();
      } catch { d.ultimaSesion = null; }
      return d;
    }));

    let html = '<h4 style="color:#4A148C;margin:0 0 12px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">monitoring</span> Actividad de docentes</h4>';
    html += '<div style="display:flex;flex-direction:column;gap:10px;">';
    docentesConSesion.forEach(d => {
      const inicial = (d.nombre || d.email || 'U')[0].toUpperCase();
      const rolBadge = d.rol === 'director'
        ? '<span style="background:#4A148C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.68rem;font-weight:600;margin-left:6px;">Director</span>'
        : d.rol === 'coordinadora'
        ? '<span style="background:#00695C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.68rem;font-weight:600;margin-left:6px;">Coordinadora</span>' : '';

      let ultimaInfo = 'Sin actividad registrada';
      let statusColor = '#E0E0E0';
      if (d.ultimaSesion) {
        const ts = d.ultimaSesion.timestamp?.toDate ? d.ultimaSesion.timestamp.toDate() : new Date(d.ultimaSesion.timestamp);
        const ahora = new Date();
        const diffHoras = (ahora - ts) / (1000 * 60 * 60);
        if (diffHoras < 1) { statusColor = '#4CAF50'; ultimaInfo = 'Activo hace menos de 1 hora'; }
        else if (diffHoras < 24) { statusColor = '#FF9800'; ultimaInfo = 'Último acceso: hoy ' + ts.toLocaleTimeString('es-DO', { hour: '2-digit', minute: '2-digit' }); }
        else if (diffHoras < 48) { statusColor = '#FF9800'; ultimaInfo = 'Último acceso: ayer'; }
        else { statusColor = '#F44336'; ultimaInfo = 'Último acceso: ' + ts.toLocaleDateString('es-DO', { day: '2-digit', month: 'short' }); }
        ultimaInfo += ' · ' + (d.ultimaSesion.device || '') + ' · ' + (d.ultimaSesion.browser || '');
      }

      html += '<div style="background:#fff;border:1.5px solid #E0E0E0;border-radius:12px;padding:14px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;">'
        + '<div style="position:relative;"><div style="width:44px;height:44px;border-radius:50%;background:#E3F2FD;display:flex;align-items:center;justify-content:center;font-weight:700;color:#1565C0;font-size:1.1rem;">' + inicial + '</div>'
        + '<div style="position:absolute;bottom:-2px;right:-2px;width:14px;height:14px;border-radius:50%;background:' + statusColor + ';border:2px solid #fff;"></div></div>'
        + '<div style="flex:1;min-width:150px;">'
        + '<div style="font-weight:700;font-size:0.95rem;color:#212121;">' + (d.nombre || 'Sin nombre') + rolBadge + '</div>'
        + '<div style="font-size:0.82rem;color:#78909C;">' + (d.email || '') + '</div>'
        + '<div style="font-size:0.75rem;color:#90A4AE;margin-top:2px;">' + ultimaInfo + '</div>'
        + '</div></div>';
    });
    html += '</div>';
    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

// ════════════════════════════════════════════════════════════════════
// ── MÓDULO: SUPERADMIN — GESTIÓN DE CENTROS EDUCATIVOS ───────────
// ════════════════════════════════════════════════════════════════════

const SUPERADMIN_EMAILS_KEY = 'tinclass_superadmin_emails';
const CENTROS_COLLECTION = 'centros';

/** Emails de superadmin por defecto — se complementan con los de Firestore */
const SUPERADMIN_DEFAULT = ['soymarcosbremont@gmail.com'];

// ── Suscripción mensual por centro (cobro manual, ver Panel Superadmin) ──
const SUSCRIPCION_DIAS_GRACIA_DEFAULT = 7;

/** Calcula el estado de la suscripción de un centro a partir de sus campos
 * livianos (fechaPagadoHasta / suscripcionSuspendidaManual / diasGraciaSuscripcion).
 * Función pura, sin I/O, reutilizable tanto por el gating de login como por el
 * listado de centros en Superadmin (que ya tiene los datos en memoria). */
function _calcularEstadoSuscripcion(centroData) {
  if (!centroData || !centroData.fechaPagadoHasta) return { activa: false, bloqueado: false, enGracia: false };
  if (centroData.suscripcionSuspendidaManual) return { activa: true, bloqueado: true, enGracia: false, motivo: 'suspendido' };
  const hoy = new Date();
  const vencimiento = new Date(centroData.fechaPagadoHasta + 'T00:00:00');
  const dias = centroData.diasGraciaSuscripcion || SUSCRIPCION_DIAS_GRACIA_DEFAULT;
  const finGracia = new Date(vencimiento);
  finGracia.setDate(finGracia.getDate() + dias);
  if (hoy <= vencimiento) return { activa: true, bloqueado: false, enGracia: false };
  if (hoy <= finGracia) {
    const diasRestantes = Math.ceil((finGracia - hoy) / 86400000);
    return { activa: true, bloqueado: false, enGracia: true, diasRestantes };
  }
  return { activa: true, bloqueado: true, enGracia: false, motivo: 'vencido' };
}

/** Lee el centro desde Firestore y calcula su estado de suscripción. Falla
 * "abierto" (no bloquea) ante cualquier error de red, para que un problema
 * transitorio de Firestore no tumbe el acceso de todo un centro. */
async function _evaluarSuscripcionCentro(centroId) {
  try {
    const doc = await db.collection(CENTROS_COLLECTION).doc(centroId).get();
    if (!doc.exists) return { activa: false, bloqueado: false, enGracia: false };
    return _calcularEstadoSuscripcion(doc.data());
  } catch (e) {
    console.warn('No se pudo evaluar la suscripción del centro:', e);
    return { activa: false, bloqueado: false, enGracia: false };
  }
}

/** Verifica si el usuario actual es superadmin */
function _esSuperadmin() {
  const email = window.currentUser?.email?.toLowerCase();
  if (!email) return false;
  if (SUPERADMIN_DEFAULT.includes(email)) return true;
  try {
    const extra = JSON.parse(localStorage.getItem(SUPERADMIN_EMAILS_KEY) || '[]');
    return extra.map(e => e.toLowerCase()).includes(email);
  } catch { return false; }
}

/** Carga lista de emails superadmin desde Firestore */
async function _cargarEmailsSuperadmin() {
  try {
    const doc = await db.collection('config').doc('superadmin').get();
    if (doc.exists) {
      const emails = doc.data().emails || [];
      localStorage.setItem(SUPERADMIN_EMAILS_KEY, JSON.stringify(emails));
      return emails;
    }
  } catch (e) { console.warn('Error cargando superadmin emails:', e); }
  return SUPERADMIN_DEFAULT;
}

/** Guarda lista de emails superadmin en Firestore */
async function _guardarEmailsSuperadmin(emails) {
  try {
    await db.collection('config').doc('superadmin').set({ emails });
    localStorage.setItem(SUPERADMIN_EMAILS_KEY, JSON.stringify(emails));
  } catch (e) { mostrarToast('Error guardando emails superadmin', 'error'); }
}

/** Muestra/oculta botón superadmin en dashboard */
function _verificarAccesoSuperadmin() {
  const btn = document.getElementById('btn-dash-superadmin');
  if (btn) btn.style.display = _esSuperadmin() ? '' : 'none';
  if (_esSuperadmin()) _actualizarBadgeSuperadmin();
}

/** Badge con el conteo global de docentes pendientes de aprobación (todos los centros) */
async function _actualizarBadgeSuperadmin() {
  const badge = document.getElementById('dash-superadmin-badge');
  if (!badge) return;
  try {
    const snap = await db.collection('usuarios').where('estado', '==', 'pendiente').get();
    // Solo las que no tienen centro real asignado (eligieron "Otro" al
    // registrarse) -- las que sí eligieron un centro existente las aprueba
    // ese centro (admin_centro/director/coordinadora), no el superadmin.
    const sinCentro = snap.docs.filter(d => !d.data().centroId).length;
    if (sinCentro > 0) { badge.style.display = 'flex'; badge.textContent = sinCentro > 9 ? '9+' : String(sinCentro); }
    else { badge.style.display = 'none'; }
  } catch { badge.style.display = 'none'; }
}

let _cacheSuperadminPerfil = { ok: false, at: 0 };

async function _esSuperadminPorPerfil() {
  if (_esSuperadmin()) return true;
  if (!window.currentUser || !window.currentUser.uid || !window.firebase || !firebase.firestore || !db) return false;

  const now = Date.now();
  if (now - _cacheSuperadminPerfil.at < 60000) return _cacheSuperadminPerfil.ok;

  let ok = false;
  try {
    const doc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    const rol = doc.exists ? String(doc.data().rol || '').toLowerCase().trim() : '';
    ok = rol === 'superadmin';
  } catch {}

  _cacheSuperadminPerfil = { ok, at: now };
  return ok;
}

/** Abre el panel de superadmin */
function abrirSuperadmin() {
  if (!_esSuperadmin()) { mostrarToast('Acceso denegado', 'error'); return; }
  _mostrarPanel('panel-superadmin');
  switchTabSuperadmin('solicitudes');
}

/** Tabs del superadmin */
function switchTabSuperadmin(tab) {
  const tabs = { solicitudes: 'tab-sa-solicitudes', centros: 'tab-sa-centros', admins: 'tab-sa-admins', opciones: 'tab-sa-opciones', opciones_coord: 'tab-sa-opciones-coord', opciones_psico: 'tab-sa-opciones-psico', prompts: 'tab-sa-prompts', monitoreo_ia: 'tab-sa-monitoreo-ia', sesiones: 'tab-sa-sesiones', bugs: 'tab-sa-bugs' };
  Object.entries(tabs).forEach(([key, id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (key === tab) { el.classList.add('activo'); el.style.background = '#B71C1C'; el.style.color = '#fff'; }
    else { el.classList.remove('activo'); el.style.background = '#F5F5F5'; el.style.color = '#616161'; }
  });
  if (tab === 'solicitudes') _renderSolicitudesPendientes();
  else if (tab === 'centros') _renderCentrosEducativos();
  else if (tab === 'admins') _renderEmailsSuperadmin();
  else if (tab === 'opciones') _renderOpcionesDocentes();
  else if (tab === 'opciones_coord') _renderOpcionesCoordinadora();
  else if (tab === 'opciones_psico') _renderOpcionesPsicologia();
  else if (tab === 'prompts') _renderPromptsIA();
  else if (tab === 'monitoreo_ia') _renderMonitoreoIA();
  else if (tab === 'sesiones') { window._coordCentroSeleccionado = null; _renderMonitoreoSesiones('sa-contenido'); }
  else if (tab === 'bugs') _renderBugsSuperadmin();
}

/**
 * Vista global de docentes con estado 'pendiente', SIN filtrar por centro.
 * El panel de Admin Centro (_renderDocentesCentro) solo lista pendientes de
 * UN centro a la vez -- un docente que se registró eligiendo "Otro" (o cuyo
 * perfil se creó sin selección de centro) queda con centroId:'' y nunca
 * calza con ningún centro real, así que no aparecía en ningún lado.
 */
async function _renderSolicitudesPendientes() {
  const cont = document.getElementById('sa-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:20px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando solicitudes...</div>';

  try {
    const [snap, centros] = await Promise.all([
      db.collection('usuarios').where('estado', '==', 'pendiente').get(),
      _cargarCentros()
    ]);
    // Solo docentes que eligieron "Otro" al registrarse (sin centro real
    // asignado). Los que sí eligieron un centro existente los debe aprobar
    // ese centro (admin_centro/director/coordinadora), no el superadmin --
    // así el control de acceso se queda en manos de cada centro.
    const solicitudes = snap.docs.map(d => ({ uid: d.id, ...d.data() }))
      .filter(d => !d.centroId)
      .sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || ''));

    const badge = document.getElementById('sa-badge-solicitudes');
    if (badge) { badge.style.display = solicitudes.length > 0 ? '' : 'none'; badge.textContent = solicitudes.length > 9 ? '9+' : solicitudes.length; }

    window._saCentrosCache = centros;

    let html = '<div style="font-size:0.78rem;color:#78909C;margin-bottom:14px;">Solo docentes que se registraron sin elegir un centro existente (opción "Otro"). Las solicitudes de docentes que sí eligieron un centro las aprueba directamente ese centro.</div>';

    if (solicitudes.length === 0) {
      html += '<div style="text-align:center;padding:30px;color:#999;"><span class="material-icons" style="font-size:48px;display:block;margin-bottom:8px;">check_circle_outline</span>No hay solicitudes sin centro asignado</div>';
      cont.innerHTML = html;
      return;
    }

    const opcionesCentros = '<option value="">— Sin asignar —</option>'
      + centros.map(c => '<option value="' + c.id + '">' + escapeHTML(c.nombre || c.id) + '</option>').join('');

    html += '<div style="display:flex;flex-direction:column;gap:10px;">';
    solicitudes.forEach(d => {
      const fecha = d.createdAt ? new Date(d.createdAt).toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric' }) : '';
      const inicial = (d.nombre || d.email || 'U')[0].toUpperCase();

      html += '<div style="background:#fff;border:1.5px solid #FFB74D;border-radius:12px;padding:14px;">'
        + '<div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;">'
        + '<div style="width:44px;height:44px;border-radius:50%;background:#E3F2FD;display:flex;align-items:center;justify-content:center;font-weight:700;color:#1565C0;font-size:1.1rem;">' + escapeHTML(inicial) + '</div>'
        + '<div style="flex:1;min-width:150px;">'
        + '<div style="font-weight:700;font-size:0.95rem;color:#212121;">' + escapeHTML(d.nombre || 'Sin nombre') + '</div>'
        + '<div style="font-size:0.82rem;color:#78909C;">' + escapeHTML(d.email || '') + '</div>'
        + '<div style="font-size:0.75rem;color:#B0BEC5;margin-top:2px;">Registro: ' + fecha + (d.centroNombre ? ' · Escribió: "' + escapeHTML(d.centroNombre) + '"' : '') + '</div>'
        + '</div>'
        + '<span style="background:#FFF3E0;color:#E65100;padding:3px 10px;border-radius:10px;font-size:0.72rem;font-weight:700;white-space:nowrap;">Sin centro asignado</span>'
        + '</div>';

      html += '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:10px;padding-top:10px;border-top:1px solid #F0F0F0;">'
        + '<select id="sa-sol-centro-' + d.uid + '" style="flex:1;min-width:160px;padding:7px 10px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.82rem;">' + opcionesCentros + '</select>'
        + '<button onclick="_saAsignarCentro(\'' + d.uid + '\')" style="padding:7px 12px;background:#1565C0;color:#fff;border:none;border-radius:6px;font-size:0.8rem;font-weight:600;cursor:pointer;">Asignar centro</button>'
        + '<button onclick="_aprobarDocente(\'' + d.uid + '\',\'global\')" style="display:inline-flex;align-items:center;gap:4px;padding:7px 14px;background:#2E7D32;color:#fff;border:none;border-radius:6px;font-size:0.82rem;font-weight:600;cursor:pointer;"><span class="material-icons" style="font-size:16px;">check</span> Aprobar</button>'
        + '<button onclick="_rechazarDocente(\'' + d.uid + '\',\'global\')" style="display:inline-flex;align-items:center;gap:4px;padding:7px 14px;background:#C62828;color:#fff;border:none;border-radius:6px;font-size:0.82rem;font-weight:600;cursor:pointer;"><span class="material-icons" style="font-size:16px;">close</span> Rechazar</button>'
        + '</div></div>';
    });
    html += '</div>';
    cont.innerHTML = html;
  } catch (e) {
    console.error('Error cargando solicitudes:', e);
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

/** Asigna (o cambia) el centro educativo de un docente desde la vista global de solicitudes */
async function _saAsignarCentro(uid) {
  const sel = document.getElementById('sa-sol-centro-' + uid);
  if (!sel) return;
  const centroId = sel.value;
  if (!centroId) { mostrarToast('Selecciona un centro', 'error'); return; }
  const centro = (window._saCentrosCache || []).find(c => c.id === centroId);
  try {
    await db.collection('usuarios').doc(uid).update({ centroId, centroNombre: centro?.nombre || '' });
    mostrarToast('Centro asignado correctamente', 'success');
    _renderSolicitudesPendientes();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

// ── MONITOREO Y EDICIÓN DE IA (Panel Superadmin) ──────────────────
/** Providers de IA soportados, mismo orden que el modal "Configurar IA" del
 * docente (ver guardarApiKey/GROQ_KEY_STORAGE en la sección de IA). */
const _MONITOREO_IA_PROVIDERS = [
  { store: 'groqKey', label: 'Groq', url: 'https://console.groq.com/keys', urlLabel: 'console.groq.com', color: '#2E7D32' },
  { store: 'geminiKey', label: 'Gemini', url: 'https://aistudio.google.com/apikey', urlLabel: 'aistudio.google.com', color: '#F57F17' },
  { store: 'openrouterKey', label: 'OpenRouter', url: 'https://openrouter.ai/keys', urlLabel: 'openrouter.ai', color: '#1565C0' }
];

/** Vista de Superadmin: busca docentes por nombre (sin necesitar su email)
 * y muestra si tienen las claves de IA configuradas, sin exponer el valor
 * real de ninguna clave -- solo permite ESCRIBIR una clave nueva para
 * reemplazarla, directamente desde la cuenta del superadmin. */
async function _renderMonitoreoIA() {
  const cont = document.getElementById('sa-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:20px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando docentes...</div>';

  try {
    const snap = await db.collection('usuarios').where('estado', '==', 'aprobado').get();
    const docentes = snap.docs.map(d => ({ uid: d.id, ...d.data() }))
      .sort((a, b) => (a.nombre || '').localeCompare(b.nombre || ''));
    window._saMonitoreoIACache = docentes;

    let html = '<div style="font-size:0.78rem;color:#78909C;margin-bottom:14px;">Busca a alguien por nombre para ver si tiene las claves de IA (Groq/Gemini/OpenRouter) configuradas, y escribirle una clave nueva directamente -- sin necesidad de pedirle su clave ni su correo.</div>';
    html += '<div style="position:relative;margin-bottom:14px;">'
      + '<span class="material-icons" style="position:absolute;left:10px;top:50%;transform:translateY(-50%);color:#B0BEC5;font-size:20px;">search</span>'
      + '<input type="text" id="sa-ia-buscar" oninput="_saFiltrarMonitoreoIA()" placeholder="Buscar por nombre..." '
      + 'style="width:100%;padding:10px 12px 10px 38px;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.88rem;box-sizing:border-box;">'
      + '</div>';
    html += '<div id="sa-ia-lista"></div>';
    cont.innerHTML = html;
    _saFiltrarMonitoreoIA();
  } catch (e) {
    console.error('Error cargando docentes para monitoreo IA:', e);
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

/** Filtra en memoria la lista ya cacheada según lo escrito en el buscador --
 * Firestore no tiene substring search nativo, y esto es una herramienta de
 * uso puntual/baja frecuencia (solo el superadmin, a demanda), igual que
 * _cargarCentros para el listado de centros. */
function _saFiltrarMonitoreoIA() {
  const lista = document.getElementById('sa-ia-lista');
  if (!lista) return;
  const termino = (document.getElementById('sa-ia-buscar')?.value || '').trim().toLowerCase();
  const todos = window._saMonitoreoIACache || [];
  const filtrados = termino ? todos.filter(d => (d.nombre || '').toLowerCase().includes(termino)) : todos;

  if (filtrados.length === 0) {
    lista.innerHTML = '<div style="text-align:center;padding:30px;color:#999;"><span class="material-icons" style="font-size:40px;display:block;margin-bottom:8px;">person_search</span>' + (termino ? 'Nadie coincide con "' + escapeHTML(termino) + '"' : 'No hay docentes aprobados') + '</div>';
    return;
  }

  const maxMostrar = termino ? filtrados.length : Math.min(filtrados.length, 30);
  let html = '<div style="display:flex;flex-direction:column;gap:8px;">';
  filtrados.slice(0, maxMostrar).forEach(d => {
    const inicial = (d.nombre || d.email || 'U')[0].toUpperCase();
    html += '<div style="background:#fff;border:1.5px solid #E0E0E0;border-radius:12px;padding:12px 14px;">'
      + '<div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;cursor:pointer;" onclick="_saVerEstadoIA(\'' + d.uid + '\')">'
      + '<div style="width:38px;height:38px;border-radius:50%;background:#E3F2FD;display:flex;align-items:center;justify-content:center;font-weight:700;color:#1565C0;font-size:1rem;flex-shrink:0;">' + escapeHTML(inicial) + '</div>'
      + '<div style="flex:1;min-width:150px;">'
      + '<div style="font-weight:700;font-size:0.92rem;color:#212121;">' + escapeHTML(d.nombre || 'Sin nombre') + '</div>'
      + '<div style="font-size:0.76rem;color:#90A4AE;">' + escapeHTML(d.centroNombre || 'Sin centro') + '</div>'
      + '</div>'
      + '<span class="material-icons" style="color:#B0BEC5;">expand_more</span>'
      + '</div>'
      + '<div id="sa-ia-detalle-' + d.uid + '"></div>'
      + '</div>';
  });
  html += '</div>';
  if (!termino && filtrados.length > maxMostrar) {
    html += '<div style="text-align:center;padding:10px;color:#90A4AE;font-size:0.8rem;">Mostrando ' + maxMostrar + ' de ' + filtrados.length + ' -- usa el buscador para encontrar a alguien más</div>';
  }
  lista.innerHTML = html;
}

/** Muestra/oculta el detalle de un docente; al abrir, dispara la carga. */
async function _saVerEstadoIA(uid) {
  const det = document.getElementById('sa-ia-detalle-' + uid);
  if (!det) return;
  if (det.dataset.abierto === '1') { det.dataset.abierto = '0'; det.innerHTML = ''; return; }
  det.dataset.abierto = '1';
  await _saCargarEstadoIA(uid);
}

/** Trae el estado (configurada / no configurada, sin exponer el valor) de
 * las 3 IAs de un docente puntual, y arma el formulario para escribirle una
 * clave nueva. Carga bajo demanda (solo al abrir a esa persona), para no
 * multiplicar por 3 las lecturas de todos los docentes listados. */
async function _saCargarEstadoIA(uid) {
  const det = document.getElementById('sa-ia-detalle-' + uid);
  if (!det) return;
  det.innerHTML = '<div style="text-align:center;padding:14px;color:#90A4AE;"><span class="material-icons" style="animation:spin 1s linear infinite;font-size:18px;vertical-align:middle;">sync</span> Consultando estado...</div>';

  try {
    const docs = await Promise.all(_MONITOREO_IA_PROVIDERS.map(p =>
      db.collection('users').doc(uid).collection('data').doc(p.store).get().catch(() => null)
    ));

    let html = '<div style="margin-top:12px;padding-top:12px;border-top:1px solid #F0F0F0;display:flex;flex-direction:column;gap:10px;">';
    _MONITOREO_IA_PROVIDERS.forEach((p, i) => {
      const doc = docs[i];
      const configurada = !!(doc && doc.exists && doc.data().payload);
      const chip = configurada
        ? '<span style="background:#E8F5E9;color:#2E7D32;padding:2px 9px;border-radius:10px;font-size:0.7rem;font-weight:700;">Configurada</span>'
        : '<span style="background:#FFEBEE;color:#C62828;padding:2px 9px;border-radius:10px;font-size:0.7rem;font-weight:700;">No configurada</span>';
      html += '<div>'
        + '<div style="display:flex;align-items:center;gap:8px;margin-bottom:5px;"><span style="font-weight:700;font-size:0.85rem;color:#37474F;">' + p.label + '</span>' + chip + '</div>'
        + '<div style="display:flex;gap:6px;">'
        + '<input type="password" id="sa-ia-input-' + p.store + '-' + uid + '" placeholder="Escribir una clave nueva de ' + p.label + '..." '
        + 'style="flex:1;padding:7px 10px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.82rem;">'
        + '<button onclick="_saGuardarClaveIA(\'' + uid + '\',\'' + p.store + '\')" style="padding:7px 12px;background:#1565C0;color:#fff;border:none;border-radius:6px;font-size:0.8rem;font-weight:600;cursor:pointer;white-space:nowrap;">Guardar</button>'
        + '</div>'
        + '<p style="margin:4px 0 0;font-size:0.78rem;color:#555;">Obtén su clave en <a href="' + p.url + '" target="_blank" style="color:' + p.color + ';font-weight:600;">' + p.urlLabel + '</a></p>'
        + '<div id="sa-ia-msg-' + p.store + '-' + uid + '" style="font-size:0.72rem;margin-top:3px;min-height:14px;"></div>'
        + '</div>';
    });
    html += '<div style="font-size:0.72rem;color:#B0BEC5;">Por seguridad no se muestra el valor de las claves ya guardadas, solo si están configuradas. Escribe una clave nueva para reemplazarla.</div>';
    html += '</div>';
    det.innerHTML = html;
  } catch (e) {
    det.innerHTML = '<div style="padding:10px;color:#C62828;font-size:0.8rem;">Error: ' + e.message + '</div>';
  }
}

/** Escribe directamente en Firestore la clave de IA de un docente, con el
 * mismo formato que usa window._syncFirebase (payload string), para que en
 * su próximo inicio de sesión _cargarDesdeFirestore la baje sola a su
 * localStorage -- no hace falta ningún cambio del lado del docente. */
async function _saGuardarClaveIA(uid, store) {
  const input = document.getElementById('sa-ia-input-' + store + '-' + uid);
  const msgEl = document.getElementById('sa-ia-msg-' + store + '-' + uid);
  const valor = (input?.value || '').trim();
  if (!valor) { if (msgEl) { msgEl.style.color = '#C62828'; msgEl.textContent = 'Escribe una clave antes de guardar.'; } return; }

  try {
    await db.collection('users').doc(uid).collection('data').doc(store).set({ payload: valor });
    mostrarToast('Clave de ' + (_MONITOREO_IA_PROVIDERS.find(p => p.store === store)?.label || store) + ' guardada', 'success');
    await _saCargarEstadoIA(uid);
  } catch (e) {
    if (msgEl) { msgEl.style.color = '#C62828'; msgEl.textContent = 'Error: ' + e.message; }
  }
}

// ── EDITOR DE PROMPTS IA ─────────────────────────────────────────

const PROMPTS_IA_DEFS = [
  {
    key: 'prompt_sesion',
    label: 'Prompt — Sesión Diaria',
    icono: 'school',
    desc: 'Prompt para generar la sesión de clase de una actividad individual. Variables disponibles: {{moduloFormativo}}, {{familiaProfesional}}, {{actividad}}, {{ecEnunciado}}, {{nivelBloom}}, {{minTotal}}, {{minInicio}}, {{minDesarrollo}}, {{minCierre}}'
  },
  {
    key: 'prompt_base',
    label: 'Prompt — Estructura Base (EC + Actividades)',
    icono: 'account_tree',
    desc: 'Prompt para generar los Elementos de Capacidad y actividades a partir del RA. Variables: {{moduloFormativo}}, {{familiaProfesional}}, {{diasStr}}, {{raDescripcion}}, {{raCriterios}}, {{raRecursos}}, {{contenidosBloque}}, {{cantEC}}, {{actsPorEC}}, {{totalActs}}, {{ecCodigosLista}}, {{actEsperadasLista}}'
  },
  {
    key: 'prompt_instrumentos',
    label: 'Prompt — Instrumentos de Evaluación',
    icono: 'checklist',
    desc: 'Prompt para generar los instrumentos de evaluación en lote. Variables: {{moduloFormativo}}, {{raDescripcion}}, {{actividadesLista}}'
  },
  {
    key: 'prompt_detalle_uno',
    label: 'Prompt — Detalle Completo (Instrumento + Sesión)',
    icono: 'description',
    desc: 'Prompt para generar el detalle completo de una sola actividad. Variables: {{moduloFormativo}}, {{familiaProfesional}}, {{raDescripcion}}, {{actividad}}, {{ecEnunciado}}, {{nivelBloom}}, {{recursos}}, {{minTotal}}, {{minInicio}}, {{minDesarrollo}}, {{minCierre}}, {{instrPrompt}}'
  }
];

let _promptsIACache = null;

async function _cargarPromptsIA() {
  if (_promptsIACache) return _promptsIACache;
  try {
    const doc = await db.collection('config').doc('prompts_ia').get();
    _promptsIACache = doc.exists ? doc.data() : {};
    return _promptsIACache;
  } catch (e) {
    console.error('[Prompts IA] Error cargando:', e);
    return {};
  }
}

async function _guardarPromptIA(key, texto) {
  try {
    await db.collection('config').doc('prompts_ia').set({ [key]: texto }, { merge: true });
    _promptsIACache = null; // invalidar cache
    mostrarToast('Prompt guardado correctamente', 'success');
  } catch (e) {
    console.error('[Prompts IA] Error guardando:', e);
    mostrarToast('Error al guardar prompt: ' + e.message, 'error');
  }
}

async function _resetearPromptIA(key) {
  try {
    await db.collection('config').doc('prompts_ia').set({ [key]: firebase.firestore.FieldValue.delete() }, { merge: true });
    _promptsIACache = null;
    mostrarToast('Prompt restaurado al valor por defecto', 'success');
    _renderPromptsIA();
  } catch (e) {
    console.error('[Prompts IA] Error reseteando:', e);
    mostrarToast('Error al restaurar prompt: ' + e.message, 'error');
  }
}

function _getPromptDefaultByKey(key) {
  if (key === 'prompt_sesion') return _DEFAULT_PROMPT_SESION;
  if (key === 'prompt_base') return _DEFAULT_PROMPT_BASE;
  if (key === 'prompt_instrumentos') return _DEFAULT_PROMPT_INSTRUMENTOS;
  if (key === 'prompt_detalle_uno') return _DEFAULT_PROMPT_DETALLE_UNO;
  return '';
}

async function _renderPromptsIA() {
  const cont = document.getElementById('sa-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:20px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando prompts...</div>';

  const saved = await _cargarPromptsIA();

  let html = `<div style="margin-bottom:12px;">
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
      <span class="material-icons" style="color:#7C4DFF;">psychology</span>
      <h3 style="margin:0;font-size:1rem;color:#424242;">Editor de Prompts de IA</h3>
    </div>
    <p style="font-size:0.8rem;color:#78909C;margin:0 0 16px;">
      Modifica los prompts que usa la IA para generar contenido. Usa las variables entre <code>{{llaves}}</code> para insertar datos dinámicos.
      Si dejas un prompt vacío o lo restauras, se usará el valor por defecto del sistema.
    </p>
  </div>

  <div style="margin-bottom:24px;border:1px solid #E0E0E0;border-radius:12px;padding:16px;background:#FAFAFA;">
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
      <span class="material-icons" style="color:#00897B;">bolt</span>
      <h3 style="margin:0;font-size:1rem;color:#424242;">Probar Proveedores de IA</h3>
    </div>
    <p style="font-size:0.8rem;color:#78909C;margin:0 0 12px;">
      Le pide a cada proveedor configurado (Groq, Gemini, OpenRouter) una respuesta corta de prueba, sin tener que generar una planificación completa. Sirve para confirmar que las claves funcionan y ver cuál responde más rápido.
    </p>
    <button id="btn-probar-ia" onclick="_probarIA()" style="display:inline-flex;align-items:center;gap:6px;padding:9px 18px;background:#00897B;color:#fff;border:none;border-radius:8px;font-weight:600;cursor:pointer;font-size:0.85rem;">
      <span class="material-icons" style="font-size:18px;">bolt</span> Probar IA ahora
    </button>
    <div id="ia-test-resultados" style="margin-top:12px;"></div>
  </div>`;

  PROMPTS_IA_DEFS.forEach(p => {
    const savedVal = saved[p.key] || '';
    const defaultVal = _getPromptDefaultByKey(p.key);
    const isCustom = savedVal && savedVal !== defaultVal;
    const displayVal = savedVal || defaultVal;
    const badgeColor = isCustom ? '#E65100' : '#4CAF50';
    const badgeText = isCustom ? 'Personalizado' : 'Por defecto';

    html += `<div style="margin-bottom:20px;border:1px solid #E0E0E0;border-radius:12px;overflow:hidden;">
      <div style="display:flex;align-items:center;gap:8px;padding:12px 16px;background:#F5F5F5;cursor:pointer;"
           onclick="document.getElementById('prompt-body-${p.key}').classList.toggle('hidden');">
        <span class="material-icons" style="font-size:20px;color:#7C4DFF;">${p.icono}</span>
        <strong style="flex:1;font-size:0.88rem;">${p.label}</strong>
        <span style="font-size:0.7rem;background:${badgeColor};color:#fff;padding:2px 8px;border-radius:10px;">${badgeText}</span>
        <span class="material-icons" style="font-size:18px;color:#9E9E9E;">expand_more</span>
      </div>
      <div id="prompt-body-${p.key}" class="hidden" style="padding:12px 16px;">
        <p style="font-size:0.75rem;color:#78909C;margin:0 0 8px;">${p.desc}</p>
        <textarea id="prompt-ta-${p.key}" style="width:100%;min-height:200px;font-family:monospace;font-size:0.78rem;
          border:1px solid #CFD8DC;border-radius:8px;padding:10px;resize:vertical;line-height:1.5;
          background:#FAFAFA;box-sizing:border-box;">${_escapeHTMLForTextarea(displayVal)}</textarea>
        <div style="display:flex;gap:8px;margin-top:8px;justify-content:flex-end;flex-wrap:wrap;">
          <button onclick="_resetearPromptIA('${p.key}')"
            style="padding:6px 14px;border:1px solid #E0E0E0;border-radius:8px;background:#fff;color:#616161;font-size:0.78rem;cursor:pointer;">
            <span class="material-icons" style="font-size:14px;vertical-align:middle;">restart_alt</span> Restaurar por defecto
          </button>
          <button onclick="_guardarPromptIADesdeEditor('${p.key}')"
            style="padding:6px 14px;border:none;border-radius:8px;background:#7C4DFF;color:#fff;font-size:0.78rem;cursor:pointer;font-weight:600;">
            <span class="material-icons" style="font-size:14px;vertical-align:middle;">save</span> Guardar
          </button>
        </div>
      </div>
    </div>`;
  });

  cont.innerHTML = html;
}

// ── GESTIÓN DE BUGS/ERRORES (superadmin) ─────────────────────────────
// error-reporter.js ya guarda cada error del sistema (de cualquier usuario)
// en la colección error_logs de Firestore, en paralelo al correo de alerta
// que ya existía -- este panel solo lee ese historial (sin escribir nada
// nuevo) y agrega un botón "Copiar" para no tener que copiar el error desde
// el correo. La regla de error_logs (firestore.rules) ya restringe la
// lectura a superadmin (y admin_centro/director solo de su propio centro,
// para otros usos futuros); este panel además solo se abre desde Superadmin,
// que ya está gateado por _esSuperadmin() en abrirSuperadmin().
async function _renderBugsSuperadmin() {
  const cont = document.getElementById('sa-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:20px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando errores...</div>';

  try {
    const snap = await db.collection('error_logs').orderBy('createdAt', 'desc').limit(200).get();
    const errores = snap.docs.map(d => ({ id: d.id, ...d.data() }));
    window._bugsCache = errores;
    _renderBugsLista('todas');
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:30px;color:#C62828;"><span class="material-icons" style="font-size:40px;display:block;margin-bottom:8px;">error_outline</span>Error cargando el historial de errores: ' + escapeHTML(e.message || String(e)) + '</div>';
  }
}

function _bugSeveridadInfo(severity) {
  if (severity === 'high') return { bg: '#FFEBEE', color: '#C62828', texto: 'Alta' };
  if (severity === 'medium') return { bg: '#FFF3E0', color: '#E65100', texto: 'Media' };
  return { bg: '#F1F8E9', color: '#558B2F', texto: 'Baja' };
}

function _bugFechaStr(e) {
  const fecha = e.createdAt && typeof e.createdAt.toDate === 'function' ? e.createdAt.toDate() : (e.ts ? new Date(e.ts) : null);
  if (!fecha || Number.isNaN(fecha.getTime())) return 'Fecha desconocida';
  return fecha.toLocaleString('es-DO', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

/** Filtra window._bugsCache por severidad + texto (mensaje/módulo/tipo/acción). */
function _filtrarBugsCache(filtroSeveridad, filtroTexto) {
  const errores = window._bugsCache || [];
  let filtrados = filtroSeveridad === 'todas' ? errores : errores.filter(e => e.severity === filtroSeveridad);
  const texto = (filtroTexto || '').trim().toLowerCase();
  if (texto) {
    filtrados = filtrados.filter(e => (
      (e.message || '') + ' ' + (e.module || '') + ' ' + (e.type || '') + ' ' + (e.action || '')
    ).toLowerCase().includes(texto));
  }
  return filtrados;
}

/** Arma solo el HTML de las tarjetas de error (sin la barra de filtros). */
function _bugsResultadosHTML(filtrados) {
  if (!filtrados.length) {
    return '<div style="text-align:center;padding:30px;color:#999;"><span class="material-icons" style="font-size:48px;display:block;margin-bottom:8px;">check_circle</span>No hay errores registrados con este filtro</div>';
  }
  let html = '<div style="display:flex;flex-direction:column;gap:10px;">';
  filtrados.forEach(e => {
    const sev = _bugSeveridadInfo(e.severity);
    const donde = (e.filename || '') + (e.lineno ? ':' + e.lineno : '');
    html += '<div style="background:#fff;border:1.5px solid #E0E0E0;border-radius:12px;padding:14px;">'
      + '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:8px;">'
      + '<div style="flex:1;min-width:200px;">'
      + '<span style="background:' + sev.bg + ';color:' + sev.color + ';padding:2px 9px;border-radius:12px;font-size:0.72rem;font-weight:700;margin-right:6px;">' + sev.texto + '</span>'
      + '<span style="font-size:0.78rem;color:#78909C;">' + escapeHTML(e.module || e.type || 'general') + ' · ' + escapeHTML(_bugFechaStr(e)) + '</span>'
      + '</div>'
      + '<button onclick="_copiarBug(\'' + e.id + '\', this)" style="display:inline-flex;align-items:center;gap:4px;padding:5px 12px;background:#1565C0;color:#fff;border:none;border-radius:6px;font-size:0.78rem;cursor:pointer;white-space:nowrap;font-family:inherit;">'
      + '<span class="material-icons" style="font-size:14px;">content_copy</span> Copiar</button>'
      + '</div>'
      + '<div style="font-size:0.88rem;color:#263238;font-weight:600;margin-bottom:6px;word-break:break-word;">' + escapeHTML(e.message || 'Sin mensaje') + '</div>'
      + '<div style="font-size:0.76rem;color:#90A4AE;">' + escapeHTML(e.userEmail || 'Usuario desconocido') + (donde ? ' · ' + escapeHTML(donde) : '') + ' · Build ' + escapeHTML(e.appVersion || 'n/a') + '</div>'
      + '</div>';
  });
  html += '</div>';
  return html;
}

// Re-filtra sin reconstruir la barra de búsqueda/select -- si se reconstruyera todo
// el contenedor en cada tecla (oninput), el <input> de búsqueda perdería el foco y
// la posición del cursor en cada letra escrita.
function _filtrarBugs() {
  const filtroSeveridad = document.getElementById('sa-bugs-filtro')?.value || 'todas';
  const filtroTexto = document.getElementById('sa-bugs-buscar')?.value || '';
  const resultados = document.getElementById('sa-bugs-resultados');
  if (resultados) resultados.innerHTML = _bugsResultadosHTML(_filtrarBugsCache(filtroSeveridad, filtroTexto));
}

function _renderBugsLista(filtroSeveridad, filtroTexto) {
  const cont = document.getElementById('sa-contenido');
  if (!cont) return;
  const errores = window._bugsCache || [];
  const filtrados = _filtrarBugsCache(filtroSeveridad, filtroTexto);

  const html = '<div style="margin-bottom:14px;display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;">'
    + '<div style="font-size:0.85rem;color:#546E7A;">' + errores.length + ' error' + (errores.length === 1 ? '' : 'es') + ' registrados (últimos 200)</div>'
    + '<div style="display:flex;gap:8px;flex-wrap:wrap;">'
    + '<input id="sa-bugs-buscar" type="text" value="' + escapeHTML(filtroTexto || '') + '" placeholder="Buscar (ej. OpenRouter, Groq, Gemini)..." '
    + 'oninput="_filtrarBugs()" style="padding:8px 10px;border:1.5px solid #CFD8DC;border-radius:8px;font-size:0.85rem;min-width:220px;">'
    + '<select id="sa-bugs-filtro" onchange="_filtrarBugs()" style="padding:8px 10px;border:1.5px solid #CFD8DC;border-radius:8px;font-size:0.85rem;">'
    + '<option value="todas"' + (filtroSeveridad === 'todas' ? ' selected' : '') + '>Todas las severidades</option>'
    + '<option value="high"' + (filtroSeveridad === 'high' ? ' selected' : '') + '>Alta</option>'
    + '<option value="medium"' + (filtroSeveridad === 'medium' ? ' selected' : '') + '>Media</option>'
    + '<option value="low"' + (filtroSeveridad === 'low' ? ' selected' : '') + '>Baja</option>'
    + '</select>'
    + '</div>'
    + '</div>'
    + '<div id="sa-bugs-resultados">' + _bugsResultadosHTML(filtrados) + '</div>';

  cont.innerHTML = html;
}

function _formatoBugTexto(e) {
  const donde = (e.filename || 'n/a') + (e.lineno ? ':' + e.lineno + ':' + (e.colno || 0) : '');
  const lineas = [
    'Error: ' + (e.message || 'Sin mensaje'),
    'Severidad: ' + (e.severity || 'n/a'),
    'Tipo: ' + (e.type || 'n/a'),
    'Módulo: ' + (e.module || 'n/a'),
    'Acción: ' + (e.action || 'n/a'),
    'Archivo: ' + donde,
    'Fecha: ' + _bugFechaStr(e),
    'Usuario: ' + (e.userEmail || 'n/a') + ' (UID: ' + (e.uid || 'n/a') + ')',
    'Build: ' + (e.appVersion || 'n/a') + ' / SW: ' + (e.swVersion || 'n/a'),
    'URL: ' + (e.url || 'n/a')
  ];
  if (e.stack) lineas.push('Stack:', e.stack);
  return lineas.join('\n');
}

function _copiarBug(id, btnEl) {
  const errores = window._bugsCache || [];
  const e = errores.find(x => x.id === id);
  if (!e) { mostrarToast('Error no encontrado', 'error'); return; }
  const texto = _formatoBugTexto(e);
  navigator.clipboard.writeText(texto).then(() => {
    mostrarToast('Error copiado al portapapeles', 'success');
    if (btnEl) {
      const original = btnEl.innerHTML;
      btnEl.innerHTML = '<span class="material-icons" style="font-size:14px;">check</span> Copiado';
      setTimeout(() => { if (btnEl) btnEl.innerHTML = original; }, 1500);
    }
  }).catch(() => mostrarToast('No se pudo copiar (revisa los permisos del navegador)', 'error'));
}

function _escapeHTMLForTextarea(str) {
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// ── PROBAR PROVEEDORES DE IA (superadmin, sin generar una planificación) ──
// Reusa las mismas funciones de llamada que usa la generación real
// (_llamarGroqConFallback, _llamarGemini, _llamarOpenRouterConFallback), con
// un prompt corto -- así la prueba refleja el comportamiento real (mismo
// fallback entre modelos, mismos reintentos) sin gastar tiempo generando EC
// y actividades completas.
async function _probarIA() {
  const cont = document.getElementById('ia-test-resultados');
  const btn = document.getElementById('btn-probar-ia');
  if (!cont) return;

  const groqKey = getGroqKey();
  const geminiKey = getGeminiKey();
  const openrouterKey = getOpenRouterKey();

  if (!groqKey && !geminiKey && !openrouterKey) {
    cont.innerHTML = '<div style="padding:10px 12px;background:#FFF3E0;border:1px solid #FFE0B2;border-radius:8px;color:#E65100;font-size:0.82rem;">No hay ninguna clave de IA configurada. Ve a ⚙️ Config. IA para agregar una.</div>';
    return;
  }

  if (btn) btn.disabled = true;
  cont.innerHTML = '';

  const testPrompt = 'Responde SOLO con JSON válido, sin markdown, sin texto adicional, con esta estructura exacta: {"chiste": "un chiste corto y original sobre programadores, en español"}';
  const proveedores = [
    { nombre: 'Groq', key: groqKey, llamar: () => _llamarGroqConFallback(testPrompt, 'Prueba IA', 200) },
    { nombre: 'Gemini', key: geminiKey, llamar: () => _llamarGemini(testPrompt, 200) },
    { nombre: 'OpenRouter', key: openrouterKey, llamar: () => _llamarOpenRouterConFallback(testPrompt, openrouterKey, 'Prueba IA', 200, 30000) }
  ];

  for (const prov of proveedores) {
    if (!prov.key) {
      cont.innerHTML += _probarIAFilaHTML(prov.nombre, 'sin_clave', null, 'Sin clave configurada');
      continue;
    }
    const filaId = 'ia-test-' + prov.nombre.toLowerCase();
    cont.innerHTML += _probarIAFilaHTML(prov.nombre, 'probando', null, null, filaId);
    const t0 = performance.now();
    try {
      const data = await prov.llamar();
      const ms = Math.round(performance.now() - t0);
      const contenido = (data && typeof data.chiste === 'string') ? data.chiste : JSON.stringify(data);
      const fila = document.getElementById(filaId);
      if (fila) fila.outerHTML = _probarIAFilaHTML(prov.nombre, 'ok', ms, contenido);
    } catch (e) {
      const ms = Math.round(performance.now() - t0);
      const fila = document.getElementById(filaId);
      if (fila) fila.outerHTML = _probarIAFilaHTML(prov.nombre, 'error', ms, e.message || String(e));
    }
  }

  if (btn) btn.disabled = false;
}

function _probarIAFilaHTML(nombre, estado, ms, detalle, id) {
  const cfg = {
    probando: { icono: 'hourglass_top', color: '#1565C0', bg: '#E3F2FD', texto: 'Probando…' },
    ok: { icono: 'check_circle', color: '#2E7D32', bg: '#E8F5E9', texto: 'Respondió en ' + ms + ' ms' },
    error: { icono: 'error', color: '#C62828', bg: '#FFEBEE', texto: 'Falló (' + ms + ' ms)' },
    sin_clave: { icono: 'key_off', color: '#78909C', bg: '#ECEFF1', texto: 'Sin clave configurada' }
  }[estado];

  return '<div' + (id ? ' id="' + id + '"' : '') + ' style="display:flex;align-items:flex-start;gap:10px;padding:10px 12px;border:1px solid #E0E0E0;border-radius:8px;margin-bottom:8px;background:#fff;">'
    + '<span class="material-icons" style="font-size:20px;color:' + cfg.color + ';' + (estado === 'probando' ? 'animation:spin 1s linear infinite;' : '') + '">' + cfg.icono + '</span>'
    + '<div style="flex:1;min-width:0;">'
    + '<div style="font-weight:700;font-size:0.85rem;color:#263238;">' + escapeHTML(nombre) + '<span style="font-weight:600;font-size:0.76rem;color:' + cfg.color + ';margin-left:8px;background:' + cfg.bg + ';padding:1px 8px;border-radius:10px;">' + cfg.texto + '</span></div>'
    + (detalle ? '<div style="font-size:0.8rem;color:#546E7A;margin-top:4px;word-break:break-word;">' + escapeHTML(detalle) + '</div>' : '')
    + '</div></div>';
}

function _guardarPromptIADesdeEditor(key) {
  const ta = document.getElementById('prompt-ta-' + key);
  if (!ta) return;
  const texto = ta.value.trim();
  const defaultVal = _getPromptDefaultByKey(key);
  if (!texto || texto === defaultVal) {
    _resetearPromptIA(key);
  } else {
    _guardarPromptIA(key, texto);
  }
}

// ── PROMPTS POR DEFECTO (templates con {{variables}}) ────────────

const _DEFAULT_PROMPT_SESION = `Eres un docente experto en educación técnico profesional de República Dominicana. Escribe el GUION REAL de una sesión de clase, lista para impartir tal cual (no una descripción abstracta), para:

Módulo: {{moduloFormativo}} | {{familiaProfesional}}
Actividad: {{actividad}}
EC: {{ecEnunciado}} (Bloom: {{nivelBloom}})
Duración total: {{minTotal}} minutos (Inicio: {{minInicio}}min, Desarrollo: {{minDesarrollo}}min, Cierre: {{minCierre}}min)
Listas de Contenidos del Resultado de Aprendizaje (Paso 2 -- para los campos contenidoConceptual/contenidoProcedimental/contenidoActitudinal, NO inventes contenido nuevo: elige textualmente 1 o 2 ítems de estas mismas listas):
- Conceptuales: {{contenidosConceptualesRA}}
- Procedimentales: {{contenidosProcedimentalesRA}}
- Actitudinales: {{contenidosActitudinalesRA}}

INSTRUCCIONES IMPORTANTES:
- Escribe como el guion real de la clase: incluye frases textuales que el docente puede decir (entre comillas), preguntas concretas para los estudiantes, y acciones específicas -- no descripciones abstractas ni genéricas.
- Cada campo largo debe tener contenido EXTENSO (mínimo 4-6 líneas o varios puntos con viñetas •).
- Adapta todo al contexto técnico profesional del módulo indicado.
- NO asumas ni inventes estudiantes reales con condiciones específicas: en "adaptacionesEspecificas" describe 1-2 escenarios HIPOTÉTICOS y genéricos (ej. "Los estudiantes que presenten dificultad visual, se les facilitará...") sin nombrar a nadie ni asumir que existen en este grupo real.
- Para contenidoConceptual, contenidoProcedimental y contenidoActitudinal: NUNCA generes texto nuevo. Copia TEXTUALMENTE 1 o 2 ítems (no más) de las listas de arriba que apliquen más a esta actividad específica.

RESPONDE SOLO JSON válido, sin markdown, sin texto extra. USA EXACTAMENTE estas 17 claves:

{
  "apertura": "Guion de apertura ({{minInicio}} min en total junto con encuadre y organización): un saludo o frase motivadora textual entre comillas, seguido de una 'frase del día' o dato curioso relacionado al tema con una breve pregunta de reflexión para los estudiantes, y una dinámica de enganche breve (pase de lista, retroalimentación de la clase anterior, etc.).",
  "encuadre": "El propósito de la sesión en 1-2 oraciones que el docente puede decir textualmente a los estudiantes, vinculado al EC y a cómo se conecta con la clase anterior y la siguiente.",
  "organizacion": "Instrucciones concretas: cómo se forman los equipos/parejas o si es individual, qué roles se asignan (ej. investigador, redactor, expositor) para favorecer la inclusión, y qué materiales debe tener listos cada quien antes de empezar.",
  "pasos": "Entre 4 y 6 pasos numerados del desarrollo ({{minDesarrollo}} min repartidos entre los pasos), en formato 'Paso N – Título breve (X min): descripción detallada de qué instrucción da el docente, qué produce el estudiante y cómo se apoya la inclusión cuando aplique.' separados por doble salto de línea.",
  "conceptual": "Un breve momento de análisis o comparación técnica dentro del desarrollo (ej. comparar casos, aplicar un concepto a una situación real) que conecte la actividad con su relevancia profesional.",
  "sintesis": "El cierre de la sesión ({{minCierre}} min): una pregunta reflexiva textual entre comillas para los estudiantes, y cómo el docente sintetiza los aprendizajes clave.",
  "conexion": "Cómo se conecta lo aprendido con la práctica profesional real o con la siguiente sesión (ej. 'Se presenta el tema del día siguiente: ...') y la despedida.",
  "estrategias": "Enumera y describe 3-4 estrategias didácticas utilizadas en la sesión. Para cada una, explica: qué es, cómo se aplica en esta sesión específica, y por qué es efectiva para el nivel de Bloom '{{nivelBloom}}'. Ejemplos: ABP, aprendizaje cooperativo, modelamiento, aula invertida, gamificación, think-pair-share.",
  "tipo": "Modalidad de trabajo de la actividad: responde EXACTAMENTE una de estas 3 opciones: 'Individual', 'Por Equipo', 'Por Equipos (en pares)'.",
  "estrategiaCorta": "Una etiqueta muy corta (2 a 5 palabras) que resuma la estrategia principal de la sesión, ej. 'Investigación/socialización'.",
  "intencionEducativa": "Un párrafo de 3-5 oraciones que explique el propósito formativo de la actividad, incluyendo explícitamente cómo se garantiza la participación inclusiva y equitativa de todos los estudiantes.",
  "apoyosPosibles": "2-3 apoyos genéricos concretos (con viñetas •) que el docente puede ofrecer durante esta actividad.",
  "adaptaciones": "2-3 adaptaciones metodológicas genéricas concretas (con viñetas •) aplicables a esta actividad.",
  "estrategiasInclusivas": "2-3 estrategias de inclusión genéricas concretas (con viñetas •) recomendadas para esta actividad.",
  "adaptacionesEspecificas": "1-2 escenarios HIPOTÉTICOS de ajustes razonables (ej. 'Los estudiantes que presenten dificultad visual, se les facilitará uso de un lector de pantalla y se les asignará el rol de...'), sin asumir estudiantes reales de este grupo.",
  "contenidoConceptual": "Copia TEXTUALMENTE 1 o 2 ítems (no más) de la lista de Contenidos Conceptuales de arriba que apliquen más a esta actividad. NO inventes contenido nuevo.",
  "contenidoProcedimental": "Copia TEXTUALMENTE 1 o 2 ítems (no más) de la lista de Contenidos Procedimentales de arriba que apliquen más a esta actividad. NO inventes contenido nuevo.",
  "contenidoActitudinal": "Copia TEXTUALMENTE 1 o 2 ítems (no más) de la lista de Contenidos Actitudinales de arriba que apliquen más a esta actividad. NO inventes contenido nuevo."
}`;

