async function _esVinculadora() {
  if (!window.currentUser) return false;
  try {
    const perfil = await _getPerfilUsuarioActualCacheado();
    return !!perfil && _tieneRol(perfil, 'vinculadora');
  } catch { return false; }
}

async function _verificarAccesoVinculacion() {
  const btn = document.getElementById('btn-dash-vinculacion');
  if (!btn) return;
  const esVinc = await _esVinculadora();
  const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
  const visible = esVinc || esSA;
  btn.style.display = visible ? '' : 'none';
}

function abrirCoordinadora() {
  window._coordCentroSeleccionado = null; // Reset para permitir cambiar centro
  // Limpiar el contenido que Panel Director pudo haber dejado renderizado en su
  // propio contenedor -- evita que queden dos elementos con el mismo id (ej.
  // "coord-rend-buscar") vivos a la vez si el usuario ya había abierto estas
  // pestañas desde Panel Director en esta misma sesión.
  const dirCont = document.getElementById('dir-contenido');
  if (dirCont) dirCont.innerHTML = '';
  _mostrarPanel('panel-coordinadora');
  switchTabCoordinadora('calificaciones');
  // La pestaña "Entradas/Salidas" solo se muestra si el superadmin la activó
  // (Superadmin > Opciones Coordinadora) -- ver _cargarOpcionesCoordinadora().
  _cargarOpcionesCoordinadora().then(opciones => {
    const tabSesiones = document.getElementById('tab-coord-sesiones');
    if (tabSesiones) tabSesiones.style.display = opciones.panel_sesiones ? '' : 'none';
  }).catch(() => {});
}

function switchTabCoordinadora(tab) {
  const tabs = { calificaciones: 'tab-coord-calificaciones', planificaciones: 'tab-coord-planificaciones', resumen: 'tab-coord-resumen', avisos: 'tab-coord-avisos', sesiones: 'tab-coord-sesiones' };
  Object.entries(tabs).forEach(([key, id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (key === tab) { el.classList.add('activo'); el.style.background = '#00695C'; el.style.color = '#fff'; }
    else { el.classList.remove('activo'); el.style.background = '#F5F5F5'; el.style.color = '#616161'; }
  });
  window._coordTabActual = tab;
  if (tab === 'calificaciones') _coordMonitorCalificaciones();
  else if (tab === 'planificaciones') _coordMonitorPlanificaciones();
  else if (tab === 'resumen') _coordResumenDocentes();
  else if (tab === 'avisos') _coordAvisos();
  else if (tab === 'sesiones') _renderMonitoreoSesiones('coord-contenido');
}

async function _coordGetCentroId() {
  // Si ya hay un centro seleccionado en el panel, usarlo
  if (window._coordCentroSeleccionado) return window._coordCentroSeleccionado;
  if (!window.currentUser) return null;
  // Buscar centroId del usuario
  try {
    const perfil = await _getPerfilUsuarioActualCacheado();
    if (perfil && perfil.centroId) return perfil.centroId;
  } catch {}
  // Admin centro: buscar en centros.admins
  try {
    const email = window.currentUser.email;
    if (email) {
      const [centro] = await _buscarCentrosPorEmailAdmin(email);
      if (centro) return centro.id;
      // Superadmin sin centroId asignado: si solo hay un centro en todo el
      // sistema, usarlo directamente en vez de forzar a elegir entre 1 opción.
      // Caso raro (solo superadmins), asi que aqui si se justifica traer la
      // coleccion completa en vez de agregar una consulta de conteo nueva.
      const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
      if (esSA) {
        const snap = await db.collection('centros').get();
        if (snap.size === 1) return snap.docs[0].id;
      }
    }
  } catch {}
  // Superadmin con varios centros / Director sin centro: mostrar selector
  return null;
}

async function _coordMostrarSelectorCentro(cont, callback, contId) {
  try {
    const snap = await db.collection('centros').get();
    const centros = snap.docs.map(d => ({ id: d.id, ...d.data() }));
    if (!centros.length) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay centros registrados.</div>'; return; }
    const args = contId ? '\'' + contId + '\'' : '';
    let html = '<div style="text-align:center;padding:30px;">'
      + '<span class="material-icons" style="font-size:48px;color:#00695C;display:block;margin-bottom:12px;">business</span>'
      + '<p style="color:#546E7A;margin-bottom:16px;">Selecciona un centro educativo para ver sus datos:</p>'
      + '<div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;">';
    centros.forEach(c => {
      html += '<button onclick="window._coordCentroSeleccionado=\'' + c.id + '\';' + callback + '(' + args + ')" style="padding:12px 20px;background:#fff;border:2px solid #00695C;border-radius:12px;cursor:pointer;font-size:0.9rem;font-weight:600;color:#00695C;transition:all 0.2s;"'
        + ' onmouseover="this.style.background=\'#00695C\';this.style.color=\'#fff\'" onmouseout="this.style.background=\'#fff\';this.style.color=\'#00695C\'">'
        + '<span class="material-icons" style="font-size:16px;vertical-align:middle;margin-right:4px;">school</span>'
        + escapeHTML(c.nombre || c.id) + '</button>';
    });
    html += '</div></div>';
    cont.innerHTML = html;
  } catch (e) { cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>'; }
}

async function _coordGetDocentes(centroId) {
  // Docentes aprobados del centro
  const snap = await db.collection('usuarios').where('centroId', '==', centroId).get();
  const docentes = snap.docs.map(d => ({ uid: d.id, ...d.data() })).filter(d => d.estado === 'aprobado');
  const uids = new Set(docentes.map(d => d.uid));

  // También incluir docentes del centro sin estado (admins auto-aprobados pueden no tener estado)
  try {
    const snap2 = await db.collection('usuarios').where('centroId', '==', centroId).get();
    snap2.docs.forEach(d => {
      if (!uids.has(d.id)) {
        uids.add(d.id);
        docentes.push({ uid: d.id, ...d.data() });
      }
    });
  } catch {}

  // Agregar admins del centro (pueden tener centroId vacío o diferente)
  try {
    const centroDoc = await db.collection('centros').doc(centroId).get();
    if (centroDoc.exists) {
      const admins = centroDoc.data().admins || [];
      for (const adminEmail of admins) {
        const emailLower = adminEmail.toLowerCase().trim();
        // Buscar por email exacto y en minúsculas
        let found = false;
        for (const variant of [emailLower, adminEmail.trim()]) {
          if (found) break;
          const adminSnap = await db.collection('usuarios').where('email', '==', variant).limit(1).get();
          if (!adminSnap.empty) {
            const adminDoc = adminSnap.docs[0];
            if (!uids.has(adminDoc.id)) {
              uids.add(adminDoc.id);
              docentes.push({ uid: adminDoc.id, ...adminDoc.data() });
            }
            found = true;
          }
        }
      }
    }
  } catch (e) { console.warn('Error buscando admins para coordinadora:', e); }

  // Incluir superadmins que pertenezcan a este centro (pueden no tener centroId en su doc)
  try {
    const saDoc = await db.collection('config').doc('superadmin').get();
    const saEmails = saDoc.exists ? (saDoc.data().emails || []) : [];
    const todosEmails = [...new Set([...SUPERADMIN_DEFAULT, ...saEmails])];
    for (const saEmail of todosEmails) {
      const emailLower = saEmail.toLowerCase().trim();
      for (const variant of [emailLower, saEmail.trim()]) {
        const saSnap = await db.collection('usuarios').where('email', '==', variant).limit(1).get();
        if (!saSnap.empty) {
          const saDocUser = saSnap.docs[0];
          if (!uids.has(saDocUser.id)) {
            uids.add(saDocUser.id);
            docentes.push({ uid: saDocUser.id, ...saDocUser.data() });
          }
          break;
        }
      }
    }
  } catch (e) { console.warn('Error buscando superadmins para coordinadora:', e); }

  return docentes;
}

// ── MONITOR DE SESIONES (entradas/salidas del sistema) ───────────
// Compartido por Director, Coordinadora (visibilidad configurable desde
// Superadmin > Opciones Coordinadora) y Superadmin. Lee la bitácora de cada
// usuario del centro (ya sincronizada a Firestore por registrarCambio()) y
// filtra únicamente sus eventos "Sesión iniciada" / "Sesión cerrada".
async function _renderMonitoreoSesiones(contId) {
  contId = contId || 'coord-contenido';
  const cont = document.getElementById(contId);
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:20px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando...</div>';

  const centroId = await _coordGetCentroId();
  if (!centroId) { await _coordMostrarSelectorCentro(cont, '_renderMonitoreoSesiones', contId); return; }

  try {
    const docentes = await _coordGetDocentes(centroId);
    if (!docentes.length) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay usuarios en este centro.</div>'; return; }

    const eventos = [];
    await Promise.all(docentes.map(async d => {
      try {
        const doc = await db.collection('users').doc(d.uid).collection('data').doc('bitacora').get();
        if (!doc.exists) return;
        const raw = doc.data().payload;
        const log = raw ? JSON.parse(raw) : [];
        (Array.isArray(log) ? log : []).forEach(e => {
          if (!e || !e.accion || !e.fecha) return;
          if (e.accion.includes('Sesión iniciada')) eventos.push({ uid: d.uid, nombre: d.nombre || d.email || 'Sin nombre', email: d.email || '', rol: d.rol || '', fecha: e.fecha, tipo: 'entrada' });
          else if (e.accion.includes('Sesión cerrada')) eventos.push({ uid: d.uid, nombre: d.nombre || d.email || 'Sin nombre', email: d.email || '', rol: d.rol || '', fecha: e.fecha, tipo: 'salida' });
        });
      } catch { /* usuario sin bitácora sincronizada aún */ }
    }));

    if (!eventos.length) {
      cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;"><span class="material-icons" style="font-size:48px;display:block;margin-bottom:8px;">login</span>Aún no hay entradas o salidas registradas en este centro.</div>';
      return;
    }

    eventos.sort((a, b) => b.fecha.localeCompare(a.fecha));

    // "Activos ahora": el evento más reciente de cada persona es una entrada sin salida posterior
    const masReciente = {};
    eventos.forEach(e => { if (!masReciente[e.uid] || e.fecha > masReciente[e.uid].fecha) masReciente[e.uid] = e; });
    const activos = Object.values(masReciente).filter(e => e.tipo === 'entrada');

    const rolBadge = rol => rol === 'director'
      ? '<span style="background:#4A148C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.65rem;font-weight:600;margin-left:6px;">Director</span>'
      : rol === 'coordinadora'
      ? '<span style="background:#00695C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.65rem;font-weight:600;margin-left:6px;">Coordinadora</span>'
      : rol === 'superadmin'
      ? '<span style="background:#B71C1C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.65rem;font-weight:600;margin-left:6px;">Superadmin</span>' : '';

    let html = '<h4 style="color:#1565C0;margin:0 0 12px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">login</span> Monitoreo de Entradas y Salidas</h4>';

    html += '<div style="margin-bottom:16px;padding:12px 14px;background:#E8F5E9;border-radius:10px;">'
      + '<div style="font-size:0.78rem;font-weight:700;color:#1B5E20;text-transform:uppercase;letter-spacing:0.05em;margin-bottom:8px;">'
      + '<span class="material-icons" style="font-size:15px;vertical-align:middle;">circle</span> Actualmente en línea (' + activos.length + ')</div>';
    html += activos.length
      ? '<div style="display:flex;flex-wrap:wrap;gap:8px;">' + activos.map(a =>
          '<span style="display:inline-flex;align-items:center;gap:5px;background:#fff;border:1px solid #A5D6A7;border-radius:20px;padding:4px 12px;font-size:0.8rem;font-weight:600;color:#2E7D32;">'
          + '<span style="width:8px;height:8px;border-radius:50%;background:#4CAF50;"></span>' + escapeHTML(a.nombre) + rolBadge(a.rol) + '</span>'
        ).join('') + '</div>'
      : '<div style="font-size:0.82rem;color:#66BB6A;">Nadie parece estar conectado en este momento.</div>';
    html += '</div>';

    // Agrupar por día
    const grupos = {};
    eventos.forEach(e => {
      const dia = e.fecha.slice(0, 10);
      if (!grupos[dia]) grupos[dia] = [];
      grupos[dia].push(e);
    });

    html += Object.entries(grupos).map(([dia, entries]) => {
      const diaLabel = new Date(dia + 'T12:00:00').toLocaleDateString('es-DO', { weekday: 'long', day: '2-digit', month: 'long' });
      const rows = entries.map(e => {
        const hora = new Date(e.fecha).toLocaleTimeString('es-DO', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
        const icon = e.tipo === 'entrada' ? 'login' : 'logout';
        const color = e.tipo === 'entrada' ? '#2E7D32' : '#C62828';
        return '<div style="display:flex;align-items:flex-start;gap:10px;padding:8px 12px;border-bottom:1px solid #F5F5F5;">'
          + '<span class="material-icons" style="font-size:16px;color:' + color + ';flex-shrink:0;margin-top:1px;">' + icon + '</span>'
          + '<div style="flex:1;min-width:0;">'
          + '<div style="font-size:0.83rem;line-height:1.4;"><strong>' + escapeHTML(e.nombre) + '</strong>' + rolBadge(e.rol) + ' — ' + (e.tipo === 'entrada' ? 'entró al sistema' : 'salió del sistema') + '</div>'
          + '<div style="font-size:0.72rem;color:#9E9E9E;margin-top:2px;">' + hora + (e.email ? ' · ' + escapeHTML(e.email) : '') + '</div>'
          + '</div></div>';
      }).join('');
      return '<div style="margin-bottom:12px;background:#fff;border-radius:10px;border:1px solid #E0E0E0;overflow:hidden;">'
        + '<div style="padding:8px 12px;background:#F5F5F5;font-size:0.75rem;font-weight:700;color:#546E7A;text-transform:capitalize;">' + diaLabel + '</div>'
        + rows + '</div>';
    }).join('');

    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

// ── 1. MONITOR DE CALIFICACIONES ────────────────────────────────

async function _coordMonitorCalificaciones(contId) {
  contId = contId || 'coord-contenido';
  window._coordActiveContId = contId;
  const cont = document.getElementById(contId);
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Analizando calificaciones...</div>';

  const centroId = await _coordGetCentroId();
  if (!centroId) { _coordMostrarSelectorCentro(cont, '_coordMonitorCalificaciones', contId); return; }

  try {
    const docentes = await _coordGetDocentes(centroId);
    if (!docentes.length) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay docentes en este centro.</div>'; return; }

    // Leer datos de calificaciones de cada docente
    const docentesData = await Promise.all(docentes.map(async d => {
      try {
        const calDoc = await db.collection('users').doc(d.uid).collection('data').doc('calificaciones').get();
        const calRaw = calDoc.exists ? calDoc.data() : {};
        const calData = calRaw.payload ? JSON.parse(calRaw.payload) : calRaw;
        const cursos = calData.cursos || {};
        let totalActs = 0, actsSinNota = 0, totalEstudiantes = 0;
        const cursosDetalle = [];
        Object.entries(cursos).forEach(([cId, curso]) => {
          const ests = curso.estudiantes || [];
          totalEstudiantes += ests.length;
          let cursoActs = 0, cursoSinNota = 0;
          const rasDetalle = [];
          Object.entries(curso.ras || {}).forEach(([rk, ra]) => {
            const acts = ra.actividades || [];
            cursoActs += acts.length;
            totalActs += acts.length;
            const actsDetalle = [];
            acts.forEach(actId => {
              const snap = (ra._actividadesSnapshot || []).find(a => a.id === actId);
              let calificados = 0;
              ests.forEach(est => {
                const nota = curso.notas?.[est.id]?.[ra.raKey]?.[actId];
                if (nota !== undefined && nota !== null) calificados++;
              });
              const sinNota = ests.length - calificados;
              if (sinNota > 0 && ests.length > 0) actsSinNota++;
              if (sinNota > 0 && ests.length > 0) cursoSinNota++;
              actsDetalle.push({ id: actId, nombre: snap?.enunciado || actId, max: ra.valores?.[actId] || 0, calificados, sinNota, total: ests.length });
            });
            rasDetalle.push({ raKey: rk, label: ra.label || rk, modulo: ra.modulo || '', actividades: actsDetalle });
          });
          cursosDetalle.push({ id: cId, nombre: curso.nombre || cId, estudiantes: ests, ras: rasDetalle, notas: curso.notas || {}, totalActs: cursoActs, sinNota: cursoSinNota });
        });
        return { ...d, nCursos: Object.keys(cursos).length, totalActs, actsSinNota, totalEstudiantes, cursosDetalle };
      } catch (e) { console.warn('Error cal coord:', e); return { ...d, nCursos: 0, totalActs: 0, actsSinNota: 0, totalEstudiantes: 0, cursosDetalle: [] }; }
    }));

    docentesData.sort((a, b) => b.actsSinNota - a.actsSinNota);

    let html = '<h4 style="color:#00695C;margin:0 0 14px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">grade</span> Estado de Calificaciones por Docente</h4>';

    const alDia = docentesData.filter(d => d.actsSinNota === 0 && d.totalActs > 0).length;
    const atrasados = docentesData.filter(d => d.actsSinNota > 0).length;
    const sinData = docentesData.filter(d => d.totalActs === 0).length;
    html += '<div style="display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap;">'
      + '<div style="flex:1;min-width:120px;background:#E8F5E9;border:1.5px solid #A5D6A7;border-radius:10px;padding:12px;text-align:center;">'
      + '<div style="font-size:1.4rem;font-weight:700;color:#2E7D32;">' + alDia + '</div><div style="font-size:0.78rem;color:#388E3C;">Al día</div></div>'
      + '<div style="flex:1;min-width:120px;background:#FFF3E0;border:1.5px solid #FFB74D;border-radius:10px;padding:12px;text-align:center;">'
      + '<div style="font-size:1.4rem;font-weight:700;color:#E65100;">' + atrasados + '</div><div style="font-size:0.78rem;color:#E65100;">Con atraso</div></div>'
      + '<div style="flex:1;min-width:120px;background:#F5F5F5;border:1.5px solid #E0E0E0;border-radius:10px;padding:12px;text-align:center;">'
      + '<div style="font-size:1.4rem;font-weight:700;color:#9E9E9E;">' + sinData + '</div><div style="font-size:0.78rem;color:#9E9E9E;">Sin actividades</div></div>'
      + '</div>';

    // Guardar datos para drill-down
    window._coordCalData = docentesData;

    html += '<div style="display:flex;flex-direction:column;gap:10px;">';
    docentesData.forEach((d, idx) => {
      const pctCalificado = d.totalActs > 0 ? Math.round(((d.totalActs - d.actsSinNota) / d.totalActs) * 100) : 0;
      let statusColor, statusIcon, statusText;
      if (d.totalActs === 0) { statusColor = '#9E9E9E'; statusIcon = 'remove_circle_outline'; statusText = 'Sin actividades'; }
      else if (d.actsSinNota === 0) { statusColor = '#2E7D32'; statusIcon = 'check_circle'; statusText = 'Al día'; }
      else if (d.actsSinNota <= 2) { statusColor = '#FF9800'; statusIcon = 'warning'; statusText = d.actsSinNota + ' sin calificar'; }
      else { statusColor = '#C62828'; statusIcon = 'error'; statusText = d.actsSinNota + ' sin calificar'; }

      html += '<div style="background:#fff;border:1.5px solid #E0E0E0;border-radius:12px;padding:14px;transition:box-shadow 0.2s;">'
        + '<div onclick="_coordToggleDetalleCal(' + idx + ')" style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;cursor:pointer;" onmouseover="this.parentElement.style.boxShadow=\'0 2px 8px rgba(0,0,0,0.1)\'" onmouseout="this.parentElement.style.boxShadow=\'none\'">'
        + '<div style="width:44px;height:44px;border-radius:50%;background:' + statusColor + '22;display:flex;align-items:center;justify-content:center;">'
        + '<span class="material-icons" style="color:' + statusColor + ';font-size:22px;">' + statusIcon + '</span></div>'
        + '<div style="flex:1;min-width:150px;">'
        + '<div style="font-weight:700;font-size:0.95rem;color:#212121;">' + escapeHTML(d.nombre || d.email || 'Sin nombre') + ' <span class="material-icons" style="font-size:16px;vertical-align:middle;color:#90A4AE;">expand_more</span></div>'
        + '<div style="font-size:0.82rem;color:#78909C;">' + d.nCursos + ' cursos · ' + d.totalEstudiantes + ' estudiantes · ' + d.totalActs + ' actividades</div>'
        + '</div>'
        + '<div style="text-align:right;min-width:100px;">'
        + '<div style="font-size:1.1rem;font-weight:700;color:' + statusColor + ';">' + pctCalificado + '%</div>'
        + '<div style="font-size:0.72rem;color:' + statusColor + ';">' + statusText + '</div>'
        + '</div></div>'
        + '<div id="coord-cal-detalle-' + idx + '" style="display:none;margin-top:12px;border-top:1px solid #E0E0E0;padding-top:12px;"></div>'
        + '</div>';
    });
    html += '</div>';
    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

/** Expandir/colapsar detalle de calificaciones de un docente */
function _coordToggleDetalleCal(idx) {
  const el = document.getElementById('coord-cal-detalle-' + idx);
  if (!el) return;
  if (el.style.display !== 'none') { el.style.display = 'none'; return; }
  const d = window._coordCalData?.[idx];
  if (!d || !d.cursosDetalle.length) { el.innerHTML = '<div style="color:#9E9E9E;font-size:0.85rem;">Este docente no tiene cursos registrados.</div>'; el.style.display = 'block'; return; }

  let h = '';
  d.cursosDetalle.forEach(curso => {
    h += '<div style="margin-bottom:14px;">'
      + '<div style="font-weight:700;font-size:0.9rem;color:#1565C0;margin-bottom:6px;display:flex;align-items:center;gap:6px;">'
      + '<span class="material-icons" style="font-size:18px;">school</span> ' + escapeHTML(curso.nombre)
      + ' <span style="font-weight:400;font-size:0.78rem;color:#78909C;">(' + curso.estudiantes.length + ' est. · ' + curso.totalActs + ' act.)</span></div>';

    if (!curso.ras.length) { h += '<div style="font-size:0.82rem;color:#9E9E9E;margin-left:24px;">Sin RAs asignados</div></div>'; return; }

    curso.ras.forEach(ra => {
      h += '<div style="margin-left:12px;margin-bottom:8px;">'
        + '<div style="font-size:0.82rem;font-weight:600;color:#00695C;margin-bottom:4px;">' + escapeHTML(ra.label) + (ra.modulo ? ' <span style="font-weight:400;color:#78909C;">(' + escapeHTML(ra.modulo) + ')</span>' : '') + '</div>';

      if (!ra.actividades.length) { h += '<div style="font-size:0.78rem;color:#9E9E9E;margin-left:12px;">Sin actividades</div></div>'; return; }

      // Tabla de actividades con estado de calificación
      h += '<div style="overflow-x:auto;margin-left:12px;"><table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:300px;">'
        + '<thead><tr style="background:#F5F5F5;"><th style="text-align:left;padding:4px 8px;border:1px solid #E0E0E0;">Actividad</th>'
        + '<th style="padding:4px 8px;border:1px solid #E0E0E0;width:60px;">Valor</th>'
        + '<th style="padding:4px 8px;border:1px solid #E0E0E0;width:80px;">Calificados</th>'
        + '<th style="padding:4px 8px;border:1px solid #E0E0E0;width:80px;">Pendientes</th></tr></thead><tbody>';

      ra.actividades.forEach(act => {
        const color = act.sinNota > 0 ? '#FFF3E0' : '#E8F5E9';
        h += '<tr style="background:' + color + ';"><td style="padding:4px 8px;border:1px solid #E0E0E0;">' + escapeHTML(act.nombre) + '</td>'
          + '<td style="padding:4px 8px;border:1px solid #E0E0E0;text-align:center;">' + act.max + '</td>'
          + '<td style="padding:4px 8px;border:1px solid #E0E0E0;text-align:center;color:#2E7D32;font-weight:600;">' + act.calificados + '/' + act.total + '</td>'
          + '<td style="padding:4px 8px;border:1px solid #E0E0E0;text-align:center;color:' + (act.sinNota > 0 ? '#C62828' : '#2E7D32') + ';font-weight:600;">' + act.sinNota + '</td></tr>';
      });
      h += '</tbody></table></div></div>';
    });

    // Notas por estudiante agrupadas por RA
    if (curso.estudiantes.length && curso.ras.length) {
      h += '<details style="margin-left:12px;margin-top:6px;"><summary style="cursor:pointer;font-size:0.82rem;color:#1565C0;font-weight:600;">Ver notas por estudiante (' + curso.estudiantes.length + ')</summary>';
      h += '<div style="margin-top:8px;">';
      curso.ras.forEach(ra => {
        if (!ra.actividades.length) return;
        h += '<div style="margin-bottom:12px;">'
          + '<div style="font-size:0.8rem;font-weight:700;color:#00695C;margin-bottom:4px;padding:4px 8px;background:#E0F2F1;border-radius:6px;">'
          + escapeHTML(ra.label) + (ra.modulo ? ' — ' + escapeHTML(ra.modulo) : '') + '</div>';
        h += '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:0.75rem;">'
          + '<thead><tr style="background:#E3F2FD;"><th style="text-align:left;padding:4px 6px;border:1px solid #BBDEFB;min-width:120px;">Estudiante</th>';
        ra.actividades.forEach(act => {
          const nombre = act.nombre.length > 25 ? act.nombre.substring(0, 25) + '…' : act.nombre;
          h += '<th style="padding:4px;border:1px solid #BBDEFB;font-size:0.68rem;max-width:90px;text-align:center;" title="' + escapeHTML(act.nombre) + ' (máx: ' + act.max + ')">' + escapeHTML(nombre) + '<br><span style="font-weight:400;color:#78909C;">/' + act.max + '</span></th>';
        });
        h += '</tr></thead><tbody>';
        curso.estudiantes.forEach(est => {
          h += '<tr><td style="padding:3px 6px;border:1px solid #BBDEFB;font-weight:500;">' + escapeHTML(est.nombre) + '</td>';
          ra.actividades.forEach(act => {
            const nota = curso.notas?.[est.id]?.[ra.raKey]?.[act.id];
            const tieneNota = nota !== undefined && nota !== null;
            h += '<td style="padding:3px 4px;border:1px solid #BBDEFB;text-align:center;background:' + (tieneNota ? '#E8F5E9' : '#FFEBEE') + ';color:' + (tieneNota ? '#1B5E20' : '#C62828') + ';font-weight:600;">' + (tieneNota ? nota : '—') + '</td>';
          });
          h += '</tr>';
        });
        h += '</tbody></table></div></div>';
      });
      h += '</div></details>';
    }
    h += '</div>';
  });
  el.innerHTML = h;
  el.style.display = 'block';
}

// ── 2. MONITOR DE PLANIFICACIONES ───────────────────────────────

/**
 * Lee la biblioteca de planificaciones de un docente. El docente NUNCA guarda
 * un doc único 'biblioteca_planificaciones' -- auth.js la parte en chunks
 * ('biblioteca_meta' + 'biblioteca_chunk_N', ver _guardarBibliotecaChunks en
 * auth.js) para no toparse con el límite de 1 MiB por documento. Leer el doc
 * único siempre daba biblioteca vacía, aunque el docente sí tuviera planes.
 */
async function _coordLeerBibliotecaDocente(uid) {
  try {
    const base = db.collection('users').doc(uid).collection('data');
    const metaDoc = await base.doc('biblioteca_meta').get();
    if (!metaDoc.exists) return { items: [] };
    const meta = JSON.parse(metaDoc.data().payload || '{}');
    const totalChunks = meta.totalChunks || 0;
    if (!totalChunks) return { items: [] };
    const chunkDocs = await Promise.all(
      Array.from({ length: totalChunks }, (_, i) => base.doc('biblioteca_chunk_' + i).get())
    );
    const items = [];
    chunkDocs.forEach(docSnap => {
      if (!docSnap.exists) return;
      try {
        const data = JSON.parse(docSnap.data().payload || '{"items":[]}');
        items.push(...(data.items || []));
      } catch {}
    });
    return { items };
  } catch (e) {
    console.warn('Error leyendo biblioteca de ' + uid + ':', e);
    return { items: [] };
  }
}

// ── LECTURA DEL PORTAFOLIO DE OTRO DOCENTE (Coordinadora) ────────
// Mismo patrón que _coordLeerBibliotecaDocente: leen directo de Firestore con
// el uid del docente en vez de window.currentUser.uid. NUNCA tocan
// portafolio_evidencias_privadas -- esa colección está fuera del alcance de
// Coordinadora tanto por regla de Firestore como porque estas funciones
// simplemente no la consultan.

async function _coordLeerPortafolioBase(uid) {
  try {
    const doc = await db.collection('users').doc(uid).collection('data').doc('portafolio_base').get();
    if (!doc.exists || !doc.data().payload) return { docente: {}, metadata: {} };
    const parsed = JSON.parse(doc.data().payload);
    return { docente: parsed.docente || {}, metadata: parsed.metadata || {} };
  } catch (e) {
    console.warn('Error leyendo portafolio_base de ' + uid + ':', e);
    return { docente: {}, metadata: {} };
  }
}

async function _coordLeerPortafolioFoto(uid) {
  try {
    const doc = await db.collection('users').doc(uid).collection('data').doc('portafolio_foto').get();
    if (!doc.exists || !doc.data().payload) return { fotoBase64: '', fotoMime: '' };
    return JSON.parse(doc.data().payload);
  } catch (e) {
    console.warn('Error leyendo portafolio_foto de ' + uid + ':', e);
    return { fotoBase64: '', fotoMime: '' };
  }
}

async function _coordLeerPortafolioCV(uid) {
  const base = db.collection('users').doc(uid).collection('data');
  try {
    const metaDoc = await base.doc('portafolio_cv_meta').get();
    if (metaDoc.exists && metaDoc.data().payload) {
      const meta = JSON.parse(metaDoc.data().payload);
      let base64 = '';
      for (let i = 0; i < (meta.totalChunks || 0); i++) {
        const chunkDoc = await base.doc('portafolio_cv_chunk_' + i).get();
        base64 += (chunkDoc.exists && chunkDoc.data().payload) || '';
      }
      return { cvBase64: base64, cvNombre: meta.cvNombre || '', cvMime: meta.cvMime || '' };
    }
    // Migración desde el formato viejo (un solo documento) -- mismo fallback que cargarPortafolioCV.
    const legacyDoc = await base.doc('portafolio_cv').get();
    if (legacyDoc.exists && legacyDoc.data().payload) {
      try {
        const legacy = JSON.parse(legacyDoc.data().payload);
        if (legacy.cvBase64) return legacy;
      } catch {}
    }
  } catch (e) {
    console.warn('Error leyendo CV de ' + uid + ':', e);
  }
  return { cvBase64: '', cvNombre: '', cvMime: '' };
}

async function _coordLeerEvidenciasPortafolio(uid) {
  try {
    const snap = await db.collection('users').doc(uid).collection('portafolio_evidencias').orderBy('fecha', 'desc').get();
    return snap.docs.map(d => ({ id: d.id, ...d.data() }));
  } catch (e) {
    console.warn('Error leyendo evidencias de ' + uid + ':', e);
    return [];
  }
}

async function _coordDescargarCVDocente(uid) {
  const cv = await _coordLeerPortafolioCV(uid);
  if (!cv.cvBase64) { mostrarToast('Este docente no ha subido un currículum', 'error'); return; }
  const bytes = Uint8Array.from(atob(cv.cvBase64), c => c.charCodeAt(0));
  const blob = new Blob([bytes], { type: cv.cvMime || 'application/octet-stream' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = cv.cvNombre || 'curriculum';
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

async function _coordDescargarEvidenciaDocente(uid, id) {
  try {
    const docRef = db.collection('users').doc(uid).collection('portafolio_evidencias').doc(id);
    const doc = await docRef.get();
    if (!doc.exists) { mostrarToast('No encontrado', 'error'); return; }
    const it = doc.data();
    const base64 = await _cargarArchivoEvidenciaBase64(docRef, it);
    if (!base64) { mostrarToast('Esta evidencia no tiene archivo adjunto', 'error'); return; }
    const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
    const blob = new Blob([bytes], { type: it.archivoMime || 'application/octet-stream' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = it.archivoNombre || 'archivo';
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  } catch (e) {
    mostrarToast('Error al descargar: ' + (e.message || e), 'error');
  }
}

/** Lee el reporte original (con todos sus campos estructurados) desde
 *  users/{uid}/data/reportes -- necesario para regenerar el Word con la
 *  plantilla del centro, ya que la evidencia del Portafolio solo guarda un
 *  resumen en texto plano, no los campos individuales (firmas, seguimiento, etc). */
async function _coordLeerReporteOriginal(uid, estId, repId) {
  try {
    const doc = await db.collection('users').doc(uid).collection('data').doc('reportes').get();
    if (!doc.exists || !doc.data().payload) return null;
    const data = JSON.parse(doc.data().payload);
    const lista = data[estId] || [];
    return lista.find(r => r.id === repId) || null;
  } catch (e) {
    console.warn('Error leyendo reporte original de ' + uid + ':', e);
    return null;
  }
}

/** Descarga el Word (plantilla del centro) de un Reporte visto desde el Portafolio de
 *  Coordinadora. Usa el docx ya guardado en el reporte si existe; si no, lo genera al
 *  vuelo -- misma lógica que descargarReporteDocx, pero cruzando al uid del docente. */
async function _coordDescargarReporteDocente(uid, estId, repId) {
  const rep = await _coordLeerReporteOriginal(uid, estId, repId);
  if (!rep) { mostrarToast('No se encontró el reporte original.', 'error'); return; }

  if (rep.reporteDocxBase64) {
    const blob = new Blob([Uint8Array.from(atob(rep.reporteDocxBase64), c => c.charCodeAt(0))], {
      type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = rep.reporteDocxNombre || 'Reporte_Psicologia.docx';
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    return;
  }

  mostrarToast('Generando Word...', 'info');
  const generado = await _generarBlobReportePsicologiaDocx(rep);
  if (!generado) { mostrarToast('No hay plantilla de reportes de Psicología cargada en el centro.', 'error'); return; }
  const url = URL.createObjectURL(generado.blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = generado.nombre;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

/** Descarga cualquier evidencia de solo texto (ej. un Comentario) como documento Word
 *  simple -- Arial 12, sin plantilla -- reusando el mismo truco HTML+Blob que ya usa
 *  Imprimir en Mi Libreta. No necesita el uid del docente: usa solo lo que ya trae la
 *  propia evidencia (título/descripción/fecha). */
function _coordDescargarEvidenciaComoWord(titulo, descripcion, fecha) {
  const fechaLabel = fecha ? new Date(fecha + 'T12:00:00').toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' }) : '';
  const textoHtml = escapeHTML(descripcion || '').replace(/\n/g, '<br>');
  const html = `<html xmlns:o='urn:schemas-microsoft-com:office:office'
    xmlns:w='urn:schemas-microsoft-com:office:word'
    xmlns='http://www.w3.org/TR/REC-html40'>
  <head><meta charset="utf-8"/>
  <style>
    body{font-family:Arial;font-size:12pt;}
    p{margin:0 0 12pt;}
  </style></head>
  <body><p><b>${escapeHTML(titulo || 'Sin título')}</b></p><p>${fechaLabel}</p><p>${textoHtml}</p></body></html>`;

  const blob = new Blob(['﻿', html], { type: 'application/msword' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = (titulo || 'Documento').replace(/[\\/:*?"<>|]+/g, '').trim() + '.doc';
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

/** Wrapper para las tarjetas de evidencia del Portafolio de Coordinadora: busca la
 *  evidencia por su índice en window._coordPortafolioEvidenciasActuales (evita meter
 *  título/descripción de texto libre dentro del onclick) y la descarga como Word simple. */
function _coordDescargarComentarioPorIndice(idx) {
  const item = window._coordPortafolioEvidenciasActuales?.[idx];
  if (!item) return;
  _coordDescargarEvidenciaComoWord(item.titulo, item.descripcion, item.fecha);
}

/** Busca en users/{uid}/data/reportes un reporte cuyo estudiante coincida con el nombre
 *  dado -- para Reportes de evidencias VIEJAS (creadas antes de guardar refEstId/refId).
 *  Recorre todos los estudiantes porque no se guardó el estId. Si hay más de una
 *  coincidencia se queda con la más reciente (por ts). Best-effort: si no encuentra nada
 *  devuelve null y el llamador debe caer al Word simple. */
async function _coordBuscarReporteHeuristico(uid, nombreBuscado) {
  if (!nombreBuscado) return null;
  try {
    const doc = await db.collection('users').doc(uid).collection('data').doc('reportes').get();
    if (!doc.exists || !doc.data().payload) return null;
    const data = JSON.parse(doc.data().payload);
    const nombreNorm = nombreBuscado.trim().toLowerCase();
    let mejor = null;
    Object.values(data).forEach(lista => {
      (lista || []).forEach(r => {
        if ((r.estudianteNombre || '').trim().toLowerCase() === nombreNorm) {
          if (!mejor || (r.ts || 0) > (mejor.ts || 0)) mejor = r;
        }
      });
    });
    return mejor;
  } catch (e) {
    console.warn('Error en búsqueda heurística de reporte de ' + uid + ':', e);
    return null;
  }
}

/** Descarga un Reporte viejo (sin refEstId/refId) desde el Portafolio de Coordinadora:
 *  intenta ubicarlo por nombre de estudiante en users/{uid}/data/reportes para poder
 *  regenerar el Word con la plantilla del centro; si no lo encuentra, cae al Word
 *  simple en Arial 12 (mismo comportamiento que tenía antes de este ajuste). */
async function _coordDescargarReporteHeuristico(idx) {
  const item = window._coordPortafolioEvidenciasActuales?.[idx];
  if (!item) return;
  const uid = window._coordPortafolioEvidenciasUid;
  const nombreBuscado = (item.titulo || '').replace(/^Reporte\s*—\s*/, '').trim();

  mostrarToast('Buscando el reporte original...', 'info');
  const rep = uid ? await _coordBuscarReporteHeuristico(uid, nombreBuscado) : null;
  if (!rep) { _coordDescargarEvidenciaComoWord(item.titulo, item.descripcion, item.fecha); return; }

  if (rep.reporteDocxBase64) {
    const blob = new Blob([Uint8Array.from(atob(rep.reporteDocxBase64), c => c.charCodeAt(0))], {
      type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = rep.reporteDocxNombre || 'Reporte_Psicologia.docx';
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    return;
  }

  const generado = await _generarBlobReportePsicologiaDocx(rep);
  if (!generado) { _coordDescargarEvidenciaComoWord(item.titulo, item.descripcion, item.fecha); return; }
  const url = URL.createObjectURL(generado.blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = generado.nombre;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

/**
 * Ciclo escolar ("2026-2027") al que pertenece una planificación guardada,
 * usando la misma convención que _getSchoolYearKey (año escolar inicia en
 * agosto). Prioriza la fecha de inicio del módulo sobre la fecha en que se
 * guardó/duplicó el registro, porque un docente puede duplicar en cualquier
 * momento un plan que en realidad es para otro ciclo.
 */
function _coordCicloDePlan(item) {
  const fechaInicio = item?.planificacion?.datosGenerales?.fechaInicio;
  const fechaRef = fechaInicio ? new Date(fechaInicio) : (item?.fechaGuardado ? new Date(item.fechaGuardado) : null);
  if (!fechaRef || isNaN(fechaRef.getTime())) return 'Sin fecha';
  return _getSchoolYearKey(fechaRef);
}

async function _coordMonitorPlanificaciones(contId) {
  contId = contId || 'coord-contenido';
  window._coordActiveContId = contId;
  const cont = document.getElementById(contId);
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Analizando planificaciones...</div>';

  const centroId = await _coordGetCentroId();
  if (!centroId) { _coordMostrarSelectorCentro(cont, '_coordMonitorPlanificaciones', contId); return; }

  try {
    const docentes = await _coordGetDocentes(centroId);
    if (!docentes.length) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay docentes en este centro.</div>'; return; }

    const cicloActual = _getSchoolYearKey(new Date());

    const docentesData = await Promise.all(docentes.map(async d => {
      try {
        const biblio = await _coordLeerBibliotecaDocente(d.uid);
        const items = biblio.items || [];
        const itemsCicloActual = items.filter(it => _coordCicloDePlan(it) === cicloActual);
        const calDoc = await db.collection('users').doc(d.uid).collection('data').doc('calificaciones').get();
        const calRaw2 = calDoc.exists ? calDoc.data() : {};
        const calData = calRaw2.payload ? JSON.parse(calRaw2.payload) : calRaw2;
        const cursos = calData.cursos || {};
        let asignadas = 0;
        const cursosConPlan = [];
        Object.entries(cursos).forEach(([cId, c]) => {
          const pIds = c.planIds || [];
          asignadas += pIds.length;
          if (pIds.length) cursosConPlan.push({ nombre: c.nombre || cId, planIds: pIds });
        });
        const sortedItems = [...items].sort((a, b) => (b.fechaGuardado || b.modificado || b.creado || '').localeCompare(a.fechaGuardado || a.modificado || a.creado || ''));
        const ultimaFecha = sortedItems[0]?.fechaGuardado || sortedItems[0]?.modificado || sortedItems[0]?.creado || null;
        return {
          ...d,
          totalPlanificaciones: itemsCicloActual.length, // activas en el ciclo actual (impulsa el estado/color de la tarjeta)
          totalBiblioteca: items.length,                 // histórico completo, incluye ciclos anteriores
          asignadas, ultimaModificacion: ultimaFecha, planItems: items, cursosConPlan
        };
      } catch { return { ...d, totalPlanificaciones: 0, totalBiblioteca: 0, asignadas: 0, ultimaModificacion: null, planItems: [], cursosConPlan: [] }; }
    }));

    docentesData.sort((a, b) => a.totalPlanificaciones - b.totalPlanificaciones);

    // Guardar para drill-down
    window._coordPlanData = docentesData;
    window._coordCicloActual = cicloActual;

    let html = '<h4 style="color:#00695C;margin:0 0 4px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">description</span> Estado de Planificaciones por Docente</h4>'
      + '<div style="font-size:0.78rem;color:#78909C;margin-bottom:14px;">Ciclo escolar actual: <strong>' + cicloActual + '</strong> — los conteos principales solo cuentan planificaciones de este ciclo; el historial completo (incluye ciclos anteriores) está disponible al expandir cada docente.</div>';

    const conPlan = docentesData.filter(d => d.totalPlanificaciones > 0).length;
    const sinPlan = docentesData.filter(d => d.totalPlanificaciones === 0).length;
    const sinAsignar = docentesData.filter(d => d.totalPlanificaciones > 0 && d.asignadas === 0).length;
    html += '<div style="display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap;">'
      + '<div style="flex:1;min-width:120px;background:#E8F5E9;border:1.5px solid #A5D6A7;border-radius:10px;padding:12px;text-align:center;">'
      + '<div style="font-size:1.4rem;font-weight:700;color:#2E7D32;">' + conPlan + '</div><div style="font-size:0.78rem;color:#388E3C;">Con planificaciones (ciclo actual)</div></div>'
      + '<div style="flex:1;min-width:120px;background:#FFEBEE;border:1.5px solid #EF9A9A;border-radius:10px;padding:12px;text-align:center;">'
      + '<div style="font-size:1.4rem;font-weight:700;color:#C62828;">' + sinPlan + '</div><div style="font-size:0.78rem;color:#C62828;">Sin planificaciones (ciclo actual)</div></div>'
      + '<div style="flex:1;min-width:120px;background:#FFF3E0;border:1.5px solid #FFB74D;border-radius:10px;padding:12px;text-align:center;">'
      + '<div style="font-size:1.4rem;font-weight:700;color:#E65100;">' + sinAsignar + '</div><div style="font-size:0.78rem;color:#E65100;">Sin asignar a cursos</div></div>'
      + '</div>';

    html += '<div style="display:flex;flex-direction:column;gap:10px;">';
    docentesData.forEach((d, idx) => {
      let statusColor, statusIcon;
      if (d.totalPlanificaciones === 0) { statusColor = '#C62828'; statusIcon = 'cancel'; }
      else if (d.asignadas === 0) { statusColor = '#FF9800'; statusIcon = 'warning'; }
      else { statusColor = '#2E7D32'; statusIcon = 'check_circle'; }

      const ultimaMod = d.ultimaModificacion ? new Date(d.ultimaModificacion).toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric' }) : 'Nunca';
      const otrasEnBiblio = d.totalBiblioteca - d.totalPlanificaciones;

      html += '<div style="background:#fff;border:1.5px solid #E0E0E0;border-radius:12px;padding:14px;transition:box-shadow 0.2s;">'
        + '<div onclick="_coordToggleDetallePlan(' + idx + ')" style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;cursor:pointer;" onmouseover="this.parentElement.style.boxShadow=\'0 2px 8px rgba(0,0,0,0.1)\'" onmouseout="this.parentElement.style.boxShadow=\'none\'">'
        + '<div style="width:44px;height:44px;border-radius:50%;background:' + statusColor + '22;display:flex;align-items:center;justify-content:center;">'
        + '<span class="material-icons" style="color:' + statusColor + ';font-size:22px;">' + statusIcon + '</span></div>'
        + '<div style="flex:1;min-width:150px;">'
        + '<div style="font-weight:700;font-size:0.95rem;color:#212121;">' + escapeHTML(d.nombre || d.email || 'Sin nombre') + ' <span class="material-icons" style="font-size:16px;vertical-align:middle;color:#90A4AE;">expand_more</span></div>'
        + '<div style="font-size:0.82rem;color:#78909C;">' + d.totalPlanificaciones + ' planificaciones (ciclo ' + cicloActual + ') · ' + d.asignadas + ' asignadas a cursos</div>'
        + (otrasEnBiblio > 0 ? '<div style="font-size:0.72rem;color:#B0BEC5;">+ ' + otrasEnBiblio + ' más en su biblioteca de ciclos anteriores</div>' : '')
        + '<div style="font-size:0.72rem;color:#B0BEC5;">Última modificación: ' + ultimaMod + '</div>'
        + '</div></div>'
        + '<div id="coord-plan-detalle-' + idx + '" style="display:none;margin-top:12px;border-top:1px solid #E0E0E0;padding-top:12px;"></div>'
        + '</div>';
    });
    html += '</div>';
    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

/** Expandir/colapsar detalle de planificaciones de un docente */
function _coordToggleDetallePlan(idx) {
  const el = document.getElementById('coord-plan-detalle-' + idx);
  if (!el) return;
  if (el.style.display !== 'none') { el.style.display = 'none'; return; }
  const d = window._coordPlanData?.[idx];
  if (!d || !d.planItems.length) { el.innerHTML = '<div style="color:#9E9E9E;font-size:0.85rem;">Este docente no tiene planificaciones.</div>'; el.style.display = 'block'; return; }

  let h = '';

  // Cursos con planificaciones asignadas
  if (d.cursosConPlan.length) {
    h += '<div style="margin-bottom:10px;font-size:0.82rem;font-weight:600;color:#1565C0;">Cursos con planificación asignada:</div>';
    d.cursosConPlan.forEach(c => {
      h += '<div style="margin-left:12px;margin-bottom:4px;font-size:0.8rem;"><span class="material-icons" style="font-size:14px;vertical-align:middle;color:#2E7D32;">check</span> ' + escapeHTML(c.nombre) + ' <span style="color:#78909C;">(' + c.planIds.length + ' plan' + (c.planIds.length > 1 ? 'es' : '') + ')</span></div>';
    });
    h += '<div style="margin-bottom:10px;"></div>';
  }

  // Planificaciones agrupadas por ciclo escolar (ciclo actual expandido, los demás colapsados)
  const cicloActual = window._coordCicloActual || _getSchoolYearKey(new Date());
  const grupos = {};
  d.planItems.forEach(item => {
    const ciclo = _coordCicloDePlan(item);
    (grupos[ciclo] = grupos[ciclo] || []).push(item);
  });
  const ciclosOrdenados = Object.keys(grupos).sort((a, b) => {
    if (a === 'Sin fecha') return 1;
    if (b === 'Sin fecha') return -1;
    return b.localeCompare(a); // más reciente primero
  });

  h += '<div style="font-size:0.82rem;font-weight:600;color:#00695C;margin-bottom:8px;">Planificaciones guardadas (' + d.planItems.length + '):</div>';

  ciclosOrdenados.forEach(ciclo => {
    const itemsCiclo = grupos[ciclo];
    const esActual = ciclo === cicloActual;
    h += '<details' + (esActual ? ' open' : '') + ' style="margin-bottom:8px;">'
      + '<summary style="cursor:pointer;font-size:0.8rem;font-weight:700;color:' + (esActual ? '#2E7D32' : '#546E7A') + ';padding:4px 0;">'
      + (ciclo === 'Sin fecha' ? 'Sin fecha identificada' : 'Ciclo ' + ciclo + (esActual ? ' (actual)' : '')) + ' — ' + itemsCiclo.length + ' plan' + (itemsCiclo.length > 1 ? 'es' : '')
      + '</summary>'
      + '<div style="display:flex;flex-direction:column;gap:6px;margin-top:6px;">'
      + itemsCiclo.map(item => _coordPlanItemHTML(item, idx)).join('')
      + '</div></details>';
  });

  el.innerHTML = h;
  el.style.display = 'block';
}

/** Tarjeta de detalle de una planificación individual (usada en el drill-down de Coordinadora) */
function _coordPlanItemHTML(item, idx) {
  const plan = item.planificacion || {};
  const raDesc = plan.ra?.descripcion || '';
  const raCorto = raDesc.substring(0, 60) + (raDesc.length > 60 ? '...' : '');
  const modulo = plan.datosGenerales?.moduloFormativo || '';
  const nActs = (plan.actividades || []).length;
  const fecha = item.fechaGuardadoLabel || (item.fechaGuardado ? new Date(item.fechaGuardado).toLocaleDateString('es-DO') : '');

  let h = '<div style="background:#F5F5F5;border:1px solid #E0E0E0;border-radius:8px;padding:10px;">'
    + '<div style="font-weight:600;font-size:0.85rem;color:#212121;">' + escapeHTML(item.nombre || 'Sin nombre') + '</div>';
  if (modulo) h += '<div style="font-size:0.78rem;color:#1565C0;">' + escapeHTML(modulo) + '</div>';
  if (raCorto) h += '<div style="font-size:0.75rem;color:#00695C;">' + escapeHTML(raCorto) + '</div>';
  h += '<div style="font-size:0.72rem;color:#78909C;margin-top:2px;">' + nActs + ' actividades · Guardada: ' + fecha + '</div>';

  if (nActs > 0) {
    h += '<details style="margin-top:4px;"><summary style="cursor:pointer;font-size:0.75rem;color:#5C6BC0;">Ver actividades</summary>';
    h += '<div style="margin-top:4px;">';
    (plan.actividades || []).forEach((act, i) => {
      h += '<div style="font-size:0.75rem;padding:3px 0;border-bottom:1px solid #EEE;display:flex;gap:6px;align-items:flex-start;">'
        + '<span style="color:#78909C;min-width:20px;">' + (i + 1) + '.</span>'
        + '<div><span style="color:#212121;">' + escapeHTML(act.enunciado || 'Sin descripción') + '</span>';
      if (act.ecCodigo) h += ' <span style="color:#5C6BC0;font-size:0.7rem;">(' + act.ecCodigo + ')</span>';
      if (act.instrumento?.tipoLabel) h += ' <span style="color:#78909C;font-size:0.7rem;">— ' + act.instrumento.tipoLabel + '</span>';
      if (act.valor) h += ' <span style="color:#E65100;font-size:0.7rem;font-weight:600;">' + act.valor + ' pts</span>';
      h += '</div></div>';
    });
    h += '</div></details>';
  }

  h += '<div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap;">'
    + '<button onclick="_coordVerPlanCompleto(' + idx + ',\'' + item.id + '\')" style="background:#EDE7F6;color:#4527A0;border:1px solid #D1C4E9;border-radius:8px;padding:4px 10px;font-size:0.72rem;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;gap:4px;font-family:inherit;">'
    + '<span class="material-icons" style="font-size:14px;">visibility</span> Ver completa / Comentar</button>'
    + '<button onclick="_coordDescargarPlanWord(' + idx + ',\'' + item.id + '\')" style="background:#E3F2FD;color:#1565C0;border:1px solid #90CAF9;border-radius:8px;padding:4px 10px;font-size:0.72rem;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;gap:4px;font-family:inherit;">'
    + '<span class="material-icons" style="font-size:14px;">description</span> Descargar Word</button>'
    + '</div>';

  h += '</div>';
  return h;
}

/** Ver el contenido completo (no resumido) de una planificación de un docente, con opción de descargar Word y dejar comentarios */
function _coordVerPlanCompleto(idx, planId) {
  const d = window._coordPlanData?.[idx];
  const item = d?.planItems.find(p => p.id === planId);
  if (!item || !item.planificacion) { mostrarToast('No se pudo cargar esta planificación', 'error'); return; }

  const backupPlan = planificacion;
  let contenido = '';
  try {
    planificacion = JSON.parse(JSON.stringify(item.planificacion));
    renderizarVistaPrevia();
    contenido = document.getElementById('vista-previa')?.innerHTML || '<p>No se pudo generar la vista previa.</p>';
  } finally {
    planificacion = backupPlan;
  }

  const overlay = document.getElementById('modal-overlay');
  const title = document.getElementById('modal-title');
  const body = document.getElementById('modal-body');
  if (!overlay || !body) return;
  if (title) title.textContent = (d.nombre || d.email || 'Docente') + ' — Planificación completa';

  body.innerHTML = '<div style="max-height:45vh;overflow-y:auto;border:1px solid #E0E0E0;border-radius:10px;padding:12px;margin-bottom:16px;">'
    + contenido + '</div>'
    + '<div style="font-size:0.85rem;font-weight:700;color:#00695C;margin-bottom:8px;display:flex;align-items:center;gap:6px;">'
    + '<span class="material-icons" style="font-size:18px;">forum</span> Comentarios para ' + escapeHTML((d.nombre || d.email || 'el docente').split(' ')[0]) + '</div>'
    + '<div id="coord-comentarios-lista" style="display:flex;flex-direction:column;gap:8px;margin-bottom:10px;">'
    + '<div style="color:#9E9E9E;font-size:0.82rem;">Cargando comentarios...</div></div>'
    + '<div style="display:flex;gap:8px;align-items:flex-start;flex-wrap:wrap;">'
    + '<textarea id="coord-comentario-texto" rows="2" placeholder="Escribe una observación o retroalimentación sobre esta planificación..." style="flex:1;min-width:200px;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:8px;font-family:inherit;font-size:0.85rem;resize:vertical;box-sizing:border-box;"></textarea>'
    + '<button class="btn-export btn-sm" style="background:#00695C;color:#fff;white-space:nowrap;" onclick="_coordEnviarComentarioPlan(' + idx + ',\'' + planId + '\')">'
    + '<span class="material-icons">send</span> Enviar</button>'
    + '</div>';

  _usarFooterDinamico(
    '<button class="btn-export btn-sm" style="background:#1565C0;color:#fff;" onclick="_coordDescargarPlanWord(' + idx + ',\'' + planId + '\')">'
    + '<span class="material-icons">description</span> Descargar Word</button>'
    + '<button class="btn-secundario" onclick="cerrarModalBtn()">Cerrar</button>'
  );

  overlay.classList.remove('hidden');
  document.body.style.overflow = 'hidden';

  _coordCargarComentariosPlan(d.uid, planId);
}

/** Carga y pinta la lista de comentarios de una planificación dentro del modal de Coordinadora */
async function _coordCargarComentariosPlan(docenteUid, planId) {
  const cont = document.getElementById('coord-comentarios-lista');
  if (!cont) return;
  try {
    const snap = await db.collection('users').doc(docenteUid).collection('plan_comentarios')
      .where('planId', '==', planId).orderBy('fecha', 'desc').get();
    if (snap.empty) {
      cont.innerHTML = '<div style="color:#9E9E9E;font-size:0.82rem;">Sin comentarios todavía.</div>';
      return;
    }
    cont.innerHTML = snap.docs.map(doc => {
      const c = doc.data();
      const fecha = c.fecha ? new Date(c.fecha).toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
      const estadoLabel = c.leido ? '<span style="color:#2E7D32;">Leído</span>' : '<span style="color:#E65100;">Sin leer</span>';
      const puedeBorrar = window.currentUser && c.coordUid === window.currentUser.uid;
      return '<div style="background:#F5F5F5;border:1px solid #E0E0E0;border-radius:8px;padding:8px 10px;display:flex;gap:8px;align-items:flex-start;">'
        + '<div style="flex:1;min-width:0;">'
        + '<div style="font-size:0.72rem;color:#9E9E9E;margin-bottom:3px;">' + escapeHTML(c.coordNombre || 'Tú') + ' · ' + fecha + ' · ' + estadoLabel + '</div>'
        + '<div style="font-size:0.85rem;color:#212121;white-space:pre-wrap;">' + escapeHTML(c.texto || '') + '</div>'
        + '</div>'
        + (puedeBorrar
          ? '<button onclick="_coordEliminarComentarioPlan(\'' + docenteUid + '\',\'' + planId + '\',\'' + doc.id + '\')" title="Eliminar comentario" style="background:none;border:none;color:#BDBDBD;cursor:pointer;padding:2px;display:flex;flex-shrink:0;">'
            + '<span class="material-icons" style="font-size:17px;">delete_outline</span></button>'
          : '')
        + '</div>';
    }).join('');
  } catch (e) {
    cont.innerHTML = '<div style="color:#C62828;font-size:0.82rem;">Error cargando comentarios: ' + e.message + '</div>';
  }
}

/** Elimina un comentario propio dejado sobre la planificación de un docente */
async function _coordEliminarComentarioPlan(docenteUid, planId, comentarioId) {
  if (!confirm('¿Eliminar este comentario? Esta acción no se puede deshacer.')) return;
  try {
    await db.collection('users').doc(docenteUid).collection('plan_comentarios').doc(comentarioId).delete();
    mostrarToast('Comentario eliminado', 'success');
    _coordCargarComentariosPlan(docenteUid, planId);
  } catch (e) {
    mostrarToast('Error al eliminar comentario: ' + e.message, 'error');
  }
}

/** Envía un comentario de la Coordinadora sobre la planificación de un docente */
async function _coordEnviarComentarioPlan(idx, planId) {
  const d = window._coordPlanData?.[idx];
  const item = d?.planItems.find(p => p.id === planId);
  const textarea = document.getElementById('coord-comentario-texto');
  const texto = (textarea?.value || '').trim();
  if (!item) return;
  if (!texto) { mostrarToast('Escribe un comentario primero', 'warning'); return; }
  if (!window.currentUser) return;

  try {
    let coordNombre = window.currentUser.displayName || window.currentUser.email || 'Coordinador(a)';
    try {
      const miPerfil = await db.collection('usuarios').doc(window.currentUser.uid).get();
      if (miPerfil.exists && miPerfil.data().nombre) coordNombre = miPerfil.data().nombre;
    } catch {}

    await db.collection('users').doc(d.uid).collection('plan_comentarios').add({
      planId,
      planNombre: item.nombre || item.planificacion?.datosGenerales?.moduloFormativo || '',
      texto,
      coordUid: window.currentUser.uid,
      coordNombre,
      centroId: await _coordGetCentroId(),
      fecha: new Date().toISOString(),
      leido: false,
    });

    if (textarea) textarea.value = '';
    mostrarToast('Comentario enviado', 'success');
    _coordCargarComentariosPlan(d.uid, planId);
  } catch (e) {
    mostrarToast('Error al enviar comentario: ' + e.message, 'error');
  }
}

/** Descarga a Word una planificación de un docente vista desde el drill-down de Coordinadora */
async function _coordDescargarPlanWord(idx, planId) {
  const d = window._coordPlanData?.[idx];
  const item = d?.planItems.find(p => p.id === planId);
  if (!item || !item.planificacion) { mostrarToast('No se pudo cargar esta planificación', 'error'); return; }

  const backupPlan = planificacion;
  try {
    planificacion = JSON.parse(JSON.stringify(item.planificacion));
    mostrarToast('Exportando a Word...', 'info');
    const usoPlantilla = await _exportarConPlantillaCentro();
    if (!usoPlantilla) { _avisarExportSinPlantilla(); _exportarWordHTML(); }
  } catch (e) {
    console.warn('[CoordExport] Error:', e);
    mostrarToast('Error al exportar: ' + e.message, 'error');
  } finally {
    planificacion = backupPlan;
  }
}

// ── 3. RESUMEN POR DOCENTE ──────────────────────────────────────

async function _coordResumenDocentes(contId) {
  contId = contId || 'coord-contenido';
  window._coordActiveContId = contId;
  const cont = document.getElementById(contId);
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando resumen...</div>';

  const centroId = await _coordGetCentroId();
  if (!centroId) { _coordMostrarSelectorCentro(cont, '_coordResumenDocentes', contId); return; }

  try {
    const docentes = await _coordGetDocentes(centroId);
    if (!docentes.length) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay docentes en este centro.</div>'; return; }

    const docentesData = await Promise.all(docentes.map(async d => {
      try {
        // Calificaciones
        const calDoc = await db.collection('users').doc(d.uid).collection('data').doc('calificaciones').get();
        const calRaw3 = calDoc.exists ? calDoc.data() : {};
        const calData = calRaw3.payload ? JSON.parse(calRaw3.payload) : calRaw3;
        const cursos = calData.cursos || {};
        let totalEst = 0, totalActs = 0, actsSinNota = 0, cursosArr = [];
        Object.entries(cursos).forEach(([cId, curso]) => {
          const ests = curso.estudiantes || [];
          totalEst += ests.length;
          let cursoActs = 0, cursoSinNota = 0;
          Object.values(curso.ras || {}).forEach(ra => {
            const acts = ra.actividades || [];
            cursoActs += acts.length;
            totalActs += acts.length;
            acts.forEach(actId => {
              const tiene = ests.some(est => {
                const n = curso.notas?.[est.id]?.[ra.raKey]?.[actId];
                return n !== undefined && n !== null;
              });
              if (!tiene && ests.length > 0) { actsSinNota++; cursoSinNota++; }
            });
          });
          cursosArr.push({ nombre: curso.nombre || cId, estudiantes: ests.length, actividades: cursoActs, sinNota: cursoSinNota });
        });

        // Planificaciones (activas del ciclo actual vs. total histórico en biblioteca)
        const biblio3 = await _coordLeerBibliotecaDocente(d.uid);
        const itemsBiblio3 = biblio3.items || [];
        const cicloActual3 = _getSchoolYearKey(new Date());
        const nPlan = itemsBiblio3.filter(it => _coordCicloDePlan(it) === cicloActual3).length;
        const nPlanTotal = itemsBiblio3.length;

        // Última sesión
        let ultimaSesion = null;
        try {
          const sesSnap = await db.collection('users').doc(d.uid).collection('sessions').orderBy('timestamp', 'desc').limit(1).get();
          if (!sesSnap.empty) ultimaSesion = sesSnap.docs[0].data();
        } catch {}

        return { ...d, totalEst, totalActs, actsSinNota, cursosArr, nPlan, nPlanTotal, ultimaSesion };
      } catch { return { ...d, totalEst: 0, totalActs: 0, actsSinNota: 0, cursosArr: [], nPlan: 0, nPlanTotal: 0, ultimaSesion: null }; }
    }));

    window._coordResumenDocentesData = docentesData;

    let html = '<h4 style="color:#00695C;margin:0 0 14px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">person</span> Ficha de cada Docente</h4>';
    html += '<div style="display:flex;flex-direction:column;gap:14px;">';

    docentesData.forEach((d, idxDoc) => {
      const pct = d.totalActs > 0 ? Math.round(((d.totalActs - d.actsSinNota) / d.totalActs) * 100) : 0;
      const barColor = pct >= 70 ? '#2E7D32' : pct >= 50 ? '#FF9800' : '#C62828';

      let sesInfo = 'Sin actividad';
      if (d.ultimaSesion) {
        const ts = d.ultimaSesion.timestamp?.toDate ? d.ultimaSesion.timestamp.toDate() : new Date(d.ultimaSesion.timestamp);
        const diff = (Date.now() - ts) / (1000 * 60 * 60);
        if (diff < 1) sesInfo = 'Activo hace menos de 1h';
        else if (diff < 24) sesInfo = 'Hoy ' + ts.toLocaleTimeString('es-DO', { hour: '2-digit', minute: '2-digit' });
        else sesInfo = ts.toLocaleDateString('es-DO', { day: '2-digit', month: 'short' });
      }

      const rolBadge = d.rol === 'director' ? ' <span style="background:#4A148C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.65rem;font-weight:600;">Director</span>'
        : d.rol === 'coordinadora' ? ' <span style="background:#00695C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.65rem;font-weight:600;">Coordinadora</span>' : '';

      html += '<div style="background:#fff;border:1.5px solid #E0E0E0;border-radius:14px;padding:16px;box-shadow:0 2px 8px rgba(0,0,0,0.04);">'
        + '<div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;">'
        + '<div style="width:48px;height:48px;border-radius:50%;background:#E3F2FD;display:flex;align-items:center;justify-content:center;font-weight:700;color:#1565C0;font-size:1.2rem;">' + (d.nombre || 'U')[0].toUpperCase() + '</div>'
        + '<div style="flex:1;">'
        + '<div style="font-weight:700;font-size:1rem;color:#212121;">' + escapeHTML(d.nombre || 'Sin nombre') + rolBadge + '</div>'
        + '<div style="font-size:0.8rem;color:#78909C;">' + escapeHTML(d.email || '') + ' · Último acceso: ' + sesInfo + '</div>'
        + '</div></div>';

      // KPIs
      html += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;">'
        + '<div style="flex:1;min-width:80px;background:#F5F5F5;border-radius:8px;padding:8px;text-align:center;">'
        + '<div style="font-weight:700;color:#1565C0;">' + d.cursosArr.length + '</div><div style="font-size:0.7rem;color:#78909C;">Cursos</div></div>'
        + '<div style="flex:1;min-width:80px;background:#F5F5F5;border-radius:8px;padding:8px;text-align:center;">'
        + '<div style="font-weight:700;color:#1565C0;">' + d.totalEst + '</div><div style="font-size:0.7rem;color:#78909C;">Estudiantes</div></div>'
        + '<div style="flex:1;min-width:80px;background:#F5F5F5;border-radius:8px;padding:8px;text-align:center;" title="Planificaciones del ciclo escolar actual · ' + d.nPlanTotal + ' en total en su biblioteca (incluye ciclos anteriores)">'
        + '<div style="font-weight:700;color:#1565C0;">' + d.nPlan + '</div><div style="font-size:0.7rem;color:#78909C;">Planificaciones (ciclo actual)</div>'
        + (d.nPlanTotal > d.nPlan ? '<div style="font-size:0.62rem;color:#B0BEC5;">' + d.nPlanTotal + ' en biblioteca total</div>' : '')
        + '</div>'
        + '<div style="flex:1;min-width:80px;background:#F5F5F5;border-radius:8px;padding:8px;text-align:center;">'
        + '<div style="font-weight:700;color:' + barColor + ';">' + pct + '%</div><div style="font-size:0.7rem;color:#78909C;">Calificado</div></div>'
        + '</div>';

      // Barra de progreso
      html += '<div style="background:#E0E0E0;border-radius:6px;height:8px;overflow:hidden;margin-bottom:10px;">'
        + '<div style="width:' + pct + '%;height:100%;background:' + barColor + ';border-radius:6px;transition:width 0.5s;"></div></div>';

      // Cursos detalle
      if (d.cursosArr.length) {
        html += '<div style="font-size:0.78rem;color:#546E7A;font-weight:600;margin-bottom:6px;">Cursos:</div>';
        html += '<div style="display:flex;flex-wrap:wrap;gap:6px;">';
        d.cursosArr.forEach(c => {
          const cColor = c.sinNota === 0 ? '#2E7D32' : c.sinNota <= 2 ? '#E65100' : '#C62828';
          html += '<span style="display:inline-flex;align-items:center;gap:4px;padding:4px 10px;background:' + cColor + '11;border:1px solid ' + cColor + '33;border-radius:8px;font-size:0.75rem;color:' + cColor + ';">'
            + '<span class="material-icons" style="font-size:13px;">class</span>' + escapeHTML(c.nombre) + ' (' + c.estudiantes + ' est, ' + c.actividades + ' act'
            + (c.sinNota > 0 ? ', <strong>' + c.sinNota + ' sin nota</strong>' : '') + ')</span>';
        });
        html += '</div>';
      }

      html += '<div style="margin-top:10px;">'
        + '<button class="btn-secundario" onclick="_coordVerPortafolioDocente(' + idxDoc + ')" style="font-size:0.78rem;padding:6px 12px;">'
        + '<span class="material-icons" style="font-size:15px;">badge</span> Ver Portafolio</button>'
        + '</div>';

      html += '</div>';
    });
    html += '</div>';
    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

/** Abre la vista de solo lectura del Portafolio de un docente desde su índice
 *  en window._coordResumenDocentesData (evita meter nombres con comillas en el onclick). */
async function _coordVerPortafolioDocente(idx) {
  const d = window._coordResumenDocentesData?.[idx];
  if (!d) return;
  await _coordRenderPortafolioDocente(d.uid, d.nombre || d.email || 'Docente');
}

/** Vista de solo lectura del Portafolio de OTRO docente, para Coordinadora/Director/
 *  admin_centro. Nunca lee portafolio_evidencias_privadas (esa colección ni siquiera
 *  la permiten las reglas de Firestore para otro rol que no sea el propio dueño). */
async function _coordRenderPortafolioDocente(uid, nombre) {
  const contId = window._coordActiveContId || 'coord-contenido';
  const cont = document.getElementById(contId);
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando portafolio...</div>';

  try {
    const [base, foto, cv, evidencias] = await Promise.all([
      _coordLeerPortafolioBase(uid),
      _coordLeerPortafolioFoto(uid),
      _coordLeerPortafolioCV(uid),
      _coordLeerEvidenciasPortafolio(uid)
    ]);
    const docente = base.docente || {};
    // Índice global para poder descargar un Comentario como Word simple desde su tarjeta
    // sin tener que meter título/descripción (texto libre) dentro del onclick.
    evidencias.forEach((it, i) => { it._idx = i; });
    window._coordPortafolioEvidenciasActuales = evidencias;
    window._coordPortafolioEvidenciasUid = uid;
    const grupos = _agruparEvidenciasPorCategoria(evidencias);

    let html = '<button class="btn-secundario" onclick="_coordResumenDocentes(\'' + contId + '\')" style="margin-bottom:14px;">'
      + '<span class="material-icons">arrow_back</span> Volver a Resumen Docentes</button>';
    html += '<h4 style="color:#00695C;margin:0 0 14px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">badge</span> Portafolio — ' + escapeHTML(nombre) + '</h4>';

    html += '<div style="background:#fff;border:1px solid #E0E0E0;border-radius:12px;padding:16px;margin-bottom:14px;">'
      + '<div style="display:flex;align-items:center;gap:14px;margin-bottom:14px;">'
      + '<div style="width:64px;height:64px;border-radius:50%;overflow:hidden;background:#ECEFF1;display:flex;align-items:center;justify-content:center;flex-shrink:0;">'
      + (foto.fotoBase64 ? '<img src="data:' + escapeHTML(foto.fotoMime) + ';base64,' + foto.fotoBase64 + '" style="width:100%;height:100%;object-fit:cover;">' : '<span class="material-icons" style="font-size:32px;color:#B0BEC5;">person</span>')
      + '</div>'
      + '<div>'
      + '<div style="font-weight:800;font-size:1rem;color:#212121;">' + escapeHTML(docente.nombre || nombre) + '</div>'
      + (docente.titulo ? '<div style="font-size:0.85rem;color:#546E7A;">' + escapeHTML(docente.titulo) + '</div>' : '')
      + (docente.cargo ? '<div style="font-size:0.82rem;color:#78909C;">' + escapeHTML(docente.cargo) + '</div>' : '')
      + '</div></div>'
      + (docente.perfilProfesional ? '<div style="margin-bottom:10px;"><div style="font-size:0.78rem;font-weight:700;color:#546E7A;margin-bottom:2px;">Perfil profesional</div><div style="font-size:0.85rem;color:#455A64;white-space:pre-wrap;line-height:1.5;">' + escapeHTML(docente.perfilProfesional) + '</div></div>' : '')
      + (docente.filosofiaEnsenanza ? '<div><div style="font-size:0.78rem;font-weight:700;color:#546E7A;margin-bottom:2px;">Filosofía de enseñanza</div><div style="font-size:0.85rem;color:#455A64;white-space:pre-wrap;line-height:1.5;">' + escapeHTML(docente.filosofiaEnsenanza) + '</div></div>' : '')
      + '</div>';

    html += '<div style="background:#fff;border:1px solid #E0E0E0;border-radius:12px;padding:16px;margin-bottom:14px;">'
      + '<div style="font-weight:800;color:#37474F;margin-bottom:10px;display:flex;align-items:center;gap:8px;"><span class="material-icons" style="font-size:18px;color:#455A64;">description</span> Currículum</div>'
      + (cv.cvNombre
          ? '<div style="font-size:0.85rem;color:#455A64;margin-bottom:10px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:16px;">attach_file</span>' + escapeHTML(cv.cvNombre) + '</div>'
            + '<button class="btn-secundario" onclick="_coordDescargarCVDocente(\'' + uid + '\')" style="font-size:0.8rem;padding:7px 12px;"><span class="material-icons">download</span> Descargar</button>'
          : '<div style="font-size:0.82rem;color:#9E9E9E;">Este docente no ha subido su currículum.</div>')
      + '</div>';

    html += '<div style="background:#fff;border:1px solid #E0E0E0;border-radius:12px;padding:16px;">'
      + '<div style="font-weight:800;color:#37474F;margin-bottom:12px;display:flex;align-items:center;gap:8px;"><span class="material-icons" style="font-size:18px;color:#455A64;">folder_special</span> Evidencias del portafolio</div>';
    Object.entries(PORTAFOLIO_CATEGORIAS).forEach(([cat, label]) => {
      const itemsCat = grupos[cat] || [];
      html += '<div style="font-size:0.8rem;font-weight:700;color:#546E7A;margin:12px 0 6px;">' + escapeHTML(label) + ' (' + itemsCat.length + ')</div>';
      html += itemsCat.length
        ? itemsCat.map(it => _coordTarjetaEvidenciaDocente(it, uid)).join('')
        : '<div style="font-size:0.78rem;color:#B0BEC5;padding:6px 0;">Sin evidencias en esta categoría.</div>';
    });
    html += '</div>';

    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

function _coordTarjetaEvidenciaDocente(item, uid) {
  const fecha = item.fecha ? new Date(item.fecha + 'T12:00:00').toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
  const archivoHtml = item.archivoNombre
    ? '<div style="font-size:0.78rem;color:#607D8B;margin-top:6px;display:flex;align-items:center;gap:4px;"><span class="material-icons" style="font-size:15px;">attach_file</span>' + escapeHTML(item.archivoNombre) + '</div>'
    : '';

  // Orden de prioridad para el botón de descarga:
  // 1) La evidencia ya trae un archivo adjunto (ej. un Reporte cuya plantilla sí generó Word al crearla).
  // 2) Viene de un Reporte de Calificaciones y tenemos con qué regenerar el Word con la plantilla del centro.
  // 3) Viene de un Reporte SIN esa referencia (evidencia vieja, de antes de este ajuste): se intenta
  //    ubicar el reporte original por nombre de estudiante para igual regenerar el Word con plantilla,
  //    y solo si no se encuentra cae al Word simple.
  // 4) Comentario: Word simple en Arial 12, sin plantilla, armado con lo que ya trae la evidencia.
  const esReporte = item.origen === 'Calificaciones — Reportes';
  const esComentario = item.origen === 'Calificaciones — Comentarios';
  let descargarBtn = '';
  if (item.archivoNombre) {
    descargarBtn = '<button class="btn-secundario" onclick="_coordDescargarEvidenciaDocente(\'' + uid + '\',\'' + item.id + '\')" style="padding:6px 10px;font-size:0.75rem;"><span class="material-icons" style="font-size:14px;">download</span> Descargar</button>';
  } else if (esReporte && item.refEstId && item.refId) {
    descargarBtn = '<button class="btn-secundario" onclick="_coordDescargarReporteDocente(\'' + uid + '\',\'' + item.refEstId + '\',\'' + item.refId + '\')" style="padding:6px 10px;font-size:0.75rem;color:#6A1B9A;"><span class="material-icons" style="font-size:14px;">description</span> Descargar Word</button>';
  } else if (esReporte && typeof item._idx === 'number') {
    descargarBtn = '<button class="btn-secundario" onclick="_coordDescargarReporteHeuristico(' + item._idx + ')" style="padding:6px 10px;font-size:0.75rem;color:#6A1B9A;"><span class="material-icons" style="font-size:14px;">description</span> Descargar Word</button>';
  } else if (esComentario && typeof item._idx === 'number') {
    descargarBtn = '<button class="btn-secundario" onclick="_coordDescargarComentarioPorIndice(' + item._idx + ')" style="padding:6px 10px;font-size:0.75rem;"><span class="material-icons" style="font-size:14px;">description</span> Descargar Word</button>';
  }

  return '<div style="background:#FAFAFA;border:1px solid #E0E0E0;border-radius:12px;padding:14px 16px;margin-bottom:10px;">'
    + '<div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start;flex-wrap:wrap;">'
    + '<div style="flex:1;min-width:0;">'
    + (item.origen ? '<span style="font-size:0.7rem;color:#546E7A;background:#ECEFF1;border-radius:20px;padding:2px 8px;">' + escapeHTML(item.origen) + '</span>' : '')
    + '<div style="font-weight:700;color:#37474F;margin:5px 0;">' + escapeHTML(item.titulo || 'Sin título') + '</div>'
    + '<div style="font-size:0.85rem;color:#455A64;line-height:1.55;white-space:pre-wrap;">' + escapeHTML(item.descripcion || '') + '</div>'
    + archivoHtml
    + '</div>'
    + '<div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px;flex-shrink:0;">'
    + '<div style="font-size:0.72rem;color:#90A4AE;">' + fecha + '</div>'
    + descargarBtn
    + '</div></div></div>';
}

// ── 4. AVISOS COORDINADORA ──────────────────────────────────────

async function _coordAvisos(contId) {
  contId = contId || 'coord-contenido';
  window._coordActiveContId = contId;
  const cont = document.getElementById(contId);
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando avisos...</div>';

  const centroId = await _coordGetCentroId();
  if (!centroId) { _coordMostrarSelectorCentro(cont, '_coordAvisos', contId); return; }

  let avisos = [];
  try {
    const snap = await db.collection('centros').doc(centroId).collection('avisos').orderBy('fecha', 'desc').get();
    avisos = snap.docs.map(d => ({ id: d.id, ...d.data() }));
  } catch (e) { console.warn('Error cargando avisos coordinadora:', e); }

  let html = '';
  // Formulario
  html += '<div style="background:#E0F2F1;border:1.5px solid #80CBC4;border-radius:12px;padding:16px;margin-bottom:20px;">'
    + '<h4 style="margin:0 0 10px;color:#00695C;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">campaign</span> Enviar aviso a docentes</h4>'
    + '<input type="text" id="coord-aviso-titulo" placeholder="Título del aviso" style="width:100%;padding:10px 12px;border:1.5px solid #80CBC4;border-radius:8px;font-size:0.9rem;margin-bottom:8px;box-sizing:border-box;">'
    + '<textarea id="coord-aviso-mensaje" placeholder="Escribe el mensaje..." rows="3" style="width:100%;padding:10px 12px;border:1.5px solid #80CBC4;border-radius:8px;font-size:0.9rem;resize:vertical;box-sizing:border-box;"></textarea>'
    + '<div style="display:flex;gap:8px;margin-top:10px;align-items:center;">'
    + '<select id="coord-aviso-prioridad" style="padding:8px 12px;border:1.5px solid #80CBC4;border-radius:8px;font-size:0.85rem;background:#fff;">'
    + '<option value="normal">Normal</option><option value="importante">Importante</option><option value="urgente">Urgente</option>'
    + '</select>'
    + '<button onclick="_coordEnviarAviso(\'' + centroId + '\')" style="display:inline-flex;align-items:center;gap:6px;padding:10px 20px;background:#00695C;color:#fff;border:none;border-radius:8px;font-weight:600;cursor:pointer;font-size:0.9rem;margin-left:auto;">'
    + '<span class="material-icons" style="font-size:18px;">send</span> Enviar</button>'
    + '</div></div>';

  // Lista
  if (avisos.length === 0) {
    html += '<div style="text-align:center;padding:30px;color:#999;"><span class="material-icons" style="font-size:48px;display:block;margin-bottom:8px;">notifications_none</span>No hay avisos</div>';
  } else {
    html += '<div style="display:flex;flex-direction:column;gap:10px;">';
    avisos.forEach(a => {
      const prioMap = { urgente: { color: '#C62828', bg: '#FFEBEE', icon: 'priority_high' }, importante: { color: '#E65100', bg: '#FFF3E0', icon: 'warning' }, normal: { color: '#00695C', bg: '#E0F2F1', icon: 'info' } };
      const prio = prioMap[a.prioridad] || prioMap.normal;
      const fechaDate = _avisoFechaToDate(a.fecha);
      const fecha = fechaDate ? fechaDate.toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
      const nombreAutor = a.autorNombre || a.enviadoPor || a.autor || '';
      const rolLabel = _avisoRolLabel(a.rolAutor);
      html += '<div style="background:' + prio.bg + ';border:1.5px solid ' + prio.color + '33;border-radius:12px;padding:14px;">'
        + '<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;">'
        + '<span class="material-icons" style="color:' + prio.color + ';font-size:18px;">' + prio.icon + '</span>'
        + '<strong style="color:' + prio.color + ';font-size:0.95rem;">' + escapeHTML(a.titulo || 'Sin título') + '</strong>'
        + '<span style="margin-left:auto;font-size:0.72rem;color:#999;">' + fecha + '</span>'
        + '<button onclick="_coordEliminarAviso(\'' + centroId + '\',\'' + a.id + '\')" style="background:none;border:none;cursor:pointer;color:#C62828;padding:2px;"><span class="material-icons" style="font-size:16px;">delete</span></button>'
        + '</div>'
        + '<div style="font-size:0.88rem;color:#333;line-height:1.5;">' + escapeHTML(a.mensaje || '').replace(/\n/g, '<br>') + '</div>'
        + '<div style="font-size:0.72rem;color:#999;margin-top:6px;">Enviado por: ' + escapeHTML(nombreAutor) + (rolLabel ? ' <span style="color:' + prio.color + ';font-weight:600;">· ' + rolLabel + '</span>' : '') + '</div>'
        + '</div>';
    });
    html += '</div>';
  }
  cont.innerHTML = html;
}

/** Convierte el campo 'fecha' de un aviso a Date, sea Firestore Timestamp (avisos nuevos)
 *  o string ISO (avisos viejos de Director, antes de unificar el esquema). */
function _avisoFechaToDate(fecha) {
  if (!fecha) return null;
  if (fecha.toDate) return fecha.toDate();
  if (typeof fecha === 'string') { const d = new Date(fecha); return isNaN(d.getTime()) ? null : d; }
  return null;
}

function _avisoRolLabel(rol) {
  return { director: 'Director', coordinadora: 'Coordinadora', admin_centro: 'Administración' }[rol] || '';
}

async function _coordEnviarAviso(centroId) {
  const titulo = document.getElementById('coord-aviso-titulo')?.value.trim();
  const mensaje = document.getElementById('coord-aviso-mensaje')?.value.trim();
  const prioridad = document.getElementById('coord-aviso-prioridad')?.value || 'normal';
  if (!titulo) { mostrarToast('Escribe un título', 'error'); return; }
  if (!mensaje) { mostrarToast('Escribe el mensaje', 'error'); return; }
  let rolAutor = 'coordinadora';
  try {
    const perfilDoc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    if (perfilDoc.exists && perfilDoc.data().rol) rolAutor = perfilDoc.data().rol;
  } catch {}
  try {
    await db.collection('centros').doc(centroId).collection('avisos').add({
      titulo, mensaje, prioridad, rolAutor,
      autor: window.currentUser?.email || '',
      autorNombre: window.currentUser?.displayName || '',
      fecha: firebase.firestore.FieldValue.serverTimestamp()
    });
    mostrarToast('Aviso enviado correctamente', 'success');
    _coordAvisos(window._coordActiveContId);
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

async function _coordEliminarAviso(centroId, avisoId) {
  if (!confirm('¿Eliminar este aviso?')) return;
  try {
    await db.collection('centros').doc(centroId).collection('avisos').doc(avisoId).delete();
    mostrarToast('Aviso eliminado', 'success');
    _coordAvisos(window._coordActiveContId);
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

// ── 5. MONITOR DE RENDIMIENTO / ALERTAS DE RIESGO ───────────────
// Reutiliza los mismos umbrales que el panel de Rendimiento del docente
// (_rendColorPct: ≥70% aprobado, 60-69% regular/riesgo, <60% reprobado)
// y las mismas funciones de cálculo de nota (_calcNotaFinal, _rendMaxTotal),
// aplicadas sobre los datos de calificaciones que Coordinadora ya descarga
// por docente. No requiere lecturas adicionales a Firestore.

async function _coordMonitorRendimiento(contId) {
  contId = contId || 'coord-contenido';
  window._coordActiveContId = contId;
  const cont = document.getElementById(contId);
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Analizando rendimiento...</div>';

  const centroId = await _coordGetCentroId();
  if (!centroId) { _coordMostrarSelectorCentro(cont, '_coordMonitorRendimiento', contId); return; }

  try {
    const docentes = await _coordGetDocentes(centroId);
    if (!docentes.length) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay docentes en este centro.</div>'; return; }

    const listas = await Promise.all(docentes.map(async d => {
      try {
        const calDoc = await db.collection('users').doc(d.uid).collection('data').doc('calificaciones').get();
        const calRaw = calDoc.exists ? calDoc.data() : {};
        const calData = calRaw.payload ? JSON.parse(calRaw.payload) : calRaw;
        const cursos = calData.cursos || {};
        const filas = [];
        Object.entries(cursos).forEach(([cId, curso]) => {
          const ests = curso.estudiantes || [];
          if (!ests.length) return;
          const maxTotal = _rendMaxTotal(curso);
          ests.forEach(est => {
            const nota = maxTotal > 0 ? _calcNotaFinal(curso, est.id) : null;
            const pct = (maxTotal > 0 && nota !== null) ? nota / maxTotal : null;
            filas.push({
              estNombre: est.nombre || 'Sin nombre', cursoNombre: curso.nombre || '',
              docente: d.nombre || d.email || 'Sin nombre', nota, maxTotal, pct,
              docenteUid: d.uid, cursoId: cId, estId: est.id
            });
          });
        });
        return filas;
      } catch (e) { console.warn('Error rendimiento coord:', e); return []; }
    }));

    window._coordRendData = listas.flat();
    window._coordRendData.forEach((f, i) => { f._idx = i; });
    window._coordRendCentroId = centroId;

    // Cargar casos de seguimiento ya abiertos para este centro
    window._coordAlertasMap = {};
    try {
      const alertasSnap = await db.collection('centros').doc(centroId).collection('alertas_rendimiento').get();
      alertasSnap.docs.forEach(docSnap => {
        const a = docSnap.data();
        const key = a.docenteUid + '|' + a.cursoId + '|' + a.estId;
        window._coordAlertasMap[key] = { id: docSnap.id, ...a };
      });
    } catch (e) { console.warn('Error cargando alertas de seguimiento:', e); }

    const evaluadas  = window._coordRendData.filter(f => f.pct !== null);
    const sinEvaluar = window._coordRendData.filter(f => f.pct === null);
    const aprobados  = evaluadas.filter(f => f.pct >= 0.7);
    const regulares  = evaluadas.filter(f => f.pct >= 0.6 && f.pct < 0.7);
    const reprobados = evaluadas.filter(f => f.pct < 0.6);

    let html = '<h4 style="color:#00695C;margin:0 0 14px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">insights</span> Alertas de Rendimiento por Estudiante</h4>';

    html += '<div style="display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap;">'
      + _coordKpiCard(aprobados.length, 'Aprobados ≥70%', '#2E7D32', '#E8F5E9', '#A5D6A7')
      + _coordKpiCard(regulares.length, 'Regular 60–69%', '#F57F17', '#FFF8E1', '#FFE082')
      + _coordKpiCard(reprobados.length, 'Reprobados <60%', '#C62828', '#FFEBEE', '#EF9A9A')
      + _coordKpiCard(sinEvaluar.length, 'Sin evaluar aún', '#9E9E9E', '#F5F5F5', '#E0E0E0')
      + '</div>';

    html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;flex-wrap:wrap;">'
      + '<span class="material-icons" style="color:#78909C;font-size:18px;">search</span>'
      + '<input id="coord-rend-buscar" type="text" placeholder="Buscar estudiante, curso o docente..." oninput="_coordFiltrarRendimiento()" '
      + 'style="flex:1;min-width:180px;padding:8px 12px;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.85rem;">'
      + '<select id="coord-rend-filtro" onchange="_coordFiltrarRendimiento()" style="padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.85rem;color:#37474F;">'
      + '<option value="riesgo">En riesgo (Regular + Reprobado)</option>'
      + '<option value="todos">Todos los estudiantes</option>'
      + '<option value="aprobados">Solo aprobados</option>'
      + '<option value="regular">Solo regular</option>'
      + '<option value="reprobados">Solo reprobados</option>'
      + '<option value="sinEvaluar">Solo sin evaluar</option>'
      + '</select>'
      + '</div>'
      + '<div id="coord-rend-tabla"></div>';

    cont.innerHTML = html;
    _coordFiltrarRendimiento();
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

function _coordKpiCard(num, label, fg, bg, border) {
  return '<div style="flex:1;min-width:120px;background:' + bg + ';border:1.5px solid ' + border + ';border-radius:10px;padding:12px;text-align:center;">'
    + '<div style="font-size:1.4rem;font-weight:700;color:' + fg + ';">' + num + '</div><div style="font-size:0.78rem;color:' + fg + ';">' + label + '</div></div>';
}

/** Devuelve { fg, label } incluso para estudiantes sin notas aún (pct === null) */
function _coordEstadoRend(pct) {
  if (pct === null) return { fg: '#9E9E9E', label: 'Sin evaluar' };
  return _rendColorPct(pct);
}

/** Re-filtra y redibuja solo la tabla de estudiantes (deja el buscador y el selector intactos) */
function _coordFiltrarRendimiento() {
  const tabla = document.getElementById('coord-rend-tabla');
  if (!tabla) return;
  const todas = window._coordRendData || [];
  const filtro = document.getElementById('coord-rend-filtro')?.value || 'riesgo';

  let base;
  if (filtro === 'todos') base = todas;
  else if (filtro === 'aprobados') base = todas.filter(f => f.pct !== null && f.pct >= 0.7);
  else if (filtro === 'regular') base = todas.filter(f => f.pct !== null && f.pct >= 0.6 && f.pct < 0.7);
  else if (filtro === 'reprobados') base = todas.filter(f => f.pct !== null && f.pct < 0.6);
  else if (filtro === 'sinEvaluar') base = todas.filter(f => f.pct === null);
  else base = todas.filter(f => f.pct !== null && f.pct < 0.7); // riesgo (default)

  base = base.slice().sort((a, b) => {
    if (a.pct === null) return 1;
    if (b.pct === null) return -1;
    return a.pct - b.pct;
  });

  const q = (document.getElementById('coord-rend-buscar')?.value || '').toLowerCase().trim();
  const filtradas = q
    ? base.filter(f => f.estNombre.toLowerCase().includes(q) || f.cursoNombre.toLowerCase().includes(q) || f.docente.toLowerCase().includes(q))
    : base;

  if (!todas.length) {
    tabla.innerHTML = '<div style="text-align:center;padding:20px;color:#9E9E9E;">No hay estudiantes registrados en este centro.</div>';
    return;
  }
  if (!base.length) {
    const msg = filtro === 'riesgo' ? 'Ningún estudiante en riesgo por el momento.' : 'No hay estudiantes en esta categoría.';
    tabla.innerHTML = '<div style="text-align:center;padding:24px;color:#2E7D32;background:#E8F5E9;border-radius:10px;"><span class="material-icons" style="font-size:32px;display:block;margin-bottom:6px;">check_circle</span>' + msg + '</div>';
    return;
  }
  if (!filtradas.length) {
    tabla.innerHTML = '<div style="text-align:center;padding:20px;color:#9E9E9E;">Sin resultados para "' + escapeHTML(q) + '".</div>';
    return;
  }

  let html = '<div style="font-size:0.75rem;color:#78909C;margin-bottom:6px;">Mostrando ' + filtradas.length + ' de ' + todas.length + ' registros (estudiante × curso)</div>';
  html += '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:0.82rem;min-width:660px;">'
    + '<thead><tr style="background:#F5F5F5;">'
    + '<th style="text-align:left;padding:6px 10px;border:1px solid #E0E0E0;">Estudiante</th>'
    + '<th style="text-align:left;padding:6px 10px;border:1px solid #E0E0E0;">Curso</th>'
    + '<th style="text-align:left;padding:6px 10px;border:1px solid #E0E0E0;">Docente</th>'
    + '<th style="padding:6px 10px;border:1px solid #E0E0E0;width:90px;">Nota</th>'
    + '<th style="padding:6px 10px;border:1px solid #E0E0E0;width:120px;">Estado</th>'
    + '<th style="padding:6px 10px;border:1px solid #E0E0E0;width:150px;">Seguimiento</th>'
    + '</tr></thead><tbody>';

  filtradas.forEach(f => {
    const col = _coordEstadoRend(f.pct);
    const notaTxt = f.pct === null ? '—' : f.nota.toFixed(1) + '/' + f.maxTotal;
    const estadoTxt = f.pct === null ? col.label : (f.pct * 100).toFixed(0) + '% · ' + col.label;
    const key = f.docenteUid + '|' + f.cursoId + '|' + f.estId;
    const alerta = window._coordAlertasMap?.[key];
    const segCol = alerta ? _coordEstadoSeguimiento(alerta.estado) : null;

    html += '<tr>'
      + '<td style="padding:6px 10px;border:1px solid #E0E0E0;font-weight:600;">' + escapeHTML(f.estNombre) + '</td>'
      + '<td style="padding:6px 10px;border:1px solid #E0E0E0;">' + escapeHTML(f.cursoNombre) + '</td>'
      + '<td style="padding:6px 10px;border:1px solid #E0E0E0;color:#546E7A;">' + escapeHTML(f.docente) + '</td>'
      + '<td style="padding:6px 10px;border:1px solid #E0E0E0;text-align:center;color:' + col.fg + ';font-weight:700;">' + notaTxt + '</td>'
      + '<td style="padding:6px 10px;border:1px solid #E0E0E0;text-align:center;">'
      + '<span style="background:' + col.fg + '22;color:' + col.fg + ';padding:3px 10px;border-radius:12px;font-weight:700;font-size:0.75rem;">' + estadoTxt + '</span>'
      + '</td>'
      + '<td style="padding:6px 10px;border:1px solid #E0E0E0;text-align:center;">'
      + (alerta
          ? '<span onclick="_coordToggleSeguimientoDetalle(' + f._idx + ')" style="cursor:pointer;background:' + segCol.fg + '22;color:' + segCol.fg + ';padding:3px 10px;border-radius:12px;font-weight:700;font-size:0.72rem;">' + segCol.label + (alerta.derivadoAPsicologia ? ' · Derivado' : '') + '</span>'
          : '<button onclick="_coordAbrirSeguimiento(' + f._idx + ')" style="background:#00695C;color:#fff;border:none;border-radius:14px;padding:4px 10px;font-size:0.72rem;font-weight:600;cursor:pointer;">+ Abrir caso</button>')
      + '</td></tr>';

    html += '<tr id="coord-rend-seg-' + f._idx + '" style="display:none;background:#FAFAFA;">'
      + '<td colspan="6" style="padding:10px 14px;border:1px solid #E0E0E0;">' + _coordSeguimientoForm(f._idx) + '</td></tr>';
  });
  html += '</tbody></table></div>';
  tabla.innerHTML = html;
}

function _coordEstadoSeguimiento(estado) {
  if (estado === 'atendida') return { fg: '#2E7D32', label: 'Atendida' };
  if (estado === 'en_seguimiento') return { fg: '#1565C0', label: 'En seguimiento' };
  return { fg: '#E65100', label: 'Nueva' };
}

/** Genera el formulario inline de gestión de un caso de seguimiento ya abierto */
function _coordSeguimientoForm(idx) {
  const f = window._coordRendData?.[idx];
  if (!f) return '';
  const key = f.docenteUid + '|' + f.cursoId + '|' + f.estId;
  const alerta = window._coordAlertasMap?.[key];
  if (!alerta) return '';
  const opciones = ['nueva', 'en_seguimiento', 'atendida'].map(v =>
    '<option value="' + v + '"' + (alerta.estado === v ? ' selected' : '') + '>' + _coordEstadoSeguimiento(v).label + '</option>'
  ).join('');
  return '<div style="display:flex;flex-direction:column;gap:8px;">'
    + '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">'
    + '<label style="font-size:0.78rem;font-weight:600;color:#546E7A;">Estado:</label>'
    + '<select id="coord-rend-seg-estado-' + idx + '" style="padding:5px 8px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.78rem;">' + opciones + '</select>'
    + '</div>'
    + '<textarea id="coord-rend-seg-nota-' + idx + '" placeholder="Nota de seguimiento (acción tomada, próximos pasos...)" '
    + 'style="width:100%;min-height:60px;padding:8px;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.8rem;font-family:inherit;resize:vertical;">' + escapeHTML(alerta.nota || '') + '</textarea>'
    + '<div style="display:flex;gap:8px;flex-wrap:wrap;">'
    + '<button onclick="_coordGuardarSeguimiento(' + idx + ')" style="background:#00695C;color:#fff;border:none;border-radius:8px;padding:6px 14px;font-size:0.78rem;font-weight:600;cursor:pointer;">Guardar</button>'
    + (alerta.derivadoAPsicologia
        ? '<span style="color:#6A1B9A;font-size:0.78rem;font-weight:600;align-self:center;">✓ Derivado a Orientación</span>'
        : '<button onclick="_coordDerivarPsicologia(' + idx + ')" style="background:#6A1B9A;color:#fff;border:none;border-radius:8px;padding:6px 14px;font-size:0.78rem;font-weight:600;cursor:pointer;">Derivar a Orientación</button>')
    + '<span style="font-size:0.72rem;color:#9E9E9E;align-self:center;">Abierto por ' + escapeHTML(alerta.creadoPor || '') + '</span>'
    + '</div></div>';
}

async function _coordAbrirSeguimiento(idx) {
  const f = window._coordRendData?.[idx];
  const centroId = window._coordRendCentroId;
  if (!f || !centroId) return;
  try {
    const nuevo = {
      docenteUid: f.docenteUid, cursoId: f.cursoId, estId: f.estId,
      estudianteNombre: f.estNombre, cursoNombre: f.cursoNombre, docenteNombre: f.docente,
      notaPct: f.pct, estado: 'nueva', nota: '', derivadoAPsicologia: false,
      creadoPor: window.currentUser?.email || '',
      fechaCreacion: firebase.firestore.FieldValue.serverTimestamp(),
      fechaActualizacion: firebase.firestore.FieldValue.serverTimestamp()
    };
    const ref = await db.collection('centros').doc(centroId).collection('alertas_rendimiento').add(nuevo);
    const key = f.docenteUid + '|' + f.cursoId + '|' + f.estId;
    window._coordAlertasMap[key] = { id: ref.id, ...nuevo };
    mostrarToast('Caso de seguimiento abierto', 'success');
    _coordFiltrarRendimiento();
    _coordActualizarBadgeAlertas();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

function _coordToggleSeguimientoDetalle(idx) {
  const el = document.getElementById('coord-rend-seg-' + idx);
  if (!el) return;
  el.style.display = el.style.display === 'none' ? 'table-row' : 'none';
}

async function _coordGuardarSeguimiento(idx) {
  const f = window._coordRendData?.[idx];
  const centroId = window._coordRendCentroId;
  if (!f || !centroId) return;
  const key = f.docenteUid + '|' + f.cursoId + '|' + f.estId;
  const alerta = window._coordAlertasMap?.[key];
  if (!alerta) return;
  const estado = document.getElementById('coord-rend-seg-estado-' + idx)?.value || alerta.estado;
  const nota = document.getElementById('coord-rend-seg-nota-' + idx)?.value || '';
  try {
    await db.collection('centros').doc(centroId).collection('alertas_rendimiento').doc(alerta.id).update({
      estado, nota, fechaActualizacion: firebase.firestore.FieldValue.serverTimestamp()
    });
    alerta.estado = estado; alerta.nota = nota;
    mostrarToast('Seguimiento actualizado', 'success');
    _coordFiltrarRendimiento();
    _coordActualizarBadgeAlertas();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

async function _coordDerivarPsicologia(idx) {
  const f = window._coordRendData?.[idx];
  const centroId = window._coordRendCentroId;
  if (!f || !centroId) return;
  const key = f.docenteUid + '|' + f.cursoId + '|' + f.estId;
  const alerta = window._coordAlertasMap?.[key];
  if (!alerta) return;
  try {
    await db.collection('centros').doc(centroId).collection('alertas_rendimiento').doc(alerta.id).update({
      derivadoAPsicologia: true, fechaActualizacion: firebase.firestore.FieldValue.serverTimestamp()
    });
    alerta.derivadoAPsicologia = true;
    mostrarToast('Caso marcado como derivado a Orientación', 'success');
    _coordFiltrarRendimiento();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

/** Actualiza el badge de alertas nuevas sobre el botón "Panel Coordinadora" del dashboard */
async function _coordActualizarBadgeAlertas() {
  const badge = document.getElementById('coord-alertas-badge');
  if (!badge) return;
  try {
    const centroId = await _coordGetCentroId();
    if (!centroId) { badge.style.display = 'none'; return; }
    const snap = await db.collection('centros').doc(centroId).collection('alertas_rendimiento').where('estado', '==', 'nueva').get();
    if (snap.size > 0) { badge.style.display = 'flex'; badge.textContent = snap.size > 9 ? '9+' : String(snap.size); }
    else { badge.style.display = 'none'; }
  } catch { badge.style.display = 'none'; }
}

function abrirVinculacion() {
  window._vincCentroSeleccionado = null;
  window._vincFormAbierto = null;
  window._vincEditId = null;
  window._vincEditItem = null;
  _mostrarPanel('panel-vinculacion');
  switchTabVinculacion('pasantiasEst');
}

function switchTabVinculacion(tab) {
  const tabs = {
    pasantiasEst: 'tab-vinc-pasantias-est', pasantiasDoc: 'tab-vinc-pasantias-doc', bolsaEmpleo: 'tab-vinc-bolsa-empleo',
    diagnosticos: 'tab-vinc-diagnosticos', convenios: 'tab-vinc-convenios', eventos: 'tab-vinc-eventos', reportes: 'tab-vinc-reportes'
  };
  Object.entries(tabs).forEach(([key, id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (key === tab) { el.classList.add('activo'); el.style.background = '#EF6C00'; el.style.color = '#fff'; }
    else { el.classList.remove('activo'); el.style.background = '#F5F5F5'; el.style.color = '#616161'; }
  });
  window._vincTabActual = tab;
  window._vincFormAbierto = null;
  window._vincEditId = null;
  window._vincEditItem = null;
  const dispatch = {
    pasantiasEst: _vincRenderPasantiasEst, pasantiasDoc: _vincRenderPasantiasDoc, bolsaEmpleo: _vincRenderBolsaEmpleo,
    diagnosticos: _vincRenderDiagnosticos, convenios: _vincRenderConvenios, eventos: _vincRenderEventos, reportes: _vincReportesImpacto
  };
  if (dispatch[tab]) dispatch[tab]('vinc-contenido');
}

async function _vincGetCentroId() {
  if (window._vincCentroSeleccionado) return window._vincCentroSeleccionado;
  if (!window.currentUser) return null;
  try {
    const doc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    if (doc.exists && doc.data().centroId) return doc.data().centroId;
  } catch {}
  try {
    const email = window.currentUser.email;
    if (email) {
      const [centro] = await _buscarCentrosPorEmailAdmin(email);
      if (centro) return centro.id;
      // Caso raro (solo superadmins): aqui si se justifica traer la coleccion
      // completa en vez de agregar una consulta de conteo nueva.
      const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
      if (esSA) {
        const snap = await db.collection('centros').get();
        if (snap.size === 1) return snap.docs[0].id;
      }
    }
  } catch {}
  return null;
}

async function _vincMostrarSelectorCentro(cont, callback, contId) {
  try {
    const snap = await db.collection('centros').get();
    const centros = snap.docs.map(d => ({ id: d.id, ...d.data() }));
    if (!centros.length) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay centros registrados.</div>'; return; }
    const args = contId ? '\'' + contId + '\'' : '';
    let html = '<div style="text-align:center;padding:30px;">'
      + '<span class="material-icons" style="font-size:48px;color:#EF6C00;display:block;margin-bottom:12px;">business</span>'
      + '<p style="color:#546E7A;margin-bottom:16px;">Selecciona un centro educativo para ver sus datos:</p>'
      + '<div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;">';
    centros.forEach(c => {
      html += '<button onclick="window._vincCentroSeleccionado=\'' + c.id + '\';' + callback + '(' + args + ')" style="padding:12px 20px;background:#fff;border:2px solid #EF6C00;border-radius:12px;cursor:pointer;font-size:0.9rem;font-weight:600;color:#EF6C00;transition:all 0.2s;"'
        + ' onmouseover="this.style.background=\'#EF6C00\';this.style.color=\'#fff\'" onmouseout="this.style.background=\'#fff\';this.style.color=\'#EF6C00\'">'
        + '<span class="material-icons" style="font-size:16px;vertical-align:middle;margin-right:4px;">school</span>'
        + escapeHTML(c.nombre || c.id) + '</button>';
    });
    html += '</div></div>';
    cont.innerHTML = html;
  } catch (e) { cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>'; }
}

